import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/18/","title":"第 18 课 · 完形填空 Cloze Test | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 18 课 · 完形填空 Cloze Test","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/18/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第一课 题型技巧 · 第一课 对应教材上册 P230–P238 · 15 题 30 分——做题主线「跳空通读 → 结合选项初选 → 先易后难 → 回填复核」，判断层级「完形服从完意，单句服从段落，段落服从全文」。 考点地图 · 点击跳转 考情与原则：命题以...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 18 课 · 完形填空 Cloze Test\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/18/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 18 课 · 完形填空 Cloze Test"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第一课 题型技巧 · 第一课 对应教材上册 P230–P238 · 15 题 30 分——做题主线「跳空通读 → 结合选项初选 → 先易后难 → 回填复核」，判断层级「完形服从完意，单句服从段落，段落服从全文」。 考点地图 · 点击跳转 考情与原则：命题以..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 18 课 · 完形填空 Cloze Test"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/18/"}]]},"readingTime":{"minutes":372,"words":111601},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/18.md","headers":[]}`),u={name:`18.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0018-cloze.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 02 · 题型技巧 / 第一课`,-1)]),l[14]||=r(`<p>题型技巧 · 第一课</p><p>对应教材上册 P230–P238 · 15 题 30 分——做题主线「跳空通读 → 结合选项初选 → 先易后难 → 回填复核」，判断层级「完形服从完意，单句服从段落，段落服从全文」。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>考情与原则</strong>：命题以语篇意义为主、语法为辅；完形服从完意、单句服从段落、段落服从全文</a></li><li><a href="#pt-2"><strong>解题三步</strong>：跳空通读抓大意 → 结合选项初选 → 先易后难、瞻前顾后</a></li><li><a href="#pt-3"><strong>七大策略</strong>：语境推理 · 语法理顺 · 复现 · 固定搭配 · 逻辑语气 · 文化常识 · 对比与平行结构</a></li><li><a href="#pt-4"><strong>实战</strong>：2025 年真题 15 题 + 题海 20 篇（每篇 15 空）</a></li></ol></div><h2 id="第一部分-·-考情分析与答题原则" tabindex="-1"><a class="header-anchor" href="#第一部分-·-考情分析与答题原则"><span>第一部分 · 考情分析与答题原则</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一部分 · 考情分析与答题原则</p><ul><li><strong>目标</strong>：先弄清完形填空考什么、按什么标准判对错：题型 15 题 30 分，考词义辨析、固定搭配、语法结构与篇章衔接；做题时按「完形服从完意、单句服从段落、段落服从全文」三级判断，不靠单句语法凑答案。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>完形填空考情与命题特征</code></li></ul></div><h3 id="第一部分-·-考情分析与答题原则-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一部分-·-考情分析与答题原则-·-小步学"><span>第一部分 · 考情分析与答题原则 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 3 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>完形填空：把空放回故事里</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>完形不是语法题：语法正确的选项未必是答案</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句话说清「完形服从完意」的含义，并说出完形填空考的四类角度与三条答题原则。</p><div class="hint-container tip"><p class="hint-container-title">完形不是语法题：语法正确的选项未必是答案</p><p><strong>句意</strong>：Giving up is easy, but ____ requires courage. 意思是「放弃很容易，但坚持需要勇气」；四个选项 stopping、quitting、persevering、retreating 在语法上都成立，能作主语、都带 -ing，只有 persevering 与前文 Giving up 构成反义呼应。</p><p><strong>拆解</strong></p><ul><li>第一步看语法：空处作主语，四个 -ing 形式都合格 —— 语法这一步筛不掉任何选项</li><li>第二步看篇章：but 要求前后一正一反，前文是 Giving up（放弃），空处必须填「不放弃」</li><li>第三步看选项：stopping、quitting 与「放弃」同义，retreating（撤退）仍属「退」，只有 persevering（坚持）是反义项</li><li>结论：完形的判分标准落在语篇意义，语法只是入场券，不是答案本身</li></ul><p><strong>语法</strong>：完形填空 15 题、每题 2 分共 30 分，命题特征是「文章短、挖空多；意义选择为主、语法选择为辅；实词为主、虚词为辅；保留提示句」。测试角度是词义辨析、固定搭配、语法结构与篇章衔接推理。三级判断原则：完形服从完意（根据整篇文意选词）、单句服从段落（与段落主题一致）、段落服从全文（推动全文发展、契合中心思想）。</p><p>正例：Giving up is easy, but persevering requires courage.（反义呼应，but 的转折成立）；He was too tired to swim any further and drowned.（too ... to 与 drowning 的结果一致） 反例：Giving up is easy, but quitting requires courage. ×（quitting 与 Giving up 同义，but 无转折可言）；先看 A 项语法对就选 A，读完再回看时才发现全文情感方向相反。×（把完形当成孤立语法题） 适用边界：「语法正确不等于答案」只适用于意义空与实词空；遇到纯语法空（如 you must work hard ____ it 的介词、not only ... ____ also 的连词），语法本身就能定案，此时仍要顺手检查搭配与形式。</p><p><strong>口诀</strong>：先完意，后完形；先全文，后单句 —— 先按整篇文意定方向，再用语法核对形式；先读通全文，再落到单句。反过来做，就会掉进「每句都通顺、整篇不对路」的陷阱。</p></div><table><thead><tr><th>命题特征</th><th>测试角度（考什么）</th><th>答题角度（从哪下手）</th></tr></thead><tbody><tr><td>1. 文章短，挖空多 2. 情景意义选择为主，语法选择为辅 3. 短文逻辑性强，结构严谨，层次分明 4. 单词填空为主，短语词组整体填空为辅 5. 逻辑性强，实词为主，虚词为辅 6. 保留提示句</td><td>1. 词义辨析 2. 固定搭配 3. 语法结构 4. 文章的衔接及推理</td><td>1. 语法角度 2. 词语用法角度 3. 上下文角度 4. 惯用法角度 5. 常识和知识角度</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>三大答题原则</p><ol><li><p><strong>完形服从完意</strong>：根据整篇文章的意思决定哪个词最合适，而不是仅看单句语法或单词用法；填入的词必须在语境中有意义。</p></li><li><p><strong>单句服从段落</strong>：一个句子内部多个选项看似合适时，要考虑该句在段落中的作用和位置，与段落主题保持一致。</p></li><li><p><strong>段落服从全文</strong>：填入的词应推动文章发展，与全文中心思想契合。</p></li></ol></div><h2 id="第二部分-·-解题三步" tabindex="-1"><a class="header-anchor" href="#第二部分-·-解题三步"><span>第二部分 · 解题三步</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二部分 · 解题三步</p><ul><li><strong>目标</strong>：把做题流程固定成三步：第一遍跳空通读抓大意（先读首句、末句定体裁与态度），第二遍结合选项初选，第三遍先易后难、瞻前顾后，最后全部回填再通读一遍。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>完形填空解题三步</code> <code>完形·复查与易错清单</code></li></ul></div><h3 id="第二部分-·-解题三步-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二部分-·-解题三步-·-小步学"><span>第二部分 · 解题三步 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>完形填空：把空放回故事里</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>三步走的时间分配：通读一遍、初选一轮、回填复核一遍</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：不看笔记，按顺序说出解题三步各做什么，并说明首句和末句在第一步里各起什么作用。</p><div class="hint-container tip"><p class="hint-container-title">三步走的时间分配：通读一遍、初选一轮、回填复核一遍</p><p><strong>句意</strong>：In a small town, there was a small cat that was very curious about the outside world. 这一句是 2025 年真题的首句，一句话交代了地点、主角和性格，后面的雪天、失踪、南行全部围绕 curious 展开。</p><p><strong>拆解</strong></p><ul><li>第一步跳空通读：看到首句 In a small town, there was a small cat，先确定这是记叙文、主人公是一只小猫</li><li>第二步结合选项初选：把有把握的空先填，例如第 22 空由十一月 + 白色覆盖直接定为 snow，用 in the snow 反过来确认</li><li>第三步先易后难：把暂时说不清的（如第 31 空两年、第 32 空 run away）留到后文读完夫妇的解释再回填</li><li>最后回填复核：把答案放回原句，检查单复数、时态、语态与介词搭配是否同时成立</li></ul><p><strong>语法</strong>：第一步「跳过空格通读全文，把握大意」——重点读首句与末句：首句帮助判断体裁、预测主要内容，末句帮助了解结局或作者态度。第二步「结合选项，综合考虑，初选答案」——以词义、句义为先，再分析句子结构，综合比较、筛选并排除干扰项；有把握的先做，没把握的先跳。第三步「先易后难，瞻前顾后，各个击破」——结合已确定的选项再读全文，随理解深入难度自然降低。</p><ol><li><strong>第一遍</strong> 跳空通读，只抓人事时地，不落笔填空</li><li><strong>第二遍</strong> 结合选项初选，简单空当场定，难空先标记</li><li><strong>第三遍</strong> 回填复核，检查数、时态、语态、搭配与全文连贯</li></ol><p>正例：首句 In a small town, there was a small cat ... 先判记叙文体裁与主角（小猫）；末句 That’s because it was a good way to escape the cold weather. 揭出作者态度：赞赏小猫的聪明 反例：一上来从第 21 空往后逐空硬做，不读全文。×（第 31 空 two years ago 这类需要全文时间线支撑的空必然做错）；每填一空就重新通读全文三遍。×（时间不够，且越读越乱） 适用边界：「先通读再填空」在短文补全类（本篇 15 空的完形）最有效；若是单句题（如策略例题那种各自独立的一句），就没有篇章可通读，直接按句内线索与搭配判断即可。</p><p><strong>口诀</strong>：有把握先填，没把握先跳；全部回填，再读一遍 —— 三步的节奏比三步的顺序更容易被忽略：先填有把握的空，等于给自己搭好脚手架，难空回过头来常常已经不言自明。</p></div><ol><li><strong>跳过空格通读全文，把握大意</strong>：第一遍通读获得整体印象，弄清文脉、抓住主旨。尤其要读懂<strong>首句和末句</strong>——首句帮助判断体裁、预测主要内容；末句帮助了解结局或作者态度。</li><li><strong>结合选项，综合考虑，初选答案</strong>：联系上下文，从语法结构、词语搭配和选项中寻找提示；以词义、句义为先，再分析句子结构，综合比较、筛选并排除干扰项。</li><li><strong>先易后难，瞻前顾后，各个击破</strong>：有把握的先做，没把握的先跳过；结合已确定的选项再读全文，随着理解深入，难度自然降低，正确率提高。</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>先完意，后完形；先全文，后单句。有把握先填，没把握先跳；全部回填，再读一遍。</strong></p></div><h2 id="第三部分-·-七大解题策略" tabindex="-1"><a class="header-anchor" href="#第三部分-·-七大解题策略"><span>第三部分 · 七大解题策略</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第三部分 · 七大解题策略</p><ul><li><strong>目标</strong>：掌握语境推理、语法理顺、复现、固定搭配、逻辑语气、文化常识、对比与平行七条策略，能在做完形时主动选策略而不是凭语感猜词。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>语境推理法</code> <code>复现解题法</code> <code>固定搭配解题法</code> <code>完形·逻辑连接词</code> <code>对比结构与平行结构</code> <code>完形·文化背景与生活常识</code> <code>完形·语法校验</code></li></ul></div><h3 id="第三部分-·-七大解题策略-·-小步学" tabindex="-1"><a class="header-anchor" href="#第三部分-·-七大解题策略-·-小步学"><span>第三部分 · 七大解题策略 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>完形填空：把空放回故事里</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>语境推理：上文有因，下文有果</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>复现解题法：原词、同义、反义三次复现</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>固定搭配与逻辑语气：整体看短语，两头看逻辑</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>对比结构与平行结构：quiet and comfortable 与 small, noisy 相对</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>文化背景与生活常识：U-turn、911、十一月下雪</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：把七条策略的名字说一遍，并各配一句自己的话：这条策略是「从哪里找线索」的。</p><div class="hint-container tip"><p class="hint-container-title">语境推理：上文有因，下文有果</p><p><strong>句意</strong>：In November, the snow fell heavily, blanketing the town in white. It was very cold outside, but this small cat still visited the backyard. 意思是「十一月大雪纷飞，小镇被盖成白色。外面很冷，但小猫仍然去后院」。</p><p><strong>拆解</strong></p><ul><li>先读原因句：十一月、大雪、很冷</li><li>再读结果句：but this small cat still visited the backyard（仍然去后院）</li><li>but 表明「天冷」与「仍出门」是对立的两面，据此可预测下一句它要在雪里想办法取暖</li><li>于是 And it dug in the snow to find a warmer place 里的 dug 就有了因果支撑</li></ul><p><strong>语法</strong>：语境推理用于难以直接选择的空：分析上下文，理解句间关系、段落结构与全文逻辑，把握文章走势。常见线索有四条——上文有因下文往往有果；从对立两面阐述中间常有转折词；从同一角度论述常出现并列连词；and 连接修饰人的形容词时通常同为褒义或同为贬义，but 连接时往往一褒一贬。</p><p>正例：In November, the snow fell heavily ... It was very cold outside, but this small cat still visited the backyard.（冷 → 仍出门）；Its owner was worried, searching everywhere but finding no sign of it.（找不到 → 担心） 反例：Its owner was delighted, searching everywhere but finding no sign of it. ×（finding no sign 与 delighted 情感相反）；And it slept in the snow to find a warmer place. ×（已睡下就不必再找更暖和的地方，结果状语落空） 适用边界：语境的因果方向必须以文中的连词与结果句为准，不能只凭常识：十一月、雪天在常识里指向「冷」，但句中的 but 说明小猫的行为另有打算，方向是「冷而主动」而不是「冷而畏缩」。</p><p><strong>口诀</strong>：首尾定主旨，上下找复现，前后判逻辑 —— 三条线索按顺序用：先定全篇主旨，再在上下句找复现，最后用逻辑词核对方向。</p></div><div class="hint-container tip"><p class="hint-container-title">复现解题法：原词、同义、反义三次复现</p><p><strong>句意</strong>：Not all of these fairies are the friendly, people-loving characters that appear in Disney films. 意思是「并非所有这些仙子都像迪士尼电影里那样友善、亲近人类」。</p><p><strong>拆解</strong></p><ul><li>原词复现：上文出现 a belief in fairies，本句 these ____ 直接复现 fairies</li><li>同义复现：Garth&#39;s email was short, but I learned more from that brief message ... 里的 brief 复现 short</li><li>反义复现：Giving up is easy, but persevering requires courage. 里的 persevering 与 Giving up 反义</li><li>三步定位：找指示词（these/that）→ 在上下句找对应词 → 判断是同义还是反义</li></ul><p><strong>语法</strong>：复现包括同义词、近义词和反义词的原形或异形复现，考查整体篇章意识与上下文推断能力。原词复现看前文出现的同一个词；同义复现看语义等值的换词；反义复现看与提示词构成对立的那一项。复现可能跨句甚至跨段，因此通读一遍比逐句硬做更省力。</p><p>正例：上文 a belief in fairies → Not all of these fairies are ...（原词复现）；Garth&#39;s email was short → from that brief message（同义复现）；Giving up is easy → but persevering requires courage（反义复现） 反例：Not all of these babies are ... ×（前面没有 babies，复现链断裂）；Garth&#39;s email was short → from that accurate message ×（accurate 与 short 之间没有语义等值关系） 适用边界：复现线索只有在「同指一个事物」时才有效：these/that 必须能找到明确的指代对象。若前文出现的是 beliefs（信念）而空处要填「持有该信念的人」，就不是复现而是词形干扰。</p><p><strong>口诀</strong>：指代词指回上文，上下文必有复现 —— 看到 these、that、such 就立刻回头找复现对象，能解决大量名词与形容词空。</p></div><div class="hint-container tip"><p class="hint-container-title">固定搭配与逻辑语气：整体看短语，两头看逻辑</p><p><strong>句意</strong>：I remember that I used to make up stories in my notebooks. 意思是「我记得我常常在笔记本里编故事」；Extrinsic motivation, on the other hand, comes from external factors. 意思是「而另一方面，外在动机来自外部因素」。</p><p><strong>拆解</strong></p><ul><li>固定搭配看整体：make up stories（编故事）、give up（放弃）、pass down（传下去）、be close to death（濒临消亡），拆开单看每个词都判断不出答案</li><li>逻辑语气看两头：内在动机 vs 外在动机是对照，用 on the other hand；do something ____ they enjoy the process 是前果后因，用 because</li><li>逻辑词只有「前后语义关系成立」才算选对：and 要求同向，but 要求相反，because 要求前果后因</li></ul><p><strong>语法</strong>：固定搭配题强调词与词的惯用组合，涉及关联词、动词、副词、形容词、名词和短语；解题时把空前后组成整体再判断。逻辑语气题的选项多为连词、副词或具有连词作用的短语，常见关系为并列、递进、因果、转折和委婉；先掌握人物、时间、地点等信息，再分析句间与段间关系。</p><p>正例：make up stories（编故事）、give up（放弃）、pass it down to future generations（传给后代）；Extrinsic motivation, on the other hand, comes from external factors.（对照）；work hard to achieve high sales figures because they want to earn a big bonus（前果后因） 反例：write up stories ×（write up 是「整理成文」，不是「编造」）；Extrinsic motivation, in addition, comes from external factors. ×（递进误用于对照）；No one responded and he assumed that people had already arrived. ×（未回应推出「已经到达」，逻辑不通） 适用边界：同一个动词搭配不同小品词意思完全不同，必须先定整个短语再比较选项；逻辑词则必须在两个小句之间能真正成立，仅凭「读着顺」容易把 in addition 与 on the other hand 混用。</p><p><strong>口诀</strong>：词义看语境，搭配看整体，语法看结构，常识作辅助 —— 四把尺子分工不同：先用语篇定词义，再用固定搭配排除，再用语法核对形式，最后才轮到常识补位。</p></div><div class="hint-container tip"><p class="hint-container-title">对比结构与平行结构：quiet and comfortable 与 small, noisy 相对</p><p><strong>句意</strong>：A pupil who can do his homework in a quiet and comfortable room is in a much better position than a pupil who does his homework in a small, noisy room with the television on. 意思是「能在安静、舒适的房间里做作业的学生，比在放着电视的小而嘈杂的房间里做作业的学生处境好得多」。</p><p><strong>拆解</strong></p><ul><li>定位：先找到比较结构 better position than，它把两类房间摆成对立面</li><li>比对：前半是 quiet and ____，后半是 small, noisy —— 空的形容词必须与 quiet 同向、与 noisy 反向</li><li>排除：furnished（有无家具）、expensive（价格）都不属「环境质量」，suitable 是评价性空词，只有 comfortable 与 quiet 并列成立</li><li>平行结构的检验标准：and 连接的成分要在词性、形式和语义方向上一致</li></ul><p><strong>语法</strong>：对比结构把两种对立事物或同一事物的两个不同方面并列起来比较；平行结构由结构相同或相似、意义密切关联、语法一致的词或句子成串排列。解题时先找对比标记（than、but、while、whereas），再把并列成分的形式与语义方向对齐。</p><p>正例：in a quiet and comfortable room ... in a small, noisy room（同向并列 vs 反向对照）；looking happy and healthy（并列表语同为褒义） 反例：in a quiet and expensive room ×（与 noisy 不构成环境质量上的正反对照）；looking happy and lonely ×（and 连接的并列成分不能一褒一贬） 适用边界：平行结构要求形式与语义同时对齐：只有当空处确实处在并列链条中（前面有 and/or、后面有同类成分）时才用这条规则。若空处只是句子里的一个普通修饰语，硬套「同向」会选错，此时要回到语境推理。</p><p><strong>口诀</strong>：and 多同向，but 常反向；上因下果，前转后折 —— 并列连词先对齐语义方向，转折连词先找对立点，因果连词先定谁解释谁。</p></div><div class="hint-container tip"><p class="hint-container-title">文化背景与生活常识：U-turn、911、十一月下雪</p><p><strong>句意</strong>：When Jim Grant spotted black smoke coming out of a building, he stopped his car to call 911. 意思是「吉姆·格兰特看到一栋楼里冒出黑烟，就把车停下来打 911 报警」。</p><p><strong>拆解</strong></p><ul><li>定位：本句没有可供复现的上下文（文章开头），只能靠常识判断</li><li>常识推理：看到冒黑烟 + 要打电话 → 打电话必须先停车；美国报警电话是 911</li><li>再看下一空 Then he made a U-turn, circling back to take another look：U-turn（掉头）是英语中固定的交通说法</li><li>结论：语言线索不足时，用英语国家的文化背景与生活常识补位，但要与后文情节互相验证</li></ul><p><strong>语法</strong>：完形填空以独立语篇命题，会交织各类常识和文化背景知识。解题时，语言知识与英美国家文化背景和生活常识都可能发挥作用，常见的有时间与季节常识（十一月下雪）、交通与制度常识（U-turn、911）、社交常识（pay one&#39;s respects to）等。</p><p>正例：In November, the snow fell heavily, blanketing the town in white.（十一月 + 白色覆盖 → 雪）；he stopped his car to call 911（报警要先停车）；Then he made a U-turn, circling back to take another look.（掉头是 U-turn） 反例：In November, the fog fell heavily, blanketing the town in white. ×（雾不会「落得很大」，也不会把小镇盖成白色）；he drove his car to call 911 ×（边开车边打报警电话与「上前查看」的动作链不符） 适用边界：常识只能用来「缩小范围、验证方向」，不能替代文本证据：十一月在常识里指向冷与雪，但若文中写的是南方、写着 warm，就必须以文本为准。常识与文本冲突时，一律以文本为准。</p><p><strong>口诀</strong>：常识补位，文本定案 —— 常识负责给方向，文本负责下决定；两者冲突时永远服从事文中的时间、地点与人物设定。</p></div><h3 id="策略一-·-语境推理" tabindex="-1"><a class="header-anchor" href="#策略一-·-语境推理"><span>策略一 · 语境推理</span></a></h3><p>遇到难以直接选择的空，分析上下文，理解句间关系、段落结构与全文逻辑，把握文章走势，选择与作者思路或意图一致的选项。</p><ul><li>上文有因，下文往往有果。</li><li>从对立两面阐述，中间常有转折词。</li><li>从同一角度论述，常出现并列连词。</li><li>and 连接修饰人的形容词时，通常同为褒义或同为贬义；but 连接时，往往一褒一贬。</li></ul><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>and 多同向，but 常反向；上因下果，前转后折。</strong></p></div><h3 id="策略二-·-运用语法理顺关系" tabindex="-1"><a class="header-anchor" href="#策略二-·-运用语法理顺关系"><span>策略二 · 运用语法理顺关系</span></a></h3><ul><li>注意<strong>时态、人称、单复数</strong>及数的变化，这类题往往容易得分。</li><li>主语从句：重点判断引导词与主谓一致。</li><li>宾语从句：重点判断引导词、语序和时态呼应（客观真理除外）。</li><li>定语从句：关键是关系词选择。</li><li>形容词、副词：结合语境判断原级、比较级或最高级，并注意各自用法。</li></ul><h3 id="策略三-·-复现解题法" tabindex="-1"><a class="header-anchor" href="#策略三-·-复现解题法"><span>策略三 · 复现解题法</span></a></h3><p>复现包括<strong>同义词、近义词和反义词</strong>的原形或异形复现，主要考查整体篇章意识与上下文推断能力。课件三例连做——原词复现、同义词复现、反义词复现（课件未附答案，答案与解析为笔记整理补充）。</p><p><strong>【原词复现】In particular, there was (and perhaps still is) a belief in fairies. Not all of these ____ are the friendly, people-loving characters that appear in Disney films.</strong></p><ul><li>A. babies</li><li>B. believes</li><li>C. fairies</li><li>D. supermen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（fairies）</strong> —— 上文已经出现 fairies，属于原词复现。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ babies（婴儿）在本句和上文都没有出现，无法与前面的 belief in fairies 形成呼应。干扰点：只按「角色」猜词，忽略上文已给出的名词。</li><li>B ❌ believes 作名词是「信仰」的误拼形式，且上面出现的是 a belief，本题要填的是「被相信的对象」而非「信仰」本身。干扰点：被上文 belief 的同形词吸引。</li><li>C ✅ 上文已经出现 fairies，these 指代的正是它，属于原词复现，故选 fairies（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ supermen（超人）与 fairy 是两套不同形象体系，迪士尼电影里的对应角色是 fairy 而非 superman。干扰点：凭「电影角色」的常识而非本段复现线索作答。</li></ul><p><strong>整句翻译</strong>：尤其是，过去（也许现在仍）有一种对仙子的信仰。并非所有这些仙子都像迪士尼电影里那样友善、亲近人类。</p><p><strong>词组</strong>：<code>a belief in fairies</code> 对仙子的信仰；<code>people-loving</code> 爱人类的、亲近人的</p><p><strong>对比自测</strong>：做完后对照 quiz-s1:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 第三部分 策略三 · 复现解题法 例题（单句题，题干即定位句））：In particular, there was (and perhaps still is) a belief in fairies. Not all of these ____ are the friendly, people-loving characters that appear in Disney films.</p></details><p><strong>【同义词复现】Garth’s email was short, but I learned more from that ____ message than I ever did from a textbook.</strong></p><ul><li>A. accurate</li><li>B. urgent</li><li>C. brief</li><li>D. humorous</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（brief）</strong> —— brief（简短的）与前文的 short 同义复现。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ accurate（准确的）与前面的 short 不是同一语义方向，全文也没有提「准确」。干扰点：把褒义形容词一律当成可用选项。</li><li>B ❌ urgent（紧急的）表「急迫」，句子只陈述邮件篇幅，没有任何紧急信息。干扰点：凭「邮件」的生活印象联想出紧急感。</li><li>C ✅ brief 与前半句的 short 是同义复现，两个小句用 but 形成对比（短却很受益）（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ humorous（幽默的）在本句和上下文都没有线索支撑，与 short 也不构成同义关系。干扰点：把「邮件」与「有趣」硬性关联。</li></ul><p><strong>整句翻译</strong>：加斯的电子邮件很短，但我从那封简短的信息中学到的东西，比从任何一本教科书中学到的都多。</p><p><strong>词组</strong>：<code>learn from</code> 从……中学到；<code>more ... than ...</code> 比……更多</p><p><strong>对比自测</strong>：做完后对照 quiz-s1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 第三部分 策略三 · 复现解题法 例题（单句题，题干即定位句））：Garth’s email was short, but I learned more from that ____ message than I ever did from a textbook.</p></details><p><strong>【反义词复现】Life is full of challenges. Sometimes we face difficulties, but we should never give up. … Giving up is easy, but ____ requires courage.</strong></p><ul><li>A. stopping</li><li>B. quitting</li><li>C. persevering</li><li>D. retreating</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（persevering）</strong> —— persevering（坚持）与前面的 Giving up（放弃）构成反义复现。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stopping 与 Giving up 语义同向（都是「停下」），填进去等于重复前半句，but 的转折落空。干扰点：只看到「-ing 形式作主语」这一语法条件。</li><li>B ❌ quitting 与 Giving up 是同义项，同样读不出转折，且 requires courage 与前文语义重复。干扰点：把「放弃」的近义词当作语义升级。</li><li>C ✅ persevering（坚持）与 Giving up 构成反义复现，正好满足 but 的转折（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ retreating（撤退）仍是「退」，与 Giving up 同向，不能与 requires courage 形成「难而值得」的对照。干扰点：把「撤退」误当作与放弃意义相反。</li></ul><p><strong>整句翻译</strong>：放弃很容易，但坚持需要勇气。</p><p><strong>词组</strong>：<code>give up</code> 放弃；<code>require courage</code> 需要勇气</p><p><strong>对比自测</strong>：做完后对照 quiz-s1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 第三部分 策略三 · 复现解题法 例题（单句题，题干即定位句））：Life is full of challenges. Sometimes we face difficulties, but we should never give up. … Giving up is easy, but ____ requires courage.</p></details><h3 id="策略四-·-固定搭配解题法" tabindex="-1"><a class="header-anchor" href="#策略四-·-固定搭配解题法"><span>策略四 · 固定搭配解题法</span></a></h3><p>这类题与语法结构题相似，但更强调<strong>词与词的惯用搭配</strong>，涉及关联词、动词、副词、形容词、名词和短语。先读下面这篇小短文，再做完三空（课件未附答案，答案与解析为笔记整理补充）。</p><p>I have a dream of becoming a successful writer. Writing has been my passion since I was a child. I remember that I used to <strong><em><strong>1</strong></em></strong> stories in my notebooks and show them to my parents. They always praised me for my creativity.</p><p>However, when I grew up, I realized that becoming a writer was not an easy task. I had to face many rejections from publishers. But I didn’t give <strong><em><strong>2</strong></em></strong>. I kept on sending my manuscripts to different publishing houses.</p><p>One day, I received a call from a publisher. He said that he was interested in my book and wanted to publish it. I was over the moon. I had finally achieved my dream <strong><em><strong>3</strong></em></strong> hard work and perseverance.</p><p><strong>I remember that I used to ____ stories in my notebooks and show them to my parents.</strong></p><ul><li>A. write up</li><li>B. make up</li><li>C. turn up</li><li>D. pick up</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（make up）</strong> —— make up stories 表示「编故事」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ write up 意为「整理成文、写成」，是把已有材料加工成文，不表示从无到有地编造。干扰点：被 stories 与 write 的天然联想带偏。</li><li>B ✅ make up stories 是固定搭配，意为「编故事」；下文的 show them to my parents（拿给父母看）也说明是自创而非抄录（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ turn up 意为「出现、调大（音量）」，与 stories 搭配后语义不成立。干扰点：只认得 up 这一小品词，不区分整个短语的意思。</li><li>D ❌ pick up 意为「捡起、学会、接人」，接 stories 只能理解成「随手收起故事」，与后文「拿给父母看」的创作场景不符。</li></ul><p><strong>整句翻译</strong>：我记得我常常在笔记本里编故事，然后拿给父母看。</p><p><strong>词组</strong>：<code>make up stories</code> 编故事；<code>used to do</code> 过去常常做（现在不做了）</p><p><strong>对比自测</strong>：做完后对照 quiz-s2:1，比较两题的判断依据</p><p><strong>原文定位</strong>（策略四 · 固定搭配解题法 · 第1段 · 第1空所在句）：I remember that I used to <em><strong>1</strong></em> stories in my notebooks and show them to my parents.</p></details><p><strong>But I didn’t give ____. I kept on sending my manuscripts to different publishing houses.</strong></p><ul><li>A. in</li><li>B. out</li><li>C. up</li><li>D. away</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（up）</strong> —— give up 表示「放弃」，与 kept on sending 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ give in 意为「让步、屈服」，一般指对某人或某要求妥协，与「继续寄稿件」的行为不对应。干扰点：in 与 up 都是常见小品词，容易混记。</li><li>B ❌ give out 意为「分发、用尽、发出」，与 didn&#39;t 连用读成「没有分发」，上下文无从照应。</li><li>C ✅ give up 意为「放弃」；下一句 I kept on sending my manuscripts 说明他没有放弃，前后逻辑一致（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ give away 意为「赠送、泄露」，与拒绝信和继续投稿的情节无关。干扰点：away 在 I didn&#39;t give away 里读起来通顺，但与后文逻辑冲突。</li></ul><p><strong>整句翻译</strong>：但我没有放弃，我继续把手稿寄给不同的出版社。</p><p><strong>词组</strong>：<code>give up</code> 放弃；<code>keep on doing</code> 继续做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-s2:0，比较两题的判断依据</p><p><strong>原文定位</strong>（策略四 · 固定搭配解题法 · 第2段 · 第2空所在句）：But I didn’t give <em><strong>2</strong></em>.</p></details><p><strong>I had finally achieved my dream ____ hard work and perseverance.</strong></p><ul><li>A. through</li><li>B. with</li><li>C. by</li><li>D. of</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（through）</strong> —— through hard work and perseverance 表示「通过努力和坚持」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ through 表示「凭借、通过（某种方式或手段）」，through hard work and perseverance 是固定搭配的状语（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ with 多表示「带有、用（工具）」，with hard work and perseverance 更像「伴随着努力」，读不出「靠努力实现」的凭借义。干扰点：with 也能译成「用」，容易通用化。</li><li>C ❌ by 表示方式时后面通常接动名词（by working hard），直接接抽象名词 hard work and perseverance 不合习惯。干扰点：只记「by 表方式」的公式。</li><li>D ❌ of 表所属，achieved my dream of hard work 会把「努力」读成梦想的内容，语义完全走偏。</li></ul><p><strong>整句翻译</strong>：我终于通过努力和坚持实现了自己的梦想。</p><p><strong>词组</strong>：<code>achieve one&#39;s dream</code> 实现梦想；<code>through hard work and perseverance</code> 通过努力与坚持</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:13，比较两题的判断依据</p><p><strong>原文定位</strong>（策略四 · 固定搭配解题法 · 第3段 · 第3空所在句）：I had finally achieved my dream <em><strong>3</strong></em> hard work and perseverance.</p></details><h3 id="策略五-·-逻辑语气解题法" tabindex="-1"><a class="header-anchor" href="#策略五-·-逻辑语气解题法"><span>策略五 · 逻辑语气解题法</span></a></h3><p>先了解全文<strong>人物、时间、地点</strong>等信息，再分析句间和段间关系。常见逻辑语气包括<strong>并列、递进、因果、转折和委婉</strong>；选项多为连词、副词或具有连词作用的短语。先读短文，再做完三空（课件未附答案，答案与解析为笔记整理补充）。</p><p>There are two main types of motivation: intrinsic and extrinsic. Intrinsic motivation comes from within oneself. It’s the kind of motivation that drives a person to do something <strong><em><strong>1</strong></em></strong> they enjoy the process or find it personally fulfilling. For example, an artist might paint because they love the act of creating and expressing themselves through colors and shapes.</p><p>Extrinsic motivation, <strong><em><strong>2</strong></em></strong>, comes from external factors. This could be rewards like money, praise, or recognition. A salesperson, for instance, might work hard to achieve high sales figures <strong><em><strong>3</strong></em></strong> they want to earn a big bonus.</p><p><strong>Intrinsic motivation comes from within oneself. It’s the kind of motivation that drives a person to do something ____ they enjoy the process or find it personally fulfilling.</strong></p><ul><li>A. because</li><li>B. although</li><li>C. unless</li><li>D. until</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（because）</strong> —— 前果后因：驱使人做事的原因是享受过程、获得满足，用 because。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后一分句 they enjoy the process or find it personally fulfilling 解释的是「驱使人去做」的原因，属前果后因，用 because（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ although 表让步，会把「享受过程」读成与「驱使人做事」相对立的条件，逻辑不通。干扰点：只凭「前后都是小句」就随手选连词。</li><li>C ❌ unless 表「除非」，等于说「除非享受过程才驱使人做事」，把原因误改成条件，且与上文对内在动机的定义冲突。</li><li>D ❌ until 表时间终点，要求前一分句是持续动作，「驱使人做某事」被读成「一直做某事直到他们享受过程」，语义荒谬。</li></ul><p><strong>整句翻译</strong>：这种动机驱使人去做某件事，因为他们享受这个过程，或觉得它让自己很有成就感。</p><p><strong>词组</strong>：<code>intrinsic motivation</code> 内在动机；<code>drive sb. to do sth.</code> 驱使某人做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-s3:2，比较两题的判断依据</p><p><strong>原文定位</strong>（策略五 · 逻辑语气解题法 · 第1段 · 第1空所在句）：It’s the kind of motivation that drives a person to do something <em><strong>1</strong></em> they enjoy the process or find it personally fulfilling.</p></details><p><strong>Extrinsic motivation, ____, comes from external factors.</strong></p><ul><li>A. in addition</li><li>B. on the other hand</li><li>C. as a result</li><li>D. in conclusion</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（on the other hand）</strong> —— 内在动机 vs 外在动机构成对照，用 on the other hand（另一方面）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in addition 表递进，等于说「此外，外在动机还来自外部」，但本段是与上段「内在动机」并列对照的另一种，不是补充。干扰点：看到两段结构相似就默认递进。</li><li>B ✅ 上文讲 intrinsic motivation 来自自身，本句讲 extrinsic motivation 来自外部，是两种动机的对照，用 on the other hand（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ as a result 表结果，会把「外在动机来自外部因素」读成上段内在动机造成的结果，逻辑倒置。</li><li>D ❌ in conclusion 表总结，用在段首会把这一段读成全文结论，后文还有例子和展开，位置不对。干扰点：把插入语误当成段落收尾信号。</li></ul><p><strong>整句翻译</strong>：而另一方面，外在动机来自外部因素。</p><p><strong>词组</strong>：<code>extrinsic motivation</code> 外在动机；<code>external factors</code> 外部因素</p><p><strong>对比自测</strong>：做完后对照 quiz-s3:2，比较两题的判断依据</p><p><strong>原文定位</strong>（策略五 · 逻辑语气解题法 · 第2段 · 第2空所在句）：Extrinsic motivation, <em><strong>2</strong></em>, comes from external factors.</p></details><p><strong>A salesperson, for instance, might work hard to achieve high sales figures ____ they want to earn a big bonus.</strong></p><ul><li>A. but</li><li>B. and</li><li>C. or</li><li>D. because</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（because）</strong> —— 前果后因：努力冲业绩的原因是想拿大额奖金，用 because。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ but 表转折，会把「想拿奖金」读成与「努力冲业绩」相反的结果，前后无法对立。干扰点：只记「but 表转折」不检查语义是否真能相反。</li><li>B ❌ and 表并列，会把「拿奖金」与「努力工作」并列为两个动作，读不出「为什么努力」的解释关系。</li><li>C ❌ or 表选择，等于说「努力工作，或者想拿奖金」，两句变成二选一，与举例说明外在动机的意图不符。</li><li>D ✅ 后一分句 they want to earn a big bonus 是努力工作（前果）的原因，属前果后因，用 because（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：例如，销售员努力工作以取得高销售额，因为他们想拿到一大笔奖金。</p><p><strong>词组</strong>：<code>for instance</code> 例如；<code>earn a big bonus</code> 挣到一大笔奖金</p><p><strong>对比自测</strong>：做完后对照 quiz-s3:0，比较两题的判断依据</p><p><strong>原文定位</strong>（策略五 · 逻辑语气解题法 · 第2段 · 第3空所在句）：A salesperson, for instance, might work hard to achieve high sales figures <em><strong>3</strong></em> they want to earn a big bonus.</p></details><h3 id="策略六-·-利用文化背景和生活常识" tabindex="-1"><a class="header-anchor" href="#策略六-·-利用文化背景和生活常识"><span>策略六 · 利用文化背景和生活常识</span></a></h3><p>完形填空以独立语篇命题，会交织各类常识和文化背景知识。解题时，语言知识以及<strong>英美国家文化背景和生活常识</strong>都可能发挥作用。</p><h3 id="策略七-·-对比结构与平行结构" tabindex="-1"><a class="header-anchor" href="#策略七-·-对比结构与平行结构"><span>策略七 · 对比结构与平行结构</span></a></h3><p><strong>对比结构</strong>把两种对立事物，或同一事物的两个不同方面，并列起来比较；<strong>平行结构</strong>由结构相同或相似、意义密切关联、语法一致的词或句子成串排列，形式整齐，内容联系紧密（课件未附答案，答案与解析为笔记整理补充）。</p><p>A pupil who can do his homework in a quiet and <strong>____</strong> room is in a much better position than a pupil who does his homework in a small, noisy room with the television on.</p><p><strong>A pupil who can do his homework in a quiet and ____ room is in a much better position than a pupil who does his homework in a small, noisy room with the television on.</strong></p><ul><li>A. furnished</li><li>B. expensive</li><li>C. comfortable</li><li>D. suitable</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（comfortable）</strong> —— comfortable 与 quiet 形成同向的平行描述，并与后面的 small, noisy 构成对比。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ furnished（配有家具的）描述房间是否带家具，与 quiet 的「环境质量」不同类，也无法与后面的 small, noisy 形成对立。干扰点：把「房间的属性」一律当作可用选项。</li><li>B ❌ expensive（昂贵的）说的是价格，与做作业效果无直接关系，且全文没有提成本。干扰点：把「好房间」默认等同于「好而贵」。</li><li>C ✅ comfortable 与 quiet 同向并列（都是有利于做作业的条件），并与后文 small, noisy 构成对比，平行与对照两重线索同时成立（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ suitable（合适的）是评价性形容词，只能泛泛说「合适」，读不出与 quiet 并列的具体环境条件，也与 noisy 形不成正反对照。干扰点：suitable 看上去最「安全」却是评价性空词。</li></ul><p><strong>整句翻译</strong>：能在安静而舒适的房间里做作业的学生，比在开着电视的小而嘈杂的房间里做作业的学生处境好得多。</p><p><strong>词组</strong>：<code>be in a much better position than</code> 比……处于有利得多的处境；<code>with the television on</code> 开着电视（with 复合结构）</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 第三部分 策略七 · 对比结构与平行结构 例句）：A pupil who can do his homework in a quiet and ____ room is in a much better position than a pupil who does his homework in a small, noisy room with the television on.</p></details><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 易错清单</p><ul><li><strong>目标</strong>：把本课高频易错点背下来并在做题时主动自检：不看全文、忽略首尾句、近义词凭中文选、逻辑词不回读、固定搭配拆开判断、忽略复现、漏查数与形式，以及被课件错页误导时如实标注而不推测。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>完形·复查与易错清单</code> <code>完形·词义辨析</code> <code>完形填空考情与命题特征</code></li></ul></div><h3 id="易错清单-·-小步学" tabindex="-1"><a class="header-anchor" href="#易错清单-·-小步学"><span>易错清单 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>完形填空：把空放回故事里</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>回填复核：答案放回原句后必须再查五件事</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：背出易错清单八条，并各举一个本课题目说明这条易错点是怎么踩到的。</p><div class="hint-container tip"><p class="hint-container-title">回填复核：答案放回原句后必须再查五件事</p><p><strong>句意</strong>：His works have been collected by a number of private collectors, museums and art galleries. 意思是「他的作品被许多私人收藏家、博物馆和美术馆收藏」。</p><p><strong>拆解</strong></p><ul><li>一查数：a number of 后接可数名词复数，主语 His works 是复数，have been 的形式正确</li><li>二查时态：本句讲至今已有的结果，用现在完成时被动 have been collected 正确</li><li>三查语态：作品是被收藏的，必须用被动，不能写 have collected</li><li>四查搭配：collect 与 collectors/museums/galleries 的语义场完全对应</li><li>五查非谓语：若空处是 leaving 这类形式，还要回头确认它作的是状语而不是谓语</li></ul><p><strong>语法</strong>：易错清单八条：只看单句不看全文；忽略首尾句；近义词凭中文选；逻辑词不回读；固定搭配拆开判断；忽略跨句跨段的复现；漏查数与形式（主谓一致、单复数、时态、语态、非谓语）；被课件错页误导。前七条是判断习惯问题，最后一条是材料问题——练习十一第 1–5 空、练习十七第 6–15 空的选项在源课件里错页缺失，本课只收录选项完整的题目，缺失部分如实标注课件勾选词，不以推测选项冒充原文。</p><p>正例：His works have been collected by a number of private collectors.（被动 + 现在完成 + 复数一致）；We think it necessary to protect the art and pass it down to future generations.（pass down 整体搭配） 反例：His works have collected by ... ×（漏了 been，语态与形式都错）；We think it necessary to protect the art and throw it down to future generations. ×（搭配被拆开单看 down 的中文「下」）；练习十一第 1–5 空自造四个选项来凑齐解析。×（源课件选项缺失，应如实标注而不补造） 适用边界：复核不是重做一遍：它的对象是「已经填进去的答案」，只查形式与搭配是否同时成立。若复核时发现整段逻辑都不通，说明问题出在第一步通读，应回到全篇主旨重判，而不是逐空修补。</p><p><strong>口诀</strong>：回填五查：数、时、态、配、形 —— 五个字对应五件事：单复数、时态、语态、搭配、非谓语形式。做完一篇最后花两分钟过一遍，能拦下大量「词义选对、形式写错」的失分。</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>只看单句，不看全文</strong>：语法正确不等于语篇正确；先确认人物、事件、情感方向和文章主旨</p></li><li><p><strong>忽略首尾句</strong>：首句常提示体裁和主题，末句常揭示结局或作者态度</p></li><li><p><strong>近义词凭中文选</strong>：要比较搭配、语义色彩和使用对象，如 learn from、pay respects to、make a U-turn</p></li><li><p><strong>逻辑词不回读</strong>：and/but/so/because 必须同时满足前后语义关系</p></li><li><p><strong>固定搭配拆开判断</strong>：看到动词或介词空，要把前后组成整体，如 give up、pass down、depend on、look for</p></li><li><p><strong>忽略复现</strong>：原词、同义词和反义词可能跨句甚至跨段出现</p></li><li><p><strong>漏查数与时态</strong>：答案放回原句后，检查主谓一致、单复数、时态、语态和非谓语形式</p></li><li><p><strong>被课件错页误导</strong>：练习十一 p28、练习十七 p43–44 的选项错页，以本课说明为准，不把重复选项当作对应题选项</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 课堂练习</p><ul><li><strong>目标</strong>：把七条策略落成可执行的三步动作（定位 → 比对 → 排除），在 2025 年真题与题海 20 篇共 310 题上练熟，做到每题都能说出「答案凭什么」。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>完形·名词词义辨析</code> <code>完形·动词词义辨析</code> <code>完形·形容词与副词辨析</code> <code>完形·代词辨析</code> <code>语境推理法</code> <code>完形·复查与易错清单</code></li></ul></div><h3 id="课堂练习-·-小步学" tabindex="-1"><a class="header-anchor" href="#课堂练习-·-小步学"><span>课堂练习 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>完形填空：把空放回故事里</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>篇章三步法：定位 → 比对 → 排除</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：挑一个自己最没把握的空，按「定位 → 比对 → 排除」三步说出理由，再说清另外三个选项各自错在哪。</p><div class="hint-container tip"><p class="hint-container-title">篇章三步法：定位 → 比对 → 排除</p><p><strong>句意</strong>：The small cat would run away when the trip was over, leaving their house and returning here some day. 意思是「旅行结束后小猫会跑开，离开它们的房子，日后再回到这里」。</p><p><strong>拆解</strong></p><ul><li>定位：先看空处所处结构 —— ____ their house and returning here some day，空后紧跟 and returning，说明空处与 returning 是并列成分</li><li>比对：and 要求形式一致，returning 是现在分词，空处也必须是 -ing；语义上要与 leave their house 连成「离开—再回来」的一条线</li><li>排除：leaves（第三人称单数谓语，一句双谓语且时态不符）、to leave（表目的，与 returning 无法并列）、left（过去式谓语），只有 leaving 两项都成立</li><li>同一套动作可复制到名词空、动词空、形容词空：先定位空在句中承担什么成分，再比对上下文与选项的形式和语义，最后逐项排除</li></ul><p><strong>语法</strong>：篇章三步法把七条策略收成一条可操作流程。第一步定位：判断空处是谓语、非谓语、从句引导词、介词还是修饰语，并圈出空所在句与前后句的连词、指示词；第二步比对：用复现、搭配、逻辑与平行结构比对语义与形式；第三步排除：逐项检查干扰点（时态、单复数、搭配、语义方向），保留唯一同时满足形式与语义的选项。</p><ol><li><strong>定位</strong> 判断空处成分 + 圈出上下句线索词</li><li><strong>比对</strong> 用复现/搭配/逻辑/平行结构比对语义与形式</li><li><strong>排除</strong> 逐项检查时态、单复数、搭配与语义方向的干扰点</li></ol><p>正例：The small cat would run away ... leaving their house and returning here some day.（and 并列 → -ing）；are commonly seen in the artworks（下文 seeing 复现 → 被动形式）；a good way to escape the cold weather（way + to do 固定搭配） 反例：The small cat would run away ... left their house and returning here ×（一句双谓语，且与 returning 形式不一致）；His works have been broken by a number of private collectors ×（形式正确但语义与「收藏」不符） 适用边界：三步法适用于所有篇章题，但重点随空的性质移动：形式空（非谓语、语态）主要靠第二步的形式比对，实词空（名词、动词、形容词）主要靠语义与搭配比对，逻辑空则先定关系再选词。若题干（不含篇章）本身就是孤立的单句，第一步没有上下文可圈，直接跳到形式与搭配判断。</p><p><strong>口诀</strong>：定位在前，比对在中，排除在末；形式与语义两条腿都要站住 —— 排除时不要只盯一个维度：形式对而语义错（broken）、语义对而形式错（left）都是常见陷阱，两条腿都站稳才落笔。</p></div><p>以下 2025 年真题 + 题海 20 篇全部取自课件原题（共 <strong>315 空</strong>）：答案为课件原答案；课件未附解析，题目解析为笔记整理补充口径。练习十一、练习十七源课件存在选项错页，已在对应位置如实说明，不以推测选项冒充课件原文。</p><h3 id="_2025-年真题-·-完形-21–35" tabindex="-1"><a class="header-anchor" href="#_2025-年真题-·-完形-21–35"><span>2025 年真题 · 完形 21–35</span></a></h3><p>In a small town, there was a small cat that was very <strong><strong>21</strong></strong> about the outside world. It often played and explored in the backyard. In November, the <strong><strong>22</strong></strong> fell heavily, blanketing the town in white. It was very cold outside, but this small cat still visited the backyard. And it <strong><strong>23</strong></strong> in the snow to find a warmer place.</p><p>As usual, this small cat went out to play but didn’t return for dinner. Its owner was <strong><strong>24</strong></strong>, searching everywhere but finding no sign of it. Soon the long winter passed. And on one morning of April, the small cat came back, looking happy and <strong><strong>25</strong></strong>. It seemed that the small cat had never been <strong><strong>26</strong></strong> in the past months.</p><p>The same thing happened again. The small cat disappeared when the cold November arrived, and <strong><strong>27</strong></strong> next spring. The owner was puzzled, and wanted to figure out the <strong><strong>28</strong></strong>. Therefore, he decided to <strong><strong>29</strong></strong> the cat when it went out in another November.</p><p>Finally, the owner found that the small cat’s destination was a nice house. There lived a couple who greeted them warmly. The couple were glad to <strong><strong>30</strong></strong> all this to the owner. They would travel to the south every winter, and the small cat began to travel with them two <strong><strong>31</strong></strong> ago. The small cat would <strong><strong>32</strong></strong> when the trip was over, <strong><strong>33</strong></strong> their house and returning here some day.</p><p>Hearing this, the owner realized that this small cat was <strong><strong>34</strong></strong>. That’s because it was a good <strong><strong>35</strong></strong> to escape the cold weather.</p><p><strong>【第21空】In a small town, there was a small cat that was very ____ about the outside world.</strong></p><ul><li>A. eager</li><li>B. curious</li><li>C. afraid</li><li>D. concerned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（curious）</strong> —— 形容词辨析。后文提到小猫经常在后院 explored（探索），说明它对世界充满好奇；eager 急切的、afraid 害怕的、concerned 担忧的。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ eager（急切的）表「急于得到」，后面一般接 for/about 且强调迫切，与「对外面世界感兴趣」这一持续状态不符。干扰点：中文里「渴望了解」也说得通。</li><li>B ✅ be curious about 是固定搭配；下一句 It often played and explored in the backyard 用「探索后院」具体说明好奇（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ afraid 表害怕，若填 afraid，后文小猫天天到后院探索的情节就自相矛盾。干扰点：只按「小猫胆小」的刻板印象选词。</li><li>D ❌ concerned about 是「为……担忧」，主语通常是关心某事的人，与小猫主动探索的形象相反。干扰点：把 concerned 与 curious 都归为「在意」而混淆。</li></ul><p><strong>整句翻译</strong>：在一个小镇上，有一只对外面的世界非常好奇的小猫。</p><p><strong>词组</strong>：<code>be curious about</code> 对……好奇；<code>the outside world</code> 外面的世界</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:13，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第1段 · 第21空所在句）：In a small town, there was a small cat that was very <strong>21</strong> about the outside world.</p></details><p><strong>【第22空】In November, the ____ fell heavily, blanketing the town in white.</strong></p><ul><li>A. cloud</li><li>B. rain</li><li>C. fog</li><li>D. snow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（snow）</strong> —— 名词辨析。小镇被白色覆盖且十一月寒冷，应为 snow；cloud 云、rain 雨、fog 雾。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cloud 与 fell heavily 不搭：云不会「落下」，也没有「遮盖成白色」的效果。干扰点：把「天上有的东西」都当成天气名词。</li><li>B ❌ rain 虽可 fall heavily，但雨不会让小镇变白，且下文反复出现 in the snow，答案已被复现锁定。干扰点：只按「下得大」这一搭配条件作答。</li><li>C ❌ fog（雾）用 come down/roll in 描述，不用 fall heavily，且雾是灰色不是白色。</li><li>D ✅ 十一月 + blanketing the town in white，加上后文 in the snow 的原词复现，只能是 snow（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：十一月，雪下得很大，给小镇盖上一层白色。</p><p><strong>词组</strong>：<code>fall heavily</code> （雨雪）下得很大；<code>blanket the town in white</code> 给小镇盖上白色（覆盖）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:2，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第1段 · 第22空所在句）：In November, the <strong>22</strong> fell heavily, blanketing the town in white.</p></details><p><strong>【第23空】And it ____ in the snow to find a warmer place.</strong></p><ul><li>A. dug</li><li>B. covered</li><li>C. slept</li><li>D. put</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（dug）</strong> —— 动词辨析。小猫要在雪中找暖和的地方，需要 dug（挖洞）躲避寒冷。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ dig in the snow 意为「在雪里挖」，与后面的 to find a warmer place（找更暖和的地方）构成「挖洞避寒」的完整动作链（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ covered 后要接宾语（覆雪的东西），而 it covered in the snow 结构残缺，且无法引出「找暖和处」的目的。干扰点：只检查词义是否与「雪」相关。</li><li>C ❌ slept in the snow 说得通，但「睡在雪里」与后文 to find a warmer place 的目的冲突：已经睡下就不必再找。干扰点：语法与搭配都成立，忽略后置目的状语。</li><li>D ❌ put 是及物动词，it put in the snow 少了宾语，句子不完整。</li></ul><p><strong>整句翻译</strong>：它还在雪里挖洞，想找一个更暖和的地方。</p><p><strong>词组</strong>：<code>in the snow</code> 在雪里；<code>a warmer place</code> 更暖和的地方</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:8，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第1段 · 第23空所在句）：And it <strong>23</strong> in the snow to find a warmer place.</p></details><p><strong>【第24空】Its owner was ____, searching everywhere but finding no sign of it.</strong></p><ul><li>A. worried</li><li>B. disappointed</li><li>C. tired</li><li>D. delighted</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（worried）</strong> —— 形容词辨析。小猫未归，主人自然是 worried（担心的）。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 小猫没有回来吃晚饭，主人 searching everywhere 却找不到，情感只能是 worried（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ disappointed（失望的）预设「本来期待某结果而落空」，而此处是宠物失踪的担忧，紧迫度更强。干扰点：把「没等到」读成「失望」。</li><li>C ❌ tired（累的）与 searching everywhere 的因果方向相反：累是找的结果，不能解释为什么去找。干扰点：把结果当成原因。</li><li>D ❌ delighted（高兴的）与 searching everywhere but finding no sign 的情感完全对立。干扰点：只看到 returned 相关词就选正向情绪。</li></ul><p><strong>整句翻译</strong>：它的主人很担心，到处寻找却没有发现它的踪迹。</p><p><strong>词组</strong>：<code>as usual</code> 像往常一样；<code>find no sign of it</code> 找不到它的踪迹</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:4，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第2段 · 第24空所在句）：Its owner was <strong>24</strong>, searching everywhere but finding no sign of it.</p></details><p><strong>【第25空】On one morning of April, the small cat came back, looking happy and ____.</strong></p><ul><li>A. lazy</li><li>B. healthy</li><li>C. lonely</li><li>D. wealthy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（healthy）</strong> —— 形容词辨析。小猫归来时状态良好，且后文提到它冬季去南方避寒，故为 healthy。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ lazy 与 happy 语义不搭：一只刚经历长途旅行回来的猫被描述成「懒」没有依据。干扰点：把「猫」与「懒」的印象挂钩。</li><li>B ✅ happy and healthy 是并列同向的褒义描述，且后文 It seemed that the small cat had never been lost 说明它状态良好（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ lonely（孤单的）与 happy 语义相反，and 连接的并列成分不能一褒一贬。干扰点：忽略并列连词的语义同向要求。</li><li>D ❌ wealthy（富有的）用于形容人的财产，用来描述猫的归家状态不合语境，全文也没有涉及财富。干扰点：被 -y 结尾的形容词形式吸引。</li></ul><p><strong>整句翻译</strong>：四月的一天早晨，小猫回来了，看起来开心又健康。</p><p><strong>词组</strong>：<code>come back</code> 回来；<code>looking happy and ...</code> 看起来又……又……（现在分词作状语）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:3，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第2段 · 第25空所在句）：And on one morning of April, the small cat came back, looking happy and <strong>25</strong>.</p></details><p><strong>【第26空】It seemed that the small cat had never been ____ in the past months.</strong></p><ul><li>A. lost</li><li>B. ignored</li><li>C. explored</li><li>D. trained</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（lost）</strong> —— 动词辨析。小猫其实有固定去处，并未 lost（走失）。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ had never been lost 与后文揭晓的真相（它有固定去处、随夫妇去南方）一致：它并没有走失（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ be ignored 意为「被忽视」，与「在外几个月不回家」这件事无关，且无人忽视它——主人一直在找。干扰点：把「没回家」误读成「被冷落」。</li><li>C ❌ explored 是不及物用法居多的动词，且 the cat had never been explored 会把猫变成被探索的对象，语义荒谬。干扰点：被上文 explored in the backyard 的形式干扰。</li><li>D ❌ trained（被训练）需要有人训练它，全文没有任何训练情节。干扰点：把「有本事」误解为「受过训练」。</li></ul><p><strong>整句翻译</strong>：看来这只小猫在过去几个月里从未走失。</p><p><strong>词组</strong>：<code>It seemed that ...</code> 似乎……；<code>in the past months</code> 在过去几个月里</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:6，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第2段 · 第26空所在句）：It seemed that the small cat had never been <strong>26</strong> in the past months.</p></details><p><strong>【第27空】The small cat disappeared when the cold November arrived, and ____ next spring.</strong></p><ul><li>A. waited</li><li>B. reappeared</li><li>C. continued</li><li>D. witnessed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（reappeared）</strong> —— 动词辨析。小猫每年冬季消失、春季 reappeared（再次出现）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ waited 后需要地点或时间状语说明「等待什么」，且与前半句 disappeared 构不成「消失—重现」的对照。干扰点：只按「小猫会在春天怎样」随意想象。</li><li>B ✅ reappear 与前面的 disappeared 构成反义复现，且主语共用 The small cat，语义为「次年春天又出现」（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ continued（继续）后需要宾语或 to do 说明继续什么，missing complement 使句子不完整。干扰点：把 continued 当成「继续存在」的万能词。</li><li>D ❌ witnessed 是及物动词，主语 The small cat witnessed next spring 语义不通（小猫不能「见证」一个季节）。</li></ul><p><strong>整句翻译</strong>：寒冷的十一月一到，小猫就消失了，次年春天又重新出现。</p><p><strong>词组</strong>：<code>disappear ... and reappear</code> 消失又重现（反义对照）；<code>next spring</code> 第二年春天</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:5，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第3段 · 第27空所在句）：The small cat disappeared when the cold November arrived, and <strong>27</strong> next spring.</p></details><p><strong>【第28空】The owner was puzzled, and wanted to figure out the ____.</strong></p><ul><li>A. moment</li><li>B. method</li><li>C. mystery</li><li>D. model</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（mystery）</strong> —— 名词辨析。主人想弄清小猫消失的 mystery（谜团）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ moment（时刻）与 figure out 搭配后读成「弄清那个时刻」，与主人想解开「小猫为什么消失」的疑问无关。干扰点：四个选项首字母相同，只靠词形记忆选词。</li><li>B ❌ method（方法）指做事的手段，主人困惑的对象不是「怎么做」而是「怎么回事」。干扰点：把「科学家式疑问」套用到情节推理上。</li><li>C ✅ 与前面 was puzzled 呼应，主人想弄清的是「小猫消失又出现的谜团」，figure out the mystery 搭配成立（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ model（模型）与全文情节毫无关联，且 the model 特指不成立。干扰点：被同首字母 m 的形式相似误导。</li></ul><p><strong>整句翻译</strong>：主人很困惑，想弄清这个谜团。</p><p><strong>词组</strong>：<code>figure out</code> 弄明白、搞清楚；<code>be puzzled</code> 感到困惑</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:8，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第3段 · 第28空所在句）：The owner was puzzled, and wanted to figure out the <strong>28</strong>.</p></details><p><strong>【第29空】Therefore, he decided to ____ the cat when it went out in another November.</strong></p><ul><li>A. check</li><li>B. invite</li><li>C. answer</li><li>D. follow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（follow）</strong> —— 动词辨析。主人决定 follow（跟踪）小猫以查明真相。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ check the cat 是「检查猫」，无法解释后文「发现小猫的目的地是一所漂亮的房子」。干扰点：把「查明真相」简化为 check。</li><li>B ❌ invite the cat 是「邀请猫」，猫是被跟踪的对象而非被邀请者，与下文情节矛盾。</li><li>C ❌ answer the cat 语义不成立：没有需要回答的对象，也读不出「跟踪侦查」的动作。</li><li>D ✅ 后文 Finally, the owner found that the small cat&#39;s destination was a nice house 说明主人是一路跟着它才找到目的地的（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：因此，又一个十一月它出门时，他决定跟着它。</p><p><strong>词组</strong>：<code>decide to do sth.</code> 决定做某事；<code>go out</code> 外出</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:7，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第3段 · 第29空所在句）：Therefore, he decided to <strong>29</strong> the cat when it went out in another November.</p></details><p><strong>【第30空】The couple were glad to ____ all this to the owner.</strong></p><ul><li>A. persuade</li><li>B. explain</li><li>C. judge</li><li>D. appreciate</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（explain）</strong> —— 动词辨析。夫妇向主人 explain（解释）真相。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ persuade sb. to do 才是「说服」；persuade all this to the owner 的结构与语义都不成立。干扰点：把「说了很多」误当作「说服」。</li><li>B ✅ explain sth. to sb. 是固定搭配；后文正是夫妇把「每年冬天去南方、两年前开始带上小猫」的原因讲给主人听（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ judge（判断）后面接 all this 会读成「评判这一切」，与后文揭晓事实真相的动作不符。</li><li>D ❌ appreciate（感激、欣赏）不能带双宾语，也不表示「把情况讲清楚」。干扰点：把夫妇的热情误读成「感谢」。</li></ul><p><strong>整句翻译</strong>：夫妇二人很乐意向主人解释这一切。</p><p><strong>词组</strong>：<code>be glad to do sth.</code> 乐意做某事；<code>explain sth. to sb.</code> 向某人解释某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:12，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第4段 · 第30空所在句）：The couple were glad to <strong>30</strong> all this to the owner.</p></details><p><strong>【第31空】They would travel to the south every winter, and the small cat began to travel with them two ____ ago.</strong></p><ul><li>A. months</li><li>B. days</li><li>C. decades</li><li>D. years</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（years）</strong> —— 名词辨析。小猫已连续「两年」随夫妇去南方。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Every winter（每年一次）这一频率与 two months ago 冲突：若只有两个月，不可能已形成「每年」的规律。干扰点：只看 two ____ ago 的数量词搭配。</li><li>B ❌ two days ago 时间太短，与上文 The same thing happened again（这件事反复发生）以及每年南下的规律不符。</li><li>C ❌ decades（几十年）与下文 it was a good way to escape the cold weather 中「刚形成的习惯」以及前文主人第一次发现的时间跨度不匹配。干扰点：把「长期习惯」夸张成几十年。</li><li>D ✅ 前文说同样的情形一再发生（至少观察到冬季消失、次年春天回来），two years ago 是唯一与「每年一次 + 开始带上小猫」都相容的时间（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：它们每年冬天都会去南方旅行，而小猫两年前开始跟它们一起出行。</p><p><strong>词组</strong>：<code>travel to the south</code> 去南方旅行；<code>two years ago</code> 两年前</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:6，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第4段 · 第31空所在句）：They would travel to the south every winter, and the small cat began to travel with them two <strong>31</strong> ago.</p></details><p><strong>【第32空】The small cat would ____ when the trip was over,</strong></p><ul><li>A. take away</li><li>B. put away</li><li>C. run away</li><li>D. give away</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（run away）</strong> —— 短语辨析。旅行结束后小猫会 run away（跑开）回原主人家；take away 带走、put away 收好、give away 赠送。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take away 是「带走（某物）」，主语是物时须接宾语，The small cat would take away 结构不完整。干扰点：away 与后面的 leaving、returning 一起读很顺。</li><li>B ❌ put away 意为「收好、收起来」，主语一般是人把东西收进抽屉之类的地方，小猫自己不构成「把什么收好」。干扰点：只记 away 的中文「离开」义。</li><li>C ✅ run away（跑开）后接 leaving their house and returning here some day，正好描述小猫离开夫妇家、日后再回来（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ give away 意为「赠送、泄露」，与小猫自行离开、日后回来的情节不符。干扰点：被前文主人「要弄清谜团」的「给答案」语感带偏。</li></ul><p><strong>整句翻译</strong>：旅行结束后，小猫就会跑开，离开它们的房子，日后再回到这里。</p><p><strong>词组</strong>：<code>run away</code> 跑开、逃走；<code>return here some day</code> 日后回到这里</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:12，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第4段 · 第32空所在句）：The small cat would <strong>32</strong> when the trip was over, <strong>33</strong> their house and returning here some day.</p></details><p><strong>【第33空】The small cat would run away when the trip was over, ____ their house and returning here some day.</strong></p><ul><li>A. leaves</li><li>B. to leave</li><li>C. left</li><li>D. leaving</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（leaving）</strong> —— 非谓语动词。现在分词 leaving 作伴随状语，与 returning 并列。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ leaves 是第三人称单数谓语，但前面 would run away 已是谓语，没有连词不允许再出一个谓语；且时态也不一致。干扰点：只按「主语是第三人称」配动词形式。</li><li>B ❌ to leave 表目的或将来，会把「离开房子」读成「为了离开房子」，与后面的 and returning 也构不成并列。干扰点：把不定式当成万能结构。</li><li>C ❌ left 是过去式谓语，同样造成一句双谓语，且与 returning 形式不一致。</li><li>D ✅ 空后 and returning 已经给出现成分词形式，说明这里是伴随状语；leaving their house and returning here some day 由 leaving 与 returning 并列（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：旅行结束时，小猫会跑开，离开它们的房子，日后再回到这里。</p><p><strong>词组</strong>：<code>leaving their house</code> 离开它们的房子（现在分词作伴随状语）；<code>and returning here</code> 并回到这里（与 leaving 并列）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:11，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第4段 · 第33空所在句）：The small cat would <strong>32</strong> when the trip was over, <strong>33</strong> their house and returning here some day.</p></details><p><strong>【第34空】Hearing this, the owner realized that this small cat was ____.</strong></p><ul><li>A. wild</li><li>B. careless</li><li>C. smart</li><li>D. free</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（smart）</strong> —— 形容词辨析。小猫主动选择避寒方式，体现 smart（聪明的）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wild（野生的）描述动物是否被驯化，小猫有主人、会回家，显然不是野生，且无法解释「会随人南下避寒」这一本事。干扰点：把「能自己远行」读成「野性」。</li><li>B ❌ careless（粗心的）与「精于安排过冬」恰恰相反：它是计划周全才搭上夫妇的车去南方。干扰点：把「不告而别」误读成粗心。</li><li>C ✅ 下一句那是个躲避寒冷的好办法，说明它主动做了对生存有利的选择，故为 smart（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ free（自由的）只说明没有约束，读不出「有头脑、会安排」的评价，与后句 because 引出的原因不匹配。</li></ul><p><strong>整句翻译</strong>：听到这些，主人意识到这只小猫很聪明。</p><p><strong>词组</strong>：<code>Hearing this</code> 听到这些（现在分词作状语）；<code>escape the cold weather</code> 躲避寒冷天气</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:14，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第5段 · 第34空所在句）：Hearing this, the owner realized that this small cat was <strong>34</strong>.</p></details><p><strong>【第35空】That’s because it was a good ____ to escape the cold weather.</strong></p><ul><li>A. way</li><li>B. action</li><li>C. secret</li><li>D. decision</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（way）</strong> —— 名词辨析。避寒是一种 way（方式）。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 空后是不定式 to escape the cold weather，a good way to do sth. 是固定搭配，与上句 smart 的评价正好接上（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ action 后一般接 of doing 或直接说 take action，a good action to escape 不成立。干扰点：把「做法」一律等同于 action。</li><li>C ❌ secret（秘密）与上下文冲突：这件事已被夫妇解释清楚、主人已经明白，不再是秘密。</li><li>D ❌ decision（决定）后接不定式虽可（a decision to do），但它指「一次决定」，无法概括「每年冬天南下的做法」。干扰点：把「一整套做法」误当作单次决定。</li></ul><p><strong>整句翻译</strong>：那是因为这是一种躲避寒冷天气的好办法。</p><p><strong>词组</strong>：<code>That’s because ...</code> 那是因为……；<code>a good way to do sth.</code> 做某事的好办法</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:13，比较两题的判断依据</p><p><strong>原文定位</strong>（2025 年真题 · 完形 21–35 · 第5段 · 第35空所在句）：That’s because it was a good <strong>35</strong> to escape the cold weather.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>在一座小镇里，有一只小猫对外面的世界非常好奇。它经常在后院玩耍和探索。十一月，大雪纷飞，给小镇盖上了一层白色。外面很冷，但小猫仍会到后院去；它还在雪里挖洞，寻找更暖和的地方。</p><p>像往常一样，小猫出去玩，却没有回来吃晚饭。主人非常担心，到处寻找也没有发现它的踪迹。漫长的冬天很快过去。四月的一天早晨，小猫回来了，看起来开心而健康，仿佛过去几个月从未走失过。</p><p>同样的事情再次发生：寒冷的十一月一到，小猫便消失了，次年春天又重新出现。主人很困惑，想弄清这个谜团。因此，又一个十一月小猫外出时，他决定跟着它。</p><p>最后，主人发现小猫的目的地是一所漂亮的房子。那里住着一对热情迎接他们的夫妇。夫妇二人很乐意向主人解释这一切：他们每年冬天都会去南方旅行，而小猫两年前开始跟他们同行。旅程结束后，小猫会跑开，离开他们的房子，日后再回到这里。</p><p>听完这些，主人意识到这只小猫很聪明，因为这是一种躲避寒冷天气的好办法。</p></details><h3 id="练习一-·-山西木雕" tabindex="-1"><a class="header-anchor" href="#练习一-·-山西木雕"><span>练习一 · 山西木雕</span></a></h3><p>A piece of wood can tell the stories of Shanxi—its history, culture, scenes and local life, Ye Yaoliang said at a recent exhibition in the provincial capital of Taiyuan. Ye is a famous woodcarving（木雕）<strong><em><strong>1</strong></em></strong>.</p><p>According to Ye, Shanxi’s woodcarving has a history of nearly 2,000 years. For thousands of years, the art has been a way to show the local culture, with its <strong><em><strong>2</strong></em></strong> covering historical legends（传说）and landscapes（乡村风景画）. Humans, mountains, rivers, flowers, birds and animals are commonly <strong><em><strong>3</strong></em></strong> in the artworks.</p><p>“We are seeing famous attractions in Shanxi on the woodcarvings <strong><em><strong>4</strong></em></strong> here, like the Yellow River, the Great Wall and the Taihang Mountains, as well as the stories and lives related to these <strong><em><strong>5</strong></em></strong>,” Ye said.</p><p>The art in Shanxi reached its top during the Ming and Qing dynasties. Shanxi traders are said to have controlled <strong><em><strong>6</strong></em></strong> in North China during those periods. They widely used woodcarvings to decorate their houses, <strong><em><strong>7</strong></em></strong> the popularity of the art.</p><p>He said he once saw a huge carved-frame（有雕花的框架）mirror in the Grand Courtyard of the Qiao Family—a <strong><em><strong>8</strong></em></strong> house of Shanxi traders—in Qixian County. With the patterns of a moon and a rhinoceros（犀牛）, Ye said this should be considered among the most <strong><em><strong>9</strong></em></strong> woodcarving works in the world.</p><p>“But nowadays, the art has gradually faded out of local life and is <strong><em><strong>10</strong></em></strong> to death,” Ye said. “We think it necessary to protect the art and <strong><em><strong>11</strong></em></strong> it down to future generations.” Ye said there are different styles and characteristics of woodcarving arts across different areas of China.</p><p>Ye started to learn the art from a master in Zhejiang Province <strong><em><strong>12</strong></em></strong> he was 16. After finishing his three-year learning, he returned to Shanxi, continued to <strong><em><strong>13</strong></em></strong> local artists and began to practice in this trade.</p><p>Because of his understanding of the art, Ye has <strong><em><strong>14</strong></em></strong> many masterpieces over the past twenty years. His works have been <strong><em><strong>15</strong></em></strong> by a number of private collectors, museums and art galleries.</p><p><strong>Ye is a famous woodcarving（木雕）____.</strong></p><ul><li>A. teacher</li><li>B. trader</li><li>C. artist</li><li>D. supplier</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（artist）</strong> —— 他在展览上谈木雕艺术，是著名木雕艺术家 artist。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ teacher（教师）与下文「学艺、创作杰作、作品被收藏」的艺术家身份不符，全文也没有他教学生的情节。干扰点：看到 continued to learn from local artists 就误判身份。</li><li>B ❌ trader（商人）在文中指 Shanxi traders（晋商），是过去的群体，不是叶耀亮本人。干扰点：把文中出现过的同词性名词直接搬来。</li><li>C ✅ 首段说他能用一块木头讲述山西的故事，后文提到他创作大量杰作、作品被博物馆收藏，身份是木雕艺术家（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ supplier（供货商）只供货不创作，与他想保护、传承这门艺术的口吻不符。干扰点：把「从事木材行业」泛化成「木雕从业者」。</li></ul><p><strong>整句翻译</strong>：叶耀亮是一位著名的木雕艺术家。</p><p><strong>词组</strong>：<code>a woodcarving artist</code> 木雕艺术家；<code>at a recent exhibition</code> 在最近的一次展览上</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第1段 · 第1空所在句）：Ye is a famous woodcarving（木雕）<em><strong>1</strong></em>.</p></details><p><strong>The art has been a way to show the local culture, with its ____ covering historical legends and landscapes.</strong></p><ul><li>A. themes</li><li>B. methods</li><li>C. skills</li><li>D. steps</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（themes）</strong> —— 与历史传说、乡村风景画并列的是作品的「题材」themes。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ covering 的宾语是 historical legends and landscapes，能被「涵盖」的是作品的题材 themes（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ methods（方法）指创作手法，不能说「方法涵盖历史传说」。干扰点：method 与 way 同义，而前面刚好有 a way to。此处 a way 指的是功能，不是 content。</li><li>C ❌ skills（技艺）同样不能被「涵盖传说与风景」，把内容说成技术。干扰点：把木雕的「手艺」当成作品内容。</li><li>D ❌ steps（步骤）指工序，与传说、风景这类内容完全不是同一范畴。</li></ul><p><strong>整句翻译</strong>：数千年来，这门艺术一直是展现当地文化的一种方式，其题材涵盖历史传说和乡村风景。</p><p><strong>词组</strong>：<code>be a way to do sth.</code> 是做某事的方式；<code>historical legends</code> 历史传说</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第2段 · 第2空所在句）：For thousands of years, the art has been a way to show the local culture, with its <em><strong>2</strong></em> covering historical legends（传说）and landscapes（乡村风景画）.</p></details><p><strong>Humans, mountains, rivers, flowers, birds and animals are commonly ____ in the artworks.</strong></p><ul><li>A. sold</li><li>B. taken</li><li>C. left</li><li>D. seen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（seen）</strong> —— 人物山水花鸟是木雕作品中常见的「形象」，即能被看见 seen。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ sold（被出售）的主语应是作品本身，不能是作品里的山水花鸟；且下一句明确说这些形象是在木雕上「被看到」的。干扰点：只按「艺术品会被买卖」的常识选词。</li><li>B ❌ taken 若要成立需 take 的固定搭配（are taken as ...），此处没有 as，语义不成立。</li><li>C ❌ left（被留下）与「常见形象」的意思无关，且 leave 的主语通常是留下东西的人。</li><li>D ✅ 下文 We are seeing famous attractions ... on the woodcarvings 用 see 直接回应，are commonly seen 表示「在作品中很常见」（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：人物、山川、河流、花鸟和动物在作品中都很常见。</p><p><strong>词组</strong>：<code>be commonly seen</code> 很常见（常被看见）；<code>in the artworks</code> 在作品中</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第2段 · 第3空所在句）：Humans, mountains, rivers, flowers, birds and animals are commonly <em><strong>3</strong></em> in the artworks.</p></details><p><strong>We are seeing famous attractions in Shanxi on the woodcarvings ____ here, like the Yellow River, the Great Wall and the Taihang Mountains.</strong></p><ul><li>A. showed</li><li>B. painted</li><li>C. drawn</li><li>D. written</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（showed）</strong> —— 这里展出的木雕用 showed（展出），与 exhibition 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 上下文是 a recent exhibition，展出的木雕用 showed here（此处作后置定语，等于 which are showed/shown here）（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ painted 只说明「被涂画」，而主语是木雕作品本身，不是画作，且全文强调雕刻而非绘画。干扰点：把「木雕有画面」误解成「画上去」。</li><li>C ❌ drawn 是「被画」，与 woodcarving（木雕）这一工艺属性冲突。</li><li>D ❌ written（被写）与木雕的视觉艺术属性不符。</li></ul><p><strong>整句翻译</strong>：叶耀亮说：「在这里展出的木雕上，我们能看到山西的著名景点，比如黄河、长城和太行山。」</p><p><strong>词组</strong>：<code>famous attractions</code> 著名景点；<code>the woodcarvings showed here</code> 这里展出的木雕</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第3段 · 第4空所在句）：“We are seeing famous attractions in Shanxi on the woodcarvings <em><strong>4</strong></em> here, like the Yellow River, the Great Wall and the Taihang Mountains, as well as the stories and lives related to these <em><strong>5</strong></em>,” Ye said.</p></details><p><strong>…as well as the stories and lives related to these ____.</strong></p><ul><li>A. stories</li><li>B. places</li><li>C. experiences</li><li>D. problems</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（places）</strong> —— 黄河、长城、太行山都是「地点」places。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ these ____ 若填 stories，会读成「与这些故事有关的故事」，同语反复，逻辑上绕圈。干扰点：把前面刚出现的近义名词当作答案。</li><li>B ✅ these 指代前文 like the Yellow River, the Great Wall and the Taihang Mountains，它们都是地点，故填 places（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ experiences（经历）不是上文列举的内容，these 找不到指代对象。干扰点：把「与地点有关」泛化成「有关的经历」。</li><li>D ❌ problems（问题）与「黄河、长城、太行山」这些景点没有对应关系，全文的基调也不是讲困难。</li></ul><p><strong>整句翻译</strong>：以及与这些地方有关的故事和生活。</p><p><strong>词组</strong>：<code>as well as</code> 以及、还有；<code>be related to</code> 与……有关</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第3段 · 第5空所在句）：“We are seeing famous attractions in Shanxi on the woodcarvings <em><strong>4</strong></em> here, like the Yellow River, the Great Wall and the Taihang Mountains, as well as the stories and lives related to these <em><strong>5</strong></em>,” Ye said.</p></details><p><strong>Shanxi traders are said to have controlled ____ in North China during those periods.</strong></p><ul><li>A. happiness</li><li>B. luckiness</li><li>C. business</li><li>D. darkness</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（business）</strong> —— 晋商掌控的是中国北方的「商业」business。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ happiness（幸福）不能被「掌控」，也无法解释「他们广泛用木雕装饰住宅」的经济实力。干扰点：被 -ness 结尾的抽象名词形式吸引。</li><li>B ❌ luckiness（运气）同样不能被掌控，而且下一句讲的是他们花钱装饰宅院，说明掌控的是经济命脉。</li><li>C ✅ 主语是 Shanxi traders，能被商人「掌控」的只能是 business；后文 widely used woodcarvings to decorate their houses 也印证其商业实力（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ darkness（黑暗）与商人、木雕、宅院的语义场完全不搭。</li></ul><p><strong>整句翻译</strong>：据说在那段时期，山西商人掌控着中国北方的商业。</p><p><strong>词组</strong>：<code>Shanxi traders</code> 山西商人（晋商）；<code>during those periods</code> 在那些时期</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第4段 · 第6空所在句）：Shanxi traders are said to have controlled <em><strong>6</strong></em> in North China during those periods.</p></details><p><strong>They widely used woodcarvings to decorate their houses, ____ the popularity of the art.</strong></p><ul><li>A. improving</li><li>B. protecting</li><li>C. avoiding</li><li>D. controlling</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（improving）</strong> —— 广泛用木雕装饰住宅，推动了这门艺术的流行 improving。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 用木雕装饰住宅带来的自然结果是艺术更流行，improving（促进、提升）与 the popularity 搭配得体（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ protecting 是「保护」，而本句讲的是晋商的使用让这门艺术流传更广，「保护」与「流行」搭配不当。干扰点：看到后文呼吁 protect the art 就误以为此处同样填保护。</li><li>C ❌ avoiding（避免）方向完全相反，等于说他们避免艺术流行。</li><li>D ❌ controlling（控制）与 popularity 搭配后读成「控制流行度」，而句中主语是他们的装饰行为，不是人为限制。干扰点：被上文 controlled business 的用词干扰。</li></ul><p><strong>整句翻译</strong>：他们广泛用木雕装饰自己的住宅，从而推动了这门艺术的流行。</p><p><strong>词组</strong>：<code>use sth. to do sth.</code> 用某物做某事；<code>the popularity of the art</code> 这门艺术的流行</p><p><strong>对比自测</strong>：做完后对照 quiz-s4:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第4段 · 第7空所在句）：They widely used woodcarvings to decorate their houses, <em><strong>7</strong></em> the popularity of the art.</p></details><p><strong>…a ____ house of Shanxi traders—in Qixian County.</strong></p><ul><li>A. small</li><li>B. cheap</li><li>C. famous</li><li>D. new</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（famous）</strong> —— 乔家大院是著名的（famous）晋商宅院。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ small 与 a huge carved-frame mirror 的规模感以及乔家大院作为地标的事实都不相称。干扰点：只按「民居」联想其小。</li><li>B ❌ cheap（便宜的）与晋商宅院的身份冲突，全文的基调是赞叹其工艺与地位。</li><li>C ✅ 破折号之间是同位语解释，用来补足「乔家大院」之所以值得提及的身份——一处著名的晋商宅院；后文说其中的镜框堪称世界级杰作，也印证其名气（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ new 与「明清时期达到鼎盛」的历史定位矛盾，乔家大院是古建筑。干扰点：把「保存完好」误读成「新建」。</li></ul><p><strong>整句翻译</strong>：他说他曾在祁县乔家大院——一处著名的晋商宅院——看到一面巨大的雕花镜框。</p><p><strong>词组</strong>：<code>the Grand Courtyard of the Qiao Family</code> 乔家大院；<code>a famous house of Shanxi traders</code> 一处著名的晋商宅院</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第5段 · 第8空所在句）：He said he once saw a huge carved-frame（有雕花的框架）mirror in the Grand Courtyard of the Qiao Family—a <em><strong>8</strong></em> house of Shanxi traders—in Qixian County.</p></details><p><strong>With the patterns of a moon and a rhinoceros, Ye said this should be considered among the most ____ woodcarving works in the world.</strong></p><ul><li>A. expensive</li><li>B. similar</li><li>C. unimportant</li><li>D. uncommon</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（uncommon）</strong> —— 带月亮与犀牛图案的雕花镜框属于世界上最不同寻常的（uncommon）作品。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ expensive（昂贵的）说的是价格，而本句的赞叹点是图案独特、工艺罕见。干扰点：把「顶级作品」默认成「最贵」。</li><li>B ❌ similar（相似的）与 among the most 的最高级评价方向相反：最相似的作品谈不上被单独拿出来称赞。</li><li>C ❌ unimportant（不重要的）是贬义，与 Ye 特意举出此例、赞其为世界级作品的语气冲突。干扰点：看到 un- 前缀就当作「不寻常」。</li><li>D ✅ 月亮与犀牛的图案组合罕见，Ye 特意举出这面镜子，评价是「最不寻常」（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：叶耀亮说，由于上面有月亮和犀牛的图案，这应当被视为世界上最不寻常的木雕作品之一。</p><p><strong>词组</strong>：<code>with the patterns of ...</code> 带有……的图案；<code>be considered among the most ...</code> 被视为最……之一</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第5段 · 第9空所在句）：With the patterns of a moon and a rhinoceros（犀牛）, Ye said this should be considered among the most <em><strong>9</strong></em> woodcarving works in the world.</p></details><p><strong>But nowadays, the art has gradually faded out of local life and is ____ to death.</strong></p><ul><li>A. close</li><li>B. harmful</li><li>C. necessary</li><li>D. opposite</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（close）</strong> —— be close to death 濒临消亡，与 faded out of local life 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ be close to death 是固定表达「濒临消亡」，与前面 has gradually faded out of local life 构成递进（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ be harmful to 意为「对……有害」，后面应接受害者（如 harmful to health），此处 death 是结果不是受害者。干扰点：只检查「to + 名词」结构是否通顺。</li><li>C ❌ necessary to 表示「对……有必要」，与「即将消亡」的危机语气相反。干扰点：被后文 necessary to protect 的用词干扰。</li><li>D ❌ opposite to 意为「与……相反」，be opposite to death 语义不成立，也不是描述濒危的搭配。</li></ul><p><strong>整句翻译</strong>：叶耀亮说：「但如今，这门艺术已渐渐淡出当地人的生活，濒临消亡。」</p><p><strong>词组</strong>：<code>be close to death</code> 濒临死亡、濒于消亡；<code>fade out of local life</code> 淡出当地生活</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第6段 · 第10空所在句）：“But nowadays, the art has gradually faded out of local life and is <em><strong>10</strong></em> to death,” Ye said.</p></details><p><strong>We think it necessary to protect the art and ____ it down to future generations.</strong></p><ul><li>A. throw</li><li>B. pass</li><li>C. pull</li><li>D. pour</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（pass）</strong> —— pass down 传给后代，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ throw down 意为「扔下」，与传给后代的方向相反。干扰点：只按 down 的中文「向下」猜测。</li><li>B ✅ pass down 是「（世代）传下去」的固定搭配，与 to future generations（传给后代）搭配严丝合缝（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ pull down 意为「拆毁、拉倒」，恰好是把建筑、艺术毁掉，与 protect the art 冲突。</li><li>D ❌ pour down 意为「倾泻（雨）」，接 it down to future generations 语义不通。干扰点：把 pour 与 pass 都看成「传递类」动词。</li></ul><p><strong>整句翻译</strong>：我们认为有必要保护这门艺术，并把它传给后代。</p><p><strong>词组</strong>：<code>pass sth. down to sb.</code> 把某物传给某人；<code>a future generation</code> 后代</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第6段 · 第11空所在句）：“We think it necessary to protect the art and <em><strong>11</strong></em> it down to future generations.” Ye said there are different styles and characteristics of woodcarving arts across different areas of China.</p></details><p><strong>Ye started to learn the art from a master in Zhejiang Province ____ he was 16.</strong></p><ul><li>A. although</li><li>B. unless</li><li>C. until</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（when）</strong> —— 十六岁时开始学艺，时间状语从句用 when。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ although 表让步，会读成「虽然他十六岁，却开始学艺」，两句并无对立。干扰点：把年龄当成让步条件的错觉。</li><li>B ❌ unless 表否定条件「除非」，等于说「除非他十六岁才学」，逻辑不通。</li><li>C ❌ until 表「直到」，要搭配持续动词或 not ... until 结构；started to learn 是瞬间动作，不能与 until 连用。干扰点：把「十六岁之前」与「直到十六岁才」混为一谈。</li><li>D ✅ he was 16 是时间点，用 when 引导时间状语从句（来源：课件原答案，解析为笔记补充）。</li></ul><p><strong>整句翻译</strong>：叶耀亮十六岁时开始向浙江的一位师傅学习这门艺术。</p><p><strong>词组</strong>：<code>learn the art from a master</code> 向大师学这门技艺；<code>when he was 16</code> 他十六岁时</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第7段 · 第12空所在句）：Ye started to learn the art from a master in Zhejiang Province <em><strong>12</strong></em> he was 16.</p></details><p><strong>After finishing his three-year learning, he returned to Shanxi, continued to ____ local artists and began to practice in this trade.</strong></p><ul><li>A. stop from</li><li>B. learn from</li><li>C. think of</li><li>D. take up</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（learn from）</strong> —— 回山西后继续向当地艺人「学习」learn from。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stop from 通常出现在 stop sb. from doing 结构中，continue to stop from local artists 结构与语义都不成立。</li><li>B ✅ learn from sb. 是「向某人学习」；与大他一辈的师傅学成后回省继续向当地艺人请教，情节连贯（来源：课件原答案，解析为笔记补充）。</li><li>C ❌ think of（想起、考虑）不能表达「学艺」，且与后面的 began to practice 不是同一条成长线索。干扰点：把「接触艺人」泛化理解。</li><li>D ❌ take up（开始从事）接人的宾语不成立：take up local artists 若读成「从事当地艺人」语义荒谬。干扰点：看到后文 practice in this trade 就想用 take up。</li></ul><p><strong>整句翻译</strong>：完成三年学习后，他回到山西，继续向当地艺人学习，并开始从事这一行业。</p><p><strong>词组</strong>：<code>learn from sb.</code> 向某人学习；<code>practice in this trade</code> 从事这一行业</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第7段 · 第13空所在句）：After finishing his three-year learning, he returned to Shanxi, continued to <em><strong>13</strong></em> local artists and began to practice in this trade.</p></details><p><strong>Because of his understanding of the art, Ye has ____ many masterpieces over the past twenty years.</strong></p><ul><li>A. borrowed</li><li>B. bought</li><li>C. created</li><li>D. invented</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（created）</strong> —— 凭借对艺术的理解，「创作」created 了许多杰作。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ borrowed（借来）的东西不能称为自己的杰作，与他的身份（artist）冲突。干扰点：只检查「有作品」这一点而不看归属。</li><li>B ❌ bought（买来）同样把主人写成收藏者而不是创作者，与后文 His works 的表述不符。干扰点：把「有很多杰作」误读为「拥有」。</li><li>C ✅ Because of his understanding of the art 给出创作的条件，has created many masterpieces 与 his works 前后呼应（来源：课件原答案，解析为笔记补充）。</li><li>D ❌ invented（发明）用于前所未有的东西，木雕作品是「创作」而非「发明」，且木雕是既有艺术门类。干扰点：把 create 与 invent 都当成「做出新东西」。</li></ul><p><strong>整句翻译</strong>：由于对这门艺术的理解，过去二十年里叶耀亮创作了许多杰作。</p><p><strong>词组</strong>：<code>over the past twenty years</code> 在过去二十年里（现在完成时信号）；<code>create masterpieces</code> 创作杰作</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第8段 · 第14空所在句）：Because of his understanding of the art, Ye has <em><strong>14</strong></em> many masterpieces over the past twenty years.</p></details><p><strong>His works have been ____ by a number of private collectors, museums and art galleries.</strong></p><ul><li>A. collected</li><li>B. broken</li><li>C. developed</li><li>D. built</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（collected）</strong> —— 收藏家、博物馆、美术馆「收藏」collected 了他的作品。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语是 His works，动作的发出者是收藏家、博物馆、美术馆，与 collect（收藏）的搭配完全对应，且用被动语态 have been collected（来源：课件原答案，解析为笔记补充）。</li><li>B ❌ broken（被打碎）与博物馆、美术馆收藏杰作的事实冲突，也违背全文的赞叹语气。</li><li>C ❌ developed（被开发、被发展）用于作品时语义不成立，不能表达「被收藏」。干扰点：把 develop 当作万能褒义动词。</li><li>D ❌ built（被建）只适合建筑物，木雕作品不是建造出来的。干扰点：把「被建造」误用于「被创作」。</li></ul><p><strong>整句翻译</strong>：他的作品被许多私人收藏家、博物馆和美术馆收藏。</p><p><strong>词组</strong>：<code>a number of</code> 许多（修饰可数名词复数）；<code>private collectors</code> 私人收藏家</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 山西木雕 · 第8段 · 第15空所在句）：His works have been <em><strong>15</strong></em> by a number of private collectors, museums and art galleries.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>叶耀亮在省会太原最近举办的一次展览上说，一块木头可以讲述山西的历史、文化、景色和当地生活。他是一位著名的木雕艺术家。</p><p>据叶耀亮介绍，山西木雕已有近两千年历史。数千年来，这门艺术一直是展现当地文化的一种方式，题材涵盖历史传说和乡村风景。人物、山川、河流、花鸟与动物都是作品中的常见形象。叶耀亮说：“这里展出的木雕让我们看见黄河、长城和太行山等山西名胜，以及与这些地方有关的故事和生活。”</p><p>山西木雕在明清时期达到鼎盛。据说当时晋商掌控着中国北方的商业，他们广泛用木雕装饰住宅，推动了这门艺术的流行。叶耀亮曾在祁县乔家大院——一处著名的晋商宅院——看到一面巨大的雕花镜框。它带有月亮和犀牛图案，在他看来应属于世界上最不同寻常的木雕作品之一。</p><p>但如今，这门艺术已逐渐淡出当地生活，濒临消亡。人们认为有必要保护它，并把它传给后代。中国不同地区的木雕艺术各有风格与特色。</p><p>叶耀亮十六岁时开始向浙江的一位师傅学习。完成三年学艺后，他回到山西，继续向当地艺人学习并投身这一行业。凭借对木雕的理解，过去二十年里他创作了许多杰作，作品被多位私人收藏家、博物馆和美术馆收藏。</p></details><h3 id="练习二-·-向救人英雄致敬" tabindex="-1"><a class="header-anchor" href="#练习二-·-向救人英雄致敬"><span>练习二 · 向救人英雄致敬</span></a></h3><p>Recently, a hotpot restaurant in Beijing’s Haidian District has become very popular. People from the capital and other places have been coming to enjoy a <strong><em><strong>1</strong></em></strong> there, as well as to pay their <strong><em><strong>2</strong></em></strong> to a hero who gave his life to save others.</p><p>Luan Liuwei, a 41-year-old man from Ningyang County in Tai’an, Shandong Province, ran the <strong><em><strong>3</strong></em></strong> in Beijing with his wife for many years. On August 10, while visiting Gu’an County of Langfang, Hebei Province with his daughter, Luan <strong><em><strong>4</strong></em></strong> three children from drowning（溺水）in the Yongding River. However, when he went back into the water to save an adult who was also in danger, Luan drowned because he was too <strong><em><strong>5</strong></em></strong>.</p><p>On Wednesday, Ningyang, which was Luan’s <strong><em><strong>6</strong></em></strong>, awarded him the title of “Model of the New Era in Ningyang”, even though he was already <strong><em><strong>7</strong></em></strong>.</p><p>Luan’s heroic act <strong><em><strong>8</strong></em></strong> moved people in Beijing and beyond. Many people visited his restaurant to remember the hero and <strong><em><strong>9</strong></em></strong> the business.</p><p>“By around 5 pm, the restaurant was already <strong><em><strong>10</strong></em></strong>, and I waited for more than an hour without getting a seat,” said a customer, who had traveled from Beijing’s Tongzhou District, about 50 kilometers <strong><em><strong>11</strong></em></strong>, according to a report in Beijing Daily.</p><p>Even though they had to wait for a long time, the customers didn’t <strong><em><strong>12</strong></em></strong>. “People came here not just for the food, but also for Luan’s <strong><em><strong>13</strong></em></strong>, so they didn’t want to leave,” said one of the waiting customers.</p><p>One restaurant employee（员工）said, “The restaurant doesn’t <strong><em><strong>14</strong></em></strong> until 11 am, but there were already customers waiting, starting at 9 am.”</p><p>Some people tried to give money to the restaurant, only to have the staff members run after them for several blocks to <strong><em><strong>15</strong></em></strong> the money.</p><p><strong>People from the capital and other places have been coming to enjoy a ____ there, as well as to pay their ____ to a hero.（本空为第 1 空）</strong></p><ul><li>A. movie</li><li>B. joke</li><li>C. meal</li><li>D. game</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（meal）</strong> —— 火锅店走红，人们到店「用餐」enjoy a meal。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ movie（电影）与 hotpot restaurant 场景矛盾，人们到火锅店不是为了看电影。干扰点：由 popular 联想到「赶热闹看片」。</li><li>B ❌ joke（玩笑）不能与 enjoy a 连用表「找乐子」，且与悼念英雄的氛围不符。干扰点：把 enjoy 理解为「取乐」。</li><li>C ✅ 首句 a hotpot restaurant has become very popular 点明场景是餐馆，人们来 enjoy a meal（用餐），并与后文 People came here not just for the food 呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ game（游戏）与餐馆场景无关。干扰点：忽略首句场景，按「人们来店里玩」猜。</li></ul><p><strong>整句翻译</strong>：来自首都和其他地方的人们一直到这里来用餐，同时也向一位为救他人而献出生命的英雄致敬。</p><p><strong>词组</strong>：<code>enjoy a meal</code> 用餐；<code>give one’s life to save others</code> 为救他人而献出生命</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第1段 · 第1空所在句）：People from the capital and other places have been coming to enjoy a <em><strong>1</strong></em> there, as well as to pay their <em><strong>2</strong></em> to a hero who gave his life to save others.</p></details><p><strong>…as well as to pay their ____ to a hero who gave his life to save others.</strong></p><ul><li>A. respects</li><li>B. regards</li><li>C. courses</li><li>D. thoughts</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（respects）</strong> —— pay respects to 向……致敬，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ pay one’s respects to 是固定搭配，意为「向……致敬」，与 a hero who gave his life 的语境吻合。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ regards 常与 give/send 连用表「代为问候」，不作 pay respects 的替换，语义是「问候」而非「致敬」。干扰点：regards/respects 形近，中文都带「致」。</li><li>C ❌ courses（课程/菜肴）与 pay their...to a hero 无法搭配。干扰点：只盯住餐馆场景。</li><li>D ❌ thoughts（思念）不能进入 pay one’s...to 结构。干扰点：受「缅怀」中文义误导。</li></ul><p><strong>整句翻译</strong>：……同时也向一位为救他人而献出生命的英雄致敬。</p><p><strong>词组</strong>：<code>pay one’s respects to</code> 向……致敬</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第1段 · 第2空所在句）：People from the capital and other places have been coming to enjoy a <em><strong>1</strong></em> there, as well as to pay their <em><strong>2</strong></em> to a hero who gave his life to save others.</p></details><p><strong>Luan Liuwei … ran the ____ in Beijing with his wife for many years.</strong></p><ul><li>A. factory</li><li>B. hospital</li><li>C. restaurant</li><li>D. hotel</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（restaurant）</strong> —— 与妻子经营的是那家火锅「餐馆」restaurant。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ factory（工厂）与 hotpot restaurant 的场景冲突。干扰点：ran 让人误以为「经营工厂」。</li><li>B ❌ hospital（医院）与 ran（经营）搭配不当，全文无医疗线索。干扰点：ran 与「奔跑/运营」混淆。</li><li>C ✅ 首段 a hotpot restaurant 与 ran...with his wife 呼应，Luan 经营的是这家餐馆 restaurant。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ hotel 虽可与 ran 搭配，但首段场景是 restaurant，下文 The restaurant doesn’t open 也复现了这一名词。</li></ul><p><strong>整句翻译</strong>：栾留伟是山东泰安宁阳县人，41 岁，多年来和妻子在北京经营这家餐馆。</p><p><strong>词组</strong>：<code>run a restaurant</code> 经营餐馆</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第2段 · 第3空所在句）：Luan Liuwei, a 41-year-old man from Ningyang County in Tai’an, Shandong Province, ran the <em><strong>3</strong></em> in Beijing with his wife for many years.</p></details><p><strong>While visiting Gu’an County … with his daughter, Luan ____ three children from drowning in the Yongding River.</strong></p><ul><li>A. found</li><li>B. saved</li><li>C. helped</li><li>D. stopped</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（saved）</strong> —— save sb. from drowning 把孩子从溺水中救出。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ found（发现）不能接 from drowning 结构，且与「英雄救人」的事迹不符。干扰点：只按「在水里发现孩子」理解。</li><li>B ✅ save sb. from drowning 把孩子从溺水中救出，与首段 a hero who gave his life to save others 的总述一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ help 后不接 sb. from doing 结构；语义上「帮助」也弱于「救起」。干扰点：help 与 save 中文都可译「帮/救」。</li><li>D ❌ stop sb. from drowning 语法成立，但强调「阻止溺水发生」，与「已经落水后施救」的语境不符。干扰点：stop...from 是熟搭配。</li></ul><p><strong>整句翻译</strong>：8 月 10 日，他带着女儿在河北廊坊固安县游玩时，从永定河中救出了三名溺水儿童。</p><p><strong>词组</strong>：<code>save sb. from drowning</code> 把某人从溺水中救出；<code>the Yongding River</code> 永定河</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第2段 · 第4空所在句）：On August 10, while visiting Gu’an County of Langfang, Hebei Province with his daughter, Luan <em><strong>4</strong></em> three children from drowning（溺水）in the Yongding River.</p></details><p><strong>When he went back into the water to save an adult …, Luan drowned because he was too ____.</strong></p><ul><li>A. sad</li><li>B. excited</li><li>C. tired</li><li>D. silly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（tired）</strong> —— 再次下水救人后体力耗尽（too tired）而溺亡。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ sad（难过）描述情绪，无法解释再次下水后溺亡的原因。干扰点：按「牺牲令人难过」代入。</li><li>B ❌ excited（激动）与溺亡结果没有因果关系。干扰点：把下水救人误读为「一时激动」。</li><li>C ✅ 再次入水救人后因体力耗尽（too tired）而溺亡，与 however 引出的转折结果吻合。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ silly（愚蠢）含贬义，与全文颂扬英雄的基调冲突。干扰点：用事后结果反推「不该下水」。</li></ul><p><strong>整句翻译</strong>：然而，当他再次下水去救另一名遇险的成年人时，却因体力耗尽而溺亡。</p><p><strong>词组</strong>：<code>go back into the water</code> 再次下水；<code>too tired</code> 太累了</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第2段 · 第5空所在句）：However, when he went back into the water to save an adult who was also in danger, Luan drowned because he was too <em><strong>5</strong></em>.</p></details><p><strong>On Wednesday, Ningyang, which was Luan’s ____, awarded him the title.</strong></p><ul><li>A. relative</li><li>B. college</li><li>C. friend</li><li>D. hometown</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（hometown）</strong> —— 宁阳是他的「家乡」hometown，故由当地追授称号。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ relative（亲戚）不能解释宁阳「这个地方」追授称号。干扰点：把 hometown 拆成「亲属家」。</li><li>B ❌ college（大学）同样与地名 Ningyang 不搭。干扰点：由 awarded title 联想到「母校/单位授奖」。</li><li>C ❌ friend（朋友）不能与 which 从句修饰的 Ningyang（地名）搭配。干扰点：按「有人替他领奖」猜。</li><li>D ✅ Ningyang 是他的家乡 hometown，由家乡政府追授称号，与非限制性定语从句的先行词吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：星期三，他的家乡宁阳追授他「宁阳新时代楷模」的称号。</p><p><strong>词组</strong>：<code>award sb. the title of</code> 授予某人……称号；<code>hometown</code> 家乡</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第3段 · 第6空所在句）：On Wednesday, Ningyang, which was Luan’s <em><strong>6</strong></em>, awarded him the title of “Model of the New Era in Ningyang”, even though he was already <em><strong>7</strong></em>.</p></details><p><strong>…awarded him the title of “Model of the New Era in Ningyang”, even though he was already ____.</strong></p><ul><li>A. busy</li><li>B. dead</li><li>C. asleep</li><li>D. sick</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（dead）</strong> —— 他为救人牺牲，虽已离世（dead）仍被追授称号。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ busy（忙碌）与 even though 引导的让步逻辑不搭。干扰点：只看 even though 表示「尽管如此还……」。</li><li>B ✅ 首段已述他因救人溺亡，even though he was already dead 表示「虽已离世仍被追授」。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ asleep（睡着）与「追授称号」语境无关。干扰点：把 already 与「长眠」联系。</li><li>D ❌ sick（生病）与牺牲事实冲突。干扰点：与第5空 too tired 混同。</li></ul><p><strong>整句翻译</strong>：……尽管他已经离世，仍被追授称号。</p><p><strong>词组</strong>：<code>even though</code> 尽管</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第3段 · 第7空所在句）：On Wednesday, Ningyang, which was Luan’s <em><strong>6</strong></em>, awarded him the title of “Model of the New Era in Ningyang”, even though he was already <em><strong>7</strong></em>.</p></details><p><strong>Luan’s heroic act ____ moved people in Beijing and beyond.</strong></p><ul><li>A. exactly</li><li>B. wisely</li><li>C. warmly</li><li>D. deeply</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（deeply）</strong> —— 英雄事迹「深深地」deeply 打动了人们。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ exactly（恰好）修饰 moved 语义不通。干扰点：把 exactly 当「确实」用。</li><li>B ❌ wisely（明智地）不能修饰「打动人」。干扰点：按「英雄行为很明智」代入。</li><li>C ❌ warmly（热情地）多修饰 welcome/greet，与 moved people 搭配不当。干扰点：与后文人们热心纪念的场景混淆。</li><li>D ✅ 英雄事迹深深地 deeply 打动了人们，moved 常与 deeply 搭配，情感深度呼应后文排长队纪念。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：栾留伟的英雄事迹深深地打动了北京及其他地区的人们。</p><p><strong>词组</strong>：<code>move people deeply</code> 深深地打动人们</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第4段 · 第8空所在句）：Luan’s heroic act <em><strong>8</strong></em> moved people in Beijing and beyond.</p></details><p><strong>Many people visited his restaurant to remember the hero and ____ the business.</strong></p><ul><li>A. support</li><li>B. protect</li><li>C. change</li><li>D. examine</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（support）</strong> —— 人们来店里纪念英雄、用消费「支持」support 店铺。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 人们到店纪念英雄、用消费支持 support 店铺生意，与后文排长队等位的情节一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ protect（保护）的对象一般是人或安全，不与 the business 搭配。干扰点：把「支持」泛化为「保护」。</li><li>C ❌ change the business（改变生意）与全文「帮店家维持」的方向相反。干扰点：按「英雄事迹改变了一切」猜。</li><li>D ❌ examine（检查）与语境无关，属于形近干扰。</li></ul><p><strong>整句翻译</strong>：许多人来到他的餐馆纪念英雄、支持店铺的生意。</p><p><strong>词组</strong>：<code>support the business</code> 支持店铺生意</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第4段 · 第9空所在句）：Many people visited his restaurant to remember the hero and <em><strong>9</strong></em> the business.</p></details><p><strong>By around 5 pm, the restaurant was already ____, and I waited for more than an hour without getting a seat.</strong></p><ul><li>A. empty</li><li>B. full</li><li>C. quiet</li><li>D. noisy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（full）</strong> —— 等一个多小时没座位，说明店里已经「满座」full。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ empty（空的）与「等了一个多小时没座位」直接矛盾。干扰点：按「到店就能坐下」误推。</li><li>B ✅ 等到五点多已经满座，等了一个多小时仍没座位，说明 restaurant was already full。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ quiet（安静）推不出「没有座位」。干扰点：按等位时的主观感受猜。</li><li>D ❌ noisy（嘈杂）与能否得到座位无关。干扰点：火锅店=吵闹的刻板印象。</li></ul><p><strong>整句翻译</strong>：到下午五点左右，餐馆已经满座，我等了一个多小时仍没有座位。</p><p><strong>词组</strong>：<code>be full</code> 满座；<code>get a seat</code> 得到座位</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第5段 · 第10空所在句）：“By around 5 pm, the restaurant was already <em><strong>10</strong></em>, and I waited for more than an hour without getting a seat,” said a customer, who had traveled from Beijing’s Tongzhou District, about 50 kilometers <em><strong>11</strong></em>, according to a report in Beijing Daily.</p></details><p><strong>A customer, who had traveled from Beijing’s Tongzhou District, about 50 kilometers ____,</strong></p><ul><li>A. away</li><li>B. above</li><li>C. again</li><li>D. along</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（away）</strong> —— 50 kilometers away 表示「五十公里外」，距离用 away。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ about 50 kilometers away 表示「约五十公里外」，away 表距离，与 traveled from Tongzhou District 呼应。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ above（在上方）表高度，不表距离。干扰点：把「50 公里」误读为高度。</li><li>C ❌ again（再次）与距离无关。干扰点：与上句 waited more than an hour 的「再」混淆。</li><li>D ❌ along（沿着）是介词，不能作后置状语表距离。干扰点：沿路的字面联想。</li></ul><p><strong>整句翻译</strong>：一位从约五十公里外的北京通州赶来的顾客说。</p><p><strong>词组</strong>：<code>50 kilometers away</code> 五十公里外</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第5段 · 第11空所在句）：“By around 5 pm, the restaurant was already <em><strong>10</strong></em>, and I waited for more than an hour without getting a seat,” said a customer, who had traveled from Beijing’s Tongzhou District, about 50 kilometers <em><strong>11</strong></em>, according to a report in Beijing Daily.</p></details><p><strong>Even though they had to wait for a long time, the customers didn’t ____.</strong></p><ul><li>A. think</li><li>B. worry</li><li>C. mind</li><li>D. arrive</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（mind）</strong> —— don’t mind 不介意久等，与下文不想离开呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ think（想）与 didn’t 连用语义不完整，不能接「久等」作宾语。干扰点：把 didn’t think 当「没多想」。</li><li>B ❌ worry（担心）与让步重心不符——顾客并不焦虑。干扰点：久等通常让人担心。</li><li>C ✅ didn’t mind 表示「不介意」，与下文 so they didn’t want to leave 的原因链一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ arrive（到达）与「等了很长时间」的语境矛盾。干扰点：把 wait 与 arrive 的时间线混淆。</li></ul><p><strong>整句翻译</strong>：尽管要排很长时间的队，顾客们却并不介意。</p><p><strong>词组</strong>：<code>don’t mind</code> 不介意</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第6段 · 第12空所在句）：Even though they had to wait for a long time, the customers didn’t <em><strong>12</strong></em>.</p></details><p><strong>People came here not just for the food, but also for Luan’s ____, so they didn’t want to leave.</strong></p><ul><li>A. story</li><li>B. dream</li><li>C. plan</li><li>D. work</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（story）</strong> —— 人们不仅为食物而来，也为英雄的「事迹」story 而来。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 人们不仅为食物而来，也为 Luan 的「事迹/故事」story 而来，与首段 a hero who gave his life 的总述呼应。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ dream（梦想）与英雄已牺牲的事实冲突。干扰点：把「向英雄致敬」误读为「追梦」。</li><li>C ❌ plan（计划）无从谈起。干扰点：与首段 popular 的「特意安排」联想。</li><li>D ❌ work（工作）与「不愿离开」的原因不符。干扰点：由 restaurant 联想到「手艺/出品」。</li></ul><p><strong>整句翻译</strong>：人们来到这里不只是为了食物，也是为了栾留伟的故事，所以不愿离开。</p><p><strong>词组</strong>：<code>not just...but also...</code> 不仅……而且……；<code>Luan’s story</code> 栾留伟的事迹</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第6段 · 第13空所在句）：“People came here not just for the food, but also for Luan’s <em><strong>13</strong></em>, so they didn’t want to leave,” said one of the waiting customers.</p></details><p><strong>The restaurant doesn’t ____ until 11 am, but there were already customers waiting, starting at 9 am.</strong></p><ul><li>A. cook</li><li>B. close</li><li>C. burn</li><li>D. open</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（open）</strong> —— 九点就有人排队、十一点才「开门」open。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cook（做饭）与 until 11 am 的时间点搭配不当。干扰点：餐馆=做饭的地方。</li><li>B ❌ close（关门）与「十一点才……九点就有人等」的逻辑相反。干扰点：not...until 与「直到……才」误导方向。</li><li>C ❌ burn（燃烧）不合语境，属熟词干扰。</li><li>D ✅ not...until 11 am 表示「直到上午十一点才开门」，与 starting at 9 am 就有人排队形成对照。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：餐馆上午十一点才开门，但九点起就已经有顾客在排队等候了。</p><p><strong>词组</strong>：<code>not...until</code> 直到……才……；<code>wait in line</code> 排队等候</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第7段 · 第14空所在句）：One restaurant employee（员工）said, “The restaurant doesn’t <em><strong>14</strong></em> until 11 am, but there were already customers waiting, starting at 9 am.”</p></details><p><strong>Some people tried to give money to the restaurant, only to have the staff members run after them for several blocks to ____ the money.</strong></p><ul><li>A. count</li><li>B. collect</li><li>C. divide</li><li>D. return</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（return）</strong> —— 员工追出几个街区把钱「退还」return 给他们。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ count（数钱）与员工追出去的动作目的不符。干扰点：与 give money 场景相关就选「数」。</li><li>B ❌ collect（收钱）与追出去的方向相反——不是收钱，是还钱。干扰点：与「人们想给钱」的表面情节混淆。</li><li>C ❌ divide（分钱）无据，仅与 money 构成搭配假象。</li><li>D ✅ 员工追出几个街区把钱退还 return 给顾客，与 only to have the staff members run after them 的目的状语一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：有些人想把钱留给餐馆，员工们却追出好几个街区把钱退还给他们。</p><p><strong>词组</strong>：<code>run after sb.</code> 追赶某人；<code>return the money</code> 退钱</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 向救人英雄致敬 · 第8段 · 第15空所在句）：Some people tried to give money to the restaurant, only to have the staff members run after them for several blocks to <em><strong>15</strong></em> the money.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>最近，北京海淀区一家火锅店走红。来自北京和其他地方的人们不仅到店用餐，也向一位为救他人而牺牲的英雄表达敬意。</p><p>栾留伟是山东泰安宁阳县人，四十一岁，多年来与妻子在北京经营这家餐馆。8 月 10 日，他带女儿到河北廊坊固安县游玩时，从永定河中救出三名溺水儿童。后来他再次下水营救另一名遇险成年人，却因体力耗尽而溺亡。</p><p>星期三，栾留伟的家乡宁阳追授他“宁阳新时代楷模”称号。尽管他已经离世，他的英雄事迹仍深深打动了北京及其他地区的人。许多人来到他的餐馆纪念英雄、支持店铺。一位从约五十公里外的北京通州赶来的顾客说，下午五点左右餐馆已经满座，自己等了一个多小时仍没有座位。</p><p>顾客即使久等也不介意，因为人们不仅为食物而来，也为栾留伟的故事而来。一名员工说，餐馆上午十一点才开门，但九点就有人排队。有些人想把钱留给餐馆，员工却追出好几个街区把钱退还给他们。</p></details><h3 id="练习三-·-培养儿童解决问题的能力" tabindex="-1"><a class="header-anchor" href="#练习三-·-培养儿童解决问题的能力"><span>练习三 · 培养儿童解决问题的能力</span></a></h3><p>When a child is faced with a problem, he or she may not be able to deal with it. Children need to learn <strong><strong>1</strong></strong> to deal with problems. You can help someone to learn how to solve problems. The best way is to take the time to talk about problems as they happen. Of course, this is not easy to do. Problems have a way of bursting upon someone at the <strong><strong>2</strong></strong> time. But even if the time is not the best, you should try to help.</p><p>There are many things you can do to help a child <strong><strong>3</strong></strong> problem-solving skills. One good way is to find out what caused the <strong><strong>4</strong></strong>. This is a skill that children <strong><strong>5</strong></strong> learn without help. A child <strong><strong>6</strong></strong> knock over his or her glass of milk at the dinner table, but he or she may not realize that the glass was too close to the <strong><strong>7</strong></strong>. You can show the child what the problem is. Then it can be solved.</p><p>The next step for a child is to learn how to solve the problem <strong><strong>8</strong></strong>. This step takes <strong><strong>9</strong></strong>. Some people are so afraid of being wrong that they cannot solve problems. You can help by talking about some possible <strong><strong>10</strong></strong>. The two of you can decide which answer is the best. Let the child <strong><strong>11</strong></strong> it out. Now the child will see that problems can be solved, and you can <strong><strong>12</strong></strong> him or her for choosing an answer.</p><p>Another step to problem solving is to help children see the relationship of cause and effect. If a child knocks over a glass, it will fall and break. He or she might <strong><strong>13</strong></strong> to write on the wall but the pencil always leaves a <strong><strong>14</strong></strong>. Soon the child will see the link <strong><strong>15</strong></strong> cause and effect, and then he or she is on the road to growth.</p><p><strong>Children need to learn ____ to deal with problems.</strong></p><ul><li>A. why</li><li>B. about</li><li>C. it</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（how）</strong> —— learn how to deal with problems 学会「如何」处理问题。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ why 表原因，与 deal with problems（处理问题的「方法」）不搭。干扰点：与下句 how to solve problems 的方向混淆。</li><li>B ❌ about 是介词，learn about to deal 语法错误。干扰点：learn about 是熟搭配。</li><li>C ❌ it 与后面的不定式 to deal 冲突，learn it to deal 结构错误。干扰点：把 learn it 当「学会这件事」。</li><li>D ✅ learn how to do sth. 学会如何做某事；下句 You can help someone to learn how to solve problems 直接复现 how。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：孩子们需要学会如何处理问题。</p><p><strong>词组</strong>：<code>learn how to do sth.</code> 学会如何做某事；<code>deal with problems</code> 处理问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第1段 · 第1空所在句）：Children need to learn <strong>1</strong> to deal with problems.</p></details><p><strong>Problems have a way of bursting upon someone at the ____ time.</strong></p><ul><li>A. exact</li><li>B. ordinary</li><li>C. worst</li><li>D. usual</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（worst）</strong> —— 与下文 even if the time is not the best 呼应：问题总在最糟（worst）的时刻出现。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ exact（精确的）不修饰 time 的评价。干扰点：与 at the exact time 的「恰恰」义混淆。</li><li>B ❌ ordinary（普通的）与下文 even if the time is not the best 矛盾。干扰点：「问题常见」≠「时间普通」。</li><li>C ✅ 与下句 even if the time is not the best 呼应：问题总在最糟的 worst 时刻突然爆发。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ usual（通常的）不能解释「偏偏挑这个时候」。干扰点：与 have a way of（往往会）混淆。</li></ul><p><strong>整句翻译</strong>：问题往往会在最糟糕的时刻突然降临到某人身上。</p><p><strong>词组</strong>：<code>have a way of doing</code> 往往会……；<code>burst upon sb.</code> 突然降临到某人身上</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第1段 · 第2空所在句）：Problems have a way of bursting upon someone at the <strong>2</strong> time.</p></details><p><strong>There are many things you can do to help a child ____ problem-solving skills.</strong></p><ul><li>A. observe</li><li>B. learn</li><li>C. watch</li><li>D. follow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（learn）</strong> —— 帮助孩子「学习」learn 解决问题的技能。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ observe（观察）技能不能表达「学会解决问题」。干扰点：observe 与 learn 在「习得」上近义。</li><li>B ✅ help a child learn problem-solving skills 帮助孩子「学习」解决问题的技能，learn...skills 搭配自然。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ watch（观看）不接 skills 表「习得」。干扰点：watch 与 observe 近义二连干扰。</li><li>D ❌ follow（跟随/遵循）与 skills 搭配勉强。干扰点：follow 有「以……为榜样学习」的古义。</li></ul><p><strong>整句翻译</strong>：你可以做很多事情来帮助一个孩子学习解决问题的技能。</p><p><strong>词组</strong>：<code>problem-solving skills</code> 解决问题的技能</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第2段 · 第3空所在句）：There are many things you can do to help a child <strong>3</strong> problem-solving skills.</p></details><p><strong>One good way is to find out what caused the ____.</strong></p><ul><li>A. way</li><li>B. skills</li><li>C. effect</li><li>D. problem</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（problem）</strong> —— 找出「问题」problem 的成因，全文主题即解决问题。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ way（方法）与 caused（引起）主谓不搭——方法不能被「引起」。干扰点：与 The next step 的步骤联想。</li><li>B ❌ skills 不能被 caused 搭配。干扰点：上句 skills 原词干扰。</li><li>C ❌ effect（结果）与 find out what caused... 逻辑顺序颠倒——先因后果，不能找「结果的原因」。干扰点：与第15空 cause and effect 混淆。</li><li>D ✅ find out what caused the problem 找出「问题」的成因，problem 与全文 deal with problems 复现。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：一个好方法是找出是什么引起了这个问题。</p><p><strong>词组</strong>：<code>find out</code> 找出；<code>cause the problem</code> 引起问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第2段 · 第4空所在句）：One good way is to find out what caused the <strong>4</strong>.</p></details><p><strong>This is a skill that children ____ learn without help.</strong></p><ul><li>A. need to</li><li>B. should</li><li>C. won’t</li><li>D. can</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（won’t）</strong> —— 这种能力没有帮助孩子「学不会」（won’t learn），所以要大人帮忙。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ need to learn 表示「需要学」，与 without help 不形成转折。干扰点：把「需要帮助」读成「需要学」。</li><li>B ❌ should（应该）不含能力判断，与 without help 的条件关系不符。干扰点：按「应当学会」的正面表述选。</li><li>C ✅ 这种技能孩子没有帮助就「学不会」（won’t learn），所以需要大人介入，与 But 转折一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ can learn without help 与下文「大人要帮忙」矛盾。干扰点：误读为「这是孩子能自学的技能」。</li></ul><p><strong>整句翻译</strong>：这是一种没有帮助孩子就学不会的技能。</p><p><strong>词组</strong>：<code>without help</code> 没有帮助；<code>learn a skill</code> 学会一项技能</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第2段 · 第5空所在句）：This is a skill that children <strong>5</strong> learn without help.</p></details><p><strong>A child ____ knock over his or her glass of milk at the dinner table,</strong></p><ul><li>A. wrongly</li><li>B. usually</li><li>C. carelessly</li><li>D. may</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（may）</strong> —— 情态动词 may：孩子「可能」打翻牛奶。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wrongly（错误地）修饰 knock over 语法可通，但与 but 后「没有意识到」不构成转折。干扰点：打翻=做错事。</li><li>B ❌ usually（通常）与后文 may not realize 的「可能没意识到」不呼应。干扰点：孩子常打翻杯子是常识。</li><li>C ❌ carelessly（粗心地）与下文「没意识到杯位」的原因重复而非转折。干扰点：与 knock over 的「不小心」近义。</li><li>D ✅ 情态动词 may 表「可能」：孩子「可能」打翻牛奶，与下句 may not realize 的 may 原词复现。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：一个孩子可能会打翻餐桌上的牛奶杯。</p><p><strong>词组</strong>：<code>knock over</code> 碰倒；<code>a glass of milk</code> 一杯牛奶</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第2段 · 第6空所在句）：A child <strong>6</strong> knock over his or her glass of milk at the dinner table, but he or she may not realize that the glass was too close to the <strong>7</strong>.</p></details><p><strong>…but he or she may not realize that the glass was too close to the ____.</strong></p><ul><li>A. edge</li><li>B. table</li><li>C. hand</li><li>D. seat</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（edge）</strong> —— 杯子被碰倒是因为离桌「边」edge 太近。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 杯子被打翻是因为离桌「边」edge 太近，物理常识加因果线索吻合。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ table（桌子）与 too close to 搭配语义冗余——杯子本就在桌上。干扰点：只按 close to the table 的字面。</li><li>C ❌ hand（手）与「打翻」无因果关系。干扰点：联想到「手碰倒杯子」。</li><li>D ❌ seat（座位）与杯子的位置无关。干扰点：与 dinner table 的就座场景混淆。</li></ul><p><strong>整句翻译</strong>：但他或她可能没有意识到杯子离桌边太近了。</p><p><strong>词组</strong>：<code>too close to the edge</code> 离边缘太近；<code>at the dinner table</code> 在餐桌上</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第2段 · 第7空所在句）：A child <strong>6</strong> knock over his or her glass of milk at the dinner table, but he or she may not realize that the glass was too close to the <strong>7</strong>.</p></details><p><strong>The next step for a child is to learn how to solve the problem ____.</strong></p><ul><li>A. quickly</li><li>B. correctly</li><li>C. alone</li><li>D. simply</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（alone）</strong> —— 下一步是学会「独立」alone 解决问题。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ quickly（快速地）与后文「这步需要勇气、有些人怕错」无关。干扰点：把 next step 当「加快进度」。</li><li>B ❌ correctly（正确地）与 The two of you can decide 的「一起做」阶段冲突——本句强调「独立」。干扰点：solve correctly 是常见搭配。</li><li>C ✅ 下一步是学会「独自」alone 解决问题，与后文 Let the child try it out 的放手过程一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ simply（简单地）不能体现本段「孩子独立尝试」的主题。干扰点：与 simply=「仅仅」的副词义混淆。</li></ul><p><strong>整句翻译</strong>：孩子的下一步是学会如何独立解决这个问题。</p><p><strong>词组</strong>：<code>solve the problem alone</code> 独立解决问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第3段 · 第8空所在句）：The next step for a child is to learn how to solve the problem <strong>8</strong>.</p></details><p><strong>This step takes ____.</strong></p><ul><li>A. courage</li><li>B. skill</li><li>C. time</li><li>D. patience</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（courage）</strong> —— 与下文 afraid of being wrong 呼应：独立解决需要「勇气」courage。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与下句 Some people are so afraid of being wrong 呼应：独立解决需要「勇气」courage。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ skill（技能）与 afraid of being wrong 无因果。干扰点：problem-solving skills 原词干扰。</li><li>C ❌ time（时间）不能解释「怕错的人无法解题」。干扰点：takes time 是高频搭配。</li><li>D ❌ patience（耐心）与 afraid 的情绪线索不对应。干扰点：「慢慢来」的泛化联想。</li></ul><p><strong>整句翻译</strong>：这一步需要勇气。</p><p><strong>词组</strong>：<code>take courage</code> 需要勇气</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第3段 · 第9空所在句）：This step takes <strong>9</strong>.</p></details><p><strong>You can help by talking about some possible ____.</strong></p><ul><li>A. help</li><li>B. ways</li><li>C. answers</li><li>D. information</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（answers）</strong> —— 与下文 which answer is the best 呼应：讨论几种可能的「答案」answers。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ help 与 talking about some possible... 语义重复。干扰点：help 与上文 help 的原词干扰。</li><li>B ❌ ways（方法）与下句 which answer is the best 的 answer 不对应。干扰点：way 的「办法」泛义。</li><li>C ✅ 与下句 which answer is the best 复现：讨论几种可能的「答案」answers。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ information（信息）不能被 decide which is best 挑选。干扰点：talk about information 的搭配假象。</li></ul><p><strong>整句翻译</strong>：你可以通过谈论一些可能的答案来提供帮助。</p><p><strong>词组</strong>：<code>talk about</code> 谈论；<code>possible answers</code> 可能的答案</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第3段 · 第10空所在句）：You can help by talking about some possible <strong>10</strong>.</p></details><p><strong>Let the child ____ it out.</strong></p><ul><li>A. work</li><li>B. find</li><li>C. carry</li><li>D. try</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（try）</strong> —— let the child try it out 让孩子亲自试一试。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ work it out（解出）语义偏「算出/解决」，与「让孩子动手验证」不符。干扰点：work out 是高频短语动词。</li><li>B ❌ find out（查明）不接 it out 的形式。干扰点：find out 与 try out 形近。</li><li>C ❌ carry out（执行）宾语是 plan/order，不接指代 answer 的 it。干扰点：carry out 的搭配假象。</li><li>D ✅ let the child try it out 让孩子亲自试一试，try out 表「试用/实践」，符合「让孩子验证答案」的语境。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：让孩子亲自试一试。</p><p><strong>词组</strong>：<code>try out</code> 试验、试一试；<code>let sb. do</code> 让某人做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第3段 · 第11空所在句）：Let the child <strong>11</strong> it out.</p></details><p><strong>You can ____ him or her for choosing an answer.</strong></p><ul><li>A. praise</li><li>B. encourage</li><li>C. support</li><li>D. congratulate</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（praise）</strong> —— 孩子选出答案后，大人「表扬」praise 他。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ praise sb. for doing sth. 是固定搭配：孩子选出答案后大人「表扬」他，结构与语义都吻合。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ encourage 接 sb. to do，不接 for doing。干扰点：encourage 与 praise 中文都译「鼓励」。</li><li>C ❌ support（支持）不与 for choosing an answer 连用。干扰点：与「帮孩子」主题相关。</li><li>D ❌ congratulate 接 on doing 而非 for doing，语法不合。干扰点：「为……祝贺」与「表扬」语义相近。</li></ul><p><strong>整句翻译</strong>：现在孩子会发现问题是可以解决的，你也可以因他选出了答案而表扬他。</p><p><strong>词组</strong>：<code>praise sb. for doing sth.</code> 因某事表扬某人；<code>choose an answer</code> 选出答案</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第3段 · 第12空所在句）：Now the child will see that problems can be solved, and you can <strong>12</strong> him or her for choosing an answer.</p></details><p><strong>He or she might ____ to write on the wall but the pencil always leaves a ____.</strong></p><ul><li>A. happen</li><li>B. consider</li><li>C. like</li><li>D. choose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（like）</strong> —— might like to write on the wall 想「喜欢」在墙上写字，与后文铅笔留痕构成因果示例。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ happen to write 表「碰巧写」，与 always leaves a mark 的常态示例矛盾。干扰点：happen to do 是熟结构。</li><li>B ❌ consider 后接 doing，不接 to write。干扰点：consider=「考虑」语义接近。</li><li>C ✅ might like to write on the wall 想/喜欢在墙上写字，与「铅笔留痕」的因果示例一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ choose to write 表「选择写」，与「因果链示例」的语境不符。干扰点：choose to do 语法成立。</li></ul><p><strong>整句翻译</strong>：他或她可能喜欢在墙上写字，但铅笔总会留下痕迹。</p><p><strong>词组</strong>：<code>write on the wall</code> 在墙上写字；<code>leave a mark</code> 留下痕迹</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第4段 · 第13空所在句）：He or she might <strong>13</strong> to write on the wall but the pencil always leaves a <strong>14</strong>.</p></details><p><strong>He or she might like to write on the wall but the pencil always leaves a ____.</strong></p><ul><li>A. line</li><li>B. mark</li><li>C. drawing</li><li>D. point</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（mark）</strong> —— 铅笔总会在墙上留下「痕迹」mark。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ line（线）过于具体，铅笔在墙上留下的不只是线。干扰点：线=痕的近义误导。</li><li>B ✅ leave a mark 留下痕迹，mark 与「铅笔在墙上留痕」的常识吻合。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ drawing（图画）与 always leaves 的「必然结果」不符——不是每次都成画。干扰点：在墙上画画是典型意象。</li><li>D ❌ point（点/要点）与痕迹无关。干扰点：与 mark 的「点状」联想。</li></ul><p><strong>整句翻译</strong>：……但铅笔总会留下痕迹。</p><p><strong>词组</strong>：<code>leave a mark</code> 留下痕迹</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第4段 · 第14空所在句）：He or she might <strong>13</strong> to write on the wall but the pencil always leaves a <strong>14</strong>.</p></details><p><strong>Soon the child will see the link ____ cause and effect, and then he or she is on the road to growth.</strong></p><ul><li>A. between</li><li>B. if</li><li>C. both</li><li>D. in</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（between）</strong> —— the link between A and B 之间的联系，用 between。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the link between A and B 是固定搭配：孩子将看到原因和结果之间的联系。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ if 引导条件句，不能连接 link 与 cause and effect。干扰点：把「联系」误读成条件。</li><li>C ❌ both 需与 and 构成 both...and...，本句结构不符。干扰点：both 与 and 的粘连。</li><li>D ❌ in 与 cause and effect 不搭配。干扰点：in 的「在……中」泛义。</li></ul><p><strong>整句翻译</strong>：很快，孩子就会看到原因与结果之间的联系，然后他或她就走上了成长之路。</p><p><strong>词组</strong>：<code>the link between A and B</code> A 与 B 之间的联系；<code>on the road to growth</code> 在成长之路上</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 培养儿童解决问题的能力 · 第4段 · 第15空所在句）：Soon the child will see the link <strong>15</strong> cause and effect, and then he or she is on the road to growth.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>孩子遇到问题时可能不会处理，因此需要学习如何面对问题。帮助孩子学会解决问题，最好的方法是在问题发生时花时间和他讨论。当然，这并不容易，因为问题往往会在最糟糕的时刻突然出现；即便时机不好，也应尽力帮助。</p><p>帮助孩子学习解决问题的技能有很多办法，其中一个好方法是找出问题的成因。这种能力若没有帮助，孩子学不会。例如，孩子可能不小心打翻餐桌上的牛奶，却没有意识到杯子离桌边太近。成人可以指出问题所在，然后一起解决。</p><p>下一步是让孩子学会独立解决问题，而这需要勇气。有些人太怕犯错，以至于无法解决问题。你可以和孩子讨论几种可能的答案，再共同判断哪一个最好，让孩子亲自试一试。孩子由此会看到问题能够解决，成人也可以因他选出答案而表扬他。</p><p>还要帮助孩子理解因果关系：碰倒杯子，杯子就会落地打碎；孩子可能想在墙上写字，但铅笔总会留下痕迹。慢慢地，孩子会看见原因与结果之间的联系，走上成长之路。</p></details><h3 id="练习四-·-买爵士音乐会门票" tabindex="-1"><a class="header-anchor" href="#练习四-·-买爵士音乐会门票"><span>练习四 · 买爵士音乐会门票</span></a></h3><p>I was very disappointed not to be able to go to the jazz concert last Friday. The announcement in the paper said that you could buy <strong><strong>1</strong></strong> at the theater box office in Richland Hills any day between 10:00 a.m. and 4:00 p.m. Since I work from 9 a.m. to 5:30 p.m., the <strong><strong>2</strong></strong> time I could go to the theater was during my 45-minute lunch break. <strong><strong>3</strong></strong>, the theater is on the other side of the town, and the bus <strong><strong>4</strong></strong> between my office and Richland Hills is not very good. <strong><strong>5</strong></strong> if you are lucky, you can make the round trip in 45 minutes.</p><p>Last Monday I stood at the bus stop for fifteen minutes waiting for a bus. By the time I saw one come around the corner, there was not enough time <strong><strong>6</strong></strong> to make the trip so I gave <strong><strong>7</strong></strong> and went back to the office. The same thing happened on Tuesday, and <strong><strong>8</strong></strong> on Wednesday. On Thursday, my <strong><strong>9</strong></strong> changed. I got on a bus right away and arrived at the theater <strong><strong>10</strong></strong> exactly twenty minutes.</p><p>When I got there, however, I found a long line of people at the box office. I heard one man say he had been waiting in line for <strong><strong>11</strong></strong> an hour. <strong><strong>12</strong></strong> I would not have enough time to wait in line, I <strong><strong>13</strong></strong> the next bus and headed back across the town. By Friday I realized my only <strong><strong>14</strong></strong> was to make the trip by taxi. It was <strong><strong>15</strong></strong>. But I felt it would be worth it to hear the concert.</p><p><strong>The announcement in the paper said that you could buy ____ at the theater box office in Richland Hills.</strong></p><ul><li>A. food</li><li>B. stamps</li><li>C. tickets</li><li>D. newspapers</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（tickets）</strong> —— 去剧院售票处买的是「票」tickets。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ food（食物）不在剧院售票处出售，与 go to the jazz concert 的目的不符。干扰点：只按「在售票处能买到的东西」猜。</li><li>B ❌ stamps（邮票）与剧院场景无关。干扰点：box office 与邮局窗口的形象混淆。</li><li>C ✅ 去剧院售票处买的是音乐会的「票」tickets，与 to hear the concert 的目的呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ newspapers（报纸）与 buy...at the theater box office 场景矛盾——公告本身刊在报纸上。干扰点：被 in the paper 误导。</li></ul><p><strong>整句翻译</strong>：报纸上的公告说，每天上午十点到下午四点，你可以在里奇兰希尔斯剧院的售票处买到票。</p><p><strong>词组</strong>：<code>theater box office</code> 剧院售票处；<code>buy tickets</code> 买票</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第1段 · 第1空所在句）：The announcement in the paper said that you could buy <strong>1</strong> at the theater box office in Richland Hills any day between 10:00 a.m. and 4:00 p.m.</p></details><p><strong>Since I work from 9 a.m. to 5:30 p.m., the ____ time I could go to the theater was during my 45-minute lunch break.</strong></p><ul><li>A. early</li><li>B. exact</li><li>C. certain</li><li>D. only</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（only）</strong> —— 上班时间无法前往，午休是「唯一的」only 时间。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ early（早的）与 9 a.m. to 5:30 p.m. 的工作时段矛盾。干扰点：lunch break 是白天，误以为「还早」。</li><li>B ❌ exact（精确的）不修饰 time 的「排他性」。干扰点：与 exactly twenty minutes（第10空）的近义干扰。</li><li>C ❌ certain（某个）弱化了「只有午休能去」的排他含义。干扰点：a certain time 的搭配假象。</li><li>D ✅ 上班时段无法前往，午休是「唯一的」only 时间，与 only 在句中的排他语义吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：由于我上午九点上班、下午五点半下班，唯一能去剧院的时间就是四十五分钟的午休时间。</p><p><strong>词组</strong>：<code>the only time</code> 唯一的时间；<code>lunch break</code> 午休</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第1段 · 第2空所在句）：Since I work from 9 a.m. to 5:30 p.m., the <strong>2</strong> time I could go to the theater was during my 45-minute lunch break.</p></details><p><strong>____, the theater is on the other side of the town, and the bus ____ between my office and Richland Hills is not very good.</strong></p><ul><li>A. Surprisingly</li><li>B. Luckily</li><li>C. Unfortunately</li><li>D. Surely</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Unfortunately）</strong> —— 剧院远、公交差，是「不幸的是」Unfortunately。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Surprisingly（令人惊讶地）与「剧院远、公交差」这一可预期的困难不符。干扰点：把坏消息当「意外」。</li><li>B ❌ Luckily（幸运地）与「公交服务不好」语义相反。干扰点：与下句 if you are lucky 混淆。</li><li>C ✅ 剧院远在城另一头、公交班次差，对「我」是「不幸的是」Unfortunately，准确传达处境的不利。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ Surely（肯定地）是判断副词，不能引出客观处境的描述。干扰点：surely 的「确实」义。</li></ul><p><strong>整句翻译</strong>：不幸的是，剧院在城市的另一边，而且我办公室和里奇兰希尔斯之间的公交服务不太好。</p><p><strong>词组</strong>：<code>on the other side of the town</code> 在城市的另一边；<code>unfortunately</code> 不幸的是</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第1段 · 第3空所在句）：<strong>3</strong>, the theater is on the other side of the town, and the bus <strong>4</strong> between my office and Richland Hills is not very good.</p></details><p><strong>…and the bus ____ between my office and Richland Hills is not very good.</strong></p><ul><li>A. service</li><li>B. driver</li><li>C. seat</li><li>D. stop</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（service）</strong> —— 公交「服务」service 不好。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ bus service（公交服务/班次）与 not very good 搭配自然：班次少、车况差。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ driver（司机）与 between my office and Richland Hills 的范围状语不搭。干扰点：把「公交差」归咎于司机。</li><li>C ❌ seat（座位）不能被 between...and... 修饰。干扰点：公交与座位的常识联想。</li><li>D ❌ stop（车站）与 between A and B 连用逻辑不通——车站是点不是线。干扰点：bus stop 是熟词组。</li></ul><p><strong>整句翻译</strong>：……而且我办公室和里奇兰希尔斯之间的公交服务不太好。</p><p><strong>词组</strong>：<code>bus service</code> 公交服务/班次；<code>not very good</code> 不太好</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第1段 · 第4空所在句）：<strong>3</strong>, the theater is on the other side of the town, and the bus <strong>4</strong> between my office and Richland Hills is not very good.</p></details><p><strong>____ if you are lucky, you can make the round trip in 45 minutes.</strong></p><ul><li>A. So</li><li>B. Even</li><li>C. As</li><li>D. But</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（But）</strong> —— But if you are lucky 承上转折：就算运气好，45 分钟也只够往返一趟。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ So（所以）表结果，但「45 分钟够往返」不是「公交差」的顺承结果，而是让步下的侥幸。干扰点：把顺承关系误当因果。</li><li>B ❌ Even（即使）需与也/都呼应，单独位于句首不能与 if 从句构成完整让步。干扰点：even if 的粘连。</li><li>C ❌ As（由于/当）表原因或时间，与「if you are lucky」的条件不兼容。干扰点：as if 的搭配假象。</li><li>D ✅ But if you are lucky 承上转折：公交本就差，就算运气好，45 分钟也只够往返一趟。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：但如果运气好，四十五分钟也只够你往返一趟。</p><p><strong>词组</strong>：<code>make the round trip</code> 完成往返；<code>if you are lucky</code> 如果运气好</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第1段 · 第5空所在句）：<strong>5</strong> if you are lucky, you can make the round trip in 45 minutes.</p></details><p><strong>There was not enough time ____ to make the trip so I gave ____ and went back to the office.</strong></p><ul><li>A. remained</li><li>B. used</li><li>C. left</li><li>D. spent</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（left）</strong> —— time left 剩余时间；enough time left 没剩多少时间了。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ remained 作后置定语时多修饰名词且常带被动意味，time remained 不符合表达「剩余时间」的习惯。干扰点：remain=「剩余」的字面对应。</li><li>B ❌ used（被用掉的）与 not enough time 连用逻辑相反。干扰点：与 used to do 的形式混淆。</li><li>C ✅ time left 剩余时间：there was not enough time left to make the trip 没有足够的时间走完这一趟，left 作后置定语。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ spent（被花掉的）修饰 time 时表示「已花掉的时间」，与「不够」的语义方向相反。干扰点：spend time 是熟搭配。</li></ul><p><strong>整句翻译</strong>：等到我看见一辆车从街角开来时，已经没有足够的时间完成这一趟了，于是我放弃并回到了办公室。</p><p><strong>词组</strong>：<code>by the time</code> 等到……时；<code>there is not enough time left</code> 没有足够的时间剩下</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第2段 · 第6空所在句）：By the time I saw one come around the corner, there was not enough time <strong>6</strong> to make the trip so I gave <strong>7</strong> and went back to the office.</p></details><p><strong>There was not enough time left to make the trip so I gave ____ and went back to the office.</strong></p><ul><li>A. away</li><li>B. up</li><li>C. in</li><li>D. out</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（up）</strong> —— give up 放弃，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ give away（赠送/泄露）与「回到办公室」的语境不符。干扰点：give away 与 give up 形近。</li><li>B ✅ give up 放弃：时间不够便放弃行程、回办公室，固定搭配。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ give in（让步/屈服）后不接宾语也不接 this trip 语境。干扰点：give in 与 give up 中文都可译「让步/放弃」。</li><li>D ❌ give out（分发/用完）与 went back 的结果不符。干扰点：give out 的「耗尽」义与 time 场景混淆。</li></ul><p><strong>整句翻译</strong>：……于是我放弃并回到了办公室。</p><p><strong>词组</strong>：<code>give up</code> 放弃；<code>go back to the office</code> 回到办公室</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第2段 · 第7空所在句）：By the time I saw one come around the corner, there was not enough time <strong>6</strong> to make the trip so I gave <strong>7</strong> and went back to the office.</p></details><p><strong>The same thing happened on Tuesday, and ____ on Wednesday.</strong></p><ul><li>A. never</li><li>B. again</li><li>C. then</li><li>D. more</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（again）</strong> —— 同样的情况星期三「再次」again 发生。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ never（从不）与 happened on Tuesday 的「重复」矛盾。干扰点：只按「我运气差」否定。</li><li>B ✅ The same thing happened on Tuesday, and again on Wednesday：星期三「再次」again 发生，与上文的 the same thing 呼应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ then（然后）只表顺序，不能表达「同样情况重现」。干扰点：then 的顺承义。</li><li>D ❌ more（更多）不能直接修饰 on Wednesday。干扰点：more 与 again 的「再」义混淆。</li></ul><p><strong>整句翻译</strong>：星期二也发生了同样的事，星期三又发生了。</p><p><strong>词组</strong>：<code>the same thing happened</code> 同样的事情发生了；<code>and again</code> 再一次</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第2段 · 第8空所在句）：The same thing happened on Tuesday, and <strong>8</strong> on Wednesday.</p></details><p><strong>On Thursday, my ____ changed. I got on a bus right away.</strong></p><ul><li>A. time</li><li>B. bus</li><li>C. mind</li><li>D. luck</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（luck）</strong> —— 与前两天等不到车对比：星期四我的「运气」luck 变好了。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ time（时间）与 changed 搭配空泛，下文说的是「立刻上车」的运气转折。干扰点：星期四=时间。</li><li>B ❌ bus（公交车）与 changed 主谓不搭——车不是「变了」而是「来了」。干扰点：下句 got on a bus 原词干扰。</li><li>C ❌ mind（主意）与后文「立刻上车、二十分钟到」的好运无关。干扰点：change one’s mind 是熟词组。</li><li>D ✅ 与前两天等不到车对比，星期四我的「运气」luck 变好了——立刻上车、准点到达。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：星期四，我的运气变了。我立刻上了一辆公交车。</p><p><strong>词组</strong>：<code>luck changed</code> 运气转变；<code>get on a bus</code> 上公交车</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第2段 · 第9空所在句）：On Thursday, my <strong>9</strong> changed.</p></details><p><strong>I got on a bus right away and arrived at the theater ____ exactly twenty minutes.</strong></p><ul><li>A. in</li><li>B. for</li><li>C. at</li><li>D. about</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in）</strong> —— 「在二十分钟后」用 in twenty minutes。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ in + 时间段表示「在……之后」：arrived at the theater in exactly twenty minutes 恰好二十分钟后到达，与一般过去时连用表用时。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ for + 时间段表持续，arrive 是瞬间动词不与 for 连用。干扰点：for twenty minutes 的搭配假象。</li><li>C ❌ at + 具体时刻，twenty minutes 是时长不是时刻。干扰点：at 与 arrive 的常规搭配误导。</li><li>D ❌ about（大约）不能把 twenty minutes 变为时长状语。干扰点：与 exactly 的「精确」对比后误选。</li></ul><p><strong>整句翻译</strong>：我立刻上了一辆公交车，恰好二十分钟后就到了剧院。</p><p><strong>词组</strong>：<code>arrive in twenty minutes</code> 二十分钟后到达；<code>in + 时间段</code> 在……之后（表将来/用时）</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第2段 · 第10空所在句）：I got on a bus right away and arrived at the theater <strong>10</strong> exactly twenty minutes.</p></details><p><strong>I heard one man say he had been waiting in line for ____ an hour.</strong></p><ul><li>A. past</li><li>B. over</li><li>C. more</li><li>D. beyond</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（over）</strong> —— over an hour 一个多小时，固定表达。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ past 表「超过」时多作介词接地点或作名词，for past an hour 不成立。干扰点：past=「过」的字面义。</li><li>B ✅ over an hour 一个多小时：for over an hour 是表时长的固定表达。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ more 需与 than 连用（more than an hour）。干扰点：more 与 over 的近义。</li><li>D ❌ beyond（超出）接时间名词不表时长。干扰点：beyond=「超过」的语义对应。</li></ul><p><strong>整句翻译</strong>：我听见一个人说他已经排队等了一个多小时了。</p><p><strong>词组</strong>：<code>wait in line</code> 排队；<code>over an hour</code> 一个多小时</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第3段 · 第11空所在句）：I heard one man say he had been waiting in line for <strong>11</strong> an hour.</p></details><p><strong>____ I would not have enough time to wait in line, I ____ the next bus and headed back across the town.</strong></p><ul><li>A. Realizing</li><li>B. Awaking</li><li>C. Expecting</li><li>D. Understanding</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Realizing）</strong> —— 现在分词作状语：「意识到」Realizing 来不及排队。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Realizing 现在分词作原因状语：意识到来不及排队，所以赶回城另一边，与主句动作形成因果。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ Awaking（醒来）与语境无关。干扰点：awake 与 aware（意识到）形近。</li><li>C ❌ Expecting（期待）与「赶不上」的紧迫判断不符。干扰点：expect 与 realize 都可译「以为/知道」。</li><li>D ❌ Understanding（理解）偏「体谅」，不含「突然判断出」的即时性。干扰点：understand 与 realize 中文近义。</li></ul><p><strong>整句翻译</strong>：我意识到没有足够的时间排队，便赶上了下一班车，返回到城市的另一边。</p><p><strong>词组</strong>：<code>wait in line</code> 排队等候；<code>have enough time to do</code> 有足够时间做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第3段 · 第12空所在句）：<strong>12</strong> I would not have enough time to wait in line, I <strong>13</strong> the next bus and headed back across the town.</p></details><p><strong>Realizing I would not have enough time to wait in line, I ____ the next bus and headed back.</strong></p><ul><li>A. found</li><li>B. waited</li><li>C. caught</li><li>D. missed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（caught）</strong> —— catch the bus 赶上下一班车返回。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ found（找到）与 the next bus 搭配弱化「赶时间上车」的紧迫感。干扰点：found 与 caught 都可译「找到/赶上」。</li><li>B ❌ waited（等）与「没时间排队」的紧迫矛盾。干扰点：与上文 waiting in line 的原词干扰。</li><li>C ✅ catch the bus 赶上班车：caught the next bus and headed back 赶上下一班车返回，与「时间不够」的紧迫一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ missed（错过）与「返回」的结果矛盾。干扰点：missed 与 caught 的方向相反。</li></ul><p><strong>整句翻译</strong>：……便赶上了下一班车，返回到城市的另一边。</p><p><strong>词组</strong>：<code>catch the bus</code> 赶上公交车；<code>head back</code> 返回</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第3段 · 第13空所在句）：<strong>12</strong> I would not have enough time to wait in line, I <strong>13</strong> the next bus and headed back across the town.</p></details><p><strong>By Friday I realized my only ____ was to make the trip by taxi.</strong></p><ul><li>A. hope</li><li>B. plan</li><li>C. idea</li><li>D. expression</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（hope）</strong> —— 唯一的「希望」hope 是乘出租车。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 公交等不到、排队来不及，唯一「希望」hope 是乘出租车，与 only 的排他义吻合。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ plan（计划）与 realized 的「无奈下的结论」语气不符。干扰点：plan 与 hope 都可译「打算」。</li><li>C ❌ idea（主意）偏「点子」，不含「最后的办法」。干扰点：idea 与 hope 的中文模糊对应。</li><li>D ❌ expression（表达）与语境完全无关。干扰点：形近干扰。</li></ul><p><strong>整句翻译</strong>：到星期五，我意识到唯一的希望就是乘出租车走这一趟了。</p><p><strong>词组</strong>：<code>by taxi</code> 乘出租车；<code>the only hope</code> 唯一的希望</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第3段 · 第14空所在句）：By Friday I realized my only <strong>14</strong> was to make the trip by taxi.</p></details><p><strong>It was ____. But I felt it would be worth it to hear the concert.</strong></p><ul><li>A. cheap</li><li>B. comfortable</li><li>C. valuable</li><li>D. expensive</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（expensive）</strong> —— But 表转折：虽然「贵」expensive，但为了听音乐会值得。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cheap（便宜）与 But 转折后的「值得」不构成让步关系。干扰点：worth it 让人误以为「不贵」。</li><li>B ❌ comfortable（舒适）不是「但值得」的让步对象。干扰点：出租车=舒适的联想。</li><li>C ❌ valuable（有价值的）与 But 转折逻辑重复——「有价值但值得」不构成转折。干扰点：valuable 与 worth 的近义。</li><li>D ✅ It was expensive 与 But I felt it would be worth it 构成「贵但值得」的转折，语义吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：虽然很贵，但我觉得为了听这场音乐会是值得的。</p><p><strong>词组</strong>：<code>be worth it</code> 值得；<code>be expensive</code> 昂贵</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 买爵士音乐会门票 · 第3段 · 第15空所在句）：It was <strong>15</strong>.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>上星期五没能去听爵士音乐会，我非常失望。报纸上的公告说，每天上午十点到下午四点可以在里奇兰希尔斯剧院售票处买票。我每天九点上班、五点半下班，唯一能去剧院的时间就是四十五分钟午休。不幸的是，剧院在城市另一边，办公室到里奇兰希尔斯之间的公交服务并不好。即使运气好，四十五分钟也只够往返一趟。</p><p>上星期一，我在公交站等了十五分钟。看到一辆车从街角开来时，已经没有足够时间走完这一趟，于是我放弃并回到办公室。星期二如此，星期三又如此。星期四我的运气变了：立刻上了车，恰好二十分钟后到达剧院。</p><p>可是售票处排着长队，有人说自己已经排了一个多小时。我意识到没有时间继续等，只好赶上下一班车返回城的另一边。到星期五，我明白唯一的希望就是乘出租车。虽然很贵，但为了听音乐会，我认为值得。</p></details><h3 id="练习五-·-老师保护学生的尊严" tabindex="-1"><a class="header-anchor" href="#练习五-·-老师保护学生的尊严"><span>练习五 · 老师保护学生的尊严</span></a></h3><p>A young man came across his old teacher. “I became a teacher because you inspired me to be like you,” said the young man and told him the following story:</p><p>One day, a friend of mine <strong><em><strong>1</strong></em></strong> the classroom with a nice new watch. I loved it so much that I <strong><em><strong>2</strong></em></strong> it from him. As soon as my friend <strong><em><strong>3</strong></em></strong> he had lost his watch, he reported it <strong><em><strong>4</strong></em></strong> to our teacher, who was you. You went to the class, “This student’s watch was missing during classes today. Whoever has taken it, please <strong><em><strong>5</strong></em></strong> it.” At that time, I was <strong><em><strong>6</strong></em></strong> to raise my hand.</p><p>Then you shut the door and told us all to get up and began to <strong><em><strong>7</strong></em></strong> our pockets one by one. But you <strong><em><strong>8</strong></em></strong> us to close our eyes.</p><p>You went from pocket to pocket, and when my <strong><em><strong>9</strong></em></strong> came, you found the watch and took it. You <strong><em><strong>10</strong></em></strong> searching everyone’s pockets until you finished, you asked us to open our eyes. It was the most <strong><em><strong>11</strong></em></strong> day of my life. But this was also the day my <strong><em><strong>12</strong></em></strong> was saved.</p><p>You never <strong><em><strong>13</strong></em></strong> anything about the incident later, nor even gave me a right or wrong lesson, but I received your <strong><em><strong>14</strong></em></strong> clearly. I understood what a real educator needs to do.</p><p>If an educator must make students lose the <strong><em><strong>15</strong></em></strong> of other people, he doesn’t know how to teach.</p><p><strong>One day, a friend of mine ____ the classroom with a nice new watch.</strong></p><ul><li>A. watched</li><li>B. cleaned</li><li>C. entered</li><li>D. designed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（entered）</strong> —— 朋友「带着」新手表「走进」entered 教室。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ watched（观看）与 the classroom 搭配不当。干扰点：watch 与手表（watch）的同词干扰。</li><li>B ❌ cleaned（打扫）与 with a nice new watch 的语境不符。干扰点：只按「教室」联想「打扫」。</li><li>C ✅ entered the classroom with a watch 带着手表「走进」教室，enter 与 with 短语搭配自然。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ designed（设计）与 classroom 搭配不当。干扰点：由 new watch 联想「设计」。</li></ul><p><strong>整句翻译</strong>：一天，我的一个朋友戴着一块漂亮的新手表走进了教室。</p><p><strong>词组</strong>：<code>come across</code> 偶遇；<code>enter the classroom</code> 走进教室</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第1空所在句）：One day, a friend of mine <em><strong>1</strong></em> the classroom with a nice new watch.</p></details><p><strong>I loved it so much that I ____ it from him.</strong></p><ul><li>A. borrowed</li><li>B. stole</li><li>C. learned</li><li>D. heard</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（stole）</strong> —— 后文老师搜口袋找表，说明「我」是偷了 steal 它。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ borrowed（借）与后文老师搜口袋找表的情节矛盾——借东西不必藏。干扰点：borrow from 搭配成立。</li><li>B ✅ I loved it so much that I stole it from him：后文 Whoever has taken it 与搜口袋找表说明是「偷」steal。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ learned（学习/得知）与 it from him 搭配语义不通。干扰点：learn from 是熟搭配。</li><li>D ❌ heard（听说）与 it from him 搭配后无法解释后文找表的情节。干扰点：hear from 的搭配假象。</li></ul><p><strong>整句翻译</strong>：我实在太喜欢它了，就把它从他那里偷了过来。</p><p><strong>词组</strong>：<code>steal sth. from sb.</code> 从某人那里偷走某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第2空所在句）：I loved it so much that I <em><strong>2</strong></em> it from him.</p></details><p><strong>As soon as my friend ____ he had lost his watch, he reported it ____ to our teacher.</strong></p><ul><li>A. imagined</li><li>B. feared</li><li>C. realized</li><li>D. regretted</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（realized）</strong> —— 朋友一「发现」realized 手表丢了就报告老师。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ imagined（想象）丢失与 reported it 的紧迫链条矛盾。干扰点：imagine 与 realize 都可接从句。</li><li>B ❌ feared（害怕）丢失是心理活动，不能触发 as soon as 的即时报告。干扰点：fear 与「丢东西」的自然联想。</li><li>C ✅ As soon as my friend realized he had lost his watch：一「发现/意识到」realized 丢失就立刻报告，与 as soon as 呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ regretted（后悔）在「尚未找到表」时无从谈起。干扰点：regret 与丢失的常识联想。</li></ul><p><strong>整句翻译</strong>：我的朋友一发现手表丢了，就立刻报告给了老师——也就是您。</p><p><strong>词组</strong>：<code>as soon as</code> 一……就……；<code>realize</code> 发现、意识到</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第3空所在句）：As soon as my friend <em><strong>3</strong></em> he had lost his watch, he reported it <em><strong>4</strong></em> to our teacher, who was you.</p></details><p><strong>As soon as my friend realized he had lost his watch, he reported it ____ to our teacher.</strong></p><ul><li>A. immediately</li><li>B. obviously</li><li>C. possibly</li><li>D. actually</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（immediately）</strong> —— as soon as 一发现就报告，说明「立刻」immediately。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ reported it immediately to our teacher：与 as soon as（一……就……）呼应，报告是「立刻」immediately 发出的。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ obviously（明显地）是评注副词，不修饰「报告」的时效。干扰点：把「显然该报告」当「立即报告」。</li><li>C ❌ possibly（可能地）与 as soon as 的即时性矛盾。干扰点：possibly 的「也许」弱化判断。</li><li>D ❌ actually（实际上）不能体现动作的紧迫。干扰点：actually 的「确实」义。</li></ul><p><strong>整句翻译</strong>：……他就立刻把这件事报告给了老师。</p><p><strong>词组</strong>：<code>report sth. to sb.</code> 向某人报告某事；<code>immediately</code> 立刻</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第4空所在句）：As soon as my friend <em><strong>3</strong></em> he had lost his watch, he reported it <em><strong>4</strong></em> to our teacher, who was you.</p></details><p><strong>Whoever has taken it, please ____ it.</strong></p><ul><li>A. change</li><li>B. share</li><li>C. throw</li><li>D. return</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（return）</strong> —— 老师请拿表的人把表「归还」return。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ change（换）与「寻回失物」的目的不符。干扰点：change 与「交换」的联想。</li><li>B ❌ share（分享）与找表语境无关。干扰点：share 与「大家的东西」混淆。</li><li>C ❌ throw（扔掉）与「请谁拿表」的恳求相反。干扰点：与「交出」的方向混淆。</li><li>D ✅ 老师请拿表的人把表「归还」return，与 Whoever has taken it 的语境和寻表目的吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：无论谁拿了它，请把它还回来。</p><p><strong>词组</strong>：<code>whoever</code> 无论谁；<code>return sth.</code> 归还某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第5空所在句）：You went to the class, “This student’s watch was missing during classes today. Whoever has taken it, please <em><strong>5</strong></em> it.”</p></details><p><strong>At that time, I was ____ to raise my hand.</strong></p><ul><li>A. forced</li><li>B. annoyed</li><li>C. amazed</li><li>D. frightened</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（frightened）</strong> —— 偷了表不敢承认，「吓得」frightened 不敢举手。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ forced（被迫）与「承认偷表」的语境相反。干扰点：be forced to do 的搭配假象。</li><li>B ❌ annoyed（恼怒）与不敢承认的心理不符。干扰点：annoyed 与「被质问」的联想。</li><li>C ❌ amazed（惊讶）不能解释「不敢举手」。干扰点：amazed 与「意外」的联想。</li><li>D ✅ 偷了表不敢承认，「吓得」frightened 不敢举手，与 I was...to raise my hand 结构吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：当时，我害怕得不敢举手。</p><p><strong>词组</strong>：<code>raise one’s hand</code> 举手；<code>be frightened to do</code> 害怕得不敢做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第2段 · 第6空所在句）：At that time, I was <em><strong>6</strong></em> to raise my hand.</p></details><p><strong>Then you shut the door and told us all to get up and began to ____ our pockets one by one.</strong></p><ul><li>A. fill</li><li>B. search</li><li>C. exchange</li><li>D. use</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（search）</strong> —— 逐个「搜查」search 我们的口袋。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ fill（装满）与「找手表」的目的相反。干扰点：fill pockets 的搭配假象。</li><li>B ✅ began to search our pockets one by one 开始「搜查」口袋，与找表目的、from pocket to pocket 呼应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ exchange（交换）口袋与语境完全无关。干扰点：exchange 与「互相」的联想。</li><li>D ❌ use（使用）不能与 pockets 构成「找表」的动作链。干扰点：use 的泛义。</li></ul><p><strong>整句翻译</strong>：然后您关上门，让我们全体起立，开始逐个搜查我们的口袋。</p><p><strong>词组</strong>：<code>search one’s pockets</code> 搜某人的口袋；<code>one by one</code> 逐个地</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第3段 · 第7空所在句）：Then you shut the door and told us all to get up and began to <em><strong>7</strong></em> our pockets one by one.</p></details><p><strong>But you ____ us to close our eyes.</strong></p><ul><li>A. encouraged</li><li>B. expected</li><li>C. allowed</li><li>D. required</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（required）</strong> —— 老师「要求」required 大家闭上眼睛，为保护拿表者尊严。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ encouraged（鼓励）与搜口袋场景的严肃氛围不符。干扰点：encourage 与「配合老师」的联想。</li><li>B ❌ expected（期待）不含强制意味，而闭眼是搜身前的必要指令。干扰点：expect sb. to do 结构成立。</li><li>C ❌ allowed（允许）把「闭眼」当成可有可无的许可，与「保护尊严」的必要安排不符。干扰点：allow 的「准许」义。</li><li>D ✅ required us to close our eyes「要求」我们闭眼——既执行搜查又保护拿表者的尊严，与下文 never mentioned 的体贴一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：但您要求我们闭上眼睛。</p><p><strong>词组</strong>：<code>require sb. to do</code> 要求某人做某事；<code>close one’s eyes</code> 闭上眼睛</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第3段 · 第8空所在句）：But you <em><strong>8</strong></em> us to close our eyes.</p></details><p><strong>You went from pocket to pocket, and when my ____ came, you found the watch and took it.</strong></p><ul><li>A. turn</li><li>B. choice</li><li>C. chance</li><li>D. result</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（turn）</strong> —— 「轮到」turn 我时，老师找到了表。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ when my turn came「轮到」我时，turn 与 went from pocket to pocket、one by one 的「逐个」方式吻合。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ choice（选择）与「顺序轮到」无关。干扰点：choice 与「选口袋」的字面联想。</li><li>C ❌ chance（机会）与语境不符。干扰点：chance 与 turn 中文都可译「机会」。</li><li>D ❌ result（结果）不能与 came 搭配表顺序。干扰点：result came 的搭配假象。</li></ul><p><strong>整句翻译</strong>：您一个接一个口袋地搜过去，当轮到我时，您找到了手表并把它取走了。</p><p><strong>词组</strong>：<code>when my turn came</code> 当轮到我时；<code>go from...to...</code> 从一个……到另一个……</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第4段 · 第9空所在句）：You went from pocket to pocket, and when my <em><strong>9</strong></em> came, you found the watch and took it.</p></details><p><strong>You ____ searching everyone’s pockets until you finished, you asked us to open our eyes.</strong></p><ul><li>A. considered</li><li>B. continued</li><li>C. started</li><li>D. stopped</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（continued）</strong> —— 找到表后仍「继续」continued 搜完，不暴露拿表的人。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ considered（考虑）接动名词时语义为「考虑做」，与「搜完所有人」的事实不符。干扰点：consider doing 的结构。</li><li>B ✅ 找到表后仍「继续」continued 搜完每个人的口袋，直到结束——不暴露拿表的人，与保护尊严的主题一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ started（开始）与 already searching 的时序矛盾。干扰点：start doing 的搭配假象。</li><li>D ❌ stopped（停止）与 until you finished 矛盾。干扰点：stop doing 与语境方向相反。</li></ul><p><strong>整句翻译</strong>：您继续搜完每个人的口袋，直到结束，才让我们睁开眼睛。</p><p><strong>词组</strong>：<code>continue doing</code> 继续做某事；<code>until you finished</code> 直到结束</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第4段 · 第10空所在句）：You <em><strong>10</strong></em> searching everyone’s pockets until you finished, you asked us to open our eyes.</p></details><p><strong>It was the most ____ day of my life.</strong></p><ul><li>A. interesting</li><li>B. confusing</li><li>C. shameful</li><li>D. dangerous</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（shameful）</strong> —— 对偷表的「我」来说，被搜口袋是最「羞愧」shameful 的一天。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ interesting（有趣的）与偷表被抓的处境完全不符。干扰点：与故事性的表面联想。</li><li>B ❌ confusing（困惑的）不能刻画「偷表者被搜出」的自我感受。干扰点：confusing 与「意外」的联想。</li><li>C ✅ 对偷表的「我」来说，被搜口袋是最「羞愧」shameful 的一天，与偷表情节和第一人称忏悔一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ dangerous（危险的）与「搜口袋」场景的风险不符。干扰点：danger 与「被揭发」的联想。</li></ul><p><strong>整句翻译</strong>：那是我一生中最羞愧的一天。</p><p><strong>词组</strong>：<code>the most shameful day</code> 最羞愧的一天；<code>of my life</code> 我的一生中</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第4段 · 第11空所在句）：It was the most <em><strong>11</strong></em> day of my life.</p></details><p><strong>But this was also the day my ____ was saved.</strong></p><ul><li>A. goal</li><li>B. face</li><li>C. business</li><li>D. dream</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（face）</strong> —— 老师闭眼搜查保住了「我」的颜面（face）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ goal（目标）与 saved 搭配不当。干扰点：goal 与「人生目标」的联想。</li><li>B ✅ 老师闭眼搜查保住了「我」的颜面（face），face 与「尊严」的中文对应、save face 是惯用表达。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ business（生意）与语境无关。干扰点：business 与「事务」的泛义。</li><li>D ❌ dream（梦想）与 saved 不搭。干扰点：dream 与「人生」的高频搭配。</li></ul><p><strong>整句翻译</strong>：但这一天也是我的颜面得以保全的一天。</p><p><strong>词组</strong>：<code>save one’s face</code> 保全某人的颜面</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第4段 · 第12空所在句）：But this was also the day my <em><strong>12</strong></em> was saved.</p></details><p><strong>You never ____ anything about the incident later.</strong></p><ul><li>A. mentioned</li><li>B. described</li><li>C. argued</li><li>D. complained</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（mentioned）</strong> —— 老师后来从未「提起」mentioned 这件事。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ never mentioned anything about the incident 从未「提起」mentioned 这件事，与保护学生尊严的主题一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ described（描述）与 never...anything 连用过于具体。干扰点：describe 与「叙述」的近义。</li><li>C ❌ argued（争论）与「事后不再追究」相反。干扰点：argue 与「对错之争」的联想。</li><li>D ❌ complained（抱怨）主体应是受损一方，与老师身份不符。干扰点：complain about 的搭配。</li></ul><p><strong>整句翻译</strong>：后来，您对这件事只字未提。</p><p><strong>词组</strong>：<code>mention sth. about</code> 提及关于……的事；<code>the incident</code> 那件事</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第5段 · 第13空所在句）：You never <em><strong>13</strong></em> anything about the incident later, nor even gave me a right or wrong lesson, but I received your <em><strong>14</strong></em> clearly.</p></details><p><strong>…nor even gave me a right or wrong lesson, but I received your ____ clearly.</strong></p><ul><li>A. reason</li><li>B. excuse</li><li>C. report</li><li>D. message</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（message）</strong> —— 虽没批评，但「我」清楚收到了老师传递的「信息」message。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ reason（理由）与 received 搭配不当。干扰点：reason 与「道理」的中文对应。</li><li>B ❌ excuse（借口）含贬义，与老师用心不符。干扰点：excuse 与「解释」的近义。</li><li>C ❌ report（报告）与「无声的教诲」语境不符。干扰点：report 与「告知」的联想。</li><li>D ✅ 虽没批评，但「我」清楚收到了老师传递的「信息」message——收到 your message 与 clearly 搭配自然。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……但我清楚收到了您传递的信息，也明白了真正的教育者应当怎么做。</p><p><strong>词组</strong>：<code>receive one’s message</code> 接收到某人的信息；<code>clearly</code> 清楚地</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第5段 · 第14空所在句）：You never <em><strong>13</strong></em> anything about the incident later, nor even gave me a right or wrong lesson, but I received your <em><strong>14</strong></em> clearly.</p></details><p><strong>If an educator must make students lose the ____ of other people, he doesn’t know how to teach.</strong></p><ul><li>A. admiration</li><li>B. impression</li><li>C. trust</li><li>D. support</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（trust）</strong> —— 教育者不能让学生失去他人的「信任」trust。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ admiration（钦佩）与「让学生蒙羞」的代价不符。干扰点：admire 与「尊敬老师」的联想。</li><li>B ❌ impression（印象）与 lose 搭配偏「留下坏印象」，程度与语境不符。干扰点：impression 与「他人看法」的联想。</li><li>C ✅ 教育者不能让学生失去他人的「信任」trust，与全文「尊严/信任」主题呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ support（支持）与 lose 搭配主语应是「被帮助者」，逻辑不同。干扰点：support 与「帮助」的联想。</li></ul><p><strong>整句翻译</strong>：如果教育者一定要让学生失去他人的信任，他就不懂得怎样教育。</p><p><strong>词组</strong>：<code>lose the trust of others</code> 失去他人的信任；<code>know how to teach</code> 懂得怎样教育</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 老师保护学生的尊严 · 第6段 · 第15空所在句）：If an educator must make students lose the <em><strong>15</strong></em> of other people, he doesn’t know how to teach.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>一名年轻人偶遇从前的老师。他说：“我之所以当老师，是因为您激励我成为像您一样的人。”随后，他讲了下面的故事。</p><p>一天，我的一位朋友戴着一块漂亮的新手表走进教室。我太喜欢它了，于是从他那里偷走了它。朋友一发现手表丢了，立刻报告给老师——也就是您。您来到班里说：“今天上课期间，这名同学的手表不见了。无论是谁拿的，请把它还回来。”当时，我害怕得不敢举手。</p><p>您关上门，让全班起立，然后逐个搜查我们的口袋，但要求大家闭上眼睛。轮到我时，您找到了手表并取走，却继续搜完每个人的口袋，最后才叫大家睁眼。那是我一生中最羞愧的一天，却也是我的颜面得以保全的一天。</p><p>后来您从未提起这件事，甚至没有给我上一堂是非教育课，但我清楚收到了您传递的信息，也明白真正的教育者应当怎么做。如果教育者一定要让学生失去他人的信任，他就不懂得怎样教育。</p></details><h3 id="练习六-·-修理工的面试" tabindex="-1"><a class="header-anchor" href="#练习六-·-修理工的面试"><span>练习六 · 修理工的面试</span></a></h3><p>Tony is a warm-hearted repairman, who lost his job again a few months ago. He was really <strong><strong><strong>1</strong></strong></strong> applying for a new job.</p><p>One day, he brought together all his courage to go to a job interview. The interview was at 10 a.m. and it was already 8:30. While waiting for a bus, he saw a man <strong><strong><strong>2</strong></strong></strong> kicking one tyre（轮胎）of his car. Clearly, there was something wrong with the car. Tony <strong><strong><strong>3</strong></strong></strong> to help.</p><p>An hour later, Tony finished repairing the car, getting his shirt dirty. The man thanked him and wanted to pay for the <strong><strong><strong>4</strong></strong></strong>. “I was just helping out,” Tony <strong><strong><strong>5</strong></strong></strong>. “I have to rush for an interview now,” he added. “Well, I could take you there. It’s the <strong><strong><strong>6</strong></strong></strong> I could do, please!” the man insisted. Then Tony agreed.</p><p>While waiting in the long line of the applicants <strong><strong><strong>7</strong></strong></strong> his dirty shirt, Tony felt embarrassed and nervous. One by one, the applicants left the interviewer’s office with <strong><strong><strong>8</strong></strong></strong> looks on their faces. Finally his name was called.</p><p>The <strong><strong><strong>9</strong></strong></strong> was sitting on big chair with his back towards Tony. “Do you really need to be interviewed?” he asked. Tony’s heart sank. “With the way I <strong><em><strong><strong>10</strong></strong></em></strong> now, how could I possibly <strong><em><strong><strong>11</strong></strong></em></strong> this interview?” he thought to himself.</p><p>Then the interviewer <strong><em><strong><strong>12</strong></strong></em></strong> his chair. To Tony’s surprise, it was the man he helped earlier in the morning!</p><p>“Sorry to keep you waiting, but I was pretty sure I had made the <strong><em><strong><strong>13</strong></strong></em></strong> decision to have you in our company even <strong><em><strong><strong>14</strong></strong></em></strong> you came into this office. I just know you’d be a good worker I can <strong><em><strong><strong>15</strong></strong></em></strong>. Congratulations!”</p><p><strong>Tony is a warm-hearted repairman, who lost his job again a few months ago. He was really ____ applying for a new job.</strong></p><ul><li>A. afraid of</li><li>B. interested in</li><li>C. crazy about</li><li>D. sure of</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（afraid of）</strong> —— 屡次失业后鼓起勇气才去面试，说明他「害怕」afraid of 申请新工作。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 下文 he brought together all his courage to go to a job interview 说明求职让他忐忑，afraid of applying 与「鼓起勇气」正好互补。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ interested in 表「对……有兴趣」，与后文需要「鼓起勇气」的情节矛盾。干扰点：apply for a job 常与 interested in 连用，搭配顺口。</li><li>C ❌ crazy about 表「对……着迷」，失业数月的人对求职不会着迷，情绪方向与 courage 相反。干扰点：crazy about 也是常见搭配。</li><li>D ❌ sure of 表「对……有把握」，与后文 heart sank、felt nervous 的紧张基调冲突。干扰点：把「热心肠」误推为「自信」。</li></ul><p><strong>整句翻译</strong>：Tony 是一位热心的修理工，几个月前又失业了。他非常害怕申请新工作。</p><p><strong>词组</strong>：<code>apply for a new job</code> 申请新工作；<code>be afraid of doing sth.</code> 害怕做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第1段 · 第1空所在句）：He was really <strong><strong>1</strong></strong> applying for a new job.</p></details><p><strong>While waiting for a bus, he saw a man ____ kicking one tyre of his car.</strong></p><ul><li>A. excitedly</li><li>B. slowly</li><li>C. hardly</li><li>D. angrily</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（angrily）</strong> —— 车坏了，那人「愤怒地」angrily 踢轮胎。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ excitedly 表兴奋地，与「车出了问题」的语境矛盾。干扰点：只看到 kick 的动作就填情绪词。</li><li>B ❌ slowly 表慢慢地，无法解释下句 Clearly, there was something wrong with the car 的判断。干扰点：把「缓慢」误读成「无奈」。</li><li>C ❌ hardly 表几乎不，否定动作本身，与「正踢着轮胎」的场面相反；且 hardly 表频率否定，不作方式状语。干扰点：hard 与 hardly 形近混用。</li><li>D ✅ 踢轮胎是遇上麻烦时的发泄动作，angrily 与 Clearly, there was something wrong with the car 构成因果；后文 Tony 主动帮修车也说明对方正着急。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：等公交时，他看见一个男人愤怒地踢着自己汽车的一个轮胎。</p><p><strong>词组</strong>：<code>one tyre of his car</code> 他车上的一个轮胎；<code>kick a tyre</code> 踢轮胎</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第2段 · 第2空所在句）：While waiting for a bus, he saw a man <strong><strong>2</strong></strong> kicking one tyre（轮胎）of his car.</p></details><p><strong>Clearly, there was something wrong with the car. Tony ____ to help.</strong></p><ul><li>A. provided</li><li>B. offered</li><li>C. asked</li><li>D. promised</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（offered）</strong> —— offer to help 主动提出帮忙，符合热心修理工形象。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ provide 表「提供」，须接宾语（provide sb. with sth.），不能直接说 provided to help。干扰点：中文「提供帮助」直译。</li><li>B ✅ offer to do sth. 是固定搭配，表「主动提出做某事」，与 Tony 热心肠的人设一致；后文他修好车却不肯收钱也印证这份主动。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ ask to help 表「请求去帮忙」，但 Tony 是主动上前的一方，ask 的语义是「请求获准」。干扰点：把「上前帮忙」读成「被叫去帮忙」。</li><li>D ❌ promise to help 表「承诺帮忙」，通常发生在对方开口之后；本句是他自己上前，且下文才由对方道谢。干扰点：都表「答应」。</li></ul><p><strong>整句翻译</strong>：显然车出了问题，Tony 主动提出帮忙。</p><p><strong>词组</strong>：<code>offer to do sth.</code> 主动提出做某事；<code>something wrong with</code> ……出了问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第2段 · 第3空所在句）：Tony <strong><strong>3</strong></strong> to help.</p></details><p><strong>The man thanked him and wanted to pay for the ____.</strong></p><ul><li>A. car</li><li>B. tyre</li><li>C. work</li><li>D. time</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（work）</strong> —— 想为修车的「工作」work 付钱。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ pay for the car 表「付车款」，陌生人只是帮忙修车，不可能替对方买下整车。干扰点：场景里出现了 car，就近取材。</li><li>B ❌ 修的是轮胎，但付的是劳动报酬；把 tyre 填进去会让「感谢」落到物件上。干扰点：把修理对象当成付款对象。</li><li>C ✅ 上文 An hour later, Tony finished repairing the car 说明他付出的是劳动，pay for the work 即「付修理费」；后文 Tony 拒绝收款也印证这里指报酬。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ pay for the time 表「按时间付费」，而文中谈的是修车这件事的报酬，不是计时收费。干扰点：把「花了一小时」读成按小时计费。</li></ul><p><strong>整句翻译</strong>：男人向他道谢，并想为这次修车付钱。</p><p><strong>词组</strong>：<code>pay for sth.</code> 为……付钱；<code>finish doing sth.</code> 做完某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第3段 · 第4空所在句）：The man thanked him and wanted to pay for the <strong><strong>4</strong></strong>.</p></details><p><strong>“I was just helping out,” Tony ____.</strong></p><ul><li>A. refused</li><li>B. accepted</li><li>C. agreed</li><li>D. avoided</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（refused）</strong> —— 「只是顺手帮忙」，即「拒绝」refused 收钱。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后文 &quot;I was just helping out&quot;（我只是顺手帮忙）直接否定收款，故用 refused；紧接 the man insisted 说明对方还要再劝一次。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ accepted 表接受，若已接受就不会出现对方 insist 的第二次劝说。干扰点：看到 pay 就想到「接受付款」。</li><li>C ❌ agreed 表同意，与 I was just helping out 的谦让语气相反。干扰点：agreed 是高频词，凭语感填。</li><li>D ❌ avoid 后接 doing 而非 it，且表「回避某事」，无法指代「付款」这一动作。干扰点：把「不想收钱」说成「回避」。</li></ul><p><strong>整句翻译</strong>：“我只是顺手帮忙。”Tony 拒绝了。</p><p><strong>词组</strong>：<code>help out</code> 帮忙、搭把手；<code>the man insisted</code> 男人坚持（要付/要送）</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第3段 · 第5空所在句）：“I was just helping out,” Tony <strong><strong>5</strong></strong>.</p></details><p><strong>“Well, I could take you there. It’s the ____ I could do, please!” the man insisted.</strong></p><ul><li>A. most</li><li>B. best</li><li>C. least</li><li>D. worst</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（least）</strong> —— 开车送你是「我至少能做的」the least I could do。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ It’s the most I could do 表「我能做的最大程度」，用于回应对方拒绝报酬时语气过重。干扰点：按中文「尽我所能」直译成 most。</li><li>B ❌ the best I could do 侧重「尽力做到最好」，而此处只是顺路送一程的小事。干扰点：best 与 least 同为最高级，凭褒义选词。</li><li>C ✅ It’s the least I could do. 是英语客套固定说法，意为「这是我至少能做的」，用来回应对方不肯收报酬；least 表最小限度，恰好匹配「送一程」的举手之劳。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ the worst I could do 表「我能做的最坏的事」，与感谢的语气完全相反。干扰点：只按「最高级 + 贬义」排除，忽略固定说法。</li></ul><p><strong>整句翻译</strong>：“好吧，我可以送你过去。这是我至少能做的事，拜托了！”男人坚持道。</p><p><strong>词组</strong>：<code>the least I could do</code> 这是我至少能做的（客套说法）；<code>insist</code> 坚持</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第3段 · 第6空所在句）：“Well, I could take you there. It’s the <strong><strong>6</strong></strong> I could do, please!”</p></details><p><strong>While waiting in the long line of the applicants ____ his dirty shirt, Tony felt embarrassed and nervous.</strong></p><ul><li>A. in</li><li>B. for</li><li>C. with</li><li>D. of</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in）</strong> —— in his dirty shirt 穿着脏衬衫排队，in 表「穿着」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ in + 衣物表「穿着」，the applicants in his dirty shirt 即「穿着脏衬衫的应聘者」，正是他感到尴尬的原因。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ for his dirty shirt 表「为了脏衬衫」，与排队等候的场景无关。干扰点：由 waiting 顺推出 waiting for。</li><li>C ❌ with 表伴随或「带有」，with his dirty shirt 会读成「随身带着衬衫」，说明不了他此刻的穿着状态。干扰点：with 也可表伴随，但这里描述的是身上穿着。</li><li>D ❌ of 表所属，the applicants of his dirty shirt 不成语义。干扰点：把 of 当万能介词。</li></ul><p><strong>整句翻译</strong>：穿着脏衬衫排在长长的应聘者队伍里时，Tony 既尴尬又紧张。</p><p><strong>词组</strong>：<code>in a dirty shirt</code> 穿着脏衬衫；<code>the long line of the applicants</code> 长长的应聘者队伍</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第4段 · 第7空所在句）：While waiting in the long line of the applicants <strong><strong>7</strong></strong> his dirty shirt, Tony felt embarrassed and nervous.</p></details><p><strong>One by one, the applicants left the interviewer’s office with ____ looks on their faces.</strong></p><ul><li>A. satisfied</li><li>B. disappointed</li><li>C. worried</li><li>D. pleased</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（disappointed）</strong> —— 面试难，应聘者一个个「失望地」disappointed 走出办公室。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ satisfied 表情满意，与「一个个离场、名额有限」的语境相反。干扰点：忽略上下文基调，只按「面完试」想象。</li><li>B ✅ 面试陆续进行、前面的人一个个走出且后面才轮到 Tony，说明机会有限；with disappointed looks 与前文 felt embarrassed and nervous 的低落气氛一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ worried 表「担心」，是结果未定时的情绪；他们已面完并离开，情绪来自结果。干扰点：把 Tony 的紧张情绪套到别人身上。</li><li>D ❌ pleased 与 disappointed 完全相反；若人人都满意，后文 Tony 也不会 heart sank。干扰点：褒义形容词随手填。</li></ul><p><strong>整句翻译</strong>：应聘者一个接一个地走出面试官的办公室，脸上带着失望的神情。</p><p><strong>词组</strong>：<code>one by one</code> 一个接一个；<code>with disappointed looks</code> 带着失望的神情</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第4段 · 第8空所在句）：One by one, the applicants left the interviewer’s office with <strong><strong>8</strong></strong> looks on their faces.</p></details><p><strong>The ____ was sitting on big chair with his back towards Tony.</strong></p><ul><li>A. clerk</li><li>B. customer</li><li>C. applicant</li><li>D. interviewer</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（interviewer）</strong> —— 坐在办公室里提问的人是「面试官」interviewer。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ clerk 表职员/文员，而此人是坐主位并主持发问的一方。干扰点：把办公室里的工作人员都叫 clerk。</li><li>B ❌ customer 表顾客，与面试场景无关。干扰点：受前文修车顾客影响而串场。</li><li>C ❌ applicant 表应聘者，但发问的是他（Do you really need to be interviewed?），Tony 才是 applicant，角色错位。干扰点：把现场唯一的另一个角色当成同类。</li><li>D ✅ 下句 &quot;Do you really need to be interviewed?&quot; he asked 说明此人在考问 Tony，后文他转过身露出真容，正是早晨被帮助的人——interviewer（面试官）。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：面试官背对 Tony 坐在一把大椅子上。</p><p><strong>词组</strong>：<code>with one’s back towards sb.</code> 背对某人；<code>sink</code> （心情）下沉</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第5段 · 第9空所在句）：The <strong><strong>9</strong></strong> was sitting on big chair with his back towards Tony.</p></details><p><strong>“With the way I ____ now, how could I possibly ____ this interview?” he thought.</strong></p><ul><li>A. talk</li><li>B. stand</li><li>C. look</li><li>D. wait</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（look）</strong> —— 看「我」现在这副样子（脏衬衫），the way I look。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the way I talk 说的是说话方式，与他的脏衬衫无关。干扰点：按「面试靠表达」的常识选词。</li><li>B ❌ the way I stand 表站姿，前文并未描写他的站姿。干扰点：由排队场景联想到站位。</li><li>C ✅ 前文交代他修完车 getting his shirt dirty、又 felt embarrassed，他担心的正是外表，故 the way I look now（我现在这副样子）。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ the way I wait 表等待的方式，与后句 how could I possibly… 的反问缺乏因果。干扰点：他正在排队等待，就近取材。</li></ul><p><strong>整句翻译</strong>：“看我现在这副样子，怎么可能通过这场面试？”他心想。</p><p><strong>词组</strong>：<code>the way I look</code> 我这副模样；<code>how could I possibly…</code> 我怎么可能……</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第5段 · 第10空所在句）：“With the way I <em><strong><strong>10</strong></strong></em> now, how could I possibly <em><strong><strong>11</strong></strong></em> this interview?” he thought to himself.</p></details><p><strong>With the way I look now, how could I possibly ____ this interview?</strong></p><ul><li>A. fail</li><li>B. pass</li><li>C. lose</li><li>D. win</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（pass）</strong> —— 心想不可能「通过」pass 面试（后文证明想错了）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ fail this interview 表「面试失败」，放在 how could I possibly… 的反问里会变成「我怎么可能不失败」，语义反了。干扰点：忽略反问的否定语气。</li><li>B ✅ 反问 how could I possibly… 表「我不可能……」，他担心的是通不过，故用 pass this interview（通过面试）。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ lose 不与 interview 搭配（可说 lose a job/game）。干扰点：把「失去机会」直译成 lose。</li><li>D ❌ win 多与比赛、奖项连用，win an interview 不成立；面试谈的是「通过」。干扰点：与 pass 同义域，凭褒义选词。</li></ul><p><strong>整句翻译</strong>：“看我现在这副样子，怎么可能通过这场面试？”</p><p><strong>词组</strong>：<code>pass an interview</code> 通过面试；<code>possibly</code> （用于反问）怎么可能</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第5段 · 第11空所在句）：“With the way I <em><strong><strong>10</strong></strong></em> now, how could I possibly <em><strong><strong>11</strong></strong></em> this interview?” he thought to himself.</p></details><p><strong>Then the interviewer ____ his chair. To Tony’s surprise, it was the man he helped earlier!</strong></p><ul><li>A. knocked</li><li>B. broke</li><li>C. shook</li><li>D. turned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（turned）</strong> —— 背对 Tony 的面试官「转过」turned 椅子，正是早晨被他帮助的人。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ knock his chair 表敲椅子，不会造成「露出面孔」的结果。干扰点：只找一个能与 chair 搭配的动词。</li><li>B ❌ break his chair 表弄坏椅子，与情节无关。干扰点：同上，动作与语境脱节。</li><li>C ❌ shake his chair 表摇晃椅子，仍不能产生「转身面对 Tony」的效果。干扰点：忽略下句需要「看到脸」作前提。</li><li>D ✅ 下句 To Tony’s surprise, it was the man he helped earlier 说明他此前背对 Tony、此刻转过身来，故 turned his chair。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：接着面试官转动了他的椅子。令 Tony 吃惊的是，那正是他早上帮过的人！</p><p><strong>词组</strong>：<code>turn one’s chair</code> 转动椅子、转过身来；<code>to one’s surprise</code> 令某人惊讶的是</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第6段 · 第12空所在句）：Then the interviewer <em><strong><strong>12</strong></strong></em> his chair.</p></details><p><strong>I was pretty sure I had made the ____ decision to have you in our company.</strong></p><ul><li>A. wrong</li><li>B. right</li><li>C. silly</li><li>D. careful</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（right）</strong> —— 录用你是「正确的」right 决定。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wrong 表「错误的」，与最终录用并祝贺的结果相反。干扰点：忽略前后一致的正面走向。</li><li>B ✅ 后文 I just know you’d be a good worker… Congratulations! 说明他确信录用 Tony 是对的，故 the right decision。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ silly 表「愚蠢的」，与道谢并祝贺的态度完全相反。干扰点：把 pretty sure 读成「随口一说」。</li><li>D ❌ careful 表「谨慎的」，强调过程审慎而非结果正确，与 even before you came into this office 的果断不符。干扰点：把「早已确定」理解成「深思熟虑」。</li></ul><p><strong>整句翻译</strong>：抱歉让你久等了，但在你走进这间办公室之前，我就很确定，录用你进我们公司是个正确的决定。</p><p><strong>词组</strong>：<code>make the right decision</code> 做出正确的决定；<code>be pretty sure</code> 十分确定</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第7段 · 第13空所在句）：“Sorry to keep you waiting, but I was pretty sure I had made the <em><strong><strong>13</strong></strong></em> decision to have you in our company even <em><strong><strong>14</strong></strong></em> you came into this office.</p></details><p><strong>…even ____ you came into this office.</strong></p><ul><li>A. until</li><li>B. after</li><li>C. before</li><li>D. since</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（before）</strong> —— 「在你走进办公室之前」before 就确定了。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ until 表「直到……才」，会读成「直到你进来我才确定」，与 even 强调的「更早」相反。干扰点：until 也是常见时间连词。</li><li>B ❌ after 表「在你进来之后」，与「早就确定」的时间方向矛盾。干扰点：只按时间先后顺推。</li><li>C ✅ even before you came into this office（甚至在你走进办公室之前）与 I was pretty sure 呼应，说明他在面试之前就下定了决心。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ since 表「自从」，需要完成时配合，且语义是「自你进来以来」。干扰点：since 引导时间状语从句很常见。</li></ul><p><strong>整句翻译</strong>：……甚至在你走进这间办公室之前（我就已经决定了）。</p><p><strong>词组</strong>：<code>even before</code> 甚至在……之前；<code>be pretty sure</code> 十分确定</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第7段 · 第14空所在句）：“Sorry to keep you waiting, but I was pretty sure I had made the <em><strong><strong>13</strong></strong></em> decision to have you in our company even <em><strong><strong>14</strong></strong></em> you came into this office.</p></details><p><strong>I just know you’d be a good worker I can ____.</strong></p><ul><li>A. trust</li><li>B. depend</li><li>C. meet</li><li>D. praise</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（trust）</strong> —— 你会成为值得「信赖」trust 的好员工。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ I can trust 是省略关系代词的定语从句，trust 表「信任」，与 good worker 的评价一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ depend 表「依靠」，必须与 on 连用，从句中并没有 on。干扰点：中文「可以依靠的员工」直译。</li><li>C ❌ meet a worker 表「见到/认识这名员工」，与 good worker 的评价逻辑断裂。干扰点：把定语从句读成「我能见到的」。</li><li>D ❌ praise 表「表扬」，与面试官对 Tony 品格的判断相比偏浅，上文强调的是可靠。干扰点：都是褒义动词，凭好坏选词。</li></ul><p><strong>整句翻译</strong>：我只知道你会是一个我可以信任的好员工。恭喜！</p><p><strong>词组</strong>：<code>a good worker I can trust</code> 一个我可以信任的好员工；<code>trust sb.</code> 信任某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 修理工的面试 · 第7段 · 第15空所在句）：I just know you’d be a good worker I can <em><strong><strong>15</strong></strong></em>.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>Tony 是一位热心的修理工，几个月前又失业了。他很害怕申请新工作。一天，他鼓足勇气去面试。面试十点开始，当时已是八点半。等公交时，他看见一个男人愤怒地踢汽车轮胎，显然车出了问题，Tony 主动上前帮忙。</p><p>一小时后，Tony 修好了车，衬衫也弄脏了。男人感谢他并想付修理费，Tony 拒绝道：“我只是顺手帮忙。我现在得赶去面试。”男人坚持开车送他，说这是自己至少能做的事，Tony 便同意了。</p><p>Tony 穿着脏衬衫排在长长的应聘者队伍里，既尴尬又紧张。应聘者一个个带着失望的神情走出办公室。终于叫到 Tony。面试官背对他坐在一把大椅子上，问：“你真的还需要接受面试吗？”Tony 心一沉，心想：“看我现在这个样子，怎么可能通过面试？”</p><p>面试官转过椅子，竟是 Tony 早晨帮助过的男人。他说：“抱歉让你久等了，但在你走进办公室之前，我就很确定，让你加入公司是正确决定。我知道你会成为一个值得信赖的好员工。恭喜！”</p></details><h3 id="练习七-·-纸袋里的爱" tabindex="-1"><a class="header-anchor" href="#练习七-·-纸袋里的爱"><span>练习七 · 纸袋里的爱</span></a></h3><p>It was Molly’s job to hand her father his paper lunch bag each morning before he left home to work. One morning, besides his <strong><strong><strong>1</strong></strong></strong> lunch bag, Molly handed him a second paper bag, which looked a bit old.</p><p>“Why two bags?” her father asked. “The other is something else,” Molly answered. “What’s in it?” “Just something. Take it with you.”</p><p>He put <strong><em><strong>2</strong></em></strong> paper bags into his briefcase（公文包）, kissed Molly and rushed off. At noon he opened Molly’s bag and took out all the things: a small Teddy bear, 2 tiny sea shells（贝壳）, 5 small stones, and 12 coins… The <strong><em><strong>3</strong></em></strong> father smiled, finished eating, and swept the desk clean into the wastebasket, Molly’s things in the bag included, and then put himself into the afternoon work.</p><p>That evening, Molly ran up to him <strong><em><strong>4</strong></em></strong> he was reading the newspaper.</p><p>“Where’s my bag?” “What’s bag?” “The one I gave you this morning.”</p><p>“I <strong><em><strong>5</strong></em></strong> it at the office. Why?” “I forgot to put this <strong><em><strong>6</strong></em></strong> in it,” she said. “And, besides, Daddy, the things in the bag are the things I really like—I thought you might like to <strong><em><strong>7</strong></em></strong> with them. You didn’t lose the bag, did you, Daddy?”</p><p>“Oh, no. I just forgot to bring it home,” he <strong><em><strong>8</strong></em></strong>.</p><p>While Molly hugged her father’s neck, he opened the note that read: “I love you, Daddy.” Molly had given him her <strong><em><strong>9</strong></em></strong>—all that a 7-year-old held.</p><p>Love in a paper bag, and he <strong><em><strong>10</strong></em></strong> it. He had even thrown it in the wastebasket. So back he went hurriedly to the <strong><em><strong>11</strong></em></strong>. Just before the night cleaner, he found all the things back and carried the bag home <strong><em><strong>12</strong></em></strong>.</p><p>After dinner, he asked Molly to tell him about the things in the bag. It <strong><em><strong>13</strong></em></strong> a long time to tell. <strong><em><strong>14</strong></em></strong> had a story or a memory.</p><p>The life journey with the people we love is all that really matters. It is such a simple <strong><em><strong>15</strong></em></strong> but it is so easily forgotten.</p><p><strong>One morning, besides his ____ lunch bag, Molly handed him a second paper bag.</strong></p><ul><li>A. usual</li><li>B. new</li><li>C. spare</li><li>D. warm</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（usual）</strong> —— 除了「平常的」usual 午餐袋，又多递了一个袋子。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ besides his usual lunch bag…a second paper bag 是对比结构：与「第二个」相对的是「一惯的那个」，故填 usual。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ new 表「新的」，若第一个袋子是新的，第二个就不能算「额外」；且后文特意说第二个 looked a bit old。干扰点：把 second 读成 new。</li><li>C ❌ spare 表「备用的」，含「多余」义，与 second 语义重复。干扰点：spare 与 usual 都能修饰 bag，凭中文语感选词。</li><li>D ❌ warm 表「温暖的」，与午餐袋的日常功能无关。干扰点：把 lunch bag 想象成保温袋。</li></ul><p><strong>整句翻译</strong>：一天早晨，除了他平常的那个午餐袋，Molly 还递给他第二个纸袋。</p><p><strong>词组</strong>：<code>usual</code> 平常的、一贯的；<code>hand sb. sth.</code> 把某物递给某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第1段 · 第1空所在句）：One morning, besides his <strong><strong>1</strong></strong> lunch bag, Molly handed him a second paper bag, which looked a bit old.</p></details><p><strong>He put ____ paper bags into his briefcase, kissed Molly and rushed off.</strong></p><ul><li>A. all</li><li>B. both</li><li>C. some</li><li>D. many</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（both）</strong> —— 两个袋子用「both」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ all 用于三者及以上，而文中明确是两个袋子。干扰点：忽略上文 Why two bags? 的数量线索。</li><li>B ✅ 上文已交代两个袋子，此处指「两个都放进公文包」，故用 both；与下句 kissed Molly and rushed off 的动作连成一气。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ some 表「一些」，与已知的确切数量不符，且 some 后接不可数名词或不确定的复数。干扰点：把确定数量模糊化。</li><li>D ❌ many 表「许多」，与 two 直接冲突。干扰点：可数名词复数前随手填 many。</li></ul><p><strong>整句翻译</strong>：他把两个纸袋都放进公文包，亲了亲 Molly 就匆匆出门了。</p><p><strong>词组</strong>：<code>put sth. into</code> 把某物放进；<code>rush off</code> 匆匆离开</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第3段 · 第2空所在句）：He put <em><strong>2</strong></em> paper bags into his briefcase（公文包）, kissed Molly and rushed off.</p></details><p><strong>The ____ father smiled, finished eating, and swept the desk clean into the wastebasket.</strong></p><ul><li>A. angry</li><li>B. careful</li><li>C. busy</li><li>D. strict</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（busy）</strong> —— 吃完就扫桌继续工作，是「忙碌的」busy 父亲。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ angry 表生气，与句中的 smiled 直接矛盾。干扰点：忽略句内已给的 smiled。</li><li>B ❌ careful 表细心，与 swept the desk clean into the wastebasket 的随手一扔相反。干扰点：按「好父亲」形象填褒义词。</li><li>C ✅ 与 finished eating…then put himself into the afternoon work 呼应：他赶着投入下午的工作，才会连同女儿的心意一起扫进废纸篓。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ strict 表严格，与「匆忙」这一语境无关。干扰点：把「严厉」与「忙碌」混为一谈。</li></ul><p><strong>整句翻译</strong>：这位忙碌的父亲笑了笑，吃完饭就把桌上的东西连同纸袋一起扫进废纸篓。</p><p><strong>词组</strong>：<code>sweep sth. clean</code> 把……清扫干净；<code>put oneself into work</code> 投入工作</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第3段 · 第3空所在句）：At noon he opened Molly’s bag and took out all the things: a small Teddy bear, 2 tiny sea shells（贝壳）, 5 small stones, and 12 coins… The <em><strong>3</strong></em> father smiled, finished eating, and swept the desk clean into the wastebasket, Molly’s things in the bag included, and then put himself into the afternoon work.</p></details><p><strong>That evening, Molly ran up to him ____ he was reading the newspaper.</strong></p><ul><li>A. since</li><li>B. till</li><li>C. as</li><li>D. because</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（as）</strong> —— 「当他正在读报时」as 引导时间状语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ since 表「自从/因为」，表时间时主句需用完成时，且此处要的是「当……时」。干扰点：since 也能引导时间状语从句。</li><li>B ❌ till 表「直到」，与 ran up to him 这一瞬时动作不搭。干扰点：只按「时间连词」类别填空。</li><li>C ✅ as 引导时间状语从句表「当……的时候」，与主句 ran up to him 的动作同时发生，正合「父亲在看报、女儿跑过来」。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ because 表原因，但「读报」不是「跑过来」的原因。干扰点：把同时关系误判为因果关系。</li></ul><p><strong>整句翻译</strong>：那天晚上，父亲正在看报纸时，Molly 跑了过来。</p><p><strong>词组</strong>：<code>run up to sb.</code> 跑向某人；<code>as…</code> 当……的时候</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第4段 · 第4空所在句）：That evening, Molly ran up to him <em><strong>4</strong></em> he was reading the newspaper.</p></details><p><strong>“I ____ it at the office. Why?”</strong></p><ul><li>A. forgot</li><li>B. hid</li><li>C. kept</li><li>D. left</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（left）</strong> —— leave sth. + 地点 表示把东西「落在」某处：left it at the office。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ forget 表「忘了」，但本题宾语 it 指袋子，forget it 是「忘掉这件事」，不等于「忘在某处」。干扰点：中文「忘在办公室」直译成 forgot it。</li><li>B ❌ hid 表藏起来，与女儿后面「忘了放便条进去」的追问不合。干扰点：凭「找不到」猜「藏」。</li><li>C ❌ kept 表「留在办公室保管」，含主动保管义，与父亲的随意不符。干扰点：只求语法通顺。</li><li>D ✅ leave sth. at the office 是「把某物落在办公室」的固定表达，与后文女儿提起便条、父亲只好补谎的情节吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“我把它落在办公室了。怎么了？”</p><p><strong>词组</strong>：<code>leave sth. at/in a place</code> 把某物落在某处；<code>at the office</code> 在办公室</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第6段 · 第5空所在句）：“I <em><strong>5</strong></em> it at the office. Why?”</p></details><p><strong>“I forgot to put this ____ in it,” she said.</strong></p><ul><li>A. letter</li><li>B. message</li><li>C. diary</li><li>D. note</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（note）</strong> —— 与下文 he opened the note 呼应：忘了放「便条」note。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ letter 表「信」，需要信封与寄送，而这是折在袋子里的纸片。干扰点：把文字载体笼统叫 letter。</li><li>B ❌ message 偏「传达的信息」，多用于口头或电子形式，而后面父亲是打开纸片看到字。干扰点：message 与 note 同义域。</li><li>C ❌ diary 表「日记」，是连续记录的本子，不会随手放进袋子送人。干扰点：由「写东西」联想到 diary。</li><li>D ✅ 后文 he opened the note that read: &quot;I love you, Daddy.&quot; 直接复现，说明女儿放的是便条。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“我忘了把这个便条放进去，”她说。</p><p><strong>词组</strong>：<code>put sth. in</code> 把某物放进；<code>a note that read…</code> 上面写着……的便条</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第6段 · 第6空所在句）：“I forgot to put this <em><strong>6</strong></em> in it,” she said.</p></details><p><strong>The things in the bag are the things I really like—I thought you might like to ____ with them.</strong></p><ul><li>A. play</li><li>B. joke</li><li>C. talk</li><li>D. deal</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（play）</strong> —— 七岁孩子以为爸爸会喜欢拿这些宝贝「玩」play。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ play with sth. 表「拿……玩」，正合七岁孩子把玩具、石头当作玩伴的口吻。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ joke with sb. 表「和某人开玩笑」，宾语须是人。干扰点：把 with 视为万能搭配。</li><li>C ❌ talk with sb. 同样需要人为宾语，不能接 them 指代石头和贝壳。干扰点：忽略宾语是物。</li><li>D ❌ deal with 表「处理」，与「喜欢这些东西、想分享」的语气相反。干扰点：只按能接 with 的动词清单填。</li></ul><p><strong>整句翻译</strong>：袋子里装的是我真正喜欢的东西——我以为你也许会喜欢拿它们玩。</p><p><strong>词组</strong>：<code>play with sth.</code> 拿某物玩；<code>really like</code> 真正喜欢</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第6段 · 第7空所在句）：“And, besides, Daddy, the things in the bag are the things I really like—I thought you might like to <em><strong>7</strong></em> with them. You didn’t lose the bag, did you, Daddy?”</p></details><p><strong>“Oh, no. I just forgot to bring it home,” he ____.</strong></p><ul><li>A. lied</li><li>B. promised</li><li>C. nodded</li><li>D. agreed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（lied）</strong> —— 其实袋子已被扔掉，父亲在「撒谎」lied。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 上文他确实把袋子落在办公室、甚至把东西扔进了废纸篓，说「只是忘了带回来」是掩盖真相，故用 lied；与后文 hurriedly 赶回办公室的补救动作一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ promise 表承诺，此处只是回答女儿的追问，并不含承诺。干扰点：把「解释」当成「承诺」。</li><li>C ❌ nod 表点头，无法与引号内的完整答语（Oh, no. I just forgot…）配合。干扰点：忽略引语是一整句话。</li><li>D ❌ agree 表同意，但女儿并未提出请求，无从同意。干扰点：把答话当成「附和」。</li></ul><p><strong>整句翻译</strong>：“哦，没有。我只是忘了把它带回家，”他撒谎道。</p><p><strong>词组</strong>：<code>forget to do sth.</code> 忘记做某事；<code>bring sth. home</code> 把某物带回家</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第7段 · 第8空所在句）：I just forgot to bring it home,” he <em><strong>8</strong></em>.</p></details><p><strong>Molly had given him her ____—all that a 7-year-old held.</strong></p><ul><li>A. coins</li><li>B. stones</li><li>C. shells</li><li>D. treasures</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（treasures）</strong> —— 袋中全是她的「宝贝」treasures——七岁孩子拥有的一切。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ coins 只是袋中列举物之一，概括不了破折号后的 all that a 7-year-old held。干扰点：就近取材。</li><li>B ❌ stones 同样只是列举中的一项，以偏概全。干扰点：把具体的一项当总称。</li><li>C ❌ shells 也只是列举中的一项，不能涵盖全部。干扰点：忽略破折号的概括作用。</li><li>D ✅ 破折号后 all that a 7-year-old held（一个七岁孩子拥有的一切）是对空的解释，能收拢玩具、贝壳、石头、硬币的只有 treasures。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：Molly 已经把她最珍视的宝贝都给了他——那是一个七岁孩子拥有的一切。</p><p><strong>词组</strong>：<code>all that one held</code> 某人拥有的一切；<code>treasure</code> 珍宝</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第8段 · 第9空所在句）：Molly had given him her <em><strong>9</strong></em>—all that a 7-year-old held.</p></details><p><strong>Love in a paper bag, and he ____ it. He had even thrown it in the wastebasket.</strong></p><ul><li>A. cleaned</li><li>B. missed</li><li>C. threw</li><li>D. dropped</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（missed）</strong> —— 纸袋里装的是爱，而他竟「错过」missed 了。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cleaned 表清洁，与「辜负心意」的主题无关。干扰点：由 wastebasket 联想到清洁。</li><li>B ✅ 下句 He had even thrown it in the wastebasket 是对上句的加重说明，全段主旨是他错失了女儿的爱，故 missed。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ threw 与后句 had even thrown 重复，逻辑上也不成立（先说扔了，再说甚至扔了）。干扰点：被后句的原词吸引。</li><li>D ❌ dropped 表掉落/丢下，指具体动作，无法概括「辜负这份心意」。干扰点：与 throw 同义域。</li></ul><p><strong>整句翻译</strong>：纸袋里装的是爱，而他错过了它。他甚至把它扔进了废纸篓。</p><p><strong>词组</strong>：<code>love in a paper bag</code> 纸袋里的爱；<code>throw sth. in the wastebasket</code> 把某物扔进废纸篓</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第9段 · 第10空所在句）：Love in a paper bag, and he <em><strong>10</strong></em> it.</p></details><p><strong>So back he went hurriedly to the ____.</strong></p><ul><li>A. school</li><li>B. office</li><li>C. shop</li><li>D. home</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（office）</strong> —— 袋子落在「办公室」office，赶在清洁工之前回去找。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ school 表学校，父亲是去上班，与学校无关。干扰点：由「孩子」联想到学校。</li><li>B ✅ 前文 I left it at the office 已交代袋子落在哪里；此处与下句 Just before the night cleaner（赶在夜班清洁工之前）呼应，地点正是办公室。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ shop 表商店，与夜班清洁工、找回物品的动作不符。干扰点：把「赶回去取」理解成「去买」。</li><li>D ❌ home 与紧接的 carried the bag home 重复，且他必须先回去取。干扰点：把最终目的地提前。</li></ul><p><strong>整句翻译</strong>：于是他急忙赶回办公室。</p><p><strong>词组</strong>：<code>go back to</code> 返回；<code>hurriedly</code> 匆忙地</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第9段 · 第11空所在句）：So back he went hurriedly to the <em><strong>11</strong></em>.</p></details><p><strong>He found all the things back and carried the bag home ____.</strong></p><ul><li>A. worriedly</li><li>B. actively</li><li>C. carefully</li><li>D. luckily</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（carefully）</strong> —— 找回爱后「小心地」carefully 带回家。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worriedly 表担忧地，而找回之后的心情是珍惜，与 after dinner 请女儿讲故事的温情基调不符。干扰点：把「急忙赶回去」的情绪顺延到之后。</li><li>B ❌ actively 表积极地，与「把袋子带回家」的方式无关。干扰点：副词当填充词随手填。</li><li>C ✅ 与上句 he found all the things back 及后文 he asked Molly to tell him about the things 的珍视态度一致：曾把心意扔掉，这次小心收好。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ luckily 表幸运地，是对整句的评价而非方式状语，不能修饰 carried。干扰点：句子副词与方式副词混用。</li></ul><p><strong>整句翻译</strong>：他找回了所有东西，并小心翼翼地把袋子带回家。</p><p><strong>词组</strong>：<code>carry sth. home</code> 把某物带回家；<code>find sth. back</code> 找回某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第9段 · 第12空所在句）：Just before the night cleaner, he found all the things back and carried the bag home <em><strong>12</strong></em>.</p></details><p><strong>It ____ a long time to tell.</strong></p><ul><li>A. spent</li><li>B. paid</li><li>C. cost</li><li>D. took</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（took）</strong> —— It takes time 花时间讲，句型用 took。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ spend 的主语必须是人（sb. spends time），本句主语是 It。干扰点：忽略 It 是形式主语。</li><li>B ❌ pay 表花钱，与时间计量无关。干扰点：把四个「花费」词混为一谈。</li><li>C ❌ cost 表花费金钱或使某人付出代价，不能用于 It cost a long time to tell 这一表「耗时」的结构。干扰点：同为「花费」义，随手选。</li><li>D ✅ It takes (sb.) some time to do sth. 是固定句型，此处 It took a long time to tell 表示「讲完这些要花很长时间」。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：把每件东西的来历讲完花了很长时间。</p><p><strong>词组</strong>：<code>It takes (sb.) time to do sth.</code> 做某事花（某人）多少时间；<code>a long time</code> 很长时间</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第10段 · 第13空所在句）：It <em><strong>13</strong></em> a long time to tell.</p></details><p><strong>____ had a story or a memory.</strong></p><ul><li>A. Anything</li><li>B. Nothing</li><li>C. Everything</li><li>D. Something</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Everything）</strong> —— 「每一样东西」Everything 都有故事或回忆。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ anything 用于否定句与疑问句，本句是肯定陈述。干扰点：忽略句式。</li><li>B ❌ nothing 与 had a story or a memory 的肯定事实矛盾（那样就不用讲很久）。干扰点：只求语法通顺。</li><li>C ✅ 与上文 It took a long time to tell 呼应——正因为每一样都有故事或回忆，才要讲很久，故用 Everything。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ something 表「某一样东西」，与「讲很久」隐含的「样样都有来历」不符。干扰点：把「多」误作「一样」。</li></ul><p><strong>整句翻译</strong>：每一样东西都有一个故事或一段回忆。</p><p><strong>词组</strong>：<code>a story or a memory</code> 一个故事或一段回忆</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第10段 · 第14空所在句）：<em><strong>14</strong></em> had a story or a memory.</p></details><p><strong>It is such a simple ____ but it is so easily forgotten.</strong></p><ul><li>A. rule</li><li>B. truth</li><li>C. idea</li><li>D. way</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（truth）</strong> —— 与所爱之人同行才最重要——这是一个简单的「道理」truth。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ rule 表规则，与「与所爱之人同行的旅程才重要」这一人生感悟不符。干扰点：把「道理」都叫规则。</li><li>B ✅ It is such a simple truth but it is so easily forgotten 是全文的点题句：这是一条简单却常被忘记的真理，故用 truth。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ idea 表想法，偏个人主张，承担不了「常被遗忘」的分量。干扰点：truth/idea 同义域，凭语感选词。</li><li>D ❌ way 表方式，与 simple、forgotten 搭配不成句意。干扰点：把 way 当万能名词。</li></ul><p><strong>整句翻译</strong>：这是一个如此简单却又那么容易被人遗忘的道理。</p><p><strong>词组</strong>：<code>a simple truth</code> 一个简单的道理；<code>be easily forgotten</code> 容易被遗忘</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 纸袋里的爱 · 第11段 · 第15空所在句）：It is such a simple <em><strong>15</strong></em> but it is so easily forgotten.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>每天早晨父亲出门上班前，Molly 都负责把装午餐的纸袋递给他。一天早晨，除了平常的午餐袋，她又递给父亲一个看上去有些旧的纸袋。父亲问为什么有两个，她只说另一个装着别的东西，让父亲带上。</p><p>父亲把两个纸袋都放进公文包，亲吻 Molly 后匆匆离开。中午，他打开 Molly 的袋子，拿出一只小泰迪熊、两个小贝壳、五颗小石头和十二枚硬币。忙碌的父亲笑了笑，吃完饭便把桌上的东西连同纸袋一起扫进废纸篓，随后投入下午的工作。</p><p>晚上父亲读报时，Molly 跑来问纸袋在哪里。父亲说把它落在办公室。Molly 说自己忘了把一张便条放进去，还说袋中都是她真正喜欢的宝贝，本以为父亲也许会喜欢拿它们玩。父亲撒谎说只是忘了带回来。Molly 搂住父亲的脖子时，他打开便条，上面写着：“我爱你，爸爸。”Molly 已把自己的宝物——一个七岁孩子拥有的一切——送给了他。</p><p>纸袋里装的是爱，而他竟错过了，甚至把它扔进废纸篓。他急忙返回办公室，赶在夜班清洁工之前找回所有东西，并小心地带回家。晚饭后，他请 Molly 讲每件东西的来历；这花了很长时间，因为每一样都有一个故事或一段回忆。与所爱之人同行的人生旅程才真正重要，这是一个简单却很容易被遗忘的道理。</p></details><h3 id="练习八-·-牵手过马路" tabindex="-1"><a class="header-anchor" href="#练习八-·-牵手过马路"><span>练习八 · 牵手过马路</span></a></h3><p>It was a cold windy winter day and I was walking home from work. My head pointed down against the <strong><em><strong>1</strong></em></strong> when I noticed an old lady. She was <strong><em><strong>2</strong></em></strong> on the sidewalk in her house slippers.</p><p>As I <strong><em><strong>3</strong></em></strong> her, I saw that she was well into her 80s, and she was holding some <strong><em><strong>4</strong></em></strong> in her hands.</p><p>I walked on and arrived at the traffic light. Waiting there, I saw the mailbox <strong><em><strong>5</strong></em></strong> the street. The light turned green, but I pretended to check my phone and waited for her to catch up with me. In this neighborhood, even crossing with the green light was <strong><em><strong>6</strong></em></strong>. Drivers often drove <strong><em><strong>7</strong></em></strong> through red lights and stop signs.</p><p>I stayed there until she <strong><em><strong>8</strong></em></strong> me. I turned to her and touched her gently on the arm. She smiled and took my hand in hers and <strong><em><strong>9</strong></em></strong> it. Her small hand was soft and warm. Hand-in-hand, we were waiting for the <strong><em><strong>10</strong></em></strong> to change.</p><p>When the light turned green, we walked together slowly across the street, <strong><em><strong>11</strong></em></strong> the letters in the mailbox. Then I took her <strong><em><strong>12</strong></em></strong> across the street.</p><p>As I walked the rest of the way home, I could still feel the <strong><em><strong>13</strong></em></strong> of her hand in my own.</p><p>People say the first language of all humans is <strong><em><strong>14</strong></em></strong>. A caring touch helps to make a bad situation <strong><em><strong>15</strong></em></strong>. And even now, every time I think of the old lady, I can still feel the power of touch.</p><p><strong>It was a cold windy winter day … My head pointed down against the ____.</strong></p><ul><li>A. crowd</li><li>B. snow</li><li>C. wind</li><li>D. rain</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（wind）</strong> —— cold windy winter day，低头迎「风」wind 走。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ crowd 表人群，与 cold windy winter day 的天气描写不接，下文也没有人流的线索。干扰点：由 walking home 联想到街上人多。</li><li>B ❌ snow 表雪，首句只说 cold and windy，未提下雪；且与 windy 呼应最紧的天气要素是风。干扰点：由 cold 顺推出 snow。</li><li>C ✅ 首句 It was a cold windy winter day 已给出 windy，My head pointed down against the wind（低头迎着风）是它的自然延续。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ rain 表雨，全文未提下雨，cold windy 与 rain 也无必然联系。干扰点：把冬日的坏天气一并想象成雨。</li></ul><p><strong>整句翻译</strong>：那是一个寒冷多风的冬日，我下班步行回家。我低着头迎着风走。</p><p><strong>词组</strong>：<code>point one’s head down</code> 低下头；<code>walk home from work</code> 下班步行回家</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第1段 · 第1空所在句）：My head pointed down against the <em><strong>1</strong></em> when I noticed an old lady.</p></details><p><strong>She was ____ on the sidewalk in her house slippers.</strong></p><ul><li>A. begging</li><li>B. walking</li><li>C. running</li><li>D. riding</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（walking）</strong> —— 穿家居拖鞋在人行道上「走」walking。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ begging 表乞讨，与后文她拿着信件去邮箱、我陪她过街的日常情节不符。干扰点：把 sidewalk 与流浪乞讨联想在一起。</li><li>B ✅ on the sidewalk in her house slippers 说明她在人行道上行走；后文要去寄信、要过马路，全程都是步行。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ running 表跑，八十多岁、穿家居拖鞋的老人不会跑；后文 I stayed there until she reached me 也说明她走得慢。干扰点：忽略年龄与拖鞋两条线索。</li><li>D ❌ riding 表骑行，与 in her house slippers、on the sidewalk 都不搭。干扰点：把 sidewalk 想象成车道。</li></ul><p><strong>整句翻译</strong>：她穿着家居拖鞋在人行道上走着。</p><p><strong>词组</strong>：<code>house slippers</code> 家居拖鞋；<code>on the sidewalk</code> 在人行道上</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第1段 · 第2空所在句）：She was <em><strong>2</strong></em> on the sidewalk in her house slippers.</p></details><p><strong>As I ____ her, I saw that she was well into her 80s.</strong></p><ul><li>A. knew</li><li>B. expected</li><li>C. missed</li><li>D. passed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（passed）</strong> —— 「经过」passed 她身边时才看清年纪。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ knew her 表「认识她」，但下文 I saw that she was well into her 80s 是对陌生人的打量。干扰点：把「看见」误作「认识」。</li><li>B ❌ expected her 表「预料到她会来」，上下文没有这层预设。干扰点：只求动词能带宾格。</li><li>C ❌ missed her 表「没看见/想念」，与后半句「我看清她八十多岁」矛盾。干扰点：忽略后半句提供的信息。</li><li>D ✅ As I passed her, I saw… 表「从我身边经过时看清了她的年纪」，与后句 walked on and arrived at the traffic light 的推进顺序一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：我从她身边经过时，看出她已经八十多岁了。</p><p><strong>词组</strong>：<code>be well into one’s 80s</code> 八十好几；<code>pass sb.</code> 从某人身边经过</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第2段 · 第3空所在句）：As I <em><strong>3</strong></em> her, I saw that she was well into her 80s, and she was holding some <em><strong>4</strong></em> in her hands.</p></details><p><strong>…and she was holding some ____ in her hands.</strong></p><ul><li>A. letters</li><li>B. pictures</li><li>C. books</li><li>D. flowers</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（letters）</strong> —— 与后文 the letters in the mailbox 呼应：手里拿着「信」letters。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后文 the letters in the mailbox、dropping the letters in the mailbox 两次复现，此处她手里拿的正是信。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ pictures 表照片，与后文向邮箱投递信件的动作不符。干扰点：把手里的纸质物泛化。</li><li>C ❌ books 表书，邮箱只投信件，不投书本。干扰点：由「手里拿着东西」联想到书。</li><li>D ❌ flowers 表花，与 the letters in the mailbox 直接冲突。干扰点：把「老太太与花」的刻板印象代入。</li></ul><p><strong>整句翻译</strong>：……她手里还拿着几封信。</p><p><strong>词组</strong>：<code>hold sth. in one’s hands</code> 手里拿着某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第2段 · 第4空所在句）：As I <em><strong>3</strong></em> her, I saw that she was well into her 80s, and she was holding some <em><strong>4</strong></em> in her hands.</p></details><p><strong>Waiting there, I saw the mailbox ____ the street.</strong></p><ul><li>A. across</li><li>B. over</li><li>C. through</li><li>D. behind</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（across）</strong> —— 邮箱在街「对面」across the street。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the mailbox across the street（街对面的邮箱）与后文 crossing、across the street 的过街动作一致，说明她必须过街寄信。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ over the street 表「在街道上方」，位置关系不对。干扰点：across 与 over 都能表「越过」。</li><li>C ❌ through the street 表「穿过街道内部」，指从街中穿过，不表「在对面」。干扰点：把 through 当 across 用。</li><li>D ❌ behind the street 不成语义，街道没有「背后」。干扰点：方位词随手填。</li></ul><p><strong>整句翻译</strong>：在那里等候时，我看见邮箱在街对面。</p><p><strong>词组</strong>：<code>across the street</code> 在街对面</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第3段 · 第5空所在句）：Waiting there, I saw the mailbox <em><strong>5</strong></em> the street.</p></details><p><strong>In this neighborhood, even crossing with the green light was ____.</strong></p><ul><li>A. strange</li><li>B. crazy</li><li>C. dangerous</li><li>D. safe</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（dangerous）</strong> —— 与下文司机乱闯红灯呼应：绿灯过马路也「危险」dangerous。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ strange 表奇怪，不能说明我为何要等她一起过街。干扰点：把「不寻常」与「危险」混同。</li><li>B ❌ crazy 表疯狂的，主语若填 crazy 会把风险说成「荒谬」，丢掉安全含义。干扰点：由下文 drove wildly 顺推 crazy。</li><li>C ✅ 下文 Drivers often drove wildly through red lights and stop signs 正是对空的解释——即便绿灯过街也很危险，这才有我假装看手机等她的举动。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ safe 表安全，与司机闯红灯的描述完全相反。干扰点：由 with the green light 误判为安全。</li></ul><p><strong>整句翻译</strong>：在这个街区，即使绿灯时过马路也很危险。</p><p><strong>词组</strong>：<code>cross with the green light</code> 绿灯时过马路</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第3段 · 第6空所在句）：In this neighborhood, even crossing with the green light was <em><strong>6</strong></em>.</p></details><p><strong>Drivers often drove ____ through red lights and stop signs.</strong></p><ul><li>A. carefully</li><li>B. quietly</li><li>C. wildly</li><li>D. calmly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（wildly）</strong> —— 司机「疯狂地」wildly 闯红灯。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ carefully 表小心，与闯红灯的行为相反。干扰点：把司机想象成守规矩的。</li><li>B ❌ quietly 表安静，与交通危险无关。干扰点：只核对词性，不看语义。</li><li>C ✅ 与上文 even crossing with the green light was dangerous 呼应——正因为司机疯狂地闯红灯，过街才危险。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ calmly 表冷静，同样与危险驾驶相反。干扰点：仔细/冷静/疯狂都是副词，凭语气选词。</li></ul><p><strong>整句翻译</strong>：司机常常疯狂地闯红灯、越过停车标志。</p><p><strong>词组</strong>：<code>drive through red lights</code> 闯红灯；<code>stop sign</code> 停车标志</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第3段 · 第7空所在句）：Drivers often drove <em><strong>7</strong></em> through red lights and stop signs.</p></details><p><strong>I stayed there until she ____ me.</strong></p><ul><li>A. called</li><li>B. reached</li><li>C. found</li><li>D. caught</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（reached）</strong> —— 一直等到她「走到身边」reached me。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ called me 表「喊我」，但下文是我主动 turn to her and touched her，若她先喊我则顺序不合。干扰点：把「赶上」误解为「呼救」。</li><li>B ✅ I stayed there until she reached me 表「我等到她走到我身边」，与下句 I turned to her and touched her gently 的动作直接衔接。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ found me 表「找到我」，可她本就住在这个街区、我就站在路口等她，不存在寻找。干扰点：由「等待」顺推成「找」。</li><li>D ❌ catch sb. 表「抓住某人」，「赶上」要用 catch up with sb.，此处缺少 up with。干扰点：中文「赶上」直译成 catch。</li></ul><p><strong>整句翻译</strong>：我一直等到她走到我身边。</p><p><strong>词组</strong>：<code>stay there until…</code> 一直等在那里直到……</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第4段 · 第8空所在句）：I stayed there until she <em><strong>8</strong></em> me.</p></details><p><strong>She smiled and took my hand in hers and ____ it.</strong></p><ul><li>A. pushed</li><li>B. pulled</li><li>C. hit</li><li>D. held</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（held）</strong> —— 她牵住我的手并「握着」held it。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ pushed 表推开，与 She smiled and took my hand 的善意相反。干扰点：只求能与 hand 搭配。</li><li>B ❌ pulled 表拉，用力方向与「相握」不符。干扰点：push/pull 成对，凭动作大小选词。</li><li>C ❌ hit 表打，与微笑、温暖的场景完全冲突。干扰点：忽略情感基调。</li><li>D ✅ She smiled and took my hand in hers and held it 与后文 Her small hand was soft and warm. Hand-in-hand 连成一串「牵手」动作。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：她微笑着把我的手握在手里，紧紧握着。</p><p><strong>词组</strong>：<code>take sb.’s hand in one’s own</code> 握住某人的手；<code>hand-in-hand</code> 手牵手</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第4段 · 第9空所在句）：She smiled and took my hand in hers and <em><strong>9</strong></em> it.</p></details><p><strong>Hand-in-hand, we were waiting for the ____ to change.</strong></p><ul><li>A. way</li><li>B. light</li><li>C. ride</li><li>D. traffic</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（light）</strong> —— 与下文 When the light turned green 呼应：等「信号灯」light 变化。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the traffic to change 不成搭配，交通不会「变」；且上句刚提到等候信号灯。干扰点：traffic 是本段高频词，就近取材。</li><li>B ✅ 上文 I walked on and arrived at the traffic light、The light turned green 反复出现，此处 waiting for the light to change 与之呼应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ sign 指标志牌，不会「变」；会变的是信号灯。干扰点：由 stop signs 联想到 sign。</li><li>D ❌ the crossing to change 表「人行横道变了」，语义不成立。干扰点：把等候对象与路口混淆。</li></ul><p><strong>整句翻译</strong>：我们手牵手等着信号灯变化。</p><p><strong>词组</strong>：<code>wait for the light to change</code> 等信号灯变化</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第4段 · 第10空所在句）：Hand-in-hand, we were waiting for the <em><strong>10</strong></em> to change.</p></details><p><strong>We walked together slowly across the street, ____ the letters in the mailbox.</strong></p><ul><li>A. took</li><li>B. sent</li><li>C. dropped</li><li>D. locked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（dropped）</strong> —— 现在分词表伴随：「把信投进」dropped 邮箱。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ took the letters in the mailbox 表「从邮箱里取信」，方向反了。干扰点：忽略老太太是来寄信的。</li><li>B ❌ send 表寄送，不能用 sent the letters in the mailbox 这一结构表「投进邮箱」。干扰点：中文「寄信」直译。</li><li>C ✅ drop the letters in the mailbox 表「把信投进邮箱」，与老太太一路拿着信过街的目的吻合。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ locked the letters 表把信锁起来，与邮箱场景无关。干扰点：由 mailbox 联想到上锁。</li></ul><p><strong>整句翻译</strong>：绿灯亮后，我们一起慢慢地走过马路，把信投进了邮箱。</p><p><strong>词组</strong>：<code>drop a letter in the mailbox</code> 把信投进邮箱</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第5段 · 第11空所在句）：When the light turned green, we walked together slowly across the street, <em><strong>11</strong></em> the letters in the mailbox.</p></details><p><strong>Then I took her ____ across the street.</strong></p><ul><li>A. forward</li><li>B. back</li><li>C. away</li><li>D. ahead</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（back）</strong> —— 邮筒在街对面，送完信再送她「返回」back。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ forward 表向前，而她住在原来那一侧，需要回去。干扰点：把过街当成单向。</li><li>B ✅ 上文 her house slippers、她原本走在人行道上，我陪她过街寄信；Then I took her back across the street 表「再送她回对侧」。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ away 表离开，与相送的语境相反。干扰点：把「送走」与「送回」混淆。</li><li>D ❌ ahead 表向前，与 back 相反，同样忽略了往返关系。干扰点：把「带她走」当成继续前进。</li></ul><p><strong>整句翻译</strong>：然后我又送她回到街对面。</p><p><strong>词组</strong>：<code>take sb. back across the street</code> 送某人回到街对面</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第5段 · 第12空所在句）：Then I took her <em><strong>12</strong></em> across the street.</p></details><p><strong>I could still feel the ____ of her hand in my own.</strong></p><ul><li>A. warmth</li><li>B. trust</li><li>C. care</li><li>D. love</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（warmth）</strong> —— 与上文 soft and warm 呼应：手中还留着她掌心的「温暖」warmth。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 上文 Her small hand was soft and warm 是直接描写，故此处 I could still feel the warmth of her hand in my own。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ trust 表信任，不能与 feel the…of her hand 搭配（手不会发出信任）。干扰点：把「温暖」误读成抽象关系。</li><li>C ❌ care 表关心，同样不与 of her hand 搭配。干扰点：把情感名词与触觉名词混同。</li><li>D ❌ love 表爱，过于宏大，且前文强调的是手的温度。干扰点：凭「善意」选最重的词。</li></ul><p><strong>整句翻译</strong>：走完回家的余路时，我仍能感觉到她手中的温暖。</p><p><strong>词组</strong>：<code>feel the warmth of sb.’s hand</code> 感受到某人手掌的温暖</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第6段 · 第13空所在句）：As I walked the rest of the way home, I could still feel the <em><strong>13</strong></em> of her hand in my own.</p></details><p><strong>People say the first language of all humans is ____.</strong></p><ul><li>A. help</li><li>B. kindness</li><li>C. touch</li><li>D. action</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（touch）</strong> —— 与末句 the power of touch 呼应：人类最初的语言是「触摸」touch。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ help 表帮助，与全文以「触碰」收束的主题不符。干扰点：把善意笼统化成 help。</li><li>B ❌ kindness 表善意，是内心品质而非「语言」，且全文落点在 the power of touch。干扰点：用同义情绪词替换主题词。</li><li>C ✅ 后句 A caring touch helps to make a bad situation… 与末句 the power of touch 直接复现，故 the first language of all humans is touch。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ action 表行动，比「触碰」笼统，丢掉了具体的身体接触意象。干扰点：把「非语言交流」理解成「用行动」。</li></ul><p><strong>整句翻译</strong>：人们说，人类最初的语言是触摸。</p><p><strong>词组</strong>：<code>the first language of all humans</code> 全人类最初的语言</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第7段 · 第14空所在句）：People say the first language of all humans is <em><strong>14</strong></em>.</p></details><p><strong>A caring touch helps to make a bad situation ____.</strong></p><ul><li>A. interesting</li><li>B. necessary</li><li>C. popular</li><li>D. hopeful</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（hopeful）</strong> —— 充满关爱的触碰让糟糕的处境变得「充满希望」hopeful。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ interesting 表有趣，与「改善糟糕处境」无关。干扰点：只求语法通顺。</li><li>B ❌ necessary 表必要，与 make…的「转变」义不符。干扰点：褒义/中性形容词随手填。</li><li>C ❌ popular 表受欢迎，不用于形容处境。干扰点：忽略搭配对象。</li><li>D ✅ 下句 It gave me hope when Hank was in trouble 复现 hope，说明关爱的触碰能让糟糕处境变得有希望。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：一次充满关爱的触碰，能让糟糕的处境变得充满希望。</p><p><strong>词组</strong>：<code>make a situation hopeful</code> 让处境变得有希望</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 牵手过马路 · 第7段 · 第15空所在句）：A caring touch helps to make a bad situation <em><strong>15</strong></em>.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>那是一个寒冷多风的冬日，我下班步行回家。低头迎风走着时，我注意到一位老太太。她穿着家居拖鞋在人行道上行走。我从她身边经过时，看出她已经八十多岁，手里还拿着几封信。</p><p>我继续向前走到交通灯旁，看见邮箱在街对面。绿灯亮了，但我假装查看手机，等她赶上来。在这个街区，即使绿灯时过马路也很危险，因为司机经常疯狂地闯红灯、越过停车标志。</p><p>我一直等到她走到身边，轻轻碰了碰她的胳膊。她微笑着牵住我的手。那只小手柔软而温暖。我们手牵手等待信号灯变化。绿灯亮后，我们缓慢地一起过街，把信投入邮箱，然后我又送她返回街对面。</p><p>走完回家的余路时，我手中仿佛仍留着她手掌的温暖。人们说，人类最初的语言是触摸。充满关爱的触碰能让糟糕的处境变得充满希望。即使现在，每当想起那位老太太，我仍能感到触摸的力量。</p></details><h3 id="练习九-·-困在树上的猫" tabindex="-1"><a class="header-anchor" href="#练习九-·-困在树上的猫"><span>练习九 · 困在树上的猫</span></a></h3><p>The first time Hank, a two-year-old cat, went out of his yard, he got stuck in a 60-foot-tall tree for five days, with no food or water.</p><p>One day last November, when Delores, the <strong><em><strong>1</strong></em></strong>, returned from a market, she found Hank didn’t come in for his lunch. As it got <strong><em><strong>2</strong></em></strong>, she began to look for him around the house. Then she heard the meow of a cat, <strong><em><strong>3</strong></em></strong>, and saw Hank in her neighbor’s tree. He must have climbed onto the tree while some dogs were running after <strong><em><strong>4</strong></em></strong>, and became too afraid to climb down.</p><p>Delores, now very <strong><em><strong>5</strong></em></strong>, called the firemen immediately. But it was not easy, as they didn’t have a ladder tall enough to <strong><em><strong>6</strong></em></strong> the cat. She asked a tree company for help then. <strong><em><strong>7</strong></em></strong>, they failed for safety reasons.</p><p>The poor owner could do nothing but sit <strong><em><strong>8</strong></em></strong> the tree and call to Hank. A kind neighbor offered her some cat food, <strong><em><strong>9</strong></em></strong> it would make the hungry cat come down. Nearby dog owners took their pets for <strong><em><strong>10</strong></em></strong> instead of letting them out in their yards, so that Hank would not climb even <strong><em><strong>11</strong></em></strong> with fear.</p><p>Nothing had worked until it came to day five. <strong><em><strong>12</strong></em></strong> Lydia, another neighbor, talked of a clever way of getting the cat down from a tree, Delores decided to <strong><em><strong>13</strong></em></strong> it at once. Together, they produced a system of pulleys（滑轮）and lifted a <strong><em><strong>14</strong></em></strong> with some of Hank’s favorite things up to him. To their excitement, Hank jumped into it.</p><p>Delores was really thankful. “I feel good living in such a <strong><em><strong>15</strong></em></strong> neighborhood. It gave me hope when Hank was in trouble,” she said.</p><p><strong>One day last November, when Delores, the ____, returned from a market, she found Hank didn’t come in for his lunch.</strong></p><ul><li>A. owner</li><li>B. visitor</li><li>C. sister</li><li>D. neighbor</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（owner）</strong> —— 后文 The poor owner 点明 Delores 是猫「主人」owner。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后文 The poor owner could do nothing but sit under the tree 直接复现 owner，Delores 就是这只猫的主人。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ visitor 表访客，与「回来发现猫没来吃午饭、四处寻找」的家人视角不符。干扰点：把「回来」想成客人到访。</li><li>C ❌ sister 表姐妹，文中没有亲属关系线索，且后文以 owner 称呼她。干扰点：凭「照顾猫」猜亲属身份。</li><li>D ❌ neighbor 表邻居，但文中邻居由 Lydia（another neighbor）担任，此处是主人本人。干扰点：把主人与邻居混同。</li></ul><p><strong>整句翻译</strong>：去年十一月的一天，猫的主人 Delores 从市场回来，发现 Hank 没有回来吃午饭。</p><p><strong>词组</strong>：<code>come in for one’s lunch</code> 回来吃午饭；<code>return from a market</code> 从市场回来</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第2段 · 第1空所在句）：One day last November, when Delores, the <em><strong>1</strong></em>, returned from a market, she found Hank didn’t come in for his lunch.</p></details><p><strong>As it got ____, she began to look for him around the house.</strong></p><ul><li>A. cold</li><li>B. dark</li><li>C. quiet</li><li>D. dirty</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（dark）</strong> —— 猫没回来吃午饭，天「黑了」dark 还没回，才开始找。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cold 表冷，十一月确实冷，但解释不了「为什么开始寻找」的紧迫。干扰点：由 November 顺推 cold。</li><li>B ✅ As it got dark, she began to look for him around the house 表「天色变暗了，她开始找猫」，与随后听见猫叫、发现猫在树上构成合理的夜间寻找链条。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ quiet 表安静，与找不到猫没有因果联系。干扰点：把傍晚的环境当成线索。</li><li>D ❌ dirty 表脏，与找猫无关。干扰点：只求搭配通顺，不看语义。</li></ul><p><strong>整句翻译</strong>：天渐渐黑了，她开始在房子周围寻找它。</p><p><strong>词组</strong>：<code>as it got dark</code> 天色渐暗；<code>look for sb.</code> 寻找某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第2段 · 第2空所在句）：As it got <em><strong>2</strong></em>, she began to look for him around the house.</p></details><p><strong>Then she heard the meow of a cat, ____, and saw Hank in her neighbor’s tree.</strong></p><ul><li>A. ran away</li><li>B. turned back</li><li>C. fell down</li><li>D. looked up</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（looked up）</strong> —— 猫在树上，听见叫声后「抬头看」looked up 才发现。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ ran away 表跑开，与后半句 saw Hank in her neighbor’s tree 矛盾——跑开就看不到树上的猫。干扰点：把「听见叫声」误当成「被吓跑」。</li><li>B ❌ turned back 表回头，回头看到的是身后，而猫在邻居家的树上，需要往上看。干扰点：把听到声音的常见反应当成答案。</li><li>C ❌ fell down 表摔倒，与「看见猫在树上」不接。干扰点：忽略后半句。</li><li>D ✅ 她先听见猫叫，再抬头（looked up）才发现树上的 Hank，动作顺序与视野方向都吻合。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：接着她听见一声猫叫，抬头一看，发现 Hank 在邻居家的树上。</p><p><strong>词组</strong>：<code>look up</code> 抬头看；<code>in one’s neighbor’s tree</code> 在邻居家的树上</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第2段 · 第3空所在句）：Then she heard the meow of a cat, <em><strong>3</strong></em>, and saw Hank in her neighbor’s tree.</p></details><p><strong>He must have climbed onto the tree while some dogs were running after ____.</strong></p><ul><li>A. it</li><li>B. her</li><li>C. him</li><li>D. them</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（him）</strong> —— Hank 是公猫，用代词 him：狗在追「它」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ it 会把猫当作物，而本句后半 She must have… 用 he 指代 Hank。干扰点：把动物一律用 it 指代。</li><li>B ❌ her 的性别与 Hank（he）不符。干扰点：由主人是女性顺推代词。</li><li>C ✅ some dogs were running after him 指狗追「他」（Hank），与后句 He must have climbed onto the tree 的 he 一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ them 会把被追的对象指向别的复数对象，句中除 dogs 外没有复数指代对象，逻辑落空。干扰点：把复数 dogs 与复数代词就近配对。</li></ul><p><strong>整句翻译</strong>：它一定是在几条狗追它的时候爬上了树。</p><p><strong>词组</strong>：<code>run after sb.</code> 追赶某人；<code>must have done</code> 一定做过某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第2段 · 第4空所在句）：He must have climbed onto the tree while some dogs were running after <em><strong>4</strong></em>, and became too afraid to climb down.</p></details><p><strong>Delores, now very ____, called the firemen immediately.</strong></p><ul><li>A. tired</li><li>B. worried</li><li>C. surprised</li><li>D. relaxed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（worried）</strong> —— 猫被困树上五天，主人「担心」worried 得立刻打电话。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tired 表疲惫，无法解释立刻叫消防员这一紧急动作。干扰点：把「找了很久」理解成累。</li><li>B ✅ 猫已困在树上、天又黑了，Delores now very worried 与 immediately called the firemen 的紧急反应一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ surprised 表惊讶，惊讶不足以支撑连续向消防员和树木公司求助。干扰点：把发现猫在树上的瞬间情绪当成持续状态。</li><li>D ❌ relaxed 表放松，与立刻求助完全相反。干扰点：忽略情节转折。</li></ul><p><strong>整句翻译</strong>：Delores 非常担心，立刻打电话给消防员。</p><p><strong>词组</strong>：<code>call the firemen</code> 打电话叫消防员；<code>immediately</code> 立刻</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第3段 · 第5空所在句）：Delores, now very <em><strong>5</strong></em>, called the firemen immediately.</p></details><p><strong>They didn’t have a ladder tall enough to ____ the cat.</strong></p><ul><li>A. feed</li><li>B. train</li><li>C. reach</li><li>D. watch</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（reach）</strong> —— 梯子不够高，「够不到」reach 那只猫。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ feed 表喂，梯子高低与喂食无关。干扰点：只想着「救猫要喂它」。</li><li>B ❌ train 表训练，与救援场景无关。干扰点：忽略语境只看搭配。</li><li>C ✅ they didn’t have a ladder tall enough to reach the cat 表「梯子不够高、够不到猫」，正是救援受阻的原因，与下文向树木公司求助衔接。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ watch 表观察，够不到猫才是困难，观察不构成困难。干扰点：把 tall enough 误读为「看得清」。</li></ul><p><strong>整句翻译</strong>：他们没有足够高的梯子能够到猫。</p><p><strong>词组</strong>：<code>tall enough to do sth.</code> 足够高可以做某事；<code>reach sb./sth.</code> 够到某人/某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第3段 · 第6空所在句）：But it was not easy, as they didn’t have a ladder tall enough to <em><strong>6</strong></em> the cat.</p></details><p><strong>She asked a tree company for help then. ____, they failed for safety reasons.</strong></p><ul><li>A. Again</li><li>B. Instead</li><li>C. Besides</li><li>D. Anyway</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Again）</strong> —— 消防员失败后换公司求助，「又一次」Again 失败。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Again 表「又一次」：消防员失败后，树木公司同样失败，与下文「只能坐在树下呼唤」的无奈衔接。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ Instead 表「相反/代替」，但两次都是失败，不是替代关系。干扰点：把「又失败」误作「换个办法」。</li><li>C ❌ Besides 表「此外」，其后应是补充信息而非又一次失败的结果。干扰点：忽略语义，只挑一个连接词。</li><li>D ❌ Anyway 表「无论如何」，与「因安全原因失败」的因果不搭。干扰点：把连接词当万能填充。</li></ul><p><strong>整句翻译</strong>：她又向一家树木服务公司求助。然而他们同样因为安全原因没能成功。</p><p><strong>词组</strong>：<code>for safety reasons</code> 出于安全原因；<code>fail</code> 失败</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第3段 · 第7空所在句）：<em><strong>7</strong></em>, they failed for safety reasons.</p></details><p><strong>The poor owner could do nothing but sit ____ the tree and call to Hank.</strong></p><ul><li>A. across</li><li>B. behind</li><li>C. under</li><li>D. opposite</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（under）</strong> —— 猫在高处，只能坐在树「下」under 呼唤。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ sit across the tree 表坐在树对面，无法边坐边朝树上的猫呼唤。干扰点：与上文的 across the street 混淆。</li><li>B ❌ sit behind the tree 坐在树后看不见猫，与 call to Hank 的互动不符。干扰点：方位词随意填。</li><li>C ✅ 猫在树上（in the tree），主人只能 sit under the tree and call to Hank，仰头呼唤。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ sit opposite the tree 表坐在对面，同 across，不能边叫边看。干扰点：把「在对面」与「在下面」混同。</li></ul><p><strong>整句翻译</strong>：可怜的主人什么也做不了，只能坐在树下呼唤 Hank。</p><p><strong>词组</strong>：<code>do nothing but do</code> 只能做某事；<code>call to sb.</code> 呼唤某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第4段 · 第8空所在句）：The poor owner could do nothing but sit <em><strong>8</strong></em> the tree and call to Hank.</p></details><p><strong>A kind neighbor offered her some cat food, ____ it would make the hungry cat come down.</strong></p><ul><li>A. expecting</li><li>B. promising</li><li>C. realizing</li><li>D. regretting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（expecting）</strong> —— 给猫粮是「指望」expecting 饿猫会下来。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ expecting：邻居送猫粮并期待猫粮能让饿猫下树，与下文 Nothing had worked 的失败结局一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ promise 表承诺，主语是邻居而非猫粮，且此处是「抱着期待」而非「作出承诺」。干扰点：promise 也能接 that 从句。</li><li>C ❌ realizing 表意识到，而此刻猫还没下来，无从「意识到结果」。干扰点：把「知道猫饿」读成「意识到结果」。</li><li>D ❌ regretting 表后悔，与好心的邻居行为相反。干扰点：忽略情感色彩。</li></ul><p><strong>整句翻译</strong>：一位好心的邻居给她拿来一些猫粮，指望这能让饿了的猫下来。</p><p><strong>词组</strong>：<code>come down</code> 下来；<code>expect (that)…</code> 指望/预计……</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第4段 · 第9空所在句）：A kind neighbor offered her some cat food, <em><strong>9</strong></em> it would make the hungry cat come down.</p></details><p><strong>Nearby dog owners took their pets for ____ instead of letting them out in their yards.</strong></p><ul><li>A. help</li><li>B. sale</li><li>C. baths</li><li>D. walks</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（walks）</strong> —— take pets for walks 遛狗，避免狗在院子里吓猫。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take their pets for help 不成搭配。干扰点：只求名词能填进去。</li><li>B ❌ for sale 表出售，与「不让狗待在院子里」的用意无关。干扰点：忽略语义。</li><li>C ❌ for baths 表洗澡，同样解释不了「避免 Hank 受惊」。干扰点：由 pets 联想到照顾动物。</li><li>D ✅ take one’s pets for walks（牵狗散步）与 instead of letting them out in their yards 形成对比，目的是不让狗叫吓到 Hank。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：附近的养狗人也改牵狗散步，而不把狗放到院子里。</p><p><strong>词组</strong>：<code>take pets for walks</code> 牵宠物散步；<code>instead of</code> 而不是</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第4段 · 第10空所在句）：Nearby dog owners took their pets for <em><strong>10</strong></em> instead of letting them out in their yards, so that Hank would not climb even <em><strong>11</strong></em> with fear.</p></details><p><strong>…so that Hank would not climb even ____ with fear.</strong></p><ul><li>A. better</li><li>B. slower</li><li>C. higher</li><li>D. harder</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（higher）</strong> —— 猫在树上，恐惧时只会爬得「更高」higher。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ better 表更好，与「因恐惧往上爬」无关。干扰点：把 climb 与「爬得更好」搭配。</li><li>B ❌ slower 表更慢，与恐惧导致的反应方向不符（恐惧会往高处躲）。干扰点：忽略 climb 的方位含义。</li><li>C ✅ so that Hank would not climb even higher with fear 表「免得 Hank 吓得爬得更高」，正呼应前文狗在院子里会惊到它。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ harder 表更用力，climb 表位移，不能说 climb harder。干扰点：把 climb 当成「攀爬用力」。</li></ul><p><strong>整句翻译</strong>：这样 Hank 就不会因恐惧爬得更高。</p><p><strong>词组</strong>：<code>with fear</code> 由于害怕</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第4段 · 第11空所在句）：Nearby dog owners took their pets for <em><strong>10</strong></em> instead of letting them out in their yards, so that Hank would not climb even <em><strong>11</strong></em> with fear.</p></details><p><strong>____ Lydia, another neighbor, talked of a clever way of getting the cat down, Delores decided to ____ it at once.（本空为第 12 空）</strong></p><ul><li>A. If</li><li>B. When</li><li>C. Since</li><li>D. Before</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（When）</strong> —— 「当」When 邻居提出聪明办法时，她立刻决定试。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ If 表条件，而 Lydia 提出办法是已发生的事实。干扰点：把时间关系误作条件。</li><li>B ✅ When Lydia…talked of a clever way of getting the cat down, Delores decided to try it at once 表「当邻居提出办法时，她立刻决定一试」，两句都是已发生的事。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ Since 表「自从/既然」，前者需完成时，后者表原因，均不合此处。干扰点：since 引导从句很常见。</li><li>D ❌ Before 表「在……之前」，与 decided to try it at once 的即时反应矛盾。干扰点：把「先听后试」读成「在之前」。</li></ul><p><strong>整句翻译</strong>：当另一位邻居 Lydia 谈起一个把猫弄下树的聪明办法时，Delores 决定立刻试一试。</p><p><strong>词组</strong>：<code>at once</code> 立刻；<code>talk of</code> 谈起</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第5段 · 第12空所在句）：<em><strong>12</strong></em> Lydia, another neighbor, talked of a clever way of getting the cat down from a tree, Delores decided to <em><strong>13</strong></em> it at once.</p></details><p><strong>Delores decided to ____ it at once.</strong></p><ul><li>A. try</li><li>B. find</li><li>C. repair</li><li>D. change</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（try）</strong> —— 决定马上「试一试」try 这个办法。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ decide to try it at once 表「决定立刻试一试（这个办法）」，与后文 Together, they produced a system of pulleys 的实际行动衔接。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ find it 表「找到它」，而 it 指办法，不能与 find 搭配（要说 find a way）。干扰点：中文「找到办法」直译。</li><li>C ❌ repair 表修理，与滑轮办法无关。干扰点：由 produced a system of pulleys 联想到器械维修。</li><li>D ❌ change 表改变，与「照办法去做」相反。干扰点：只求动词能接 it。</li></ul><p><strong>整句翻译</strong>：Delores 决定立刻试一试（这个办法）。</p><p><strong>词组</strong>：<code>decide to do sth.</code> 决定做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第5段 · 第13空所在句）：<em><strong>12</strong></em> Lydia, another neighbor, talked of a clever way of getting the cat down from a tree, Delores decided to <em><strong>13</strong></em> it at once.</p></details><p><strong>They lifted a ____ with some of Hank’s favorite things up to him. Hank jumped into it.</strong></p><ul><li>A. toy</li><li>B. fish</li><li>C. rope</li><li>D. basket</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（basket）</strong> —— Hank 能「跳进去」的是装有它爱物的「篮子」basket。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a toy 与 with some of Hank’s favorite things 语义重复（玩具已属喜爱之物），且猫要「跳进」的是容器。干扰点：把玩具当成载体。</li><li>B ❌ fish 表鱼，是食物而非能装东西、让猫跳进去的容器。干扰点：由 cat 联想到 fish。</li><li>C ❌ rope 表绳子，而 with some of Hank’s favorite things 说明是装载器皿，且猫是 jumped into 而非爬绳。干扰点：由 system of pulleys 联想到绳子。</li><li>D ✅ 后句 To their excitement, Hank jumped into it 需要能装物的容器——由滑轮吊上去的篮子。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：他们把装有一些 Hank 喜爱的物品的篮子吊上去给它。</p><p><strong>词组</strong>：<code>jump into</code> 跳进；<code>a system of pulleys</code> 滑轮系统</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第5段 · 第14空所在句）：Together, they produced a system of pulleys（滑轮）and lifted a <em><strong>14</strong></em> with some of Hank’s favorite things up to him.</p></details><p><strong>I feel good living in such a ____ neighborhood. It gave me hope when Hank was in trouble.</strong></p><ul><li>A. peaceful</li><li>B. friendly</li><li>C. popular</li><li>D. wealthy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（friendly）</strong> —— 邻里纷纷帮忙，是「友善的」friendly 社区。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ peaceful 表平静，而全段讲的是邻居送猫粮、牵狗散步、出主意等主动相助，重点是友善。干扰点：把「安宁」当成邻里关系的评价。</li><li>B ✅ I feel good living in such a friendly neighborhood. It gave me hope 概括了邻居们的相助，故 friendly。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ popular 表受欢迎的，用来形容社区说不通。干扰点：褒义形容词随手填。</li><li>D ❌ wealthy 表富裕，文中完全未涉及经济条件。干扰点：把「住得好」理解成「有钱」。</li></ul><p><strong>整句翻译</strong>：住在这样一个友善的社区里我感觉很好。</p><p><strong>词组</strong>：<code>give sb. hope</code> 给某人希望；<code>in trouble</code> 处在困境中</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 困在树上的猫 · 第6段 · 第15空所在句）：“I feel good living in such a <em><strong>15</strong></em> neighborhood. It gave me hope when Hank was in trouble,”</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>两岁的猫 Hank 第一次走出自家院子，就被困在一棵六十英尺高的树上五天，没有食物也没有水。</p><p>去年十一月的一天，猫主人 Delores 从市场回来，发现 Hank 没有回来吃午饭。天渐渐黑了，她开始在房子周围寻找。后来她听见猫叫，抬头一看，发现 Hank 在邻居家的树上。它一定是在被几条狗追赶时爬上树，随后吓得不敢下来。</p><p>Delores 非常担心，立刻打电话给消防员。但消防员没有足够高的梯子，无法够到猫。她又向一家树木服务公司求助，他们也因安全原因没能成功。无助的主人只能坐在树下呼唤 Hank。一位好心邻居给她一些猫粮，希望能引诱饥饿的猫下来。附近养狗的人也改为牵狗散步，不把狗放在院中，以免 Hank 因恐惧爬得更高。</p><p>直到第五天，所有办法都没有奏效。另一位邻居 Lydia 提出一个聪明的方法，Delores 立刻决定试一试。大家一起搭建滑轮系统，把装有 Hank 喜爱物品的篮子吊上去。令人兴奋的是，Hank 跳进了篮子。Delores 十分感激，庆幸自己住在一个友善的社区；Hank 遇险时，邻里互助给了她希望。</p></details><h3 id="练习十-·-《格列佛游记》节选" tabindex="-1"><a class="header-anchor" href="#练习十-·-《格列佛游记》节选"><span>练习十 · 《格列佛游记》节选</span></a></h3><p>Late one night, Gulliver received a warning that some nobles wanted him killed. Even the emperor of Lilliput wanted to give him less food to save <strong><em><strong>1</strong></em></strong>. It was true Gulliver was very expensive.</p><p>Quickly, he wrote a letter to the emperor, “I’m <strong><em><strong>2</strong></em></strong> to visit Blefuscu, as I promised.”</p><p>Then he hurried down to the sea <strong><em><strong>3</strong></em></strong> Lilliput and Blefuscu.</p><p>The king of Blefuscu himself came out to meet him.</p><p>“Welcome!” cried the king. “Stay as <strong><em><strong>4</strong></em></strong> as you like.”</p><p>Walking on the beach a week later, Gulliver saw out at sea a small boat—but a full-sized one. It was <strong><em><strong>5</strong></em></strong> upside down in the water.</p><p>Gulliver rushed to the king. He begged, “Can you help me rescue the boat? This could be my chance to go home.”</p><p>“Of course,” said the king. “Take some ships to help you.”</p><p>Gulliver swam out to the boat, holding ropes from each of the <strong><em><strong>6</strong></em></strong>.</p><p>With the ships pulling and Gulliver <strong><em><strong>7</strong></em></strong>, the boat was brought safely to shore.</p><p>Gulliver and the king’s men set about fixing the boat for his long journey home. Soon, the boat was finished.</p><p>“I’d like to leave now,” Gulliver told the king. “But no one at home will <strong><em><strong>8</strong></em></strong> my story. Could I take some of your people with me?”</p><p>“I can’t possibly <strong><em><strong>9</strong></em></strong> that,” said the king. “But you may take some <strong><em><strong>10</strong></em></strong> and a sheep.”</p><p>He also gave Gulliver fifty bags of gold coins. “I don’t want you to go,” he said. “But I understand <strong><em><strong>11</strong></em></strong> you have to.”</p><p>“Thank you,” said Gulliver. “I’ll never <strong><em><strong>12</strong></em></strong> you all.”</p><p>After only a few days at sea in his boat, Gulliver saw a ship. He shouted and waved wildly.</p><p>He was <strong><em><strong>13</strong></em></strong>! One sailor found him. The ship sailed over and <strong><em><strong>14</strong></em></strong> Gulliver. “Where have you come from?” asked the captain. “A place called Lilliput,” said Gulliver and he showed the captain the <strong><em><strong>15</strong></em></strong> from the emperor.</p><p>The captain was so surprised. For a few gold coins and a couple of cows, he agreed to take Gulliver all the way home.</p><p>—Adapted from <em>Gulliver’s Travels</em></p><p><strong>Even the emperor of Lilliput wanted to give him less food to save ____.</strong></p><ul><li>A. life</li><li>B. time</li><li>C. money</li><li>D. energy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（money）</strong> —— 减少食物供给是为了「省钱」save money，与下文 very expensive 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ save his life 表「救他的命」，与「少给食物」的手段矛盾。干扰点：由前文 wanted him killed 联想到 life。</li><li>B ❌ save time 表节省时间，与食物没有关系。干扰点：把 save 一律理解成「节省」，不看宾语。</li><li>C ✅ 后句 It was true Gulliver was very expensive 直接解释动机——少给食物是为了省钱。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ save energy 表节省能源/体力，与「养他很费钱」的解释不符。干扰点：把食物与能量联系起来。</li></ul><p><strong>整句翻译</strong>：就连小人国皇帝也想少给他食物来省钱。</p><p><strong>词组</strong>：<code>save money</code> 省钱；<code>give sb. less food</code> 少给某人食物</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第1段 · 第1空所在句）：Even the emperor of Lilliput wanted to give him less food to save <em><strong>1</strong></em>.</p></details><p><strong>“I’m ____ to visit Blefuscu, as I promised.”</strong></p><ul><li>A. against</li><li>B. beyond</li><li>C. off</li><li>D. through</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（off）</strong> —— be off to 出发去某地：按承诺动身访问不来夫斯古。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ be against 表反对，与 as I promised（我答应过）矛盾。干扰点：只求能与 be 搭配。</li><li>B ❌ be beyond 表「超出」，说不通「超出访问」。干扰点：把 beyond 当方位介词随手填。</li><li>C ✅ be off to visit 表「动身去访问」，与下句 he hurried down to the sea 的动身动作直接衔接。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ be through 表「结束」，与「去访问」方向相反。干扰点：忽略语义只核对介词。</li></ul><p><strong>整句翻译</strong>：“我要按承诺出发去不来夫斯古了。”</p><p><strong>词组</strong>：<code>be off to do sth.</code> 动身去做某事；<code>as I promised</code> 正如我承诺的</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第2段 · 第2空所在句）：Quickly, he wrote a letter to the emperor, “I’m <em><strong>2</strong></em> to visit Blefuscu, as I promised.”</p></details><p><strong>Then he hurried down to the sea ____ Lilliput and Blefuscu.</strong></p><ul><li>A. between</li><li>B. among</li><li>C. upon</li><li>D. during</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（between）</strong> —— 两国「之间」的海边，用 between。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the sea between Lilliput and Blefuscu 表「两国之间的海」，与后文他渡海去不来夫斯古一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ among 用于三者及以上，且不表「两地之间」。干扰点：between/among 数量规则混用。</li><li>C ❌ the sea upon Lilliput 不成语义，海不会「在小人国之上」。干扰点：方位介词随手填。</li><li>D ❌ during 后接时间段，不能接地名。干扰点：只求介词能填进空里。</li></ul><p><strong>整句翻译</strong>：随后他赶到小人国与不来夫斯古之间的海边。</p><p><strong>词组</strong>：<code>between A and B</code> 在 A 与 B 之间；<code>hurry down to</code> 匆匆赶往</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第3段 · 第3空所在句）：Then he hurried down to the sea <em><strong>3</strong></em> Lilliput and Blefuscu.</p></details><p><strong>“Welcome!” cried the king. “Stay as ____ as you like.”</strong></p><ul><li>A. long</li><li>B. far</li><li>C. often</li><li>D. soon</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（long）</strong> —— as long as you like 想住多久住多久。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Stay as long as you like（想住多久就住多久）是主人挽留客人的固定说法，且与后文他住了一周相印证。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ as far as you like 表「想去多远就多远」，而本句是留他住下。干扰点：把「欢迎」误读为「放行」。</li><li>C ❌ as often as you like 表「想多频繁就多频繁」，与「住」不搭。干扰点：忽略 Stay 的语义。</li><li>D ❌ as soon as you like 是时间短语，不合 Stay as…as 的句式。干扰点：只求副词能填进去。</li></ul><p><strong>整句翻译</strong>：“欢迎！”国王大声说，“你想住多久就住多久。”</p><p><strong>词组</strong>：<code>as long as you like</code> 想住多久就住多久</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第5段 · 第4空所在句）：“Stay as <em><strong>4</strong></em> as you like.”</p></details><p><strong>He saw out at sea a small boat—but a full-sized one. It was ____ upside down in the water.</strong></p><ul><li>A. taking</li><li>B. falling</li><li>C. swimming</li><li>D. floating</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（floating）</strong> —— 船底朝上「漂浮」floating 在海面上。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ taking upside down in the water 不成语义。干扰点：只求词能与 in the water 连用。</li><li>B ❌ falling 表坠落，而船是漂在海上，后文还要打捞。干扰点：忽略 upside down 暗示的「浮着」。</li><li>C ❌ swim 的主语通常是人或动物，船不会游泳。干扰点：把「在水里」按生物理解。</li><li>D ✅ It was floating upside down in the water 表「船底朝天漂在水上」，与后文 Gulliver 游过去打捞的情节一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：他看到海面上漂着一艘小船——但那是正常尺寸的船。它船底朝天漂在水上。</p><p><strong>词组</strong>：<code>upside down</code> 颠倒、底朝天；<code>out at sea</code> 在远海上</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第6段 · 第5空所在句）：It was <em><strong>5</strong></em> upside down in the water.</p></details><p><strong>Gulliver swam out to the boat, holding ropes from each of the ____.</strong></p><ul><li>A. boats</li><li>B. ships</li><li>C. men</li><li>D. sails</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（ships）</strong> —— 与上文 Take some ships to help you 呼应：拉着各艘「大船」ships 的绳索。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ boat 文中有专指：a small boat 是需要打捞的那艘；而拉着绳子的是国王派出协助的船。干扰点：boat/ship 不分。</li><li>B ✅ 上句 Take some ships to help you，此处 holding ropes from each of the ships 与之对应，格列佛拉着它们游向小船。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ 他拉的是绳子，绳子系在船上，不系在人身上。干扰点：由 the king’s men 联想到人。</li><li>D ❌ 绳子不会从帆上拉出（帆在船的上方）。干扰点：把船的部位当成绳子的来源。</li></ul><p><strong>整句翻译</strong>：格列佛游到小船那里，手里拉着各艘大船上的绳索。</p><p><strong>词组</strong>：<code>hold ropes from</code> 拉着来自……的绳子；<code>swim out to</code> 游向</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第9段 · 第6空所在句）：Gulliver swam out to the boat, holding ropes from each of the <em><strong>6</strong></em>.</p></details><p><strong>With the ships pulling and Gulliver ____, the boat was brought safely to shore.</strong></p><ul><li>A. filling</li><li>B. shaking</li><li>C. pushing</li><li>D. carrying</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（pushing）</strong> —— 大船拉、格列佛「推」pushing，小船安全靠岸。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ filling 表装满，与「把船送上岸」的动作无关。干扰点：只求词形正确。</li><li>B ❌ shaking 表摇动，摇动不会把小船送上岸。干扰点：忽略 pull/push 的方向对立。</li><li>C ✅ With the ships pulling and Gulliver pushing（大船拉、格列佛推）构成一组相对的力量，正好解释船被安全弄上岸。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ carrying 表搬运，而格列佛是在水里推船，且人不可能抬着船游。干扰点：把「出力」理解为「搬」。</li></ul><p><strong>整句翻译</strong>：大船拉着、格列佛推着，小船被安全地弄到了岸边。</p><p><strong>词组</strong>：<code>bring sth. to shore</code> 把某物弄到岸边；<code>safely</code> 安全地</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第10段 · 第7空所在句）：With the ships pulling and Gulliver <em><strong>7</strong></em>, the boat was brought safely to shore.</p></details><p><strong>“But no one at home will ____ my story.”</strong></p><ul><li>A. make</li><li>B. expect</li><li>C. suppose</li><li>D. believe</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（believe）</strong> —— 小人国的经历太离奇，家乡没人会「相信」believe。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ make my story 表「编造故事」，与他的诉求（让人相信）相反。干扰点：把「讲经历」当成「编故事」。</li><li>B ❌ expect my story 表期待这个故事，与「没人相信」不搭。干扰点：忽略上下文。</li><li>C ❌ suppose 后接从句，不能直接带 story 作宾语。干扰点：只求动词能带宾语。</li><li>D ✅ no one at home will believe my story 解释了他为何要带走小人国的牛羊与金币作证据——家乡没人相信他。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“可我家乡没人会相信我的故事。”</p><p><strong>词组</strong>：<code>believe one’s story</code> 相信某人讲的事</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第12段 · 第8空所在句）：“But no one at home will <em><strong>8</strong></em> my story. Could I take some of your people with me?”</p></details><p><strong>“I can’t possibly ____ that,” said the king.</strong></p><ul><li>A. require</li><li>B. refuse</li><li>C. avoid</li><li>D. allow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（allow）</strong> —— 国王不能「允许」allow 带走他的臣民。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ require that 表「要求」，而国王是被请求的一方。干扰点：把「同意」与「要求」混同。</li><li>B ❌ refuse 表拒绝，I can’t possibly refuse that 就等于同意，与后文 But you may take some cows and a sheep 的让步转折矛盾。干扰点：只看语法通顺，忽略转折。</li><li>C ❌ avoid that 表「回避这件事」，与「带人回去」的请求不接。干扰点：只求能带宾语从句。</li><li>D ✅ I can’t possibly allow that（我不能允许）与 But you may take some cows and a sheep 形成「先拒绝后让步」的对照。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“我不能答应这件事，”国王说，“但你可以带几头牛和一只羊。”</p><p><strong>词组</strong>：<code>allow</code> 允许；<code>take…with me</code> 带……同行</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第13段 · 第9空所在句）：“I can’t possibly <em><strong>9</strong></em> that,” said the king.</p></details><p><strong>“But you may take some ____ and a sheep.”</strong></p><ul><li>A. food</li><li>B. people</li><li>C. coins</li><li>D. cows</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（cows）</strong> —— 与结尾 a couple of cows 呼应：带上几头「牛」cows 和一只羊。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ food 与随后国王另送的金币重复，且后文并未复现 food。干扰点：把「带证据」理解成「带食物」。</li><li>B ❌ people 与上一句的拒绝（I can’t possibly allow that）直接冲突。干扰点：忽略上一句。</li><li>C ❌ coins 由国王随后另送（He also gave Gulliver fifty bags of gold coins），不在本句。干扰点：把两种礼物倒置。</li><li>D ✅ 后文 For a few gold coins and a couple of cows, he agreed to take Gulliver all the way home 复现 cows，说明国王许他带走的是牛（与一只羊）。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“但你可以带几头牛和一只羊。”</p><p><strong>词组</strong>：<code>a couple of cows</code> 几头牛</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第13段 · 第10空所在句）：“But you may take some <em><strong>10</strong></em> and a sheep.”</p></details><p><strong>“But I understand ____ you have to.”</strong></p><ul><li>A. when</li><li>B. how</li><li>C. why</li><li>D. whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（why）</strong> —— 理解他「为什么」why 必须回家。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ when you have to 表「理解你何时必须走」，与「舍不得却体谅」的情绪不搭。干扰点：把「为什么」误作「什么时候」。</li><li>B ❌ understand how you have to 结构不成语义。干扰点：只求疑问词能引导从句。</li><li>C ✅ I understand why you have to 表「理解你为什么必须回去」，与 I don’t want you to go 的舍不得形成对照。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ whether you have to 表「是否必须」，而国王显然已知道他要回家。干扰点：whether 引导宾语从句很常见。</li></ul><p><strong>整句翻译</strong>：“我不想让你走，”他说，“但我理解你为什么必须走。”</p><p><strong>词组</strong>：<code>have to</code> 不得不</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第14段 · 第11空所在句）：“But I understand <em><strong>11</strong></em> you have to.”</p></details><p><strong>“Thank you. I’ll never ____ you all.”</strong></p><ul><li>A. forget</li><li>B. regret</li><li>C. force</li><li>D. obey</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（forget）</strong> —— 道谢即是「不会忘记」forget 你们大家。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ I’ll never forget you all（我永远不会忘记你们）是临别时对照顾的答谢，与 Thank you 一气相连。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ regret 表后悔，与感激的语气相反。干扰点：把离别情绪一律填成负面。</li><li>C ❌ force 表强迫，语义不成立。干扰点：只求动词能带宾语。</li><li>D ❌ obey 表服从，与道谢场景无关。干扰点：由「国王」联想到「服从」。</li></ul><p><strong>整句翻译</strong>：“谢谢，”格列佛说，“我永远不会忘记你们。”</p><p><strong>词组</strong>：<code>never forget</code> 永不忘怀</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第15段 · 第12空所在句）：“I’ll never <em><strong>12</strong></em> you all.”</p></details><p><strong>He shouted and waved wildly. He was ____!</strong></p><ul><li>A. in danger</li><li>B. in luck</li><li>C. in fear</li><li>D. in peace</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（in luck）</strong> —— 水手发现了他，「他走运了」He was in luck。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in danger 表处于危险中，而下句 One sailor found him 是获救。干扰点：由 shouted and waved wildly 误判为危急。</li><li>B ✅ He was in luck!（他走运了）与下句 One sailor found him、The ship sailed over 的转机完全一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ in fear 表恐惧，与「被发现」的结果不符。干扰点：把拼命挥手理解成害怕。</li><li>D ❌ in peace 表安宁，与获救的瞬间转折不接。干扰点：只看短语是正面的，不问语境。</li></ul><p><strong>整句翻译</strong>：他大声呼喊、拼命挥手。他走运了！</p><p><strong>词组</strong>：<code>be in luck</code> 走运；<code>wave wildly</code> 拼命挥手</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第17段 · 第13空所在句）：He was <em><strong>13</strong></em>!</p></details><p><strong>The ship sailed over and ____ Gulliver.</strong></p><ul><li>A. picked up</li><li>B. gave up</li><li>C. set up</li><li>D. dressed up</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（picked up）</strong> —— pick up （把人）救起、接上船。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ The ship sailed over and picked up Gulliver 表「船驶过来把格列佛接上船」，与后文他与船长对话衔接。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ give up 表放弃，与获救相反。干扰点：只求短语词形正确。</li><li>C ❌ set up 表建立，不能带「人」作宾语表示搭救。干扰点：把「安置」与「救起」混淆。</li><li>D ❌ dress up 表盛装打扮，与救援无关。干扰点：忽略语义只看短语。</li></ul><p><strong>整句翻译</strong>：船驶了过来，把格列佛救了上去。</p><p><strong>词组</strong>：<code>pick sb. up</code> 接某人上船/车；<code>sail over</code> 驶过来</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第17段 · 第14空所在句）：The ship sailed over and <em><strong>14</strong></em> Gulliver.</p></details><p><strong>…and he showed the captain the ____ from the emperor.</strong></p><ul><li>A. awards</li><li>B. presents</li><li>C. victims</li><li>D. rewards</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（presents）</strong> —— 国王送的礼物「presents」，包括金币和牛羊。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ awards 表奖项，是荣誉而非实物，而后文船长收下的是金币和牛。干扰点：把「皇帝所赠」理解成「颁奖」。</li><li>B ✅ he showed the captain the presents from the emperor（他给船长看皇帝送的礼物）与后文船长收下金币与牛的情节一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ victims 表受害者，与馈赠无关。干扰点：只求名词词形正确。</li><li>D ❌ rewards 表报酬/赏金，多因功劳而得；此处是国王临别的赠礼。干扰点：presents 与 rewards 同义域，凭中文「赏」选词。</li></ul><p><strong>整句翻译</strong>：……他给船长看了皇帝送的礼物。</p><p><strong>词组</strong>：<code>show sb. sth.</code> 给某人看某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 《格列佛游记》节选 · 第17段 · 第15空所在句）：“A place called Lilliput,” said Gulliver and he showed the captain the <em><strong>15</strong></em> from the emperor.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>一天深夜，格列佛收到警告：一些贵族想杀死他，就连小人国皇帝也想少给他食物以节省钱，因为供养格列佛的确花费巨大。他赶紧写信给皇帝，说自己要按承诺出发访问不来夫斯古，随后赶到两国之间的海边。不来夫斯古国王亲自迎接，并欢迎他想住多久就住多久。</p><p>一周后，格列佛在海滩散步，看到海面上漂着一艘对他而言很小、但属于正常尺寸的船，船底朝上。他请求国王帮助打捞，因为这可能是回家的机会。国王同意派船协助。格列佛游到小船处，手里拉着各艘大船的绳索；大船拉、格列佛推，终于把小船安全弄到岸边。格列佛和国王的手下修好了船。</p><p>格列佛想马上离开，却担心家乡没人相信自己的故事，便请求带一些小人回去。国王不能允许，但让他带上几头牛和一只羊，还送了五十袋金币。国王虽舍不得他离开，却理解他为什么必须回家。格列佛道谢，并承诺永远不会忘记大家。</p><p>出海几天后，格列佛看见一艘船，便大声呼喊、拼命挥手。他走运了，一名水手发现并把他救上船。格列佛告诉船长自己来自小人国，并展示皇帝送的礼物。船长十分惊讶，答应收下几枚金币和几头牛，把他一路送回家。</p></details><h3 id="练习十一-·-颜色与感受" tabindex="-1"><a class="header-anchor" href="#练习十一-·-颜色与感受"><span>练习十一 · 颜色与感受</span></a></h3><div class="hint-container caution"><p class="hint-container-title">易错</p><p>源课件错页源 PDF p28 误把练习十第 11–15 题的选项排在本文第 1–5 空旁，第 1–5 题各自的 A–D 选项缺失，故此处只收录选项完整的第 6–15 题；按课件勾选，第 1–5 空所填词依次为 <strong>anger、danger、leaves、lively、sunlight</strong>。</p></div><p>Different things usually stand for different feelings. Red, for example, is the color of fire, heat, blood and life. People say red is an exciting and active color. They associate（使发生联系）red with a strong feeling like <strong><strong>1</strong></strong>. Red is used for signs of <strong><strong>2</strong></strong>, such as STOP signs and fire engines. Orange is the bright, warm color of <strong><strong>3</strong></strong> in autumn. People say orange is a <strong><strong>4</strong></strong> color. They associate orange with happiness. Yellow is the color of <strong><strong>5</strong></strong>. People say it is a cheerful color. They associate yellow too, with happiness.</p><p>Green is the cool color of grass in <strong><strong>6</strong></strong>. People say it is a refreshing color. In general, people <strong><strong>7</strong></strong> two groups of colors: warm colors and cool colors. The warm colors are red, orange and <strong><strong>8</strong></strong>. Where there are warm color and a lot of light, people usually want to be <strong><strong>9</strong></strong>. Those who like to be with <strong><strong>10</strong></strong> like red. The cool colors are <strong><strong>11</strong></strong> and blue. Where are these colors, people are usually worried. Some scientists say that time seems to <strong><strong>12</strong></strong> more slowly in a room with warm colors. They suggest that a warm color is a good <strong><strong>13</strong></strong> for a living room or a <strong><strong>14</strong></strong>. People who are having a rest or are eating do not want time to pass quickly. <strong><strong>15</strong></strong> colors are better for some offices if the people working there want time to pass quickly.</p><p><strong>【第6空】Green is the cool color of grass in ____.</strong></p><ul><li>A. summer</li><li>B. spring</li><li>C. autumn</li><li>D. winter</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（spring）</strong> —— 草是绿色的季节是「春天」spring。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ summer 表夏天，与 cool color 的定位不符（夏天是热的）。干扰点：把绿与夏天自然联想。</li><li>B ✅ Green is the cool color of grass in spring 与后句 People say it is a refreshing color 呼应——春草正是「清凉、清爽」的意象。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ autumn 在上一段已配给橙色的树叶（the color of leaves in autumn），此处再填会重复。干扰点：忽略颜色—季节的对应关系。</li><li>D ❌ winter 配雪与冷色（黑色、蓝色），不是绿草。干扰点：把 cool 直接读成「冬天」。</li></ul><p><strong>整句翻译</strong>：绿色是春天青草的清凉色。</p><p><strong>词组</strong>：<code>the cool color of grass in spring</code> 春天青草的清凉色；<code>refreshing</code> 清爽的</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第6空所在句）：Green is the cool color of grass in <strong>6</strong>.</p></details><p><strong>【第7空】In general, people ____ two groups of colors: warm colors and cool colors.</strong></p><ul><li>A. speak</li><li>B. say</li><li>C. talk about</li><li>D. tell</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（talk about）</strong> —— talk about 谈论（两组颜色），speak/say/tell 不接话题宾语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ speak 表说话动作，后接谈论对象要用 speak about/of，不能直接带宾语。干扰点：中文「说」直译。</li><li>B ❌ say 后接说话内容（say something），不能说 say two groups of colors。干扰点：忽略宾语类型。</li><li>C ✅ people talk about two groups of colors 表「人们谈论两组颜色」，宾语正是谈论的话题。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ tell 需要人作宾语（tell sb. sth.），不能说 tell two groups of colors。干扰点：tell/say/speak/talk 四词混用。</li></ul><p><strong>整句翻译</strong>：一般而言，人们谈论两组颜色：暖色与冷色。</p><p><strong>词组</strong>：<code>talk about</code> 谈论；<code>in general</code> 一般而言</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第7空所在句）：In general, people <strong>7</strong> two groups of colors: warm colors and cool colors.</p></details><p><strong>【第8空】The warm colors are red, orange and ____.</strong></p><ul><li>A. green</li><li>B. yellow</li><li>C. white</li><li>D. gray</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（yellow）</strong> —— 上文说 yellow 是欢快、与幸福相关的颜色，属暖色。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ green 在下一段被划入 cool colors。干扰点：忽略下文 The cool colors are… 的划分。</li><li>B ✅ 前文已把红、橙归为暖色，而黄色刚被描述为 cheerful 且与幸福相关；The warm colors are red, orange and yellow 依此收拢。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ white 在文中未被列入暖色。干扰点：凭「明亮」联想白色。</li><li>D ❌ gray 不属于文中任何一组颜色。干扰点：把中性色当作暖色。</li></ul><p><strong>整句翻译</strong>：暖色是红色、橙色和黄色。</p><p><strong>词组</strong>：<code>warm colors</code> 暖色</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第8空所在句）：The warm colors are red, orange and <strong>8</strong>.</p></details><p><strong>【第9空】Where there are warm color and a lot of light, people usually want to be ____.</strong></p><ul><li>A. calm</li><li>B. sleepy</li><li>C. active</li><li>D. helpful</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（active）</strong> —— 红色令人兴奋、充满活力（exciting and active），暖色环境让人想「活动」active。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ calm 表平静，属冷色环境的状态，与暖色加充足光线的刺激作用相反。干扰点：把暖色误读成温暖舒适。</li><li>B ❌ sleepy 表困倦，与 a lot of light 的提神作用相反。干扰点：把「暖」与「懒」联想在一起。</li><li>C ✅ 上文说 red is an exciting and active color，暖色与充足光线让人想活动，故 want to be active。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ helpful 表乐于助人，与颜色环境对人的影响无关。干扰点：褒义形容词随手填。</li></ul><p><strong>整句翻译</strong>：在暖色且光线充足的地方，人们往往想活动起来。</p><p><strong>词组</strong>：<code>want to be active</code> 想活动起来；<code>a lot of light</code> 充足的光线</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第9空所在句）：Where there are warm color and a lot of light, people usually want to be <strong>9</strong>.</p></details><p><strong>【第10空】Those who like to be with ____ like red.</strong></p><ul><li>A. the other</li><li>B. another</li><li>C. other one</li><li>D. others</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（others）</strong> —— 泛指「其他人」others；the other/another 后不接零复数名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the other 表「两者中的另一个」，此处指「其他人」的复数概念。干扰点：other 与 others 的单复数范围混淆。</li><li>B ❌ another 表「另一个」单数，与 be with（和别人在一起）的复数概念不符。干扰点：只求词能接 with。</li><li>C ❌ other one 是特指单数，同样不合复数概念。干扰点：用 one 来补足名词。</li><li>D ✅ those who like to be with others 指「喜欢与人相处的人」，与后文 like red（红色外向、社交）对应。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：喜欢与人相处的人喜欢红色。</p><p><strong>词组</strong>：<code>be with others</code> 与人相处；<code>those who…</code> ……的人</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第10空所在句）：Those who like to be with <strong>10</strong> like red.</p></details><p><strong>【第11空】The cool colors are ____ and blue.</strong></p><ul><li>A. black</li><li>B. pink</li><li>C. golden</li><li>D. yellow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（black）</strong> —— 与暖色红橙黄相对，冷色是「黑色」black 和蓝色。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与 blue 并列的冷色调是 black；后句 Where are these colors, people are usually worried 也与黑色、蓝色带来的压抑感相符。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ pink 属暖色系，与 cool colors 相反。干扰点：按个人喜好给颜色分类。</li><li>C ❌ golden 属暖色，与黄色同族。干扰点：把金色与黄色混为一谈。</li><li>D ❌ yellow 上句刚被划入 warm colors，不能再算冷色。干扰点：忽略上一句的划分。</li></ul><p><strong>整句翻译</strong>：冷色是黑色和蓝色。</p><p><strong>词组</strong>：<code>cool colors</code> 冷色</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第11空所在句）：The cool colors are <strong>11</strong> and blue.</p></details><p><strong>【第12空】Some scientists say that time seems to ____ more slowly in a room with warm colors.</strong></p><ul><li>A. go round</li><li>B. go by</li><li>C. go off</li><li>D. go along</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（go by）</strong> —— go by （时间）流逝：暖色房间里时间似乎过得更慢。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ go round 表绕行、流传，不表时间流逝。干扰点：只求 go 的短语能填。</li><li>B ✅ time seems to go by more slowly（时间似乎过得更慢）与后文 do not want time to pass quickly 中的 pass 同义复现。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ go off 表爆炸、变质，语义不成立。干扰点：短语只看词形不看义。</li><li>D ❌ go along 表「进行、赞同」，同样不表时间流逝。干扰点：与 go by 形近误填。</li></ul><p><strong>整句翻译</strong>：一些科学家说，在暖色的房间里时间似乎过得更慢。</p><p><strong>词组</strong>：<code>go by</code> （时间）流逝；<code>time seems to…</code> 时间似乎……</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第12空所在句）：Some scientists say that time seems to <strong>12</strong> more slowly in a room with warm colors.</p></details><p><strong>【第13空】They suggest that a warm color is a good ____ for a living room.</strong></p><ul><li>A. one</li><li>B. way</li><li>C. fact</li><li>D. matter</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（way）</strong> —— a good way for … 是做……的好「办法/选择」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a good one for a living room 里的 one 指代颜色本身，说的是「一种好颜色」，而句意是「一个合适的办法」。干扰点：把 one 当万能替代词。</li><li>B ✅ a warm color is a good way for a living room 表「暖色对客厅而言是个好办法/好选择」，与后文 for a living room or a restaurant 的并列场所一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ fact 表事实，不能被 good 修饰来表达「适合」。干扰点：只求搭配读得通。</li><li>D ❌ matter 表事情，与 for a living room 的适配义不合。干扰点：把 matter 与 way 混同。</li></ul><p><strong>整句翻译</strong>：他们建议，暖色是客厅或餐厅的好选择。</p><p><strong>词组</strong>：<code>a good way for…</code> 对……而言是个好办法</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第13空所在句）：They suggest that a warm color is a good <strong>13</strong> for a living room or a <strong>14</strong>.</p></details><p><strong>【第14空】A warm color is a good way for a living room or a ____. People who are having a rest or are eating do not want time to pass quickly.</strong></p><ul><li>A. factory</li><li>B. classroom</li><li>C. restaurant</li><li>D. hospital</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（restaurant）</strong> —— 「吃饭」的人不希望时间过得快，对应「餐厅」restaurant。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ factory 表工厂，与后句 People who are having a rest or are eating 不符。干扰点：把场所笼统理解为「室内」。</li><li>B ❌ classroom 表教室，与 are eating 的场景不符。干扰点：忽略后半句的场所线索。</li><li>C ✅ 后句 are having a rest or are eating 正好对应 a living room（休息）or a restaurant（吃饭），故填 restaurant。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ hospital 表医院，与吃饭、休息的日常场景不符。干扰点：由「休息」联想到住院。</li></ul><p><strong>整句翻译</strong>：暖色适合客厅或餐厅。</p><p><strong>词组</strong>：<code>have a rest</code> 休息；<code>do not want time to pass quickly</code> 不希望时间过得太快</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第14空所在句）：They suggest that a warm color is a good <strong>13</strong> for a living room or a <strong>14</strong>.</p></details><p><strong>【第15空】____ colors are better for some offices if the people working there want time to pass quickly.</strong></p><ul><li>A. Different</li><li>B. Cool</li><li>C. Warm</li><li>D. All</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Cool）</strong> —— 想让时间过得快就用「冷色」Cool colors，与暖色房间时间变慢相反。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ different 表「不同的」，与前文 warm/cool 的二分不接。干扰点：只求形容词能修饰 colors。</li><li>B ✅ 前文说暖色让时间显得更慢，而办公室的人希望时间过得快，故 Cool colors are better for some offices。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ warm 与「希望时间过得快」相反（暖色使时间变慢）。干扰点：忽略上文的时间—颜色对应。</li><li>D ❌ all 表「所有」，与 better for some offices 的限定不符。干扰点：把泛指词填进限定句。</li></ul><p><strong>整句翻译</strong>：如果办公室的人希望时间过得快些，冷色对他们更合适。</p><p><strong>词组</strong>：<code>be better for</code> 对……更合适；<code>pass quickly</code> 过得快</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 颜色与感受 · 第2段 · 第15空所在句）：<strong>15</strong> colors are better for some offices if the people working there want time to pass quickly.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>不同事物通常代表不同感受。例如，红色是火、热、血液和生命的颜色。人们说红色令人兴奋、充满活力，并把它和愤怒等强烈情绪联系起来。红色也用于危险标志，如停车标志和消防车。橙色是秋日树叶明亮而温暖的颜色，人们认为它活泼，并把它与幸福联系起来。黄色是阳光的颜色，是一种欢快的颜色，也与幸福相关。</p><p>绿色是春草的清凉色彩，令人神清气爽。一般而言，人们谈论两组颜色：暖色和冷色。暖色包括红、橙、黄；在暖色和充足光线的环境中，人们往往想要活动。喜欢和别人相处的人喜欢红色。冷色包括黑色和蓝色；处在这些颜色的环境中，人们通常会感到忧虑。一些科学家说，在暖色房间里，时间似乎过得更慢。因此，暖色适合客厅或餐厅，因为休息或吃饭的人不希望时间过得太快。若办公室里的人希望时间过得快一些，冷色会更合适。</p></details><h3 id="练习十二-·-电视购物" tabindex="-1"><a class="header-anchor" href="#练习十二-·-电视购物"><span>练习十二 · 电视购物</span></a></h3><p>For several years, Americans have enjoyed teleshopping—watching TV and buying things by phone. Now teleshopping is starting in Europe. In some <strong><strong>1</strong></strong> countries, people can turn on their <strong><strong>2</strong></strong> and shop for clothes, jewelry, food, toys and <strong><strong>3</strong></strong> things.</p><p>Teleshopping is becoming popular in Sweden. <strong><strong>4</strong></strong>, the biggest Swedish company sells different kinds of things on TV in fifteen European countries, and in one year, it makes $10 million. In France, there are two teleshopping channels, and the French <strong><strong>5</strong></strong> about $20 million a year in buying things through those channels.</p><p>In Germany, <strong><strong>6</strong></strong> last year teleshopping was only possible on one channel for one hour every day. Then the government allowed more teleshopping. Other channels can <strong><strong>7</strong></strong> for telebusiness, including the largest American teleshopping company and a 24-hour teleshopping company. German <strong><strong>8</strong></strong> are hoping these will help them sell more things.</p><p>Some people like teleshopping because it allows them to do their shopping without <strong><strong>9</strong></strong>. With all the traffic problems in cities, going shopping is not an easy thing. But at the same time, other Europeans <strong><strong>10</strong></strong> like this new way of buying things. They call <strong><strong>11</strong></strong> “junk on the air”. Many Europeans usually worry about the quality of the things <strong><strong>12</strong></strong> on TV. They think high quality is the most important thing, and they don’t believe they can be sure about the quality of the things <strong><strong>13</strong></strong>.</p><p>The need of high quality means that European teleshopping companies will have to be <strong><strong>14</strong></strong> the American companies. They will have to be more careful about <strong><strong>15</strong></strong> of the things they sell. They will also have to work harder to sell things that the buyers cannot touch or see by themselves.</p><p><strong>Now teleshopping is starting in Europe. In some ____ countries, people can turn on their ____ and shop.</strong></p><ul><li>A. European</li><li>B. Asian</li><li>C. American</li><li>D. African</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（European）</strong> —— 上文说电视购物开始进入「欧洲」，故为欧洲国家。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 上句 Now teleshopping is starting in Europe（正从欧洲起步），故此处是 In some European countries。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ Asian 与 Europe 直接矛盾。干扰点：四个大洲选项凭常识随手填。</li><li>C ❌ 首句的 Americans 是背景对比（美国已成熟），本句谈的是欧洲刚起步。干扰点：把背景句的主体当成答案。</li><li>D ❌ 文中未提非洲。干扰点：四个大洲并列，凭排除法选词。</li></ul><p><strong>整句翻译</strong>：现在，电视购物正在欧洲兴起。在一些欧洲国家，人们可以打开电视，选购衣服、珠宝、食品、玩具以及许多其它东西。</p><p><strong>词组</strong>：<code>teleshopping</code> 电视购物；<code>turn on</code> 打开（电器）</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第1段 · 第1空所在句）：In some <strong>1</strong> countries, people can turn on their <strong>2</strong> and shop for clothes, jewelry, food, toys and <strong>3</strong> things.</p></details><p><strong>In some European countries, people can turn on their ____ and shop for clothes, jewelry, food, toys.</strong></p><ul><li>A. lights</li><li>B. switches</li><li>C. radios</li><li>D. TVs</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（TVs）</strong> —— 电视购物是看电视、打电话购物，打开的是「电视」TVs。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 打开灯无法购物。干扰点：只想着 turn on 要接一个电器。</li><li>B ❌ switch 指开关本体；turn on their switches 不是购物方式。干扰点：由 turn on 联想到开关。</li><li>C ❌ 收音机看不到商品，与 teleshopping（电视购物）矛盾。干扰点：把电视购物误作广播购物。</li><li>D ✅ 电视购物靠电视，turn on their TVs and shop 顺理成章；后面的 shop for clothes… 正是屏幕选购。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：在一些欧洲国家，人们可以打开电视，选购衣服、珠宝、食品、玩具等。</p><p><strong>词组</strong>：<code>turn on one’s TV</code> 打开电视</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第1段 · 第2空所在句）：In some <strong>1</strong> countries, people can turn on their <strong>2</strong> and shop for clothes, jewelry, food, toys and <strong>3</strong> things.</p></details><p><strong>…shop for clothes, jewelry, food, toys and ____ things.</strong></p><ul><li>A. some else</li><li>B. another many</li><li>C. the other</li><li>D. many other</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（many other）</strong> —— 「许多其他」many other + 复数名词；else 不能修饰名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ some else 结构错误（应为 something else 或 some other）。干扰点：else 与 other 混用。</li><li>B ❌ another many 语序错误，不成立。干扰点：只求词形对得上。</li><li>C ❌ the other things 表「其余的全部」，需要明确的前文范围；此处是开放式列举。干扰点：把 other 当万能限定词。</li><li>D ✅ 列举以 clothes, jewelry, food, toys 开头，接 and many other things 表「以及许多其它东西」，是开放的枚举。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……以及许多其它东西。</p><p><strong>词组</strong>：<code>and many other things</code> 以及许多其它东西</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第1段 · 第3空所在句）：In some <strong>1</strong> countries, people can turn on their <strong>2</strong> and shop for clothes, jewelry, food, toys and <strong>3</strong> things.</p></details><p><strong>Teleshopping is becoming popular in Sweden. ____, the biggest Swedish company sells different kinds of things on TV.</strong></p><ul><li>A. Such as</li><li>B. For example</li><li>C. For teleshopping</li><li>D. It is like</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（For example）</strong> —— 举瑞典公司为例，句首用 For example；such as 不单独成句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ such as 后接名词短语，不引导完整句子。干扰点：such as 与 for example 中文都译「例如」。</li><li>B ✅ 空格后是完整的句子（the biggest Swedish company sells…），用 For example 引导举例。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ for teleshopping 表「为了电视购物」，不引导举例。干扰点：把主题词塞进连接成分。</li><li>D ❌ it is like 结构不完整，不能作插入语。干扰点：只求读得通。</li></ul><p><strong>整句翻译</strong>：电视购物在瑞典越来越流行。例如，瑞典最大的公司在十五个欧洲国家的电视上销售各类商品，一年就赚到一千万美元。</p><p><strong>词组</strong>：<code>for example</code> 例如；<code>make $10 million</code> 赚到一千万美元</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第2段 · 第4空所在句）：<strong>4</strong>, the biggest Swedish company sells different kinds of things on TV in fifteen European countries, and in one year, it makes $10 million.</p></details><p><strong>There are two teleshopping channels, and the French ____ about $20 million a year in buying things.</strong></p><ul><li>A. takes</li><li>B. cost</li><li>C. spends</li><li>D. spend</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（spend）</strong> —— the French 法国人（复数）作主语，spend … in doing，用动词原形 spend。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take 表花费多用于 It takes… 句型，不用于「人 + 花多少钱」。干扰点：中文「花费」四词混用。</li><li>B ❌ cost 的主语是物（The book cost me 10 yuan）。干扰点：忽略主语是人。</li><li>C ❌ 主语 the French（法国人，复数）与 spends 主谓不一致。干扰点：忽略主谓一致。</li><li>D ✅ the French 表复数意义，谓语用 spend；spend money in buying sth. 表「花钱买某物」。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：在法国，有两个电视购物频道，法国人一年通过这些频道购物大约花两千万美元。</p><p><strong>词组</strong>：<code>spend money in doing sth.</code> 花钱做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第2段 · 第5空所在句）：In France, there are two teleshopping channels, and the French <strong>5</strong> about $20 million a year in buying things through those channels.</p></details><p><strong>In Germany, ____ last year teleshopping was only possible on one channel for one hour every day.</strong></p><ul><li>A. to</li><li>B. until</li><li>C. unless</li><li>D. by</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（until）</strong> —— 「直到去年」until last year，与后文政府放开政策呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ to 是介词，不能引导时间从句。干扰点：只求词形。</li><li>B ✅ until last year teleshopping was only possible on one channel（直到去年还只允许一个频道）与后句 Then the government allowed more teleshopping 的限制放宽形成对照。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ unless 表「除非」，与事实陈述不搭。干扰点：until 与 unless 形近。</li><li>D ❌ by last year 表「到去年为止」，需与完成时连用，且与 only possible 的持续状态不符。干扰点：把 by 当时间介词。</li></ul><p><strong>整句翻译</strong>：在德国，直到去年，电视购物还只能在一个频道每天进行一小时。</p><p><strong>词组</strong>：<code>until last year</code> 直到去年；<code>be possible</code> 可行</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第3段 · 第6空所在句）：In Germany, <strong>6</strong> last year teleshopping was only possible on one channel for one hour every day.</p></details><p><strong>Other channels can ____ for telebusiness, including the largest American teleshopping company.</strong></p><ul><li>A. begin</li><li>B. leave</li><li>C. open</li><li>D. turn on</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（open）</strong> —— 其他频道可以「开办」open 电视商业节目。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ begin for 不成搭配。干扰点：只求动词能填进空里。</li><li>B ❌ leave for telebusiness 表「动身去做电视商务」，与「频道放开」无关。干扰点：leave for 是常见搭配，但与语境不符。</li><li>C ✅ open for telebusiness 表「为电视商务开放（频道）」，与后文美国公司与 24 小时公司进驻的列举一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ turn on 表打开电器，主语是「频道」，不能自己打开自己。干扰点：由 teleshopping 联想到开设备。</li></ul><p><strong>整句翻译</strong>：其它频道可以为电视商务开放，其中包括美国最大的电视购物公司和一家 24 小时电视购物公司。</p><p><strong>词组</strong>：<code>open for</code> 为……开放</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第3段 · 第7空所在句）：Other channels can <strong>7</strong> for telebusiness, including the largest American teleshopping company and a 24-hour teleshopping company.</p></details><p><strong>German ____ are hoping these will help them sell more things.</strong></p><ul><li>A. people</li><li>B. women</li><li>C. businessmen</li><li>D. officials</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（businessmen）</strong> —— 希望多卖货的是德国「商人」businessmen。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ German people are hoping these will help them sell more things 中的泛指「人们」并不卖东西。干扰点：泛指词掩盖了行为主体。</li><li>B ❌ 文中未限定女性。干扰点：由「购物」联想到女性。</li><li>C ✅ 卖东西的主体是商人——German businessmen are hoping these will help them sell more things。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ 官员刚放开限制，此处盼着多卖货的应是商人。干扰点：上句出现 government，就近取材。</li></ul><p><strong>整句翻译</strong>：德国商人希望这些能帮他们卖出更多东西。</p><p><strong>词组</strong>：<code>sell more things</code> 卖出更多东西</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第3段 · 第8空所在句）：German <strong>8</strong> are hoping these will help them sell more things.</p></details><p><strong>Some people like teleshopping because it allows them to do their shopping without ____.</strong></p><ul><li>A. to go out</li><li>B. going out</li><li>C. to buy things</li><li>D. buying things</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（going out）</strong> —— without 是介词，接动名词 going out：不用出门。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ without 是介词，后接动名词，不能接不定式 to go out。干扰点：只求「出门」的语义。</li><li>B ✅ 介词 without 后接动名词 going out，表「不出门就能购物」，与下句 going shopping is not an easy thing 呼应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ to buy things 同理不能接在介词 without 后。干扰点：只看语义不看形式。</li><li>D ❌ buying things 会把句意变成「不必买东西」，与「购物不便」的焦点相悖。干扰点：忽略与 without 组合后的逻辑。</li></ul><p><strong>整句翻译</strong>：有些人喜欢电视购物，因为它让他们不必出门就能购物。</p><p><strong>词组</strong>：<code>without doing sth.</code> 不必做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第4段 · 第9空所在句）：Some people like teleshopping because it allows them to do their shopping without <strong>9</strong>.</p></details><p><strong>But at the same time, other Europeans ____ like this new way of buying things.</strong></p><ul><li>A. still</li><li>B. don’t</li><li>C. even</li><li>D. won’t</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（don’t）</strong> —— But 表转折：另一些欧洲人「并不」don’t 喜欢这种方式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ still like 表「仍然喜欢」，与后文 They call it &quot;junk on the air&quot; 的贬称矛盾。干扰点：忽略后文的批评态度。</li><li>B ✅ But at the same time, other Europeans don’t like this new way of buying things 与后文把它称作「空中的垃圾」一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ even like 表「甚至喜欢」，同样与贬称相反。干扰点：把 even 当强调词随手填。</li><li>D ❌ won’t 表「将来不会喜欢」，与 at the same time 的当下态度不符。干扰点：忽略时间状语。</li></ul><p><strong>整句翻译</strong>：但与此同时，另一些欧洲人不喜欢这种新的购物方式。</p><p><strong>词组</strong>：<code>at the same time</code> 与此同时</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第4段 · 第10空所在句）：But at the same time, other Europeans <strong>10</strong> like this new way of buying things.</p></details><p><strong>They call ____ “junk on the air”.</strong></p><ul><li>A. teleshopping</li><li>B. TV</li><li>C. radio</li><li>D. telephone</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（teleshopping）</strong> —— 把「电视购物」teleshopping 称为空中垃圾。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ They call teleshopping &quot;junk on the air&quot; 指代上句 this new way of buying things，被贬的是电视购物本身。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ 电视只是载体，被批评的是购物方式。干扰点：把媒介当成批评对象。</li><li>C ❌ 全文讲的是电视购物，不是广播。干扰点：由 on the air 联想到 radio。</li><li>D ❌ 电话只是下单手段，不是被贬的对象。干扰点：把 teleshopping 的实现手段当成对象。</li></ul><p><strong>整句翻译</strong>：他们称电视购物为「空中的垃圾」。</p><p><strong>词组</strong>：<code>call sth. sth.</code> 称某物为某物；<code>junk on the air</code> 空中的垃圾（贬称）</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第4段 · 第11空所在句）：They call <strong>11</strong> “junk on the air”.</p></details><p><strong>Many Europeans usually worry about the quality of the things ____ on TV.</strong></p><ul><li>A. appearing</li><li>B. coming out</li><li>C. for sale</li><li>D. to buy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（for sale）</strong> —— 「电视上出售的」for sale 商品的质量。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ appearing on TV 表「出现在电视上」，侧重节目而非可购买的商品。干扰点：只求搭配读得通。</li><li>B ❌ come out 表出现/出版，不表「在售」。干扰点：把「出现」与「出售」混同。</li><li>C ✅ the things for sale on TV（电视上出售的东西）与后文对质量的担忧直接对应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ the things to buy on TV 会把视角拧成「要买的东西」，而担忧的对象是「别人卖的」。干扰点：只求语义相近。</li></ul><p><strong>整句翻译</strong>：许多欧洲人常常担心电视上出售商品的质量。</p><p><strong>词组</strong>：<code>for sale</code> 待售、在售</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第4段 · 第12空所在句）：Many Europeans usually worry about the quality of the things <strong>12</strong> on TV.</p></details><p><strong>They don’t believe they can be sure about the quality of the things ____.</strong></p><ul><li>A. in the shop</li><li>B. on TV</li><li>C. they bought</li><li>D. by this way</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（on TV）</strong> —— 不相信仅凭「电视」on TV 就能确定商品质量。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in the shop 与「担心电视购物质量」的语境冲突。干扰点：用「商店看得见」反向推理。</li><li>B ✅ they don’t believe they can be sure about the quality of the things on TV 复现上句 for sale on TV，说明担心的正是电视上的商品。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ they bought 把担忧时点移到买之后，而本段讲的是「买前无法确认」。干扰点：忽略时点。</li><li>D ❌ by this way 结构错误（应为 in this way）。干扰点：只求语义相近。</li></ul><p><strong>整句翻译</strong>：他们觉得，电视上的商品质量无法确定。</p><p><strong>词组</strong>：<code>be sure about</code> 对……有把握</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第4段 · 第13空所在句）：They think high quality is the most important thing, and they don’t believe they can be sure about the quality of the things <strong>13</strong>.</p></details><p><strong>European teleshopping companies will have to be ____ the American companies.</strong></p><ul><li>A. the same with</li><li>B. different from</li><li>C. as big as</li><li>D. larger than</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（different from）</strong> —— 欧洲公司须更重质量，故必须「不同于」different from 美国公司。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the same with 结构错误（应为 the same as）。干扰点：same with 在口语里常见。</li><li>B ✅ The need of high quality means that European teleshopping companies will have to be different from the American companies：高质量要求使欧洲公司必须「走不同的路」，与后两句「更注意质量、更努力推销」一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ as big as 表规模相同，与质量话题无关。干扰点：把「不同」与「规模」混为一谈。</li><li>D ❌ larger than 表规模更大，同样偏离质量主题。干扰点：只看比较级词形。</li></ul><p><strong>整句翻译</strong>：对高质量的需求意味着欧洲电视购物公司必须与美国公司有所不同。</p><p><strong>词组</strong>：<code>be different from</code> 与……不同</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第5段 · 第14空所在句）：The need of high quality means that European teleshopping companies will have to be <strong>14</strong> the American companies.</p></details><p><strong>They will have to be more careful about ____ of the things they sell.</strong></p><ul><li>A. the number</li><li>B. the quality</li><li>C. the places</li><li>D. the buyers</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（the quality）</strong> —— 全文主题是质量：更谨慎地把控「质量」the quality。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the number 表数量，与上句 The need of high quality 无关。干扰点：把 careful about 与数量挂钩。</li><li>B ✅ They will have to be more careful about the quality of the things they sell 复现上句 high quality 的核心词，是本段的收束。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ the places 表地点，与质量要求无关。干扰点：只求搭配通顺。</li><li>D ❌ the buyers 表买家，句意会变成「对买家更小心」，不合。干扰点：把「为买家负责」误作「对买家小心」。</li></ul><p><strong>整句翻译</strong>：他们必须更加注意所售商品的质量。</p><p><strong>词组</strong>：<code>be careful about</code> 对……小心、注意</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 电视购物 · 第5段 · 第15空所在句）：They will have to be more careful about <strong>15</strong> of the things they sell.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>多年来，美国人一直享受电视购物：看电视，再通过电话购买商品。如今电视购物开始进入欧洲。在一些欧洲国家，人们可以打开电视，购买衣服、珠宝、食品、玩具和许多其他商品。</p><p>电视购物在瑞典日益流行。例如，瑞典最大的公司通过电视向十五个欧洲国家销售各类商品，一年能赚一千万美元。法国有两个电视购物频道，法国人每年通过这些频道购物约花费两千万美元。</p><p>在德国，直到去年，电视购物还只能每天在一个频道播出一小时。后来政府允许增加电视购物，其他频道也可以开办电视商业节目，其中包括美国最大的电视购物公司和一家二十四小时电视购物公司。德国商人希望这些频道能帮助他们销售更多商品。</p><p>有些人喜欢电视购物，因为不用出门。在交通问题严重的城市里，外出购物并不容易。但另一些欧洲人仍不喜欢这种新方式，把电视购物称为“空中垃圾”。许多欧洲人担心电视上出售商品的质量，认为高质量最重要，却不相信仅靠电视能确定所买商品的质量。</p><p>这种质量要求意味着欧洲电视购物公司必须与美国公司不同，更谨慎地把控所售商品的质量，也要更加努力地推销买家无法亲手触摸或亲眼查看的商品。</p></details><h3 id="练习十三-·-错吃巧克力" tabindex="-1"><a class="header-anchor" href="#练习十三-·-错吃巧克力"><span>练习十三 · 错吃巧克力</span></a></h3><p>Last Friday, after doing all the family shopping in the town. I wanted to have a rest before catching the rain. I <strong><strong>1</strong></strong> a newspaper and some chocolate and <strong><strong>2</strong></strong> into the station coffee shop. It was a cheap self-service place with long tables to <strong><strong>3</strong></strong> at. I put my heavy bag down on the floor, <strong><strong>4</strong></strong> the newspaper and the chocolate on the table and then went to get a cup of coffee.</p><p>When I came back with the coffee, there was someone <strong><strong>5</strong></strong> in the next seat. <strong><strong>6</strong></strong> was a boy, with dark glasses and old clothes, and <strong><strong>7</strong></strong> bright red at the front. He had started to eat my chocolate!</p><p>Naturally, I was rather uneasy about him, but I didn’t want to have any <strong><strong>8</strong></strong>. I just read the newspaper, tasted my coffee and took a bit of chocolate. The boy looked at me in <strong><strong>9</strong></strong>. Then he took a <strong><strong>10</strong></strong> piece of my chocolate. I could hardly believe it. Still I didn’t say anything to him. When he took a third piece, I felt more angry than uneasy. I thought, “Well, I shall have the last piece.” And I got it.</p><p>The boy gave me a strange look, then <strong><strong>11</strong></strong> up. As he left, he shouted out, “There’s something <strong><strong>12</strong></strong> with that woman!” Everyone looked at me, <strong><strong>13</strong></strong> I didn’t want to quarrel with the boy, so I kept quiet. I did not realize that I had <strong><strong>14</strong></strong> a mistake until I finished my coffee and was ready to <strong><strong>15</strong></strong>. My face turned red when I saw my unopened chocolate under the newspaper. The chocolate that I had been eating was the boy’s!</p><p><strong>I ____ a newspaper and some chocolate and ____ into the station coffee shop.</strong></p><ul><li>A. stole</li><li>B. bought</li><li>C. sold</li><li>D. wrote</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（bought）</strong> —— 买完东西想休息，于是「买了」bought 报纸和巧克力。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stole 表偷，与后文在车站咖啡店从容休息、看报的场景不符。干扰点：把「拿了报纸」想成偷拿。</li><li>B ✅ I bought a newspaper and some chocolate 与后文仍有一块未拆的巧克力（my unopened chocolate）一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ sold 表出售，方向相反。干扰点：只求动词能带宾语。</li><li>D ❌ wrote 表写，与买巧克力休息的日常场景不符。干扰点：与 newspaper 搭配联想到写稿。</li></ul><p><strong>整句翻译</strong>：上周五，在城里买完家里要用的东西后，我想在赶火车前休息一下。我买了一份报纸和一些巧克力，走进车站的咖啡店。</p><p><strong>词组</strong>：<code>do the family shopping</code> 采购家用物品；<code>catch the train</code> 赶火车</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第1段 · 第1空所在句）：I <strong>1</strong> a newspaper and some chocolate and <strong>2</strong> into the station coffee shop.</p></details><p><strong>I bought a newspaper and some chocolate and ____ into the station coffee shop.</strong></p><ul><li>A. went</li><li>B. sat</li><li>C. seated</li><li>D. looked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（went）</strong> —— go into 走进车站咖啡馆。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ went into the station coffee shop 表「走进车站咖啡店」，与后文对店里长桌、自助式的描述衔接。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ sat into 不成搭配（应为 sat in）。干扰点：只求「坐下」的语义。</li><li>C ❌ seat 是及物动词，须用 seated myself 或 be seated。干扰点：seat/sit 混用。</li><li>D ❌ looked into 表「朝里看」，不会带来后面「在店内坐下」的情节。干扰点：只求介词搭配成立。</li></ul><p><strong>整句翻译</strong>：我买了一份报纸和一些巧克力，走进了车站的咖啡店。</p><p><strong>词组</strong>：<code>go into</code> 走进</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第1段 · 第2空所在句）：I <strong>1</strong> a newspaper and some chocolate and <strong>2</strong> into the station coffee shop.</p></details><p><strong>It was a cheap self-service place with long tables to ____ at.</strong></p><ul><li>A. sit</li><li>B. seat</li><li>C. lie</li><li>D. laugh</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（sit）</strong> —— sit at a table 坐在桌边；seat 是及物动词不合此处。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ long tables to sit at 表「有可以坐着就餐的长桌」，动词不定式与被修饰的 tables 构成 sit at tables。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ seat 不能这样用（seat sb. 才成立），tables to seat at 不成立。干扰点：seat/sit 混用。</li><li>C ❌ lie at 表躺在桌旁，与「长桌」的就餐用途不符。干扰点：把「休息」的语义串进来。</li><li>D ❌ laugh 表笑，语意不成立。干扰点：只求词形能填。</li></ul><p><strong>整句翻译</strong>：那是一家便宜的自助店，有可以坐下的长桌。</p><p><strong>词组</strong>：<code>tables to sit at</code> 可以坐下的桌子</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第1段 · 第3空所在句）：It was a cheap self-service place with long tables to <strong>3</strong> at.</p></details><p><strong>I put my heavy bag down on the floor, ____ the newspaper and the chocolate on the table and then went to get a cup of coffee.</strong></p><ul><li>A. pushed</li><li>B. took</li><li>C. put</li><li>D. pulled</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（put）</strong> —— 与 put my bag down 并列：「把」报纸和巧克力「放」put 在桌上。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ pushed 表推，报纸和巧克力是放在桌上，不是推过去。干扰点：与 put 同属手部动作。</li><li>B ❌ took…on the table 表「拿在桌上」，动作不合。干扰点：忽略并列结构的要求。</li><li>C ✅ 与前半句 I put my heavy bag down on the floor 结构对称，此处 put the newspaper and the chocolate on the table。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ pulled 表拉，与「放下」相反。干扰点：push/pull 成对，凭动作方向感选词。</li></ul><p><strong>整句翻译</strong>：我把沉重的包放在地上，把报纸和巧克力放在桌上，然后去取咖啡。</p><p><strong>词组</strong>：<code>put sth. on the table</code> 把某物放在桌上</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第1段 · 第4空所在句）：I put my heavy bag down on the floor, <strong>4</strong> the newspaper and the chocolate on the table and then went to get a cup of coffee.</p></details><p><strong>When I came back with the coffee, there was someone ____ in the next seat.</strong></p><ul><li>A. jumping</li><li>B. playing</li><li>C. sitting</li><li>D. sleeping</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（sitting）</strong> —— 旁边座位「坐着」sitting 一个人。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ jumping 表跳，与咖啡店座位旁的场景不符。干扰点：只求词形能填。</li><li>B ❌ playing 表玩，无法解释他随后吃「我」的巧克力。干扰点：由「男孩」联想到玩耍。</li><li>C ✅ there was someone sitting in the next seat 表「旁边座位上坐着一个人」，与随后对这个男孩的外貌描写衔接。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ sleeping 若在睡觉，就不会接着吃我的巧克力并瞪我。干扰点：把「安静坐着」想象成熟睡。</li></ul><p><strong>整句翻译</strong>：当我端着咖啡回来时，旁边座位上坐着一个人。</p><p><strong>词组</strong>：<code>in the next seat</code> 在旁边的座位上</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第2段 · 第5空所在句）：When I came back with the coffee, there was someone <strong>5</strong> in the next seat.</p></details><p><strong>____ was a boy, with dark glasses and old clothes.</strong></p><ul><li>A. He</li><li>B. It</li><li>C. Who</li><li>D. What</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（He）</strong> —— 指代上文的 someone，用人称代词 He。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 前句 someone sitting 指人，本句 He was a boy 继续说明身份。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ 用 it 指人不合，且后文一律用 He 指代。干扰点：把 someone 当成身份不明的对象用 it。</li><li>C ❌ Who 是疑问词，不能作陈述句的主语。干扰点：只求词形。</li><li>D ❌ What 同 Who，且与「他是个男孩」的肯定描述冲突。干扰点：忽略句式。</li></ul><p><strong>整句翻译</strong>：他是个男孩，戴着墨镜，穿着旧衣服，正面染着鲜红色。</p><p><strong>词组</strong>：<code>with dark glasses</code> 戴着墨镜</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第2段 · 第6空所在句）：<strong>6</strong> was a boy, with dark glasses and old clothes, and <strong>7</strong> bright red at the front.</p></details><p><strong>…with dark glasses and old clothes, and ____ bright red at the front.</strong></p><ul><li>A. cut</li><li>B. washed</li><li>C. covered</li><li>D. colored</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（colored）</strong> —— 头发前面「染成」colored 鲜红色。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cut 表剪，与「染成红色」不符。干扰点：只求动词能填进空里。</li><li>B ❌ washed 表洗，与 bright red 的着色义不合。干扰点：把「染」与「洗」混同。</li><li>C ❌ covered 表覆盖，与 at the front（只在正面）的局部着色不符。干扰点：只看搭配读得通。</li><li>D ✅ colored bright red at the front 表「正面被染成鲜红色」，描述男孩头发（或衣服）的外观特征。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……正面被染成鲜红色。</p><p><strong>词组</strong>：<code>be colored</code> 被染成……色</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第2段 · 第7空所在句）：<strong>6</strong> was a boy, with dark glasses and old clothes, and <strong>7</strong> bright red at the front.</p></details><p><strong>I was rather uneasy about him, but I didn’t want to have any ____.</strong></p><ul><li>A. coffee</li><li>B. trouble</li><li>C. chocolate</li><li>D. matter</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（trouble）</strong> —— have trouble 惹麻烦：不想与陌生男孩起冲突。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ have any coffee 与「不想惹麻烦」的语境无关。干扰点：就近取材。</li><li>B ✅ I didn’t want to have any trouble 表「我不想惹麻烦」，直接解释了我随后忍着不吭声的行为。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ have any chocolate 与「保持沉默」的态度无关。干扰点：把巧克力这道具当成答案。</li><li>D ❌ have any matter 不成搭配（What’s the matter? 才用 matter）。干扰点：trouble 与 matter 中文都译「麻烦」。</li></ul><p><strong>整句翻译</strong>：说实话，我对他很不安，但我不想惹麻烦。</p><p><strong>词组</strong>：<code>have trouble</code> 遇到麻烦</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第3段 · 第8空所在句）：Naturally, I was rather uneasy about him, but I didn’t want to have any <strong>8</strong>.</p></details><p><strong>The boy looked at me in ____.</strong></p><ul><li>A. carelessness</li><li>B. anger</li><li>C. surprise</li><li>D. happiness</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（surprise）</strong> —— 陌生女子也拿「他的」巧克力吃，男孩「惊讶」surprise 地看我。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in carelessness 表粗心，与「盯着我看」的表情不符。干扰点：把男孩当成粗心的人。</li><li>B ❌ in anger 表愤怒，可他随后又拿了一块，说明不是愤怒。干扰点：只看「看」这一动作。</li><li>C ✅ The boy looked at me in surprise 表「男孩惊讶地看着我」——在他眼里是「我」一直在吃他的巧克力。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ in happiness 表高兴，与他稍后抱怨「那女人有问题」的恼怒不符。干扰点：褒义名词随手填。</li></ul><p><strong>整句翻译</strong>：男孩惊讶地看着我。接着他拿起了我的第二块巧克力。</p><p><strong>词组</strong>：<code>in surprise</code> 惊讶地</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第3段 · 第9空所在句）：The boy looked at me in <strong>9</strong>.</p></details><p><strong>Then he took a ____ piece of my chocolate.</strong></p><ul><li>A. first</li><li>B. second</li><li>C. very</li><li>D. last</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（second）</strong> —— 与后文 a third piece 呼应：接着拿了「第二块」second。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 上文已说他 started to eat my chocolate，此处不可能是第一块。干扰点：忽略上文已吃。</li><li>B ✅ Then he took a second piece of my chocolate 与后文 When he took a third piece 构成「第二块 → 第三块」的递进。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ a very piece 结构错误。干扰点：只求词形能填。</li><li>D ❌ last 表最后一块，与后文又出现第三块矛盾。干扰点：把「我的最后忍让」提前。</li></ul><p><strong>整句翻译</strong>：接着他拿起了我的第二块巧克力。</p><p><strong>词组</strong>：<code>a second piece</code> 第二块</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第3段 · 第10空所在句）：Then he took a <strong>10</strong> piece of my chocolate.</p></details><p><strong>The boy gave me a strange look, then ____ up.</strong></p><ul><li>A. stood</li><li>B. took</li><li>C. cried</li><li>D. looked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（stood）</strong> —— stood up 站起来离开。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ stood up 与 As he left 的离场动作衔接，也解释了 Everyone looked at me 的场景。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ take up 表开始从事或占去时间，不能表起身。干扰点：只求带 up 的短语。</li><li>C ❌ cried up 不成搭配。干扰点：词形相近随手填。</li><li>D ❌ looked up 表抬头，与「离开」不接。干扰点：忽略 As he left 这一走向提示。</li></ul><p><strong>整句翻译</strong>：男孩奇怪地看了我一眼，然后站了起来。</p><p><strong>词组</strong>：<code>stand up</code> 站起来</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第4段 · 第11空所在句）：The boy gave me a strange look, then <strong>11</strong> up.</p></details><p><strong>As he left, he shouted out, “There’s something ____ with that woman!”</strong></p><ul><li>A. strange</li><li>B. wrong</li><li>C. OK</li><li>D. funny</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（wrong）</strong> —— There’s something wrong with … 那个女人有毛病。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ something strange with that woman 侧重「奇特」，而这里是要指控对方有问题。干扰点：strange 也能译「奇怪」。</li><li>B ✅ There’s something wrong with that woman!（那女人有问题！）是抱怨的固定句式，也是他引来众人目光的原因。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ something OK 表「没问题」，与喊叫抱怨相反。干扰点：忽略情绪方向。</li><li>D ❌ funny 表可笑，偏离指控的语义。干扰点：把「怪」与「可笑」混同。</li></ul><p><strong>整句翻译</strong>：他离开时大声喊道：“那女人有问题！”</p><p><strong>词组</strong>：<code>There’s something wrong with…</code> ……有问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第4段 · 第12空所在句）：As he left, he shouted out, “There’s something <strong>12</strong> with that woman!”</p></details><p><strong>Everyone looked at me, ____ I didn’t want to quarrel with the boy, so I kept quiet.</strong></p><ul><li>A. and</li><li>B. but</li><li>C. so</li><li>D. while</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（but）</strong> —— 大家看着我，「但」我不想争吵，转折用 but。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ and 表并列，但「众人看我」与「我不想吵」是让步转折。干扰点：按顺承关系理解。</li><li>B ✅ Everyone looked at me, but I didn’t want to quarrel with the boy, so I kept quiet：转折 + 因果，完整解释了我沉默的缘由。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ so 会让「大家看我」成为沉默的原因，逻辑偏。干扰点：只看后半句的 so。</li><li>D ❌ while 表「当……时/而」，与前后两个较短的动作不搭。干扰点：连接词随手选。</li></ul><p><strong>整句翻译</strong>：大家都看着我，但我不想和那男孩吵架，所以保持沉默。</p><p><strong>词组</strong>：<code>quarrel with sb.</code> 与某人争吵；<code>keep quiet</code> 保持沉默</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第4段 · 第13空所在句）：Everyone looked at me, <strong>13</strong> I didn’t want to quarrel with the boy, so I kept quiet.</p></details><p><strong>I did not realize that I had ____ a mistake until I finished my coffee.</strong></p><ul><li>A. spelt</li><li>B. corrected</li><li>C. made</li><li>D. found</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（made）</strong> —— make a mistake 犯错误，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ do a mistake 不成搭配（do 不与 mistake 连用）。干扰点：do/make 混用。</li><li>B ❌ take a mistake 不成搭配。干扰点：只求动词能填。</li><li>C ✅ make a mistake 是固定搭配，指我误吃了男孩的巧克力这桩错事。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ give a mistake 不成搭配。干扰点：忽略搭配。</li></ul><p><strong>整句翻译</strong>：直到我喝完咖啡准备离开时，才意识到自己犯了一个错误。</p><p><strong>词组</strong>：<code>make a mistake</code> 犯错误；<code>not…until…</code> 直到……才……</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第4段 · 第14空所在句）：I did not realize that I had <strong>14</strong> a mistake until I finished my coffee and was ready to <strong>15</strong>.</p></details><p><strong>I did not realize that I had made a mistake until I finished my coffee and was ready to ____.</strong></p><ul><li>A. finish</li><li>B. leave</li><li>C. jump</li><li>D. shop</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（leave）</strong> —— 喝完咖啡准备「离开」leave 时才发现拿错了巧克力。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ finish 表结束，与「起身离店」的动作不符。干扰点：把「结束」与「离开」混同。</li><li>B ✅ was ready to leave 表「准备离开」，与后文 My face turned red when I saw my unopened chocolate 的发现时点吻合——收拾东西时才看到。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ jump 表跳，语义不成立。干扰点：只求动词能填。</li><li>D ❌ shop 表购物，可她刚买完东西（doing all the family shopping）。干扰点：由 chocolate 联想到购物。</li></ul><p><strong>整句翻译</strong>：直到我喝完咖啡、准备离开时才发现自己的错误。</p><p><strong>词组</strong>：<code>be ready to do sth.</code> 准备做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 错吃巧克力 · 第4段 · 第15空所在句）：I did not realize that I had <strong>14</strong> a mistake until I finished my coffee and was ready to <strong>15</strong>.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>上星期五，我在城里买完家中所需物品，想在赶车前休息一下。我买了一份报纸和一些巧克力，走进车站咖啡馆。那是一家便宜的自助店，里面有长桌可供就座。我把沉重的袋子放在地上，把报纸和巧克力放到桌上，然后去取咖啡。</p><p>我端着咖啡回来时，旁边座位坐着一个男孩。他戴深色眼镜、穿旧衣服，头发前面染成鲜红色，竟开始吃我的巧克力。我心里不安，却不想惹麻烦，只好读报、喝咖啡，也拿了一块巧克力。男孩惊讶地看着我，然后拿了第二块。我难以置信，却依然不说话。他拿第三块时，我气愤多于不安，心想最后一块必须归我，于是抢先拿走。</p><p>男孩奇怪地看我一眼，站起来离开，并喊道：“这个女人有毛病！”大家都看着我，但我不想和男孩争吵，便保持沉默。直到喝完咖啡准备离开，我才意识到自己犯了错误：我的脸顿时红了，因为看见自己那块尚未拆封的巧克力就在报纸下面。原来我一直吃的是男孩的巧克力！</p></details><h3 id="练习十四-·-rosa-编造的旅行" tabindex="-1"><a class="header-anchor" href="#练习十四-·-rosa-编造的旅行"><span>练习十四 · Rosa 编造的旅行</span></a></h3><p>Rosa liked making up stories. She was so <strong><strong>1</strong></strong> that her classmates believed her from time to time. In fact, the whole class believed her! At first she supposed it was <strong><strong>2</strong></strong>. Now, as she got up to <strong><strong>3</strong></strong> before the class, she knew that make-believe stories had some way of coming back to make you sad.</p><p>Rosa’s parents were separated. Nine months out of the year, Rosa lived with her mother in an apartment on Anderson Street. But when summer <strong><strong>4</strong></strong>, she went to her father’s farm in Arizona.</p><p>The farm was great! Rosa rode horses and <strong><strong>5</strong></strong> with some farm work. Her father, however, was so <strong><strong>6</strong></strong> that he couldn’t find time to go places with her. When she arrived each summer, her father would <strong><strong>7</strong></strong> her at the airport and take her out to eat. And the day she went back to the <strong><strong>8</strong></strong> he would always buy her a present.</p><p>When summer came to a close, Rosa <strong><strong>9</strong></strong> to her mother. At school she heard lots of stories her friends told about their family trips. Rosa wished she had a <strong><strong>10</strong></strong> to talk about.</p><p>Not long after <strong><strong>11</strong></strong> began, Rosa was looking through travel magazines in the school library. They talked about many exciting <strong><strong>12</strong></strong>, like England and Germany. When Rosa’s friends asked what she had done that summer, she made up something that was not <strong><strong>13</strong></strong>.</p><p>Remembering the travel magazines she had looked at, she told her classmates that she and her father had gone to <strong><strong>14</strong></strong>.</p><p>When the class began studying England, Mr. Thomas asked Rosa to tell all the things she could <strong><strong>15</strong></strong> about her trip to England!</p><p><strong>Rosa liked making up stories. She was so ____ that her classmates believed her from time to time.</strong></p><ul><li>A. afraid</li><li>B. worried</li><li>C. sure</li><li>D. happy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（sure）</strong> —— 同学们都信她，说明她说得「煞有介事」sure（很有把握的样子）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ afraid 表害怕，与「同学们相信她」没有因果。干扰点：把「编故事」想成心虚。</li><li>B ❌ worried 表担心，同样解释不了别人为何相信她。干扰点：忽略 so…that 的因果要求。</li><li>C ✅ She was so sure that her classmates believed her from time to time 表「她说得笃定，同学们就信了」；后半句 In fact, the whole class believed her 也印证这份笃定。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ happy 表高兴，与「令人相信」无因果。干扰点：褒义形容词随手填。</li></ul><p><strong>整句翻译</strong>：Rosa 喜欢编故事。她说得那么笃定，同学们不时就会相信她。事实上，全班都相信她。</p><p><strong>词组</strong>：<code>make up stories</code> 编故事；<code>from time to time</code> 不时</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第1段 · 第1空所在句）：She was so <strong>1</strong> that her classmates believed her from time to time.</p></details><p><strong>At first she supposed it was ____.</strong></p><ul><li>A. joke</li><li>B. fun</li><li>C. turn</li><li>D. game</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（fun）</strong> —— 起初她觉得这很好「玩」fun。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ joke 是可数名词，单独使用须加 a；it was joke 语法不合。干扰点：把「好玩」等同于「玩笑」。</li><li>B ✅ At first she supposed it was fun 表「起初她觉得很有趣」，与 Now…had some way of coming back to make you sad 形成今昔对照。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ it was turn 不成语义。干扰点：只求词形能填。</li><li>D ❌ game 把乐趣窄化为游戏，与后文「故事反噬」的对照也更弱。干扰点：只求褒义名词。</li></ul><p><strong>整句翻译</strong>：起初她觉得这很好玩。</p><p><strong>词组</strong>：<code>at first</code> 起初；<code>make-believe</code> 虚构的</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第1段 · 第2空所在句）：At first she supposed it was <strong>2</strong>.</p></details><p><strong>Now, as she got up to ____ before the class, she knew that make-believe stories had some way of coming back.</strong></p><ul><li>A. talk</li><li>B. teach</li><li>C. show</li><li>D. travel</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（talk）</strong> —— 站到全班面前「讲话」talk，谎言要被拆穿。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ get up to talk before the class 表「站起来在班上讲述」，与后文她讲旅行谎言的处境一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ teach 表教学，与「她讲自己编的故事」不符。干扰点：把 stand up 联想成上课。</li><li>C ❌ show 缺少宾语（展示什么？）。干扰点：只求动词能填。</li><li>D ❌ travel 表旅行，与「在班上站起来」的动作不接。干扰点：由后文的旅行谎言反推。</li></ul><p><strong>整句翻译</strong>：如今，当她在全班面前站起来讲述时，她明白虚构的故事总会以某种方式回来让你难过。</p><p><strong>词组</strong>：<code>get up to do sth.</code> 站起来做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第1段 · 第3空所在句）：Now, as she got up to <strong>3</strong> before the class, she knew that make-believe stories had some way of coming back to make you sad.</p></details><p><strong>But when summer ____, she went to her father’s farm in Arizona.</strong></p><ul><li>A. passed</li><li>B. arrived</li><li>C. lasted</li><li>D. changed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（arrived）</strong> —— 夏天「到来」arrived 时去父亲的农场。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ passed 表过去，与「去父亲的农场」的动身方向相反。干扰点：把「夏天过去」与「夏天到来」混同。</li><li>B ✅ when summer arrived 表「夏天来临时」，与 she went to her father’s farm 的动身直接对应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ lasted 表持续，不能引出「她去农场」的动作。干扰点：只求动词能填。</li><li>D ❌ changed 表改变，语义不成立。干扰点：忽略上下文。</li></ul><p><strong>整句翻译</strong>：一年里有九个月，Rosa 和母亲住在安德森街的公寓里。可一到夏天，她就去亚利桑那州的农场。</p><p><strong>词组</strong>：<code>arrive</code> （季节）到来；<code>live with</code> 和……同住</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第2段 · 第4空所在句）：But when summer <strong>4</strong>, she went to her father’s farm in Arizona.</p></details><p><strong>Rosa rode horses and ____ with some farm work.</strong></p><ul><li>A. made</li><li>B. played</li><li>C. helped</li><li>D. did</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（helped）</strong> —— help with 帮忙干农活。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ make with some farm work 不成搭配。干扰点：只求动词能接 with。</li><li>B ❌ play with some farm work 表「拿农活玩」，语义荒谬。干扰点：与 rode horses 并列就顺手填 play。</li><li>C ✅ Rosa rode horses and helped with some farm work 表「骑马、帮着干些农活」，与农场生活的正面描写一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ do with some farm work 表「处置农活」，不如 help with 贴切。干扰点：忽略固定搭配。</li></ul><p><strong>整句翻译</strong>：农场棒极了！Rosa 骑马，还帮忙做些农活。</p><p><strong>词组</strong>：<code>help with</code> 帮忙做……</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第3段 · 第5空所在句）：Rosa rode horses and <strong>5</strong> with some farm work.</p></details><p><strong>Her father, however, was so ____ that he couldn’t find time to go places with her.</strong></p><ul><li>A. weak</li><li>B. pleased</li><li>C. busy</li><li>D. lonely</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（busy）</strong> —— 没时间陪她，是因为父亲太「忙」busy。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ weak 表虚弱，与「没时间」的解释不符。干扰点：把「不能陪她」想成身体原因。</li><li>B ❌ pleased 表高兴，与没时间无因果。干扰点：褒义形容词随手填。</li><li>C ✅ Her father, however, was so busy that he couldn’t find time to go places with her：however 提示与「农场棒极了」相反的处境——父亲太忙。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ lonely 表孤独，逻辑反向（孤独并非「没时间」的原因）。干扰点：由「独自在农场」联想孤独。</li></ul><p><strong>整句翻译</strong>：然而她父亲太忙了，抽不出时间陪她出去。</p><p><strong>词组</strong>：<code>so…that…</code> 如此……以至于……；<code>find time to do sth.</code> 抽出时间做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第3段 · 第6空所在句）：Her father, however, was so <strong>6</strong> that he couldn’t find time to go places with her.</p></details><p><strong>When she arrived each summer, her father would ____ her at the airport.</strong></p><ul><li>A. show</li><li>B. visit</li><li>C. meet</li><li>D. send</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（meet）</strong> —— 去机场「接」meet 她。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ show her at the airport 表在机场「展示她」，不合。干扰点：只求动词能带人。</li><li>B ❌ visit 表拜访，与父亲接机的场景不符。干扰点：把「见面」与「拜访」混同。</li><li>C ✅ her father would meet her at the airport 表「父亲到机场接她」，与后文 take her out to eat 的接待动作连贯。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ send her at the airport 结构错误（应说 send sb. to）。干扰点：忽略介词。</li></ul><p><strong>整句翻译</strong>：每年夏天她到达时，父亲都会到机场接她，带她出去吃饭。</p><p><strong>词组</strong>：<code>meet sb. at the airport</code> 到机场接某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第3段 · 第7空所在句）：When she arrived each summer, her father would <strong>7</strong> her at the airport and take her out to eat.</p></details><p><strong>And the day she went back to the ____ he would always buy her a present.</strong></p><ul><li>A. farm</li><li>B. city</li><li>C. family</li><li>D. school</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（city）</strong> —— 与乡下农场相对，她回「城里」city 的那天父亲总买礼物。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ farm 与「父亲就在农场」相矛盾，往返方向反了。干扰点：把出发地当成目的地。</li><li>B ✅ the day she went back to the city he would always buy her a present 表「回城那天总会给她买礼物」，与母亲住在城里（Anderson Street 的公寓）呼应。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ family 是抽象名词，不作具体地点。干扰点：只求语义相近。</li><li>D ❌ school 与「回母亲身边」的往返主线不符。干扰点：由「开学」联想学校。</li></ul><p><strong>整句翻译</strong>：而她回城的那天，他总会给她买一件礼物。</p><p><strong>词组</strong>：<code>go back to</code> 回到；<code>buy sb. sth.</code> 给某人买某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第3段 · 第8空所在句）：And the day she went back to the <strong>8</strong> he would always buy her a present.</p></details><p><strong>When summer came to a close, Rosa ____ to her mother.</strong></p><ul><li>A. wrote</li><li>B. called</li><li>C. moved</li><li>D. returned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（returned）</strong> —— 夏天结束「回到」returned 母亲身边。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wrote 表写信，与「夏天结束」后的返程不接。干扰点：把「联系母亲」想成写信。</li><li>B ❌ called 表打电话，同样不表返程。干扰点：只求与 to her mother 搭配。</li><li>C ❌ moved 表搬家，与每年夏天往返的周期性不符。干扰点：把「回去」理解成搬家。</li><li>D ✅ When summer came to a close, Rosa returned to her mother 表「夏天一结束，Rosa 就回到母亲身边」，与本节开头的往返安排呼应。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：夏天结束时，Rosa 回到了母亲身边。</p><p><strong>词组</strong>：<code>come to a close</code> 结束；<code>return to</code> 回到</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第4段 · 第9空所在句）：When summer came to a close, Rosa <strong>9</strong> to her mother.</p></details><p><strong>Rosa wished she had a ____ to talk about.</strong></p><ul><li>A. family</li><li>B. school</li><li>C. teacher</li><li>D. farm</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（family）</strong> —— 朋友谈的都是家庭旅行，她也希望有个可谈的「家庭/家事」family。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 上文同学们讲的是 stories about their family trips，故 Rosa wished she had a family to talk about——她缺的是完整的家。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ 学校不是「谈资」的对象。干扰点：忽略上文 family trips。</li><li>C ❌ 老师不是她要谈的对象。干扰点：把学校生活当成话题。</li><li>D ❌ 农场她确实去过，缺的并不是农场。干扰点：就近取材。</li></ul><p><strong>整句翻译</strong>：在学校里，她听到朋友们讲的许多家庭旅行故事。Rosa 希望自己也有个家可以谈。</p><p><strong>词组</strong>：<code>family trips</code> 家庭旅行</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第4段 · 第10空所在句）：Rosa wished she had a <strong>10</strong> to talk about.</p></details><p><strong>Not long after ____ began, Rosa was looking through travel magazines in the school library.</strong></p><ul><li>A. meeting</li><li>B. school</li><li>C. summer</li><li>D. talk</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（school）</strong> —— 「开学」school 不久，地点是学校图书馆。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ meeting 表会议，与后文 in the school library 不搭。干扰点：只求名词能填。</li><li>B ✅ Not long after school began 表「开学不久」，与后文地点 in the school library 一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ summer 与刚结束的夏天重复，且假期里她不在学校。干扰点：忽略场所线索。</li><li>D ❌ talk 表谈话，不成语义。干扰点：只求词形能填。</li></ul><p><strong>整句翻译</strong>：开学不久，Rosa 在学校图书馆翻看旅行杂志。</p><p><strong>词组</strong>：<code>not long after</code> 不久之后；<code>look through</code> 翻阅</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第5段 · 第11空所在句）：Not long after <strong>11</strong> began, Rosa was looking through travel magazines in the school library.</p></details><p><strong>They talked about many exciting ____, like England and Germany.</strong></p><ul><li>A. people</li><li>B. cities</li><li>C. languages</li><li>D. places</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（places）</strong> —— 英国、德国是令人向往的「地方」places。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ England 和 Germany 是国家（地方），不是人。干扰点：只求名词能填。</li><li>B ❌ 英德是国家而非城市。干扰点：把国家与城市混同。</li><li>C ❌ languages 与 like England and Germany 的国名举例不符。干扰点：由「英德」联想到语言。</li><li>D ✅ many exciting places, like England and Germany 表「许多令人兴奋的地方，比如英国和德国」，与后文她谎称去了英国一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：杂志里谈到许多令人兴奋的地方，比如英国和德国。</p><p><strong>词组</strong>：<code>like</code> 例如</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第5段 · 第12空所在句）：They talked about many exciting <strong>12</strong>, like England and Germany.</p></details><p><strong>When Rosa’s friends asked what she had done that summer, she made up something that was not ____.</strong></p><ul><li>A. interesting</li><li>B. true</li><li>C. long</li><li>D. same</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（true）</strong> —— 编造「不真实」not true 的经历。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ interesting 表有趣，与「编造」的真假对照无关。干扰点：把谎言的评价理解成「没意思」。</li><li>B ✅ she made up something that was not true 表「她编了些不真实的东西」，与开头 liked making up stories 呼应，也是后文窘境的根源。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ long 表长，与虚构无关。干扰点：只求形容词能填。</li><li>D ❌ same 表相同，不表真假。干扰点：忽略语义。</li></ul><p><strong>整句翻译</strong>：当朋友们问她这个夏天做了什么时，她编了些不真实的东西。</p><p><strong>词组</strong>：<code>make up</code> 编造；<code>not true</code> 不真实</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第5段 · 第13空所在句）：When Rosa’s friends asked what she had done that summer, she made up something that was not <strong>13</strong>.</p></details><p><strong>She told her classmates that she and her father had gone to ____.</strong></p><ul><li>A. England</li><li>B. Germany</li><li>C. farm</li><li>D. home</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（England）</strong> —— 与下文全班开始学习英国、老师请她讲英国见闻呼应：去了「英国」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后文 When the class began studying England, Mr. Thomas asked Rosa to tell all the things…（全班开始学英国，老师让她讲英国见闻）直接印证她撒的谎是「去了英国」。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ Germany 与后文针对 England 的追问不符。干扰点：杂志里两个国家都出现过，随手选一个。</li><li>C ❌ farm 与她「旅行到某国」的谎言不符。干扰点：她确实去过农场。</li><li>D ❌ home 表家，不是旅行目的地。干扰点：只求词能填。</li></ul><p><strong>整句翻译</strong>：她想起看过的旅行杂志，于是告诉同学她和父亲去了英国。</p><p><strong>词组</strong>：<code>go to</code> 去（某地）</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第6段 · 第14空所在句）：Remembering the travel magazines she had looked at, she told her classmates that she and her father had gone to <strong>14</strong>.</p></details><p><strong>Mr. Thomas asked Rosa to tell all the things she could ____ about her trip to England!</strong></p><ul><li>A. think</li><li>B. see</li><li>C. remember</li><li>D. read</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（remember）</strong> —— 谎言的破绽：只能讲「记得」remember 的，却根本没有这趟旅行。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ think 表思考，需加 about；此处要的是「能想起的事」。干扰点：think 与 remember 中文都带「想」。</li><li>B ❌ see 表看见，而她从未去过英国，什么也看不到。干扰点：忽略谎言前提。</li><li>C ✅ tell all the things she could remember about her trip to England：定语从句 she could remember 表「她能记得的（见闻）」，正是撒谎后的窘境。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ read 表读到，与「讲述旅行见闻」不搭。干扰点：由 travel magazines 联想到读。</li></ul><p><strong>整句翻译</strong>：当全班开始学习英国时，Thomas 老师让 Rosa 讲讲她所能记得的关于英国之行的一切！</p><p><strong>词组</strong>：<code>tell all the things one can remember</code> 讲出所有记得的事</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · Rosa 编造的旅行 · 第7段 · 第15空所在句）：Thomas asked Rosa to tell all the things she could <strong>15</strong> about her trip to England!</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>Rosa 喜欢编故事，而且说得很像真的，同学们不时会相信她，事实上全班都信。起初她觉得这很好玩；可当她站到全班面前讲话时，才明白虚构的故事终会反过来让自己难受。</p><p>Rosa 的父母分居。一年中有九个月，她和母亲住在 Anderson Street 的公寓；暑天到来时，她会去亚利桑那州父亲的农场。农场很棒，她骑马，也帮忙干农活。但父亲太忙，没有时间带她四处游玩。每年她到达时，父亲会去机场接她并带她吃饭；她回城那天，父亲总会买一件礼物。</p><p>夏天结束时，Rosa 回到母亲身边。在学校里，她听朋友讲许多家庭旅行的故事，也希望自己能有一次旅行可谈。开学不久，她在学校图书馆翻阅旅游杂志，里面介绍英国、德国等许多令人兴奋的地方。朋友问她暑假做了什么，她便编造了不真实的经历。</p><p>她想起杂志内容，告诉同学自己和父亲去了英国。后来全班开始学习英国，Thomas 老师请 Rosa 讲讲她能记得的英国旅行见闻！</p></details><h3 id="练习十五-·-怎样选择儿童读物" tabindex="-1"><a class="header-anchor" href="#练习十五-·-怎样选择儿童读物"><span>练习十五 · 怎样选择儿童读物</span></a></h3><p>Most parents, I suppose, have had the experience of reading a bedtime story <strong><strong>1</strong></strong> their children. And they must have realized how difficult it is to write a <strong><strong>2</strong></strong> children’s book. Either the author has aimed too <strong><strong>3</strong></strong>, so that children can’t follow what is in his (or more often, her) story, <strong><strong>4</strong></strong> the story seems to be talking to the readers.</p><p>The best children’s books are <strong><strong>5</strong></strong> very difficult nor very simple, and satisfy the <strong><strong>6</strong></strong> who hears the story and the adult who <strong><strong>7</strong></strong> it. Unfortunately, there are in fact few books like this, <strong><strong>8</strong></strong> the problem of finding the right bedtime story is not <strong><strong>9</strong></strong> to solve. This may be why many of the books regarded as <strong><strong>10</strong></strong> of children’s literature were in fact written for <strong><strong>11</strong></strong>. “Alice in Wonderland” is perhaps the most obvious of this.</p><p>Children, left for themselves, often <strong><strong>12</strong></strong> the worst possible interest in literature. Just leave a child in a bookshop or a <strong><strong>13</strong></strong> and he will more willingly choose the books written in an unimaginative way, or have a look at the most children’s comics, full of the stories and jokes which are the rejections of teachers and right-thinking parents.</p><p>Perhaps we parents should stop <strong><strong>14</strong></strong> to brainwash children into accepting our taste in literature. After all, children and adults are so <strong><strong>15</strong></strong> that we parents should not expect that they will enjoy the same books. So I suppose we’ll just have to compromise over the bedtime story.</p><p><strong>Most parents have had the experience of reading a bedtime story ____ their children.</strong></p><ul><li>A. to</li><li>B. in</li><li>C. with</li><li>D. around</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（to）</strong> —— read a story to sb. 给孩子读故事。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ read a bedtime story to their children 表「给孩子读睡前故事」，read sth. to sb. 是固定搭配。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ read a story in their children 不成语义。干扰点：介词随手填。</li><li>C ❌ read a story with their children 表「和孩子一起读」，而本文强调的是父母读给孩子听。干扰点：with 也能表共同活动。</li><li>D ❌ read around 表「泛读」，不成「给孩子读」。干扰点：忽略宾语结构。</li></ul><p><strong>整句翻译</strong>：我想，多数父母都有给孩子读睡前故事的体验。</p><p><strong>词组</strong>：<code>read a story to sb.</code> 给某人读故事；<code>bedtime story</code> 睡前故事</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第1段 · 第1空所在句）：Most parents, I suppose, have had the experience of reading a bedtime story <strong>1</strong> their children.</p></details><p><strong>They must have realized how difficult it is to write a ____ children’s book.</strong></p><ul><li>A. short</li><li>B. long</li><li>C. bad</li><li>D. good</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（good）</strong> —— 写一本「好的」good 儿童读物很难。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ short 表短，与「难写」的普遍困难无关。干扰点：把 difficulty 理解为篇幅。</li><li>B ❌ long 同理，篇幅长并不是童书难写的原因。干扰点：只求形容词能填。</li><li>C ❌ bad 表差：写一本糟糕的童书并不难，与 how difficult 矛盾。干扰点：忽略评价方向。</li><li>D ✅ 下句讲这本书要让孩子听得懂、又不能太简单，说明难写的是「好」童书。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：他们一定体会过写一本好的童书有多难。</p><p><strong>词组</strong>：<code>how difficult it is to do sth.</code> 做某事有多难</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第1段 · 第2空所在句）：And they must have realized how difficult it is to write a <strong>2</strong> children’s book.</p></details><p><strong>Either the author has aimed too ____, so that children can’t follow what is in his story,</strong></p><ul><li>A. easy</li><li>B. short</li><li>C. high</li><li>D. difficult</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（high）</strong> —— 「立意太高」aimed too high，孩子跟不上。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ aim too easy 不成立，表「目标过低」应用 aim too low。干扰点：只求词形能填。</li><li>B ❌ aim too short 不成搭配。干扰点：忽略 aim 的搭配。</li><li>C ✅ aim too high 表「目标定得太高」，与 so that children can’t follow 的因果一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ aim too difficult 搭配不当（difficult 描述书，不描述目标）。干扰点：把 difficult 当万能形容词。</li></ul><p><strong>整句翻译</strong>：要么作者目标定得太高，孩子跟不上书里的内容；要么这本书像是在对读者说教。</p><p><strong>词组</strong>：<code>aim too high</code> 目标定得太高；<code>follow</code> 跟上、听懂</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第1段 · 第3空所在句）：Either the author has aimed too <strong>3</strong>, so that children can’t follow what is in his (or more often, her) story, <strong>4</strong> the story seems to be talking to the readers.</p></details><p><strong>Either the author has aimed too high …, ____ the story seems to be talking to the readers.</strong></p><ul><li>A. and</li><li>B. but</li><li>C. or</li><li>D. so</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（or）</strong> —— either…or… 固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ and 与前面的 Either 不配对。干扰点：忽略 either…or… 的固定关联。</li><li>B ❌ but 表转折，与 Either 结构不合。干扰点：按语气随手选词。</li><li>C ✅ either…or… 是固定关联结构，表示两种情况之一，与前半句的 Either 呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ so 与 Either 结构不合。干扰点：只求连接词能填进去。</li></ul><p><strong>整句翻译</strong>：要么作者目标定得太高……要么这本书像是在对读者说教。</p><p><strong>词组</strong>：<code>either…or…</code> 要么……要么……</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第1段 · 第4空所在句）：Either the author has aimed too <strong>3</strong>, so that children can’t follow what is in his (or more often, her) story, <strong>4</strong> the story seems to be talking to the readers.</p></details><p><strong>The best children’s books are ____ very difficult nor very simple.</strong></p><ul><li>A. both</li><li>B. neither</li><li>C. either</li><li>D. very</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（neither）</strong> —— neither…nor… 既不很难也不过分简单。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ both…nor 不搭配。干扰点：忽略后面 nor 的搭配要求。</li><li>B ✅ neither…nor… 是固定结构，表「既不太难也不太简单」。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ either…nor 不搭配（either 要与 or 配对）。干扰点：neither/either 混用。</li><li>D ❌ very…nor 不成结构。干扰点：只求词形能填。</li></ul><p><strong>整句翻译</strong>：最好的童书既不太难也不太简单，既能满足听故事的孩子，也能满足读故事的成人。</p><p><strong>词组</strong>：<code>neither…nor…</code> 既不……也不……</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第5空所在句）：The best children’s books are <strong>5</strong> very difficult nor very simple, and satisfy the <strong>6</strong> who hears the story and the adult who <strong>7</strong> it.</p></details><p><strong>…and satisfy the ____ who hears the story and the adult who ____ it.</strong></p><ul><li>A. child</li><li>B. father</li><li>C. mother</li><li>D. teacher</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（child）</strong> —— 听故事的是「孩子」child，与 adult 相对。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the child who hears the story 与后半句 the adult who reads it 构成「孩子—成人」对照。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ father 与 the adult 重复（父母本身就是成人）。干扰点：把陪伴者写进选项。</li><li>C ❌ mother 同理与 the adult 重复。干扰点：由「家长陪读」联想。</li><li>D ❌ teacher 不在睡前故事场景里。干扰点：把「读者」联想成老师。</li></ul><p><strong>整句翻译</strong>：既能满足听故事的孩子，也能满足读故事的成人。</p><p><strong>词组</strong>：<code>satisfy sb.</code> 使某人满意</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第6空所在句）：The best children’s books are <strong>5</strong> very difficult nor very simple, and satisfy the <strong>6</strong> who hears the story and the adult who <strong>7</strong> it.</p></details><p><strong>…the adult who ____ it.</strong></p><ul><li>A. hears</li><li>B. buys</li><li>C. understands</li><li>D. reads</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（reads）</strong> —— 「朗读」reads 它的成人。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ hears 与前半句 who hears the story 重复，构不成对照。干扰点：忽略对照关系。</li><li>B ❌ buys 表买书，不是与「听」相对的阅读行为。干扰点：把成人与买书联系。</li><li>C ❌ understands 表理解，是双方共同的要求，不构成与 hears 的对照。干扰点：只求语义通顺。</li><li>D ✅ the child who hears the story and the adult who reads it 构成「听—读」对照。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……也能满足读这本书的成人。</p><p><strong>词组</strong>：<code>the adult who reads it</code> 读这本书的成人</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第7空所在句）：The best children’s books are <strong>5</strong> very difficult nor very simple, and satisfy the <strong>6</strong> who hears the story and the adult who <strong>7</strong> it.</p></details><p><strong>Unfortunately, there are in fact few books like this, ____ the problem of finding the right bedtime story is not ____ to solve.</strong></p><ul><li>A. but</li><li>B. however</li><li>C. so</li><li>D. because</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（so）</strong> —— 这样的书少，「所以」so 找到合适睡前故事不容易。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ but 表转折，而此处前后是因果（书少 → 难找）。干扰点：把 Unfortunately 当成转折标志。</li><li>B ❌ however 需独立成句或加逗号，且此处是因果。干扰点：只求连接词能填。</li><li>C ✅ there are few books like this, so the problem of finding the right bedtime story is not easy to solve：因果顺承，说明难找的原因。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ because 会造成「因为难找，所以书少」的反向因果。干扰点：因果方向倒置。</li></ul><p><strong>整句翻译</strong>：不幸的是，这样的书其实很少，因此要找到合适的睡前故事并不容易。</p><p><strong>词组</strong>：<code>in fact</code> 事实上；<code>solve a problem</code> 解决问题</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第8空所在句）：Unfortunately, there are in fact few books like this, <strong>8</strong> the problem of finding the right bedtime story is not <strong>9</strong> to solve.</p></details><p><strong>…the problem of finding the right bedtime story is not ____ to solve.</strong></p><ul><li>A. hard</li><li>B. easy</li><li>C. enough</li><li>D. fast</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（easy）</strong> —— 与上文 few books like this 呼应：问题并不「容易」easy 解决。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ not hard to solve 表「不难解决」，与「这样的书很少」的困境矛盾。干扰点：忽略 not 与实义方向。</li><li>B ✅ not easy to solve 与上句 there are few books like this 的困境一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ not enough to solve 表「不足以解决」，语义偏离「难易」。干扰点：只求词能填。</li><li>D ❌ fast 与 solve 搭配不当。干扰点：把「快」与「容易」混同。</li></ul><p><strong>整句翻译</strong>：……因此要找到合适的睡前故事并不容易。</p><p><strong>词组</strong>：<code>be easy to solve</code> 容易解决</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第9空所在句）：Unfortunately, there are in fact few books like this, <strong>8</strong> the problem of finding the right bedtime story is not <strong>9</strong> to solve.</p></details><p><strong>Many of the books regarded as ____ of children’s literature were in fact written for ____.</strong></p><ul><li>A. articles</li><li>B. work</li><li>C. arts</li><li>D. works</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（works）</strong> —— 「杰作」masterpieces 用 works（可数名词复数）；work 作作品讲不可数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ articles 表文章，children’s literature 的「作品」用 works。干扰点：与「文学」联想文章。</li><li>B ❌ work 表「作品」时是可数名词，单数不合此处泛指的复数概念。干扰点：忽略单复数。</li><li>C ❌ arts 表艺术门类，不作单件文学作品。干扰点：把文学与艺术相混。</li><li>D ✅ works of children’s literature 表「儿童文学作品」，是固定说法。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：许多被视为儿童文学作品的书，其实是写给成人的。</p><p><strong>词组</strong>：<code>works of literature</code> 文学作品；<code>be regarded as</code> 被视为</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第10空所在句）：This may be why many of the books regarded as <strong>10</strong> of children’s literature were in fact written for <strong>11</strong>.</p></details><p><strong>Many of the books regarded as works of children’s literature were in fact written for ____.</strong></p><ul><li>A. grown-ups</li><li>B. girls</li><li>C. boys</li><li>D. children</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（grown-ups）</strong> —— 《爱丽丝梦游仙境》其实是为「成年人」grown-ups 写的。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ grown-ups 与下句 &quot;Alice in Wonderland&quot; is perhaps the most obvious of this（《爱丽丝漫游奇境》最典型）呼应：它被公认为写给成人看的。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ girls 与「为成人写作」的论点不符，下文举例也无法印证。干扰点：由「儿童文学」联想孩子。</li><li>C ❌ boys 同上。干扰点：只求名词能填。</li><li>D ❌ children 与 in fact（其实是）的转折相反——本句前提就是「人们以为是给孩子写的」。干扰点：忽略 in fact 的转折。</li></ul><p><strong>整句翻译</strong>：……其实是写给成人的。</p><p><strong>词组</strong>：<code>be written for</code> 为……而写</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第2段 · 第11空所在句）：This may be why many of the books regarded as <strong>10</strong> of children’s literature were in fact written for <strong>11</strong>.</p></details><p><strong>Children, left for themselves, often ____ the worst possible interest in literature.</strong></p><ul><li>A. are</li><li>B. show</li><li>C. find</li><li>D. add</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（show）</strong> —— 任其选择时，孩子「表现出」show 最糟糕的文学兴趣。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are the worst possible interest 缺少成分，interest 不能直接作表语。干扰点：只求主谓一致。</li><li>B ✅ show the worst possible interest in literature 表「表现出最糟糕的兴趣」，与后文挑无想象力书籍的情节一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ find interest 结构不完整（须说 find sth. interesting）。干扰点：把「发现兴趣」当成固定说法。</li><li>D ❌ add the interest 不成立（add 需搭配 to）。干扰点：只求动词能填。</li></ul><p><strong>整句翻译</strong>：孩子们如果放任自流，往往会对文学表现出最糟糕的品味。</p><p><strong>词组</strong>：<code>show interest in</code> 对……表现出兴趣</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第3段 · 第12空所在句）：Children, left for themselves, often <strong>12</strong> the worst possible interest in literature.</p></details><p><strong>Just leave a child in a bookshop or a ____ and he will more willingly choose the books written in an unimaginative way.</strong></p><ul><li>A. school</li><li>B. home</li><li>C. office</li><li>D. library</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（library）</strong> —— 与书店并列的选书场所：「图书馆」library。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ school 与 bookshop 并列的是另一个「可挑书」的地方，学校不强调这一点。干扰点：把「孩子」与学校联想。</li><li>B ❌ home 与「在书店或某处挑选」的并列不搭。干扰点：只求词能填。</li><li>C ❌ office 与儿童选书无关。干扰点：忽略主体是孩子。</li><li>D ✅ a bookshop or a library 是「书店或图书馆」的常见并列，都提供大量书籍可挑。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：只要把孩子放到书店或图书馆里，他就更愿意挑那些写得毫无想象力的书。</p><p><strong>词组</strong>：<code>leave sb. in a place</code> 把某人留在某处</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第3段 · 第13空所在句）：Just leave a child in a bookshop or a <strong>13</strong> and he will more willingly choose the books written in an unimaginative way, or have a look at the most children’s comics, full of the stories and jokes which are the rejections of teachers and right-thinking parents.</p></details><p><strong>Perhaps we parents should stop ____ to brainwash children into accepting our taste in literature.</strong></p><ul><li>A. going</li><li>B. liking</li><li>C. trying</li><li>D. preferring</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（trying）</strong> —— stop trying to do 停止「试图」给孩子洗脑。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stop going to brainwash 表「不再去洗脑」，与 should stop 的建议语义不搭。干扰点：只求与 to 搭配。</li><li>B ❌ like to brainwash 表「喜欢给人洗脑」，偏离「别再做」的建议。干扰点：忽略语义。</li><li>C ✅ stop trying to brainwash children into accepting our taste 表「别再试图把我们的品味灌输给孩子」，与后句「不该期待孩子喜欢同样的书」一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ prefer to brainwash 表「更愿意洗脑」，不成建议。干扰点：只求词形能填。</li></ul><p><strong>整句翻译</strong>：也许我们父母应该停止试图把自己的文学品味灌输给孩子。</p><p><strong>词组</strong>：<code>stop trying to do sth.</code> 停止试图做某事；<code>brainwash sb. into doing sth.</code> 给某人洗脑使其做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第4段 · 第14空所在句）：Perhaps we parents should stop <strong>14</strong> to brainwash children into accepting our taste in literature.</p></details><p><strong>After all, children and adults are so ____ that we parents should not expect that they will enjoy the same books.</strong></p><ul><li>A. same</li><li>B. friendly</li><li>C. different</li><li>D. common</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（different）</strong> —— 儿童和成人「差别很大」different，不必期待喜欢同样的书。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ so same that we should not expect that they will enjoy the same books 自相矛盾。干扰点：忽略与后句的逻辑。</li><li>B ❌ friendly 与「不该期待同好」的推论无关。干扰点：只求形容词能填。</li><li>C ✅ children and adults are so different that we should not expect that they will enjoy the same books：因果一致，收束全文并引出 compromise。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ common 不表差异。干扰点：把 common 当 different 用。</li></ul><p><strong>整句翻译</strong>：毕竟，孩子和成人如此不同，我们不该指望他们会喜欢同样的书。</p><p><strong>词组</strong>：<code>so…that…</code> 如此……以至于……；<code>compromise over sth.</code> 在某事上妥协</p><p><strong>对比自测</strong>：做完后对照 quiz-p16:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 怎样选择儿童读物 · 第4段 · 第15空所在句）：After all, children and adults are so <strong>15</strong> that we parents should not expect that they will enjoy the same books.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>我想，大多数父母都有给孩子读睡前故事的经历，也一定意识到，写一本优秀的儿童读物非常困难。作者要么立意太高，孩子跟不上故事内容；要么故事显得像在对读者说教。</p><p>最好的儿童书既不很难，也不过分简单，既能满足听故事的孩子，也能满足朗读它的成人。遗憾的是，这样的书实际上很少，所以找到合适睡前故事的问题并不容易解决。也许正因如此，许多被视为儿童文学杰作的书其实是为成年人写的，《爱丽丝梦游仙境》或许就是最明显的例子。</p><p>若任由孩子自己选择，他们往往会表现出最糟糕的文学兴趣。把孩子单独留在书店或图书馆，他更可能挑选缺乏想象力的书，或翻看充满故事和笑话、却被老师和观念端正的父母排斥的儿童漫画。</p><p>也许父母应停止试图给孩子“洗脑”，逼他们接受成人的文学品味。毕竟儿童和成人差别很大，父母不应期待他们喜欢同样的书。因此，在睡前故事上恐怕只能彼此妥协。</p></details><h3 id="练习十六-·-mick-的鼻子和耳朵" tabindex="-1"><a class="header-anchor" href="#练习十六-·-mick-的鼻子和耳朵"><span>练习十六 · Mick 的鼻子和耳朵</span></a></h3><p>Mrs. Ball had a son. His name was Mick. She <strong><strong>1</strong></strong> him very much and as he was not a <strong><strong>2</strong></strong> child, she was always <strong><strong>3</strong></strong> that he might be ill, <strong><strong>4</strong></strong> she used to take him to see the best <strong><strong>5</strong></strong> in the town four times a year to be looked <strong><strong>6</strong></strong>.</p><p>During one of these <strong><strong>7</strong></strong>, the doctor gave Mick all kinds of tests and then said to him, “Have you had any <strong><strong>8</strong></strong> with your nose or ears recently?” Mick <strong><strong>9</strong></strong> for a second and then answered, “Yes, I <strong><strong>10</strong></strong>.”</p><p>Mrs. Ball was very <strong><strong>11</strong></strong>. “But I’m sure you have <strong><strong>12</strong></strong> told me that, Mick!” she said worriedly. “Oh, really?” said the doctor <strong><strong>13</strong></strong>. “And what trouble have you with your nose and ears, my boy?” “Well,” answered Mick, “I always have trouble with them when I’m <strong><strong>14</strong></strong> my sweater off, because the <strong><strong>15</strong></strong> is very tight.”</p><p><strong>Mrs. Ball had a son. His name was Mick. She ____ him very much.</strong></p><ul><li>A. loved</li><li>B. hated</li><li>C. missed</li><li>D. cared</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（loved）</strong> —— 总担心他生病、常带他看病，说明非常「爱」loved 他。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ She loved him very much 与后文她一年四次带孩子体检的关切一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ hated 表恨，与反复体检的照顾相反。干扰点：只看「母亲」的身份就下判断。</li><li>C ❌ missed 表想念，与母子同住的语境不符。干扰点：把「关心」混作「思念」。</li><li>D ❌ care 表在乎时须接 for/about，care him 不合。干扰点：只求语义相近。</li></ul><p><strong>整句翻译</strong>：Ball 太太有一个儿子，名叫 Mick。她非常爱他。</p><p><strong>词组</strong>：<code>love sb. very much</code> 非常爱某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第1空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>…and as he was not a ____ child, she was always ____ that he might be ill,</strong></p><ul><li>A. rich</li><li>B. clever</li><li>C. strong</li><li>D. happy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（strong）</strong> —— 总担心生病，是因为他体格不「强壮」strong。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ rich 表富有，与「怕他生病」无因果。干扰点：只求形容词能填。</li><li>B ❌ clever 表聪明，同样解释不了生病的担忧。干扰点：褒义形容词随手填。</li><li>C ✅ as he was not a strong child, she was always afraid that he might be ill：体质弱才总担心生病。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ happy 表快乐，与担忧无因果。干扰点：忽略语义。</li></ul><p><strong>整句翻译</strong>：……因为他不是个强壮的孩子，她总担心他会生病。</p><p><strong>词组</strong>：<code>a strong child</code> 身体结实的孩子</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第2空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>…as he was not a strong child, she was always ____ that he might be ill,</strong></p><ul><li>A. afraid</li><li>B. surprised</li><li>C. glad</li><li>D. sure</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（afraid）</strong> —— be afraid that 担心他可能生病。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ be afraid that he might be ill 表「担心他会生病」，也是频繁体检的原因。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ surprised 表惊讶，不会催生一年四次的体检。干扰点：忽略行为的持续性。</li><li>C ❌ glad 表高兴，与担心生病相反。干扰点：把照护视为快乐。</li><li>D ❌ sure 与 might 语义冲突（不能既确定又「可能」）。干扰点：只求能带从句。</li></ul><p><strong>整句翻译</strong>：……她总担心他会生病。</p><p><strong>词组</strong>：<code>be afraid that…</code> 担心……</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第3空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>…she was always afraid that he might be ill, ____ she used to take him to see the best ____ in the town four times a year.</strong></p><ul><li>A. which</li><li>B. for</li><li>C. but</li><li>D. so</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（so）</strong> —— 前因后果：担心生病，「所以」so 经常带他去看医生。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 不能这样连接两个句子且缺先行词。干扰点：只求能连接。</li><li>B ❌ for 表原因，会构成「因为体检所以担心」的反向因果。干扰点：因果方向倒置。</li><li>C ❌ but 表转折，此处是顺承因果。干扰点：按语气随手选词。</li><li>D ✅ she was always afraid that he might be ill, so she used to take him to see the best doctor four times a year：担心 → 带他看医生，因果顺承。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……所以她每年带他去看城里最好的医生四次。</p><p><strong>词组</strong>：<code>used to do sth.</code> 过去常常做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第4空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>…she used to take him to see the best ____ in the town four times a year.</strong></p><ul><li>A. player</li><li>B. teacher</li><li>C. doctor</li><li>D. lawyer</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（doctor）</strong> —— 担心生病要去看「医生」doctor。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ player 与后文 look over（体检）不符。干扰点：只求名词能填。</li><li>B ❌ teacher 与体检无关。干扰点：把「孩子」与老师联想。</li><li>C ✅ 后文 the doctor gave Mick all kinds of tests 复现 doctor，且 be looked over 指向医生。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ lawyer 与体检无关。干扰点：忽略下文提示。</li></ul><p><strong>整句翻译</strong>：……带他去看城里最好的医生。</p><p><strong>词组</strong>：<code>the best doctor in the town</code> 城里最好的医生</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第5空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>…to see the best doctor in the town four times a year to be looked ____.</strong></p><ul><li>A. round</li><li>B. over</li><li>C. for</li><li>D. after</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（over）</strong> —— look over 检查身体，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ look round 表「四处看看」，不是体检。干扰点：只求与 look 搭配。</li><li>B ✅ be looked over 表「接受检查」，与 the doctor gave Mick all kinds of tests 一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ look for 表寻找，与体检无关。干扰点：忽略宾语是 Mick。</li><li>D ❌ look after 表照顾，偏日常照料而非医学检查。干扰点：与「父母照顾孩子」联想。</li></ul><p><strong>整句翻译</strong>：……一年四次去接受检查。</p><p><strong>词组</strong>：<code>be looked over</code> 接受体检</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第1段 · 第6空所在句）：She <strong>1</strong> him very much and as he was not a <strong>2</strong> child, she was always <strong>3</strong> that he might be ill, <strong>4</strong> she used to take him to see the best <strong>5</strong> in the town four times a year to be looked <strong>6</strong>.</p></details><p><strong>During one of these ____, the doctor gave Mick all kinds of tests.</strong></p><ul><li>A. talks</li><li>B. years</li><li>C. visits</li><li>D. stays</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（visits）</strong> —— 每年四次的看病，「就诊」visits 中的一次。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ talks 与「医生做各种检查」的诊疗场景不搭。干扰点：只求名词能填。</li><li>B ❌ years 与 four times a year 的频次矛盾。干扰点：忽略时间线索。</li><li>C ✅ During one of these visits 表「在其中一次就诊中」，与每年四次看诊的安排一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ stays 表逗留，与门诊不符。干扰点：把就诊理解成住院。</li></ul><p><strong>整句翻译</strong>：在其中的一次就诊中，医生给 Mick 做了各种检查。</p><p><strong>词组</strong>：<code>during one of these visits</code> 在其中一次就诊时</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第2段 · 第7空所在句）：During one of these <strong>7</strong>, the doctor gave Mick all kinds of tests and then said to him, “Have you had any <strong>8</strong> with your nose or ears recently?”</p></details><p><strong>“Have you had any ____ with your nose or ears recently?”</strong></p><ul><li>A. answer</li><li>B. thing</li><li>C. word</li><li>D. trouble</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（trouble）</strong> —— have trouble with 有不舒服/毛病；与结尾 have trouble with them 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ have any answer with your nose 不成语义。干扰点：只求名词能填。</li><li>B ❌ have any thing with 不成立（应为 anything wrong with）。干扰点：把 anything 拆开来填。</li><li>C ❌ have any word with 不表病症。干扰点：忽略语义。</li><li>D ✅ 后文 what trouble have you with your nose and ears 直接复现 trouble，表「鼻子或耳朵有什么不适」。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“你的鼻子或耳朵最近有什么不适吗？”</p><p><strong>词组</strong>：<code>have trouble with sth.</code> 某处有毛病/不适</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第2段 · 第8空所在句）：During one of these <strong>7</strong>, the doctor gave Mick all kinds of tests and then said to him, “Have you had any <strong>8</strong> with your nose or ears recently?”</p></details><p><strong>Mick ____ for a second and then answered, “Yes, I ____.”</strong></p><ul><li>A. waited</li><li>B. thought</li><li>C. stood</li><li>D. looked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（thought）</strong> —— 想了一会儿才回答：「想了想」thought。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ waited for a second 表等待，与随后的「答话」缺少「思考」环节。干扰点：只求动词能填。</li><li>B ✅ thought for a second and then answered 表「想了一秒才回答」，解释了随后出人意料的回答（毛衣领口太紧）。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ stood for a second 与作答不接。干扰点：忽略语义。</li><li>D ❌ looked for a second 表看一秒，不合「思考后作答」的逻辑。干扰点：只求搭配成立。</li></ul><p><strong>整句翻译</strong>：Mick 想了一秒，然后回答。</p><p><strong>词组</strong>：<code>think for a second</code> 想了一会儿</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第2段 · 第9空所在句）：Mick <strong>9</strong> for a second and then answered, “Yes, I <strong>10</strong>.”</p></details><p><strong>Mick thought for a second and then answered, “Yes, I ____.”</strong></p><ul><li>A. did</li><li>B. will</li><li>C. have</li><li>D. do</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（have）</strong> —— 回答 Have you had …? 用 have：Yes, I have。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ did 与问句的完成时不一致（否定/肯定回答需与 have 呼应）。干扰点：忽略时态呼应。</li><li>B ❌ will 表将来，与 recently（最近）矛盾。干扰点：只求词形。</li><li>C ✅ 问句 Have you had… 的肯定回答是 Yes, I have。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ do 与完成时不符。干扰点：一般现在时顺口。</li></ul><p><strong>整句翻译</strong>：“是的，有过。”</p><p><strong>词组</strong>：<code>Yes, I have.</code> 是的，有过。</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第2段 · 第10空所在句）：Mick <strong>9</strong> for a second and then answered, “Yes, I <strong>10</strong>.”</p></details><p><strong>Mrs. Ball was very ____. “But I’m sure you have ____ told me that, Mick!”</strong></p><ul><li>A. excited</li><li>B. interested</li><li>C. pleased</li><li>D. surprised</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（surprised）</strong> —— 从没听儿子说过，所以非常「惊讶」surprised。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ excited 表兴奋，与「你从没告诉过我」的质问语气不符。干扰点：褒义词随手填。</li><li>B ❌ interested 表感兴趣，与担忧矛盾。干扰点：忽略语气。</li><li>C ❌ pleased 表高兴，与 But 引出的质疑相反。干扰点：忽略转折。</li><li>D ✅ Mrs. Ball was very surprised 表「非常惊讶」，因为她从未听儿子提过这些不适。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：Ball 太太非常惊讶。“可我敢肯定你从没告诉过我，Mick！”她担心地说。</p><p><strong>词组</strong>：<code>be surprised at sth.</code> 对某事感到惊讶</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第3段 · 第11空所在句）：Ball was very <strong>11</strong>.</p></details><p><strong>“But I’m sure you have ____ told me that, Mick!” she said worriedly.</strong></p><ul><li>A. already</li><li>B. just</li><li>C. never</li><li>D. always</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（never）</strong> —— 「你以前从没告诉过我」never told me。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ already 表已经，与 but 引出的反驳不合。干扰点：完成时高频状语顺口填。</li><li>B ❌ just 表刚刚，同样不与质问呼应。干扰点：只看时态。</li><li>C ✅ I’m sure you have never told me that（我肯定你从没告诉过我）与 was very surprised、worriedly 的语气一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ always 表总是，与「没告诉过」相反。干扰点：忽略否定语义。</li></ul><p><strong>整句翻译</strong>：“可我敢肯定你从没告诉过我，Mick！”</p><p><strong>词组</strong>：<code>have never done sth.</code> 从未做过某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第3段 · 第12空所在句）：“But I’m sure you have <strong>12</strong> told me that, Mick!” she said worriedly.</p></details><p><strong>“Oh, really?” said the doctor ____.</strong></p><ul><li>A. angrily</li><li>B. seriously</li><li>C. happily</li><li>D. carefully</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（seriously）</strong> —— 医生「严肃地」seriously 追问。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ angrily 表生气，而医生只是认真追问病情。干扰点：把问诊当责备。</li><li>B ✅ said the doctor seriously 表「医生认真地说」，与随后 And what trouble have you with your nose and ears? 的专业追问相符。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ happily 表开心，与严肃问诊不搭。干扰点：只看褒贬色彩。</li><li>D ❌ carefully 表仔细，多修饰动作；此处问话的语调用 seriously 更贴切。干扰点：seriously/carefully 同义域。</li></ul><p><strong>整句翻译</strong>：“哦，真的吗？”医生认真地说。</p><p><strong>词组</strong>：<code>say seriously</code> 认真地说</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第3段 · 第13空所在句）：“Oh, really?” said the doctor <strong>13</strong>.</p></details><p><strong>“I always have trouble with them when I’m ____ my sweater off.”</strong></p><ul><li>A. turning</li><li>B. taking</li><li>C. keeping</li><li>D. putting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（taking）</strong> —— take off 脱掉：脱毛衣时鼻子耳朵有麻烦。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ turning off 表关闭（电器），与毛衣不符。干扰点：忽略与 sweater 的搭配。</li><li>B ✅ take one’s sweater off 表「脱下毛衣」，与 because the collar is very tight 构成合理因果。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ keeping off 表远离，不表脱下。干扰点：只求与 off 搭配。</li><li>D ❌ putting off 表推迟；表示穿上的是 put on，与「有麻烦」的抱怨不符。干扰点：忽略 off 的搭配义。</li></ul><p><strong>整句翻译</strong>：“我脱毛衣的时候鼻子和耳朵总是不舒服……”</p><p><strong>词组</strong>：<code>take sth. off</code> 脱下某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第3段 · 第14空所在句）：“Well,” answered Mick, “I always have trouble with them when I’m <strong>14</strong> my sweater off, because the <strong>15</strong> is very tight.”</p></details><p><strong>“…because the ____ is very tight.”</strong></p><ul><li>A. collar</li><li>B. nose</li><li>C. mouth</li><li>D. ear</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（collar）</strong> —— 脱毛衣会扯到头脸，是因为「领口」collar 太紧。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the collar is very tight 表「领口很紧」——脱毛衣时勒到鼻子和耳朵，这正是「鼻子耳朵有毛病」的真相。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ nose 不会「紧」，与 very tight 搭配不当。干扰点：把被卡住的部位当答案。</li><li>C ❌ mouth 同理不能与 tight 搭配。干扰点：只求词形能填。</li><li>D ❌ ear 也不会「紧」。干扰点：忽略 very tight 的语义要求。</li></ul><p><strong>整句翻译</strong>：“……因为领口太紧了。”</p><p><strong>词组</strong>：<code>a tight collar</code> 很紧的领口</p><p><strong>对比自测</strong>：做完后对照 quiz-p17:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十六 · Mick 的鼻子和耳朵 · 第3段 · 第15空所在句）：“Well,” answered Mick, “I always have trouble with them when I’m <strong>14</strong> my sweater off, because the <strong>15</strong> is very tight.”</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>Ball 太太有个儿子叫 Mick。她非常爱他。因为他身体不强壮，她总担心他会生病，所以过去每年四次带他去看城里最好的医生，接受检查。</p><p>一次就诊时，医生给 Mick 做了各种检查，然后问：“最近你的鼻子或耳朵有什么不舒服吗？”Mick 想了一会儿，回答：“有。”Ball 太太非常惊讶，担忧地说：“可我敢肯定，你以前从没告诉过我！”医生严肃地追问究竟有什么问题。Mick 说：“我脱毛衣时，鼻子和耳朵总有麻烦，因为领口太紧了。”</p></details><h3 id="练习十七-·-计算机" tabindex="-1"><a class="header-anchor" href="#练习十七-·-计算机"><span>练习十七 · 计算机</span></a></h3><div class="hint-container caution"><p class="hint-container-title">易错</p><p>源课件错页源 PDF p43–44 两页右侧都误重复了第 1–5 题的选项，第 6–15 题各自的 A–D 选项缺失，故此处只收录选项完整的第 1–5 题；按课件勾选，第 6–15 空所填词依次为 <strong>called、large、Since、through、useful、for、learn、what、for、As</strong>。</p></div><p>The computer plays an important part in our everyday life. It is one of the great <strong><strong>1</strong></strong> in the world in the <strong><strong>2</strong></strong> century. It works for us not only at home, in the offices, in big shops, <strong><strong>3</strong></strong> at schools. Today it is used <strong><strong>4</strong></strong> many ways. It really <strong><strong>5</strong></strong> the world large wealth and happiness.</p><p>The first computer in the world was <strong><strong>6</strong></strong> Enid. It was built in America in 1946. It was <strong><strong>7</strong></strong> and heavy. <strong><strong>8</strong></strong> it was born, it has been developing very fast. Until now it has gone <strong><strong>9</strong></strong> four periods and changed a lot. There’re many kinds of computers. Computers are getting smaller and smaller and computing faster and faster. It becomes more and more <strong><strong>10</strong></strong>.</p><p>The computer can do most of the things <strong><strong>11</strong></strong> the people. It can help us to <strong><strong>12</strong></strong> about the real world more quickly, to learn <strong><strong>13</strong></strong> we want to learn and to think <strong><strong>14</strong></strong> ourselves. <strong><strong>15</strong></strong> a student in the twenty-first century, you must work hard at it.</p><p><strong>【第1空】It is one of the great ____ in the world in the ____ century.（本空为第 1 空）</strong></p><ul><li>A. inventions</li><li>B. discoveries</li><li>C. robots</li><li>D. inventors</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（inventions）</strong> —— 计算机是二十世纪的伟大「发明」inventions；discoveries 指发现。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 计算机是原本不存在、被人造出来的东西，故用 invention（发明）。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ discovery 表「发现」，指原本存在、被人找到的事物（如新大陆、元素）。干扰点：中文「发明」与「发现」都带「新」。</li><li>C ❌ robots 表机器人，计算机不只是机器人，且 the great robots in the world 与「最伟大的」这一评价不搭。干扰点：把计算机与机器人混同。</li><li>D ❌ inventor 表「发明者」，指的是人，而本句主语 It 指计算机。干扰点：忽略 It 指代的是物。</li></ul><p><strong>整句翻译</strong>：计算机在我们的日常生活中扮演着重要的角色。它是二十世纪世界上最伟大的发明之一。</p><p><strong>词组</strong>：<code>play an important part in</code> 在……中起重要作用；<code>one of the…</code> 最……之一</p><p><strong>对比自测</strong>：做完后对照 quiz-p18:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十七 · 计算机 · 第1段 · 第1空所在句）：It is one of the great <strong>1</strong> in the world in the <strong>2</strong> century.</p></details><p><strong>【第2空】It is one of the great inventions in the world in the ____ century.</strong></p><ul><li>A. twenty-first</li><li>B. twenties</li><li>C. twelfth</li><li>D. twentieth</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（twentieth）</strong> —— 1946 年建成，属「二十世纪」the twentieth century。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ twenty-first 与后文 It was built in America in 1946（第一台计算机 1946 年在美国造出）矛盾。干扰点：把「当今」误作「二十一世纪」。</li><li>B ❌ twenties 表「二十年代/二十几岁」，不是世纪表述。干扰点：只求词形相近。</li><li>C ❌ twelfth 与 1946 年相去甚远。干扰点：序数词随手填。</li><li>D ✅ in the twentieth century 与后文 1946 年建成的事实一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……它是二十世纪世界上最伟大的发明之一。</p><p><strong>词组</strong>：<code>in the twentieth century</code> 在二十世纪</p><p><strong>对比自测</strong>：做完后对照 quiz-p18:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十七 · 计算机 · 第1段 · 第2空所在句）：It is one of the great <strong>1</strong> in the world in the <strong>2</strong> century.</p></details><p><strong>【第3空】It works for us not only at home, in the offices, in big shops, ____ at schools.</strong></p><ul><li>A. also</li><li>B. but also</li><li>C. too</li><li>D. either</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（but also）</strong> —— not only … but also … 固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ also 单独使用不能与前面的 not only 呼应。干扰点：中文「也」直译。</li><li>B ✅ not only…but also… 是固定关联结构，表「不仅……而且……」，与前面的 not only 配对。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ too 与 not only 不配对。干扰点：把表示「也」的几种说法混用。</li><li>D ❌ either 与 not only 不配对（either 需与 or 配对）。干扰点：只求词能填进去。</li></ul><p><strong>整句翻译</strong>：它不仅在家中、办公室、大商店里为我们工作，在学校里也是如此。</p><p><strong>词组</strong>：<code>not only…but also…</code> 不仅……而且……</p><p><strong>对比自测</strong>：做完后对照 quiz-p18:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十七 · 计算机 · 第1段 · 第3空所在句）：It works for us not only at home, in the offices, in big shops, <strong>3</strong> at schools.</p></details><p><strong>【第4空】Today it is used ____ many ways.</strong></p><ul><li>A. in</li><li>B. to</li><li>C. by</li><li>D. over</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in）</strong> —— in many ways 在许多方面。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ in many ways 表「在许多方面」，是固定搭配。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ used to do 表「过去常常」，与 is used（被使用）的被动语义冲突。干扰点：忽略 used to 的特殊含义。</li><li>C ❌ be used by 后接使用者，而 many ways 表方式。干扰点：把被动语态的使用者与方式混淆。</li><li>D ❌ used over many ways 不成搭配。干扰点：介词随手填。</li></ul><p><strong>整句翻译</strong>：今天，它在许多方面被使用。</p><p><strong>词组</strong>：<code>in many ways</code> 在许多方面；<code>be used</code> 被使用</p><p><strong>对比自测</strong>：做完后对照 quiz-p18:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十七 · 计算机 · 第1段 · 第4空所在句）：Today it is used <strong>4</strong> many ways.</p></details><p><strong>【第5空】It really ____ the world large wealth and happiness.</strong></p><ul><li>A. takes</li><li>B. helps</li><li>C. gets</li><li>D. brings</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（brings）</strong> —— bring sb. sth. 给世界「带来」brings 财富与幸福。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take 表拿走，方向相反（take…away from）。干扰点：bring/take 方向混用。</li><li>B ❌ help 表帮助，不能说 help the world large wealth（缺介词 to）。干扰点：只求语义正面。</li><li>C ❌ get 表获得，主语是 It（计算机），把它当作受益方不合逻辑。干扰点：只求动词能填。</li><li>D ✅ bring the world large wealth and happiness 表「给世界带来巨大财富与幸福」，bring sb. sth. 双宾结构成立。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：它确实给世界带来了巨大的财富与幸福。</p><p><strong>词组</strong>：<code>bring sb. sth.</code> 给某人带来某物；<code>wealth and happiness</code> 财富与幸福</p><p><strong>对比自测</strong>：做完后对照 quiz-p18:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十七 · 计算机 · 第1段 · 第5空所在句）：It really <strong>5</strong> the world large wealth and happiness.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>计算机在日常生活中发挥重要作用，是二十世纪世界上的伟大发明之一。它不仅在家庭、办公室和大型商店中为人们工作，也用于学校。如今计算机被用于许多方面，的确给世界带来大量财富与幸福。</p><p>世界上第一台计算机名为 Enid，于 1946 年在美国建成。它又大又重。自诞生以来，计算机发展得非常快，迄今已经历四个阶段并发生巨大变化。计算机种类很多，体积越来越小，运算速度越来越快，也越来越有用。</p><p>计算机能替人们做大多数事情，帮助我们更快了解真实世界、学习想学的内容，并独立思考。作为二十一世纪的学生，你必须努力学习计算机知识。</p></details><h3 id="练习十八-·-沙漠中的生活" tabindex="-1"><a class="header-anchor" href="#练习十八-·-沙漠中的生活"><span>练习十八 · 沙漠中的生活</span></a></h3><p>You may think there is only sand in the desert of the world, <strong><strong>1</strong></strong> it is not true. In the desert, as we know, there is a little <strong><strong>2</strong></strong>, but it is not <strong><strong>3</strong></strong> for most plants. Still we can see some plants <strong><strong>4</strong></strong> in the desert.</p><p>There is <strong><strong>5</strong></strong> in some places in the desert. We <strong><strong>6</strong></strong> these places oases. In the oases, there are villages and towns. People grow <strong><strong>7</strong></strong> kinds of crops in the fields there.</p><p>People <strong><strong>8</strong></strong> live outside the oases. They have camels, sheep and other animals. These animals depend <strong><strong>9</strong></strong> the desert plants for their food and do not need <strong><strong>10</strong></strong> water.</p><p>The <strong><strong>11</strong></strong> are useful to the desert people in many ways. They eat the meat and drink the milk of the animals. They use the camels for carrying water, food, tents and something else.</p><p>The people of the desert have to keep moving from place to place. They must always look <strong><strong>12</strong></strong> grass or desert plants for their animals. When there is no more food for their animals, they move to <strong><strong>13</strong></strong> place. The desert people are <strong><strong>14</strong></strong>. No man in the desert would ever refuse <strong><strong>15</strong></strong> the people in trouble and give them food and water.</p><p><strong>You may think there is only sand in the desert of the world, ____ it is not true.</strong></p><ul><li>A. and</li><li>B. but</li><li>C. or</li><li>D. so</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（but）</strong> —— 前后转折：其实并非如此，用 but。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ and 表并列，而前后是「你以为」与「其实不对」的对立。干扰点：按顺承理解。</li><li>B ✅ You may think there is only sand…, but it is not true 是「先立后破」的常见句式，but 表转折。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ or 表选择，不合此处。干扰点：只求连接词能填。</li><li>D ❌ so 表结果，逻辑不通。干扰点：因果词随手填。</li></ul><p><strong>整句翻译</strong>：你也许以为世界上的沙漠里只有沙子，但事实并非如此。</p><p><strong>词组</strong>：<code>as we know</code> 正如我们所知</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第1段 · 第1空所在句）：You may think there is only sand in the desert of the world, <strong>1</strong> it is not true.</p></details><p><strong>In the desert, as we know, there is a little ____, but it is not ____ for most plants.</strong></p><ul><li>A. rain</li><li>B. rains</li><li>C. wind</li><li>D. winds</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（rain）</strong> —— a little 修饰不可数名词，沙漠里有少量「雨水」rain。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ rain 是不可数名词，a little rain 表「一点雨水」，与后句 not enough for most plants 一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ rain 作「雨」时不可数，不能加 s。干扰点：忽略不可数。</li><li>C ❌ wind 与植物生长的「够不够」关系不如雨水直接，下文也未提风。干扰点：把沙漠特征随手填。</li><li>D ❌ winds 复数同样不合，且与植物的关系更远。干扰点：只求词形。</li></ul><p><strong>整句翻译</strong>：在沙漠里，正如我们所知，有一点雨水，但对大多数植物来说并不够。</p><p><strong>词组</strong>：<code>a little + 不可数名词</code> 一点……</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第1段 · 第2空所在句）：In the desert, as we know, there is a little <strong>2</strong>, but it is not <strong>3</strong> for most plants.</p></details><p><strong>There is a little rain in the desert, but it is not ____ for most plants.</strong></p><ul><li>A. good</li><li>B. good enough</li><li>C. enough good</li><li>D. enough</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（enough）</strong> —— enough 修饰形容词时后置，not enough for most plants 不够大多数植物生长。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ not good for most plants 表「对植物不好」，语义偏「有害」，而本句是「量不够」。干扰点：把「不够」与「不好」混同。</li><li>B ❌ good enough 会把主语理解错：not good enough for plants 表「（沙漠）对植物不够好」，而本句主语是 rain。干扰点：忽略主语。</li><li>C ❌ enough good 语序错误（enough 修饰形容词时须后置）。干扰点：只求词形。</li><li>D ✅ it is not enough for most plants 中的 it 指前句的 rain，表「雨水不够」，与 but 的转折一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：沙漠里有一点雨水，但对大多数植物来说并不够。</p><p><strong>词组</strong>：<code>be enough for</code> 对……足够</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第1段 · 第3空所在句）：In the desert, as we know, there is a little <strong>2</strong>, but it is not <strong>3</strong> for most plants.</p></details><p><strong>Still we can see some plants ____ in the desert.</strong></p><ul><li>A. live</li><li>B. to live</li><li>C. lives</li><li>D. lived</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（live）</strong> —— see sb./sth. do 省略 to 的不定式作宾补：see some plants live。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ see some plants live in the desert 中 live 作宾语补足语，表「看到植物生长着」。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ 感官动词 see 后接省略 to 的不定式，不能写 to live。干扰点：把 see sb. to do 当成结构。</li><li>C ❌ plants 是复数，lives 主谓不一致。干扰点：忽略复数主语。</li><li>D ❌ lived 与全篇一般现在时不一致。干扰点：只求词形。</li></ul><p><strong>整句翻译</strong>：尽管如此，我们仍能看到一些植物在沙漠中生长。</p><p><strong>词组</strong>：<code>see sb./sth. do sth.</code> 看到某人/某物做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第1段 · 第4空所在句）：Still we can see some plants <strong>4</strong> in the desert.</p></details><p><strong>There is ____ in some places in the desert. We ____ these places oases.</strong></p><ul><li>A. stones</li><li>B. plants</li><li>C. wood</li><li>D. water</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（water）</strong> —— 绿洲 oases 的特征是有「水」water。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stones 与「绿洲」的成因无关。干扰点：把沙漠要素随手填。</li><li>B ❌ plants 是绿洲的结果而非成因。干扰点：只求名词能填。</li><li>C ❌ wood 与绿洲无关。干扰点：忽略下文 oases。</li><li>D ✅ There is water in some places in the desert. We call these places oases.——有水才有绿洲，与命名直接对应。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：在沙漠的有些地方有水。我们把这样的地方叫做绿洲。</p><p><strong>词组</strong>：<code>oasis</code> 绿洲（复数 oases）</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第2段 · 第5空所在句）：There is <strong>5</strong> in some places in the desert.</p></details><p><strong>We ____ these places oases.</strong></p><ul><li>A. say</li><li>B. tell</li><li>C. call</li><li>D. find</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（call）</strong> —— call + 宾语 + 宾补：把这些地方「称为」call 绿洲。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ say 后接说话内容，不能带双宾语表命名。干扰点：中文「叫做」直译成 say。</li><li>B ❌ tell sb. sth. 需以人作间接宾语。干扰点：只求动词能填。</li><li>C ✅ call sth. sth. 表「把……叫做……」，We call these places oases 结构正确。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ find these places oases 表「发现这些地方是绿洲」，与「命名」不同。干扰点：把「叫」与「发现」混同。</li></ul><p><strong>整句翻译</strong>：我们把这样的地方叫做绿洲。</p><p><strong>词组</strong>：<code>call sth. sth.</code> 把某物叫做……</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第2段 · 第6空所在句）：We <strong>6</strong> these places oases.</p></details><p><strong>People grow ____ kinds of crops in the fields there.</strong></p><ul><li>A. every</li><li>B. all</li><li>C. a</li><li>D. one</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（all）</strong> —— 各种农作物用 all kinds of。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ every 后接单数名词，不能修饰 kinds。干扰点：忽略单复数。</li><li>B ✅ all kinds of crops 表「各种各样的庄稼」，是固定搭配。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ a kinds 单复数冲突。干扰点：只求词形能填。</li><li>D ❌ one kinds 同样单复数冲突。干扰点：忽略复数形式。</li></ul><p><strong>整句翻译</strong>：那里的人们在地里种各种各样的庄稼。</p><p><strong>词组</strong>：<code>all kinds of</code> 各种各样的</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第2段 · 第7空所在句）：People grow <strong>7</strong> kinds of crops in the fields there.</p></details><p><strong>People ____ live outside the oases.</strong></p><ul><li>A. also</li><li>B. too</li><li>C. either</li><li>D. still</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（also）</strong> —— also 位于实义动词前：绿洲「外也有人」也生活。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ also 用于句中（实义动词前），People also live outside the oases 合乎位置规则。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ too 多用于句末，不放在实义动词前。干扰点：also/too 的位置规则不清。</li><li>C ❌ either 用于否定句。干扰点：忽略句式。</li><li>D ❌ still 表「仍然」，与「绿洲之外也有人住」的并列义不同。干扰点：只求语义相近。</li></ul><p><strong>整句翻译</strong>：人们也住在绿洲之外。</p><p><strong>词组</strong>：<code>also</code> 也（句中位置）</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第3段 · 第8空所在句）：People <strong>8</strong> live outside the oases.</p></details><p><strong>These animals depend ____ the desert plants for their food.</strong></p><ul><li>A. with</li><li>B. in</li><li>C. on</li><li>D. by</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（on）</strong> —— depend on 依靠，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ depend with 不成搭配。干扰点：只求介词能填。</li><li>B ❌ depend in 不成搭配。干扰点：忽略固定搭配。</li><li>C ✅ depend on 是固定搭配，表「依靠」，These animals depend on the desert plants for their food。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ depend by 不成搭配。干扰点：与被动语态联想。</li></ul><p><strong>整句翻译</strong>：这些动物靠沙漠植物为食，不需要很多水。</p><p><strong>词组</strong>：<code>depend on</code> 依靠</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第3段 · 第9空所在句）：These animals depend <strong>9</strong> the desert plants for their food and do not need <strong>10</strong> water.</p></details><p><strong>These animals depend on the desert plants for their food and do not need ____ water.</strong></p><ul><li>A. a little</li><li>B. few</li><li>C. much</li><li>D. any</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（much）</strong> —— 骆驼等耐旱，「不需要很多水」much water（water 不可数用 much）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a little 表「一点（肯定）」，与 do not need 的否定语境冲突。干扰点：忽略否定。</li><li>B ❌ few 修饰可数名词，water 不可数。干扰点：few/little 混用。</li><li>C ✅ do not need much water 表「不需要很多水」，与沙漠动物靠植物取水的习性一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ any 会与 not 叠加成「不需要任何水」，与它们仍需少量水的实际矛盾。干扰点：忽略语义强度。</li></ul><p><strong>整句翻译</strong>：……不需要很多水。</p><p><strong>词组</strong>：<code>not need much</code> 不需要很多</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第3段 · 第10空所在句）：These animals depend <strong>9</strong> the desert plants for their food and do not need <strong>10</strong> water.</p></details><p><strong>The ____ are useful to the desert people in many ways.</strong></p><ul><li>A. water</li><li>B. plants</li><li>C. crops</li><li>D. animals</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（animals）</strong> —— 吃肉喝奶、骆驼运货，是「动物」animals 有用。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ water 不会「被吃肉、被喝奶」。干扰点：忽略后文 the meat and the milk。</li><li>B ❌ plants 不产奶，也不被吃「肉」。干扰点：只求名词能填。</li><li>C ❌ crops 同样不产肉与奶。干扰点：与上段 crops 就近取材。</li><li>D ✅ 后文 They eat the meat and drink the milk of the animals 直接对应 The animals are useful…。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：这些动物在很多方面都对沙漠居民很有用。</p><p><strong>词组</strong>：<code>be useful to</code> 对……有用</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第4段 · 第11空所在句）：The <strong>11</strong> are useful to the desert people in many ways.</p></details><p><strong>They must always look ____ grass or desert plants for their animals.</strong></p><ul><li>A. at</li><li>B. for</li><li>C. up</li><li>D. after</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（for）</strong> —— look for 寻找草料。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ look at 表「看」，而他们要做的是找到食物。干扰点：只求与 look 搭配。</li><li>B ✅ look for 表「寻找」，They must always look for grass or desert plants for their animals。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ look up 表查阅或仰视，不合。干扰点：带 up 的短语随手选。</li><li>D ❌ look after 表照顾，与「寻找草料」的语境不符。干扰点：由「牲畜」联想到照顾。</li></ul><p><strong>整句翻译</strong>：他们必须不断为牲畜寻找草地或沙漠植物。</p><p><strong>词组</strong>：<code>look for</code> 寻找；<code>from place to place</code> 从一个地方到另一个地方</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第5段 · 第12空所在句）：They must always look <strong>12</strong> grass or desert plants for their animals.</p></details><p><strong>When there is no more food for their animals, they move to ____ place.</strong></p><ul><li>A. other</li><li>B. the other</li><li>C. the others</li><li>D. another</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（another）</strong> —— 泛指「另一个地方」another place。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ other place 单数前需限定词（another 或 the other）。干扰点：other/another 混用。</li><li>B ❌ the other 表「两者中的另一个」，而这里是「再换一个地方」，不限于两个。干扰点：把「另一个」一律用 the other。</li><li>C ❌ the others 是复数代词，不能修饰 place。干扰点：忽略单复数。</li><li>D ✅ move to another place 表「搬到另一个地方」，与 keep moving from place to place 呼应。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：当牲畜没有更多食物时，他们就搬到另一个地方。</p><p><strong>词组</strong>：<code>move to another place</code> 搬到另一个地方</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第5段 · 第13空所在句）：When there is no more food for their animals, they move to <strong>13</strong> place.</p></details><p><strong>The desert people are ____. No man in the desert would ever refuse ____ the people in trouble.</strong></p><ul><li>A. well</li><li>B. friend</li><li>C. friendly</li><li>D. carefully</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（friendly）</strong> —— 绝不拒绝帮助别人，说明沙漠居民很「友善」friendly。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ well 作表语表「身体好」，也可作副词，不能表示「友善」。干扰点：把 well 当 good 用。</li><li>B ❌ friend 是名词，不能作 are 的表语形容词。干扰点：忽略词性。</li><li>C ✅ The desert people are friendly 表「沙漠居民很友善」，与后句没人会拒绝帮助遇困者一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ carefully 是副词，不能作表语。干扰点：忽略词性。</li></ul><p><strong>整句翻译</strong>：沙漠居民很友善。</p><p><strong>词组</strong>：<code>be friendly</code> 友善的</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第5段 · 第14空所在句）：The desert people are <strong>14</strong>.</p></details><p><strong>No man in the desert would ever refuse ____ the people in trouble and give them food and water.</strong></p><ul><li>A. help</li><li>B. helps</li><li>C. helping</li><li>D. to help</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（to help）</strong> —— refuse to do sth. 拒绝做某事，接不定式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ refuse 后须接不定式，不能直接跟动词原形。干扰点：只求语义。</li><li>B ❌ helps 的形式与 refuse 的结构不符。干扰点：忽略结构只看词形。</li><li>C ❌ refuse doing 不是规范搭配（refuse 后接 to do）。干扰点：把 avoid/enjoy 类动词的规则错套过来。</li><li>D ✅ refuse to help the people in trouble 表「拒绝帮助有困难的人」，refuse to do 是固定结构。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：沙漠里没有人会拒绝帮助遇到困难的人，并给他们食物和水。</p><p><strong>词组</strong>：<code>refuse to do sth.</code> 拒绝做某事；<code>in trouble</code> 处于困境</p><p><strong>对比自测</strong>：做完后对照 quiz-p19:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十八 · 沙漠中的生活 · 第5段 · 第15空所在句）：No man in the desert would ever refuse <strong>15</strong> the people in trouble and give them food and water.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>你也许认为世界上的沙漠只有沙子，但事实并非如此。我们知道，沙漠里有少量雨水，只是不足以供大多数植物生长；即便如此，仍能看到一些植物生活在沙漠中。</p><p>沙漠有些地方有水，人们称这些地方为绿洲。绿洲中有村庄和城镇，人们在田地里种植各种农作物。绿洲外也有人生活，他们饲养骆驼、绵羊和其他动物。这些动物依靠沙漠植物获取食物，不需要很多水。</p><p>动物在许多方面对沙漠居民有用：人们吃肉、喝奶，还用骆驼运水、食物、帐篷及其他物品。沙漠居民必须不断迁徙，为动物寻找草或沙漠植物。食物耗尽时，他们便搬到另一个地方。沙漠居民十分友善，绝不会拒绝帮助遇到困难的人，还会给他们食物和水。</p></details><h3 id="练习十九-·-最聪明的行李选择" tabindex="-1"><a class="header-anchor" href="#练习十九-·-最聪明的行李选择"><span>练习十九 · 最聪明的行李选择</span></a></h3><p>Once upon a time, a rich man wanted to make a trip to another town. He tried not only to take things to sell but also to take money to <strong><strong>1</strong></strong> things with. He <strong><strong>2</strong></strong> to take ten servants with him. They would <strong><strong>3</strong></strong> the things to sell and the food to <strong><strong>4</strong></strong> on their trip. Before they started, a little boy ran up to <strong><strong>5</strong></strong> and asked to <strong><strong>6</strong></strong> with them.</p><p>The rich man said to the little boy, “Well, <strong><strong>7</strong></strong> may go with us. <strong><strong>8</strong></strong> you are the smallest, the thinnest and the weakest of all my <strong><strong>9</strong></strong>, you can’t carry a <strong><strong>10</strong></strong> load. You must <strong><strong>11</strong></strong> the lightest one to carry.” The boy thanked his master and chose the biggest load to carry. That was bread.</p><p>“You are <strong><strong>12</strong></strong>,” said his master. “That is the biggest and the heaviest one.” The boy said <strong><strong>13</strong></strong> and lifted the load gladly.</p><p>On the trip they walked for days and at last they got to the town. All the servants were tired <strong><strong>14</strong></strong> the little servant. Do you know <strong><strong>15</strong></strong>? Most of the bread was eaten during the trip and a little was left when they arrived at the town.</p><p><strong>He tried not only to take things to sell but also to take money to ____ things with.</strong></p><ul><li>A. eat</li><li>B. buy</li><li>C. change</li><li>D. get</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（buy）</strong> —— 带钱是为了「买」buy 东西。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ eat 与 take money 的目的不合。干扰点：把「带钱」联想成买吃的。</li><li>B ✅ take money to buy things with 表「带钱买东西」，与 not only 前半句 take things to sell 构成「卖—买」对照。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ change things 表「换东西」，与商人做买卖的设定不符。干扰点：把「交易」笼统化成 change。</li><li>D ❌ get things 表「得到东西」，而带钱的目的正是购买，buy 更精确。干扰点：get 语义过宽。</li></ul><p><strong>整句翻译</strong>：他不仅想带上要卖的东西，还想带上买东西用的钱。</p><p><strong>词组</strong>：<code>not only…but also…</code> 不仅……而且……；<code>make a trip to</code> 去……旅行</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第1空所在句）：He tried not only to take things to sell but also to take money to <strong>1</strong> things with.</p></details><p><strong>He ____ to take ten servants with him.</strong></p><ul><li>A. decided</li><li>B. liked</li><li>C. hoped</li><li>D. tried</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（decided）</strong> —— 「决定」decided 带十个仆人同行。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ decided to take ten servants 表「决定带十个仆人」，为出行做安排，与下文 They would carry… 的分工一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ liked to take 表「喜欢带」，是一种偏好而非本次行程的安排。干扰点：只看语义通顺。</li><li>C ❌ hoped 表希望，语气不确定，与后文明确的十人分工不符。干扰点：忽略后续实施。</li><li>D ❌ tried to take 表尝试，与「确实带上了」矛盾。干扰点：只求能接 to do。</li></ul><p><strong>整句翻译</strong>：他决定带上十个仆人。</p><p><strong>词组</strong>：<code>decide to do sth.</code> 决定做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第2空所在句）：He <strong>2</strong> to take ten servants with him.</p></details><p><strong>They would ____ the things to sell and the food to ____ on their trip.</strong></p><ul><li>A. take</li><li>B. bring</li><li>C. carry</li><li>D. borrow</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（carry）</strong> —— 仆人「搬运」carry 货物和食物。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take 表带走，侧重方向而不表「负重搬运」。干扰点：take/bring/carry 混用。</li><li>B ❌ bring 表带来，方向与「随行搬运」不符。干扰点：把三者当成同义词。</li><li>C ✅ carry 表搬运、负重，They would carry the things to sell and the food。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ borrow 表借，与旅途携带无关。干扰点：只求动词能填。</li></ul><p><strong>整句翻译</strong>：他们要在旅途中搬运要卖的东西和要吃的食物。</p><p><strong>词组</strong>：<code>carry a load</code> 搬运货物</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第3空所在句）：They would <strong>3</strong> the things to sell and the food to <strong>4</strong> on their trip.</p></details><p><strong>They would carry the things to sell and the food to ____ on their trip.</strong></p><ul><li>A. cook</li><li>B. eat</li><li>C. buy</li><li>D. drink</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（eat）</strong> —— 旅途中「吃」eat 的食物。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cook 表烹煮，旅途中的食物不一定现煮，且下文并未提炊事。干扰点：把「食物」与厨房联想。</li><li>B ✅ the food to eat 表「要吃的食物」，与前半句 the things to sell（要卖的东西）结构对称。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ buy 与「带在路上的食物」矛盾（已在出发前备好）。干扰点：忽略时间。</li><li>D ❌ drink 只是食物的一部分，不能涵盖 food。干扰点：把范围缩小。</li></ul><p><strong>整句翻译</strong>：……和旅途中要吃的食物。</p><p><strong>词组</strong>：<code>the food to eat</code> 要吃的食物</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第4空所在句）：They would <strong>3</strong> the things to sell and the food to <strong>4</strong> on their trip.</p></details><p><strong>Before they started, a little boy ran up to ____ and asked to ____ with them.（本空为第 5 空）</strong></p><ul><li>A. them</li><li>B. the servants</li><li>C. the road</li><li>D. the rich man</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（the rich man）</strong> —— 下文 The rich man said to the little boy 呼应：男孩跑到「富人」the rich man 面前。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ them 指仆人群体，但决定权在富人手里，且下段 The rich man said to the little boy 直接对应。</li><li>B ❌ the servants 同样不是决定者。干扰点：把随行人群当成请求对象。</li><li>C ❌ the road 不是人，不能作为 run up to 的对象。干扰点：只求词形。</li><li>D ✅ the rich man 与下段开头 The rich man said to the little boy 的对话对象一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：出发前，一个小男孩跑到富人面前，请求和他们一起去。</p><p><strong>词组</strong>：<code>run up to sb.</code> 跑到某人面前；<code>ask to do sth.</code> 请求做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第5空所在句）：Before they started, a little boy ran up to <strong>5</strong> and asked to <strong>6</strong> with them.</p></details><p><strong>A little boy ran up to the rich man and asked to ____ with them.</strong></p><ul><li>A. stop</li><li>B. stay</li><li>C. go</li><li>D. talk</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（go）</strong> —— 请求「一起去」go with them。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ stop with them 表「和他们一起停下」，与出行的语境相反。干扰点：只求与 with 搭配。</li><li>B ❌ stay with them 表「和他们待在一起」，同样不合「随队出行」。干扰点：忽略上下文。</li><li>C ✅ asked to go with them 表「请求一起去」，与下段 The rich man said Well, you may go with us 的答复呼应。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ talk with them 表交谈，不能表达随行。干扰点：只求搭配成立。</li></ul><p><strong>整句翻译</strong>：请求和他们一起去。</p><p><strong>词组</strong>：<code>go with sb.</code> 和某人一起去</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第1段 · 第6空所在句）：Before they started, a little boy ran up to <strong>5</strong> and asked to <strong>6</strong> with them.</p></details><p><strong>“Well, ____ may go with us.”</strong></p><ul><li>A. you</li><li>B. he</li><li>C. I</li><li>D. they</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（you）</strong> —— 富人对男孩说话：「你」you 可以跟我们一起去。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 富人对男孩说话，用 you 指对方，与 may go with us 的许可语气一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ he 会变成第三人称，与直接对话的语境不符。干扰点：把对话当成转述。</li><li>C ❌ I 会变成富人自己要同行，与 with us 重复。干扰点：忽略人称一致性。</li><li>D ❌ they 与眼前的男孩不对应。干扰点：只求词形能填。</li></ul><p><strong>整句翻译</strong>：“好吧，你可以和我们一起去。”</p><p><strong>词组</strong>：<code>may do sth.</code> 可以（允许）做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第2段 · 第7空所在句）：The rich man said to the little boy, “Well, <strong>7</strong> may go with us.</p></details><p><strong>____ you are the smallest, the thinnest and the weakest of all my ____, you can’t carry a ____ load.</strong></p><ul><li>A. Since</li><li>B. If</li><li>C. Because</li><li>D. But</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（But）</strong> —— But you are the smallest… 表转折：不过你最矮最瘦最弱。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Since 表「既然/因为」，会与后句 you can’t carry 构成强因果，但此处语气是「不过」的转折限定。干扰点：把让步读成因果。</li><li>B ❌ If 表条件，与事实描述不符。干扰点：只求连接词能填。</li><li>C ❌ Because 表原因，同样会把语气读成因果。干扰点：与 Since 同类的误填。</li><li>D ✅ But 表转折：上一句已同意他同行（you may go with us），这里补上限制条件。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：但你是我所有仆人中最矮小、最瘦弱的一个，你扛不了太重的担子。</p><p><strong>词组</strong>：<code>the smallest of all</code> ……中最小的</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第2段 · 第8空所在句）：<strong>8</strong> you are the smallest, the thinnest and the weakest of all my <strong>9</strong>, you can’t carry a <strong>10</strong> load.</p></details><p><strong>But you are the smallest, the thinnest and the weakest of all my ____, you can’t carry a heavy load.</strong></p><ul><li>A. family</li><li>B. guests</li><li>C. servants</li><li>D. things</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（servants）</strong> —— 十个同行的是「仆人」servants。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ family 表家人，与 the smallest of all my… 的身高比较不符。干扰点：把「男孩」联想成孩子。</li><li>B ❌ guests 表客人，而男孩来请求随行，之后成为仆人。干扰点：把请求同行者当客人。</li><li>C ✅ 后文 All the servants were tired except the little servant 复现 servant，说明男孩身份是仆人。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ things 是物，不能用于比较人的体型。干扰点：忽略比较对象是人。</li></ul><p><strong>整句翻译</strong>：……你是我所有仆人中最矮小、最瘦弱的一个。</p><p><strong>词组</strong>：<code>of all my servants</code> 在我所有仆人中</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:10，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第2段 · 第9空所在句）：<strong>8</strong> you are the smallest, the thinnest and the weakest of all my <strong>9</strong>, you can’t carry a <strong>10</strong> load.</p></details><p><strong>You can’t carry a ____ load.</strong></p><ul><li>A. heavy</li><li>B. light</li><li>C. small</li><li>D. difficult</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（heavy）</strong> —— 最弱的不能背「重的」heavy 担子。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ you can’t carry a heavy load 与前半句「最矮小、最瘦弱」的体力判断一致，也引出选最轻担子的要求。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ light 表轻，与 can’t carry 的否定逻辑矛盾（扛不了轻的？）。干扰点：忽略否定。</li><li>C ❌ small 修饰 load 不如 heavy 自然（a small load 表量小，不合体力判断）。干扰点：只求形容词能填。</li><li>D ❌ difficult 表难，与体力无关。干扰点：把「重」与「难」混同。</li></ul><p><strong>整句翻译</strong>：你扛不了太重的担子。</p><p><strong>词组</strong>：<code>carry a heavy load</code> 扛重担</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第2段 · 第10空所在句）：<strong>8</strong> you are the smallest, the thinnest and the weakest of all my <strong>9</strong>, you can’t carry a <strong>10</strong> load.</p></details><p><strong>You must ____ the lightest one to carry.</strong></p><ul><li>A. eat</li><li>B. choose</li><li>C. pick up</li><li>D. understand</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（choose）</strong> —— 必须「挑选」choose 最轻的一担。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ eat 与「挑担子」无关。干扰点：由前面的 food 就近取材。</li><li>B ✅ choose the lightest one to carry 表「挑最轻的一个来扛」，与上句「扛不了重担」的要求一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ pick up 表「捡起」，侧重动作而非在多个选项中挑选。干扰点：与 choose 语义相近。</li><li>D ❌ understand 表理解，与选择担子无关。干扰点：只求动词能填。</li></ul><p><strong>整句翻译</strong>：你必须挑最轻的来扛。</p><p><strong>词组</strong>：<code>choose sth. to carry</code> 挑选要扛的东西</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第2段 · 第11空所在句）：You must <strong>11</strong> the lightest one to carry.”</p></details><p><strong>“You are ____,” said his master. “That is the biggest and the heaviest one.”</strong></p><ul><li>A. brave</li><li>B. right</li><li>C. clever</li><li>D. foolish</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（foolish）</strong> —— 男孩偏选最大的一担，主人说他「愚蠢」foolish。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ brave 表勇敢，与主人指出他选错的神态不符。干扰点：把「主动扛大件」当成勇敢。</li><li>B ❌ right 表正确，与「那是最重的」的纠正相反。干扰点：忽略后半句。</li><li>C ❌ clever 表聪明，同样与纠正矛盾。干扰点：忽略主人的语气。</li><li>D ✅ You are foolish 表「你真傻」，与后句 That is the biggest and the heaviest one 的提醒一致。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：“你真傻，”主人说，“那是最重最大的一个。”</p><p><strong>词组</strong>：<code>the biggest and the heaviest one</code> 最大最重的那个</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第3段 · 第12空所在句）：“You are <strong>12</strong>,” said his master.</p></details><p><strong>The boy said ____ and lifted the load gladly.</strong></p><ul><li>A. sorry</li><li>B. nothing</li><li>C. angrily</li><li>D. good-bye</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（nothing）</strong> —— 男孩「什么也没说」said nothing，却高兴地抬起来。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ said sorry 会与 gladly（高兴地）的语气不符。干扰点：把「被说傻」当成需要道歉。</li><li>B ✅ said nothing and lifted the load gladly 表「什么也没说，却高兴地扛起担子」，与他是主动、心甘情愿的选择一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ said angrily 表生气地说，与 gladly 矛盾。干扰点：忽略 gladly。</li><li>D ❌ said good-bye 表道别，与随队出发后的动作不接。干扰点：只求词能填。</li></ul><p><strong>整句翻译</strong>：男孩什么也没说，高兴地举起了担子。</p><p><strong>词组</strong>：<code>lift the load</code> 举起担子</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第3段 · 第13空所在句）：The boy said <strong>13</strong> and lifted the load gladly.</p></details><p><strong>All the servants were tired ____ the little servant.</strong></p><ul><li>A. besides</li><li>B. of</li><li>C. except</li><li>D. with</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（except）</strong> —— 面包被吃掉大半，所以只有小仆人不累：除他「之外」except。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ besides 表「除……之外（还有）」，会把小仆人也算在疲劳之列，与下文「他甚至还有力气」相反。干扰点：besides/except 中文都译「除了」。</li><li>B ❌ tired of 表「厌烦」，与旅途劳顿的语境不符。干扰点：把 tired of 当固定搭配顺手填。</li><li>C ✅ All the servants were tired except the little servant 表「除小仆人外大家都累了」，与后文 Do you know why? 的悬念一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ tired with 不成搭配（应为 tired from/with 后接原因，且此处需要「排除」义）。干扰点：只求介词能填。</li></ul><p><strong>整句翻译</strong>：到了最后，所有仆人都累了——除了那个小仆人。</p><p><strong>词组</strong>：<code>except</code> 除……之外</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:14，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第4段 · 第14空所在句）：All the servants were tired <strong>14</strong> the little servant.</p></details><p><strong>Do you know ____? Most of the bread was eaten during the trip.</strong></p><ul><li>A. who</li><li>B. him</li><li>C. that</li><li>D. why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（why）</strong> —— 设问引出原因：「知道为什么吗」Do you know why。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ who 与后句「面包被吃掉」的解释不接。干扰点：把「你知道吗」当成问人。</li><li>B ❌ him 是代词，不能作 know 的宾语从句引导词。干扰点：只求词形。</li><li>C ❌ that 引导陈述，无法承接下句的解释性说明。干扰点：忽略悬念句式。</li><li>D ✅ 后句 Most of the bread was eaten during the trip 正是对 why 的回答：他挑了面包，越走越轻。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：你知道为什么吗？旅途中大部分面包都被吃掉了。</p><p><strong>词组</strong>：<code>most of</code> 大部分</p><p><strong>对比自测</strong>：做完后对照 quiz-p20:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十九 · 最聪明的行李选择 · 第4段 · 第15空所在句）：Do you know <strong>15</strong>?</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>从前，一位富人要去另一个城镇。他不仅想带些东西去卖，也带钱去购买商品。他决定让十个仆人同行，由他们携带要卖的货物和旅途中吃的食物。出发前，一个小男孩跑到富人面前，请求一起走。</p><p>富人说：“好吧，你可以跟我们一起。因为你是所有仆人中最矮、最瘦、最弱的，不能背重担，必须挑最轻的。”男孩谢过主人，却选择了最大的一担——面包。主人说他很愚蠢，因为那一担最大、最重。男孩什么也没说，高兴地把担子抬起来。</p><p>众人走了许多天，终于到达城镇。除小仆人外，其他人都累坏了。你知道为什么吗？旅途中大部分面包都被吃掉了，到达时只剩下一点。</p></details><h3 id="练习二十-·-火场救援" tabindex="-1"><a class="header-anchor" href="#练习二十-·-火场救援"><span>练习二十 · 火场救援</span></a></h3><p>When Jim Grant spotted black smoke coming out of a building on his way to work, he <strong><strong><strong>1</strong></strong></strong> his car to call 911. Then he <strong><strong><strong>2</strong></strong></strong> a U-turn, circling back to take another look.</p><p>Pulling up to the building, Grant saw flames shooting out of a second-floor window. Not seeing or hearing any fire engines <strong><strong><strong>3</strong></strong></strong>. Grant rushed to a side <strong><strong><strong>4</strong></strong></strong> and ran up the stairs.</p><p>On the second floor, he <strong><strong><strong>5</strong></strong></strong> every apartment door. “Get out!” Grant shouted. No one <strong><em><strong>6</strong></em></strong> and he assumed that people had already <strong><strong><strong>7</strong></strong></strong>. Reaching the end of the hallway, though, Grant <strong><strong><strong>8</strong></strong></strong> a half-open door. He kicked it wide open, finding a <strong><strong><strong>9</strong></strong></strong> woman in a wheelchair with a little boy and a tiny baby. “Let’s <strong><em><strong><strong>10</strong></strong></em></strong>!” he screamed. The woman looked at him in confusion and said something about changing her clothes. Grant didn’t wait, clutching（抓牢）the baby to his chest and <strong><em><strong><strong>11</strong></strong></em></strong> the boy alongside, Grant ran down the hallway. When he was <strong><em><strong><strong>12</strong></strong></em></strong> outside, the only <strong><strong><strong>13</strong></strong></strong> in sight was a policeman. Grant told him about the <strong><em><strong><strong>14</strong></strong></em></strong> and they rushed into the smoky building.</p><p>Thanks to them, a family was saved from the fire. Grant and the policeman were honored for their <strong><em><strong><strong>15</strong></strong></em></strong>.</p><p><strong>When Jim Grant spotted black smoke coming out of a building, he ____ his car to call 911.</strong></p><ul><li>A. drove</li><li>B. stopped</li><li>C. reached</li><li>D. abandoned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（stopped）</strong> —— 为了打电话报警，「停下」stopped 车。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ drove 表继续开车，与「停下来打电话」矛盾。干扰点：忽略 to call 911 的目的。</li><li>B ✅ stopped his car to call 911 表「把车停下打 911」，与下句 made a U-turn（掉头）的动作顺序一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ reached 表到达，不能与 his car 搭配。干扰点：只求动词能填。</li><li>D ❌ abandoned 表弃车，与后文他还掉头回来查看的动作矛盾。干扰点：把「停车」夸张成「弃车」。</li></ul><p><strong>整句翻译</strong>：上班途中，Jim Grant 发现一栋楼里冒出黑烟，他把车停下打 911。</p><p><strong>词组</strong>：<code>spot black smoke</code> 发现黑烟；<code>call 911</code> 拨打 911</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第1段 · 第1空所在句）：When Jim Grant spotted black smoke coming out of a building on his way to work, he <strong><strong>1</strong></strong> his car to call 911.</p></details><p><strong>Then he ____ a U-turn, circling back to take another look.</strong></p><ul><li>A. saw</li><li>B. made</li><li>C. missed</li><li>D. crossed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（made）</strong> —— make a U-turn 掉头，固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ saw a U-turn 表「看见一个掉头」，语义不成立。干扰点：只求动词能填。</li><li>B ✅ made a U-turn 是「掉头」的固定说法，与 circling back to take another look 衔接。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ missed a U-turn 表「错过掉头」，与绕回去查看的情节矛盾。干扰点：只求搭配成立。</li><li>D ❌ crossed a U-turn 不成搭配。干扰点：只求词形。</li></ul><p><strong>整句翻译</strong>：接着他掉了个头，绕回去再看一眼。</p><p><strong>词组</strong>：<code>make a U-turn</code> 掉头；<code>take another look</code> 再看一眼</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第1段 · 第2空所在句）：Then he <strong><strong>2</strong></strong> a U-turn, circling back to take another look.</p></details><p><strong>Not seeing or hearing any fire engines ____.</strong></p><ul><li>A. burning</li><li>B. leaving</li><li>C. approaching</li><li>D. waiting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（approaching）</strong> —— 没看见没听见消防车「赶来」approaching，于是他自己冲进去。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ burning 表燃烧，消防车「燃烧」不合语义。干扰点：由 fire 联想燃烧。</li><li>B ❌ leaving 表离开，与他随后自己冲进去救人的情节矛盾。干扰点：忽略他为何孤身行动。</li><li>C ✅ Not seeing or hearing any fire engines approaching 表「没看到/听到消防车赶来」，正解释他为何独自冲进火场。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ waiting 表等待，与「赶来」的语义不同。干扰点：只求词能填。</li></ul><p><strong>整句翻译</strong>：没看到也没听到任何消防车赶来，Grant 冲到一个侧门跑上楼梯。</p><p><strong>词组</strong>：<code>fire engines</code> 消防车</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第2段 · 第3空所在句）：Not seeing or hearing any fire engines <strong><strong>3</strong></strong>.</p></details><p><strong>Grant rushed to a side ____ and ran up the stairs.</strong></p><ul><li>A. entrance</li><li>B. road</li><li>C. building</li><li>D. window</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（entrance）</strong> —— 从「侧门」side entrance 冲进楼里跑上楼梯。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ side entrance 表「侧门」，与后句 ran up the stairs（跑上楼梯）直接衔接。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ side road 表小路，不能在「小路」上跑楼梯。干扰点：把「侧面」统一理解成侧路。</li><li>C ❌ side building 不成搭配。干扰点：只求词形。</li><li>D ❌ side window 表侧窗，从窗户进楼不可能「跑上楼梯」。干扰点：把入口类词随手填。</li></ul><p><strong>整句翻译</strong>：Grant 冲到一个侧门，跑上楼梯。</p><p><strong>词组</strong>：<code>side entrance</code> 侧门</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第2段 · 第4空所在句）：Grant rushed to a side <strong><strong>4</strong></strong> and ran up the stairs.</p></details><p><strong>On the second floor, he ____ every apartment door.</strong></p><ul><li>A. locked</li><li>B. kicked</li><li>C. counted</li><li>D. repaired</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（kicked）</strong> —— 与下文 He kicked it wide open 呼应：逐门「敲踢」kicked 提醒住户。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ locked 表锁门，与「通知屋里人逃出」的救人行为不符。干扰点：只求与 door 搭配。</li><li>B ✅ kicked every apartment door 表「踢每户的门」，与下句 Get out! Grant shouted 的呼救方式一致。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ counted 表数门，与救人行动无关。干扰点：只求动词能填。</li><li>D ❌ repaired 表修门，与火场救人无关。干扰点：忽略场景。</li></ul><p><strong>整句翻译</strong>：在二楼，他踢每一户公寓的门。</p><p><strong>词组</strong>：<code>apartment door</code> 公寓门</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第5空所在句）：On the second floor, he <strong><strong>5</strong></strong> every apartment door.</p></details><p><strong>“Get out!” Grant shouted. No one ____ and he assumed that people had already ____.</strong></p><ul><li>A. agreed</li><li>B. cared</li><li>C. responded</li><li>D. understood</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（responded）</strong> —— 喊了没人「回应」responded。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ agreed 表同意，与「没人响应」的语境不搭（同意什么？）。干扰点：只求动词能填。</li><li>B ❌ cared 表在乎，不合「应答」义。干扰点：忽略语义。</li><li>C ✅ No one responded 表「没有人应答」，直接引出他以为人都已逃走的推断。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ understood 表理解，与「应答」不同。干扰点：只求语义相近。</li></ul><p><strong>整句翻译</strong>：“快出来！”Grant 大喊。没人应答，他以为人们都已经逃出去了。</p><p><strong>词组</strong>：<code>respond</code> 应答</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第6空所在句）：No one <em><strong>6</strong></em> and he assumed that people had already <strong><strong>7</strong></strong>.</p></details><p><strong>No one responded and he assumed that people had already ____.</strong></p><ul><li>A. arrived</li><li>B. returned</li><li>C. hidden</li><li>D. escaped</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（escaped）</strong> —— 无人回应，他以为大家已经「逃生」escaped。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ arrived 表到达，与火场逃生的推断无关。干扰点：只求动词能填。</li><li>B ❌ returned 表返回，与「不在楼里」的推断相反。干扰点：忽略语义。</li><li>C ❌ hidden 表躲藏，与「没人应答所以以为楼里没人」的逻辑不符。干扰点：把「不说话」理解成「躲起来」。</li><li>D ✅ had already escaped 表「已经逃出去了」，正是他推断没人应答的原因。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……他以为人们都已经逃出去了。</p><p><strong>词组</strong>：<code>escape from the fire</code> 从火场逃出</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第7空所在句）：No one <em><strong>6</strong></em> and he assumed that people had already <strong><strong>7</strong></strong>.</p></details><p><strong>Reaching the end of the hallway, though, Grant ____ a half-open door.</strong></p><ul><li>A. skipped</li><li>B. closed</li><li>C. noticed</li><li>D. remembered</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（noticed）</strong> —— 转折 though：他「注意到」noticed 一扇半开的门。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ skipped 表跳过，与「注意到一扇半开的门」的转折不符。干扰点：只求动词能填。</li><li>B ❌ closed 表关上门，与 half-open（半开）的状态矛盾。干扰点：忽略后置定语。</li><li>C ✅ noticed a half-open door 表「注意到一扇半开的门」，正是这个发现带出了后面被救的一家人。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ remembered 表记起，与现场查看的动作不合。干扰点：只求语义通顺。</li></ul><p><strong>整句翻译</strong>：然而走到走廊尽头时，Grant 注意到一扇半开的门。</p><p><strong>词组</strong>：<code>a half-open door</code> 半开的门</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第8空所在句）：Reaching the end of the hallway, though, Grant <strong><strong>8</strong></strong> a half-open door.</p></details><p><strong>He kicked it wide open, finding a ____ woman in a wheelchair with a little boy and a tiny baby.</strong></p><ul><li>A. frightened</li><li>B. curious</li><li>C. patient</li><li>D. grateful</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（frightened）</strong> —— 被困火场的女子「惊恐万分」frightened。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ a frightened woman in a wheelchair 表「一位吓坏了的、坐在轮椅上的妇女」，既符合火场情境，也解释了她为何没能逃走。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ curious 表好奇，与火场中被困的处境不符。干扰点：忽略危险场景。</li><li>C ❌ patient 表有耐心的，与火场中的情绪状态无关。干扰点：把 patient 当「病人」用。</li><li>D ❌ grateful 表感激，而此刻她还没被救出。干扰点：把结果情绪提前。</li></ul><p><strong>整句翻译</strong>：他把门一脚踹开，发现一位坐在轮椅上的妇女，身边还有一个小男孩和一个小婴儿。</p><p><strong>词组</strong>：<code>kick the door wide open</code> 把门踹开</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第9空所在句）：He kicked it wide open, finding a <strong><strong>9</strong></strong> woman in a wheelchair with a little boy and a tiny baby.</p></details><p><strong>“Let’s ____!” he screamed.</strong></p><ul><li>A. turn back</li><li>B. go up</li><li>C. get out</li><li>D. lie down</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（get out）</strong> —— 与 Get out! 呼应：大喊「快出去」get out。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ turn back 表返回，与逃生方向相反。干扰点：只求与 let’s 搭配。</li><li>B ❌ go up 表上楼，而他们要离开这栋楼。干扰点：忽略人物位置。</li><li>C ✅ “Let’s get out!” he screamed 表「我们快出去！」，与后文他抱着婴儿、拽着男孩跑下走廊一致。（来源：课件原答案，解析为笔记补充）</li><li>D ❌ lie down 表躺下，与逃生相反。干扰点：只求短语能填。</li></ul><p><strong>整句翻译</strong>：“我们快出去！”他尖叫道。</p><p><strong>词组</strong>：<code>get out</code> 出去</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第10空所在句）：“Let’s <em><strong><strong>10</strong></strong></em>!” he screamed.</p></details><p><strong>Grant didn’t wait, clutching the baby to his chest and ____ the boy alongside.</strong></p><ul><li>A. following</li><li>B. dragging</li><li>C. examining</li><li>D. passing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（dragging）</strong> —— 一手抱婴儿、一手「拖着」dragging 男孩冲下走廊。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ following 表跟随，与「他带人跑」的主从关系相反。干扰点：忽略主语是他。</li><li>B ✅ clutching the baby to his chest and dragging the boy alongside 与前半句构成并列的搬运动作——一手抱、一手拽。（来源：课件原答案，解析为笔记补充）</li><li>C ❌ examining 表检查，与火场逃离无关。干扰点：忽略场景。</li><li>D ❌ passing 表经过，不能说明他带着男孩走。干扰点：只求词能填。</li></ul><p><strong>整句翻译</strong>：Grant 没有等，把婴儿紧抱在胸前、拽着小男孩，沿着走廊跑下去。</p><p><strong>词组</strong>：<code>drag sb. alongside</code> 拽着某人同行</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第11空所在句）：Grant didn’t wait, clutching（抓牢）the baby to his chest and <em><strong><strong>11</strong></strong></em> the boy alongside, Grant ran down the hallway.</p></details><p><strong>When he was ____ outside, the only ____ in sight was a policeman.</strong></p><ul><li>A. safely</li><li>B. secretly</li><li>C. suddenly</li><li>D. previously</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（safely）</strong> —— 「安全地」safely 到达室外。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ safely outside 表「安全地到了外面」，与整段成功逃生的结果一致。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ secretly 表秘密地，与火场逃生的公开场景不符。干扰点：只求副词能填。</li><li>C ❌ suddenly 表突然，修饰外出的方式不合。干扰点：把「突然」与「顺利」混同。</li><li>D ❌ previously 表先前，与 when 从句的即时性矛盾。干扰点：忽略时态。</li></ul><p><strong>整句翻译</strong>：当他安全来到外面时，视野里唯一的帮手是一位警察。</p><p><strong>词组</strong>：<code>in sight</code> 在视野中</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第12空所在句）：When he was <em><strong><strong>12</strong></strong></em> outside, the only <strong><strong>13</strong></strong> in sight was a policeman.</p></details><p><strong>When he was safely outside, the only ____ in sight was a policeman.</strong></p><ul><li>A. witness</li><li>B. guide</li><li>C. service</li><li>D. help</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（help）</strong> —— 现场唯一能「提供帮助」help 的是一名警察。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ witness 表目击者，与需要救火的情形不符。干扰点：由「现场」联想目击者。</li><li>B ❌ guide 表向导，与火场救援无关。干扰点：只求名词能填。</li><li>C ❌ service 表服务，抽象且不合 the only…in sight 的具体所指。干扰点：把「帮助」抽象化。</li><li>D ✅ 后文 Grant told him about the woman and they rushed into the building 说明警察是来帮忙的，the only help in sight 表「唯一能求助的人」。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：……视野中唯一的帮手是一位警察。</p><p><strong>词组</strong>：<code>the only help in sight</code> 视野中唯一的帮手</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:13，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第13空所在句）：When he was <em><strong><strong>12</strong></strong></em> outside, the only <strong><strong>13</strong></strong> in sight was a policeman.</p></details><p><strong>Grant told him about the ____ and they rushed into the smoky building.</strong></p><ul><li>A. woman</li><li>B. door</li><li>C. car</li><li>D. baby</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（woman）</strong> —— 他告诉警察「那名女子」woman 仍在楼里。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the woman 与上段 he kicked it wide open, finding a frightened woman in a wheelchair 呼应——他要回去救的正是她。（来源：课件原答案，解析为笔记补充）</li><li>B ❌ door 表门，与「冲进楼里救人」的目标不符。干扰点：把道具当对象。</li><li>C ❌ car 与救火无关。干扰点：由开头停车联想车。</li><li>D ❌ baby 只是被困家庭的一员，而他告诉警察的紧急情况核心是还被困的妇女。干扰点：把婴儿当成唯一求助对象。</li></ul><p><strong>整句翻译</strong>：Grant 把那位妇女的情况告诉了他，两人便冲进冒烟的楼里。</p><p><strong>词组</strong>：<code>rush into the building</code> 冲进楼里</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:12，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第3段 · 第14空所在句）：Grant told him about the <em><strong><strong>14</strong></strong></em> and they rushed into the smoky building.</p></details><p><strong>Grant and the policeman were honored for their ____.</strong></p><ul><li>A. wisdom</li><li>B. generosity</li><li>C. honesty</li><li>D. courage</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（courage）</strong> —— 冲进火场救人受表彰，是因为「勇气」courage。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wisdom 表智慧，与冲入火场的举动相比不如 courage 贴切。干扰点：把「机敏」与「英勇」混淆。</li><li>B ❌ generosity 表慷慨，与舍身救人无关。干扰点：只求褒义名词。</li><li>C ❌ honesty 表诚实，与火场救援无关。干扰点：忽略事迹本身。</li><li>D ✅ courage 表勇气，对应他们冲入燃烧的建筑救人的行为，故 honored for their courage。（来源：课件原答案，解析为笔记补充）</li></ul><p><strong>整句翻译</strong>：多亏了他们，一家人从火灾中被救了出来。Grant 和那位警察因勇敢而受到表彰。</p><p><strong>词组</strong>：<code>be honored for</code> 因……而受到表彰</p><p><strong>对比自测</strong>：做完后对照 quiz-p21:11，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二十 · 火场救援 · 第4段 · 第15空所在句）：Grant and the policeman were honored for their <em><strong><strong>15</strong></strong></em>.</p></details><details class="hint-container details"><summary>本篇中文译文</summary><p>Jim Grant 上班途中发现一栋楼冒出黑烟，便停车拨打 911，随后掉头绕回来再看一眼。他把车停到楼前，看到火焰从二楼窗户窜出。既没看见也没听见消防车赶来，Grant 便冲向侧门，跑上楼梯。</p><p>到了二楼，他踢响每一扇公寓门，大喊“快出去！”无人回应，他以为人们已经逃走。可是到走廊尽头时，他注意到一扇半开的门，便一脚踢开。屋里有一名坐轮椅、惊恐万分的女子，还有一个小男孩和一个小婴儿。Grant 大喊“快出去！”女子困惑地看着他，还说要换衣服。Grant 没有等待，他把婴儿紧抱在胸前，同时拖着男孩冲下走廊。</p><p>Grant 安全到达室外时，现场唯一能提供帮助的人是一名警察。他告诉警察那名女子仍在楼里，两人随即冲进烟雾弥漫的大楼。多亏他们，一家人获救；Grant 和警察也因勇气受到表彰。</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 做题总纲：<strong>先完意，后完形；先全文，后单句。</strong></p><p>定位线索：<strong>首尾定主旨，上下找复现，前后判逻辑，搭配作终审。</strong></p><p>节奏：<strong>有把握先填，没把握先跳；全部回填，再读一遍。</strong></p><p>逻辑词：<strong>and 多同向，but 常反向；上因下果，前转后折。</strong></p><p>分工：<strong>词义看语境，搭配看整体，语法看结构，常识作辅助。</strong></p></div>`,1176),a(`p`,null,[l[7]||=e(`关联复习：`,-1),o(m,{href:`/courses/zsb-english/l/19/`},{default:i(()=>[...l[5]||=[e(`阅读理解`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/23/`},{default:i(()=>[...l[6]||=[e(`语法填空`,-1)]]),_:1})]),l[15]||=a(`p`,null,`延伸阅读：完形填空 · 完整笔记 · 原始课件 PDF`,-1),l[16]||=a(`p`,null,`有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。`,-1),l[17]||=a(`hr`,null,null,-1),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/17/`},{default:i(()=>[...l[9]||=[e(`← 第 17 课`,-1)]]),_:1}),l[12]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[10]||=[e(`课程目录`,-1)]]),_:1}),l[13]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/19/`},{default:i(()=>[...l[11]||=[e(`第 19 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};